INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (1, 1, 'Solve: 6 + 2 × 3', 'text', 1, 'Use BODMAS', '{"why":"BODMAS: Multiplication before Addition → 2 × 3 = 6, then 6 + 6 = 12","sol":"Step 1: 6 + 2 × 3\nStep 2: 6 + (2 × 3) = 6 + 6\nStep 3: = 12","steps":["Step 1: 6 + 2 × 3","Step 2: 6 + (2 × 3) = 6 + 6","Step 3: = 12"],"options":[],"conceptId":"math_numbers_number_systems_basic_operations","skillId":"math_numbers","subskillId":"math_numbers_q1","subject":"math","chapter":"numbers","topic":"Number Systems & Basic Operations"}', 0),
  (2, 1, 'Find: 15 ÷ 3 + 2', 'text', 1, 'Division first', '{"why":"BODMAS: Division before Addition → 15 ÷ 3 = 5, then 5 + 2 = 7","sol":"Step 1: 15 ÷ 3 + 2\nStep 2: (15 ÷ 3) + 2 = 5 + 2\nStep 3: = 7","steps":["Step 1: 15 ÷ 3 + 2","Step 2: (15 ÷ 3) + 2 = 5 + 2","Step 3: = 7"],"options":[],"conceptId":"math_numbers_number_systems_basic_operations","skillId":"math_numbers","subskillId":"math_numbers_q2","subject":"math","chapter":"numbers","topic":"Number Systems & Basic Operations"}', 1),
  (3, 1, 'What type of number is -5?', 'text', 1, 'check sign', '{"why":"ℤ = {..., -3, -2, -1, 0, 1, 2, ...} → -5 ∈ ℤ","sol":"Step 1: -5 < 0 → negative number\nStep 2: -5 ∈ {..., -3, -2, -1, 0, 1, 2, 3, ...}\nStep 3: ∴ -5 ∈ ℤ (integers)","steps":["Step 1: -5 < 0 → negative number","Step 2: -5 ∈ {..., -3, -2, -1, 0, 1, 2, 3, ...}","Step 3: ∴ -5 ∈ ℤ (integers)"],"options":[],"conceptId":"math_numbers_number_systems_basic_operations","skillId":"math_numbers","subskillId":"math_numbers_q3","subject":"math","chapter":"numbers","topic":"Number Systems & Basic Operations"}', 2),
  (4, 1, 'Convert 3/4 into a decimal', 'text', 1, 'divide', '{"why":"3/4 = 3 ÷ 4 = 0.75","sol":"Step 1: 3/4 = 3 ÷ 4\nStep 2: 3 ÷ 4 = 0.75","steps":["Step 1: 3/4 = 3 ÷ 4","Step 2: 3 ÷ 4 = 0.75"],"options":[],"conceptId":"math_numbers_number_systems_basic_operations","skillId":"math_numbers","subskillId":"math_numbers_q4","subject":"math","chapter":"numbers","topic":"Number Systems & Basic Operations"}', 3),
  (5, 1, 'Solve: (5 + 3) × 2', 'text', 1, 'brackets first', '{"why":"BODMAS: Brackets first → (5 + 3) = 8, then 8 × 2 = 16","sol":"Step 1: (5 + 3) × 2\nStep 2: (8) × 2\nStep 3: = 16","steps":["Step 1: (5 + 3) × 2","Step 2: (8) × 2","Step 3: = 16"],"options":[],"conceptId":"math_numbers_number_systems_basic_operations","skillId":"math_numbers","subskillId":"math_numbers_q5","subject":"math","chapter":"numbers","topic":"Number Systems & Basic Operations"}', 4),
  (6, 2, 'Evaluate 3x + 5 when x = 2', 'text', 1, 'substitute first', '{"why":"Substitution must be done before simplifying","sol":"Step 1: Replace x with 2 → 3(2) + 5\nStep 2: Multiply → 6 + 5\nStep 3: = 11","steps":["Step 1: Replace x with 2 → 3(2) + 5","Step 2: Multiply → 6 + 5","Step 3: = 11"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 0),
  (7, 2, 'Simplify 2x + 3x', 'text', 1, 'like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 2x + 3x\nStep 2: (2 + 3)x\nStep 3: = 5x","steps":["Step 1: 2x + 3x","Step 2: (2 + 3)x","Step 3: = 5x"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 1),
  (8, 2, 'Identify: 4y + 7', 'text', 1, 'expression parts', '{"why":"It has variables and constants but no equation","sol":"Step 1: Contains variable y\nStep 2: Contains constant 7\nStep 3: No equals sign","steps":["Step 1: Contains variable y","Step 2: Contains constant 7","Step 3: No equals sign"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 2),
  (9, 2, 'Translate: ‘5 less than a number x’', 'text', 1, 'subtract 5', '{"why":"Word phrases convert into algebraic expressions","sol":"Step 1: number x → x\nStep 2: 5 less → −5\nStep 3: x − 5","steps":["Step 1: number x → x","Step 2: 5 less → −5","Step 3: x − 5"],"options":[],"conceptId":"math_algebra_algebraic_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Algebraic expressions"}', 3),
  (10, 3, 'Simplify 3x + 4x + 2', 'text', 1, 'group like terms', '{"why":"Only like terms can be combined","sol":"Step 1: 3x + 4x = 7x\nStep 2: +2 remains unchanged\nStep 3: 7x + 2","steps":["Step 1: 3x + 4x = 7x","Step 2: +2 remains unchanged","Step 3: 7x + 2"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 0),
  (11, 3, 'Simplify 6a - 2a', 'text', 1, 'subtract coefficients', '{"why":"Same variable means combine coefficients","sol":"Step 1: 6a − 2a\nStep 2: (6 − 2)a = 4a","steps":["Step 1: 6a − 2a","Step 2: (6 − 2)a = 4a"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 1),
  (12, 3, 'Simplify 2x + 3y + 5x', 'text', 1, 'group x terms', '{"why":"Like terms grouped together","sol":"Step 1: (2x + 5x) + 3y\nStep 2: 7x + 3y","steps":["Step 1: (2x + 5x) + 3y","Step 2: 7x + 3y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 2),
  (13, 3, 'Simplify x + 2x + y + 3y', 'text', 1, 'group both variables', '{"why":"Combine each variable separately","sol":"Step 1: (x + 2x) + (y + 3y)\nStep 2: 3x + 4y","steps":["Step 1: (x + 2x) + (y + 3y)","Step 2: 3x + 4y"],"options":[],"conceptId":"math_algebra_simplifying_expressions","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Simplifying expressions"}', 3),
  (14, 4, 'Solve x + 5 = 12', 'text', 1, 'inverse operation', '{"why":"Maintain balance by doing same operation on both sides","sol":"Step 1: Subtract 5 from both sides\nStep 2: x = 12 − 5\nStep 3: x = 7","steps":["Step 1: Subtract 5 from both sides","Step 2: x = 12 − 5","Step 3: x = 7"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Linear equations"}', 0),
  (15, 4, 'Solve 2x = 10', 'text', 1, 'divide both sides', '{"why":"Inverse of multiplication is division","sol":"Step 1: Divide both sides by 2\nStep 2: x = 5","steps":["Step 1: Divide both sides by 2","Step 2: x = 5"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Linear equations"}', 1),
  (16, 4, 'Solve 3x + 2 = 11', 'text', 1, 'remove constant first', '{"why":"Isolate variable step by step","sol":"Step 1: 3x = 11 − 2\nStep 2: 3x = 9\nStep 3: x = 3","steps":["Step 1: 3x = 11 − 2","Step 2: 3x = 9","Step 3: x = 3"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Linear equations"}', 2),
  (17, 4, 'Solve 4x − 6 = 10', 'text', 1, 'add 6 first', '{"why":"Move constants using inverse operations","sol":"Step 1: 4x = 10 + 6\nStep 2: 4x = 16\nStep 3: x = 4","steps":["Step 1: 4x = 10 + 6","Step 2: 4x = 16","Step 3: x = 4"],"options":[],"conceptId":"math_algebra_linear_equations","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Linear equations"}', 3),
  (18, 5, 'If x = 3, find x + 4', 'text', 1, 'replace x first', '{"why":"Substitution replaces variables with numbers","sol":"Step 1: Substitute x = 3\nStep 2: 3 + 4\nStep 3: = 7","steps":["Step 1: Substitute x = 3","Step 2: 3 + 4","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Substitution"}', 0),
  (19, 5, 'If x = 2, find 2x + 1', 'text', 1, 'multiply first', '{"why":"Follow multiplication before addition","sol":"Step 1: Substitute → 2(2) + 1\nStep 2: Multiply → 4 + 1\nStep 3: = 5","steps":["Step 1: Substitute → 2(2) + 1","Step 2: Multiply → 4 + 1","Step 3: = 5"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Substitution"}', 1),
  (20, 5, 'If x = 4, y = 3, find x + y', 'text', 1, 'replace both variables', '{"why":"Both variables must be replaced","sol":"Step 1: Substitute → 4 + 3\nStep 2: Simplify\nStep 3: = 7","steps":["Step 1: Substitute → 4 + 3","Step 2: Simplify","Step 3: = 7"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Substitution"}', 2),
  (21, 5, 'If x = 5, find 3x − 2', 'text', 1, 'multiply then subtract', '{"why":"Substitution followed by order of operations","sol":"Step 1: 3 × 5 = 15\nStep 2: 15 − 2\nStep 3: = 13","steps":["Step 1: 3 × 5 = 15","Step 2: 15 − 2","Step 3: = 13"],"options":[],"conceptId":"math_algebra_substitution","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Substitution"}', 3),
  (22, 6, 'Expand 2(x + 3)', 'text', 1, 'multiply each term', '{"why":"Distributive law multiplies each term inside bracket","sol":"Step 1: 2 × x = 2x\nStep 2: 2 × 3 = 6\nStep 3: Combine → 2x + 6","steps":["Step 1: 2 × x = 2x","Step 2: 2 × 3 = 6","Step 3: Combine → 2x + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q1","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 0),
  (23, 6, 'Expand 3(a + 2)', 'text', 1, 'distribute 3', '{"why":"Each term inside bracket must be multiplied","sol":"Step 1: 3 × a = 3a\nStep 2: 3 × 2 = 6\nStep 3: 3a + 6","steps":["Step 1: 3 × a = 3a","Step 2: 3 × 2 = 6","Step 3: 3a + 6"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q2","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 1),
  (24, 6, 'Expand 4(x + 1)', 'text', 1, 'multiply each term', '{"why":"Distributive property applies to all terms","sol":"Step 1: 4 × x = 4x\nStep 2: 4 × 1 = 4\nStep 3: 4x + 4","steps":["Step 1: 4 × x = 4x","Step 2: 4 × 1 = 4","Step 3: 4x + 4"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q3","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 2),
  (25, 6, 'What is the distributive law?', 'text', 1, 'a(b + c)', '{"why":"It ensures correct expansion of brackets","sol":"Step 1: Multiply outside term\nStep 2: Multiply each inside term\nStep 3: Combine results","steps":["Step 1: Multiply outside term","Step 2: Multiply each inside term","Step 3: Combine results"],"options":[],"conceptId":"math_algebra_expanding_brackets","skillId":"math_algebra","subskillId":"math_algebra_q4","subject":"math","chapter":"algebra","topic":"Expanding brackets"}', 3),
  (26, 7, 'Classify 60°', 'text', 1, 'Compare with 90°', '{"why":"Angles less than 90° are acute","sol":"Step 1: 60° is less than 90°\nStep 2: Therefore it is acute","steps":["Step 1: 60° is less than 90°","Step 2: Therefore it is acute"],"options":[],"conceptId":"math_geometry_types_of_angles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Types of angles"}', 0),
  (27, 7, 'Classify 120°', 'text', 1, 'Between 90° and 180°', '{"why":"Angles between 90° and 180° are obtuse","sol":"Step 1: Compare with 90°\nStep 2: Compare with 180°\nStep 3: Determine range","steps":["Step 1: Compare with 90°","Step 2: Compare with 180°","Step 3: Determine range"],"options":[],"conceptId":"math_geometry_types_of_angles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Types of angles"}', 1),
  (28, 7, 'What is a right angle?', 'text', 1, 'corner', '{"why":"It forms a perfect square corner","sol":"Step 1: Identify angle size\nStep 2: Check if exactly 90°\nStep 3: Define type","steps":["Step 1: Identify angle size","Step 2: Check if exactly 90°","Step 3: Define type"],"options":[],"conceptId":"math_geometry_types_of_angles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Types of angles"}', 2),
  (29, 7, 'What is a straight angle?', 'text', 1, 'line', '{"why":"It forms a straight line","sol":"Step 1: Observe full line\nStep 2: Measure angle\nStep 3: Identify value","steps":["Step 1: Observe full line","Step 2: Measure angle","Step 3: Identify value"],"options":[],"conceptId":"math_geometry_types_of_angles","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Types of angles"}', 3),
  (30, 8, 'Find missing angle: 30° + 80° + x = 180°', 'text', 1, 'Use 180° rule', '{"why":"All triangle angles must sum to 180°","sol":"Step 1: Add known angles → 110°\nStep 2: 180 − 110\nStep 3: x = 70°","steps":["Step 1: Add known angles → 110°","Step 2: 180 − 110","Step 3: x = 70°"],"options":[],"conceptId":"math_geometry_triangles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Triangles"}', 0),
  (31, 8, 'What is the sum of angles in a triangle?', 'text', 1, 'constant rule', '{"why":"All triangles have a fixed angle sum of 180°","sol":"Step 1: Identify shape\nStep 2: Apply rule\nStep 3: State result","steps":["Step 1: Identify shape","Step 2: Apply rule","Step 3: State result"],"options":[],"conceptId":"math_geometry_triangles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Triangles"}', 1),
  (32, 8, 'Which triangle has all sides equal?', 'text', 1, 'equilateral', '{"why":"All sides and angles are equal","sol":"Step 1: Compare sides\nStep 2: Check equality\nStep 3: Identify type","steps":["Step 1: Compare sides","Step 2: Check equality","Step 3: Identify type"],"options":[],"conceptId":"math_geometry_triangles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Triangles"}', 2),
  (33, 8, 'What is special about right-angled triangles?', 'text', 1, '90° angle', '{"why":"It forms perpendicular sides","sol":"Step 1: Identify angle\nStep 2: Check for 90°\nStep 3: Define type","steps":["Step 1: Identify angle","Step 2: Check for 90°","Step 3: Define type"],"options":[],"conceptId":"math_geometry_triangles","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Triangles"}', 3),
  (34, 9, 'Find missing angle: 100° + 70° + 80° + x = 360°', 'text', 1, 'Use 360° rule', '{"why":"Interior angles of a quadrilateral always sum to 360°","sol":"Step 1: Add known angles → 250°\nStep 2: 360 − 250\nStep 3: x = 110°","steps":["Step 1: Add known angles → 250°","Step 2: 360 − 250","Step 3: x = 110°"],"options":[],"conceptId":"math_geometry_quadrilaterals","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Quadrilaterals"}', 0),
  (35, 9, 'What is the sum of interior angles of a quadrilateral?', 'text', 1, 'constant rule', '{"why":"All four interior angles always add up to 360°","sol":"Step 1: Identify shape\nStep 2: Apply formula\nStep 3: State result","steps":["Step 1: Identify shape","Step 2: Apply formula","Step 3: State result"],"options":[],"conceptId":"math_geometry_quadrilaterals","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Quadrilaterals"}', 1),
  (36, 9, 'Which quadrilateral has all sides equal?', 'text', 1, 'rhombus or square', '{"why":"Both have equal side lengths","sol":"Step 1: Check side lengths\nStep 2: Compare properties\nStep 3: Identify shape","steps":["Step 1: Check side lengths","Step 2: Compare properties","Step 3: Identify shape"],"options":[],"conceptId":"math_geometry_quadrilaterals","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Quadrilaterals"}', 2),
  (37, 9, 'What makes a rectangle different from a square?', 'text', 1, 'side lengths', '{"why":"Square is a special type of rectangle","sol":"Step 1: Compare sides\nStep 2: Compare angles\nStep 3: Identify difference","steps":["Step 1: Compare sides","Step 2: Compare angles","Step 3: Identify difference"],"options":[],"conceptId":"math_geometry_quadrilaterals","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Quadrilaterals"}', 3),
  (38, 10, 'Diameter 14 cm, find radius', 'text', 1, 'Divide by 2', '{"why":"Radius is always half the diameter","sol":"Step 1: Identify formula radius = diameter ÷ 2\nStep 2: 14 ÷ 2\nStep 3: = 7 cm","steps":["Step 1: Identify formula radius = diameter ÷ 2","Step 2: 14 ÷ 2","Step 3: = 7 cm"],"options":[],"conceptId":"math_geometry_circles","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Circles"}', 0),
  (39, 10, 'Radius 9 cm, find diameter', 'text', 1, 'Multiply by 2', '{"why":"Diameter is twice the radius","sol":"Step 1: Use formula diameter = 2 × radius\nStep 2: 2 × 9\nStep 3: = 18 cm","steps":["Step 1: Use formula diameter = 2 × radius","Step 2: 2 × 9","Step 3: = 18 cm"],"options":[],"conceptId":"math_geometry_circles","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Circles"}', 1),
  (40, 10, 'What is a circle?', 'text', 1, 'distance from center', '{"why":"This equal distance defines a perfect circular shape","sol":"Step 1: Identify center point\nStep 2: All points equal distance\nStep 3: Define shape","steps":["Step 1: Identify center point","Step 2: All points equal distance","Step 3: Define shape"],"options":[],"conceptId":"math_geometry_circles","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Circles"}', 2),
  (41, 10, 'What is circumference?', 'text', 1, 'outer edge', '{"why":"It measures the perimeter of a circle","sol":"Step 1: Look at boundary\nStep 2: Measure full distance around circle\nStep 3: Define term","steps":["Step 1: Look at boundary","Step 2: Measure full distance around circle","Step 3: Define term"],"options":[],"conceptId":"math_geometry_circles","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Circles"}', 3),
  (42, 11, 'Area of rectangle 8 × 2', 'text', 1, 'Multiply length and width', '{"why":"Area of rectangle is length × width","sol":"Step 1: Multiply 8 × 2\nStep 2: Compute result = 16","steps":["Step 1: Multiply 8 × 2","Step 2: Compute result = 16"],"options":[],"conceptId":"math_geometry_area_and_perimeter","skillId":"math_geometry","subskillId":"math_geometry_q1","subject":"math","chapter":"geometry","topic":"Area and Perimeter"}', 0),
  (43, 11, 'What is perimeter of a square with side 5?', 'text', 1, '4 × side', '{"why":"Perimeter adds all four equal sides","sol":"Step 1: Use formula 4 × side\nStep 2: 4 × 5 = 20","steps":["Step 1: Use formula 4 × side","Step 2: 4 × 5 = 20"],"options":[],"conceptId":"math_geometry_area_and_perimeter","skillId":"math_geometry","subskillId":"math_geometry_q2","subject":"math","chapter":"geometry","topic":"Area and Perimeter"}', 1),
  (44, 11, 'Find area of triangle with base 10 and height 6', 'text', 1, '½ × b × h', '{"why":"Triangle area is half of rectangle","sol":"Step 1: Multiply 10 × 6 = 60\nStep 2: Divide by 2\nStep 3: = 30","steps":["Step 1: Multiply 10 × 6 = 60","Step 2: Divide by 2","Step 3: = 30"],"options":[],"conceptId":"math_geometry_area_and_perimeter","skillId":"math_geometry","subskillId":"math_geometry_q3","subject":"math","chapter":"geometry","topic":"Area and Perimeter"}', 2),
  (45, 11, 'What is the difference between area and perimeter?', 'text', 1, 'inside vs outside', '{"why":"They measure different properties of shapes","sol":"Step 1: Define area\nStep 2: Define perimeter\nStep 3: Compare meanings","steps":["Step 1: Define area","Step 2: Define perimeter","Step 3: Compare meanings"],"options":[],"conceptId":"math_geometry_area_and_perimeter","skillId":"math_geometry","subskillId":"math_geometry_q4","subject":"math","chapter":"geometry","topic":"Area and Perimeter"}', 3),
  (46, 12, 'Evaluate 7/9 as a decimal', 'text', 1, 'division', '{"why":"Fraction is expressed as division of numerator by denominator","sol":"Step 1: Divide 7 ÷ 9\nStep 2: Perform long division\nStep 3: Obtain repeating decimal\nStep 4: Round to required precision","steps":["Step 1: Divide 7 ÷ 9","Step 2: Perform long division","Step 3: Obtain repeating decimal","Step 4: Round to required precision"],"options":[],"conceptId":"math_fractions_fraction_basics","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Fraction basics"}', 0),
  (47, 12, 'Find the missing denominator if 3/x = 0.6', 'text', 1, 'solve equation', '{"why":"Denominator is found by rearranging fractional equation","sol":"Step 1: Write 3/x = 0.6\nStep 2: Multiply both sides by x\nStep 3: 3 = 0.6x\nStep 4: Divide both sides by 0.6\nStep 5: Solve for x","steps":["Step 1: Write 3/x = 0.6","Step 2: Multiply both sides by x","Step 3: 3 = 0.6x","Step 4: Divide both sides by 0.6","Step 5: Solve for x"],"options":[],"conceptId":"math_fractions_fraction_basics","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Fraction basics"}', 1),
  (48, 12, 'Convert 3/5 into percentage', 'text', 1, 'fraction to percent', '{"why":"Fraction conversion uses multiplication by 100","sol":"Step 1: Divide 3 ÷ 5\nStep 2: Multiply result by 100\nStep 3: Compute final percentage","steps":["Step 1: Divide 3 ÷ 5","Step 2: Multiply result by 100","Step 3: Compute final percentage"],"options":[],"conceptId":"math_fractions_fraction_basics","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Fraction basics"}', 2),
  (49, 12, 'Find equivalent fraction of 3/5 with denominator 20', 'text', 1, 'scaling fractions', '{"why":"Equivalent fractions preserve ratio by scaling numerator and denominator equally","sol":"Step 1: Determine multiplier from 5 to 20\nStep 2: Multiply numerator by same factor\nStep 3: Form new fraction","steps":["Step 1: Determine multiplier from 5 to 20","Step 2: Multiply numerator by same factor","Step 3: Form new fraction"],"options":[],"conceptId":"math_fractions_fraction_basics","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Fraction basics"}', 3),
  (50, 13, '2/3 + 1/3', 'text', 1, 'Same denominator', '{"why":"Forms a whole","sol":"Step 1: Add numerators → 2 + 1 = 3\nStep 2: 3/3\nStep 3: Simplify → 1","steps":["Step 1: Add numerators → 2 + 1 = 3","Step 2: 3/3","Step 3: Simplify → 1"],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Adding and subtracting fractions"}', 0),
  (51, 13, '1/2 + 1/4', 'text', 1, 'Find LCM', '{"why":"Common denominator method","sol":"Step 1: LCM of 2 and 4 = 4\nStep 2: Convert 1/2 = 2/4\nStep 3: 2/4 + 1/4 = 3/4","steps":["Step 1: LCM of 2 and 4 = 4","Step 2: Convert 1/2 = 2/4","Step 3: 2/4 + 1/4 = 3/4"],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Adding and subtracting fractions"}', 1),
  (52, 13, '5/6 - 1/3', 'text', 1, 'Convert denominator', '{"why":"Subtraction with LCM","sol":"Step 1: 1/3 = 2/6\nStep 2: 5/6 - 2/6\nStep 3: 3/6 = 1/2","steps":["Step 1: 1/3 = 2/6","Step 2: 5/6 - 2/6","Step 3: 3/6 = 1/2"],"options":[],"conceptId":"math_fractions_adding_and_subtracting_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Adding and subtracting fractions"}', 2),
  (53, 14, '4/7 × 2/3', 'text', 1, 'Multiply straight across', '{"why":"Multiply numerators and denominators","sol":"Step 1: 4 × 2 = 8\nStep 2: 7 × 3 = 21","steps":["Step 1: 4 × 2 = 8","Step 2: 7 × 3 = 21"],"options":[],"conceptId":"math_fractions_multiplying_and_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Multiplying and dividing fractions"}', 0),
  (54, 14, '5/6 ÷ 1/3', 'text', 1, 'Flip second fraction', '{"why":"Division uses reciprocal","sol":"Step 1: 5/6 × 3/1\nStep 2: 15/6\nStep 3: Simplify → 5/2","steps":["Step 1: 5/6 × 3/1","Step 2: 15/6","Step 3: Simplify → 5/2"],"options":[],"conceptId":"math_fractions_multiplying_and_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Multiplying and dividing fractions"}', 1),
  (55, 14, '2/5 ÷ 2/5', 'text', 1, 'Same fractions', '{"why":"Any number divided by itself = 1","sol":"Step 1: Flip → 2/5 × 5/2\nStep 2: Cancel common factors\nStep 3: 1","steps":["Step 1: Flip → 2/5 × 5/2","Step 2: Cancel common factors","Step 3: 1"],"options":[],"conceptId":"math_fractions_multiplying_and_dividing_fractions","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Multiplying and dividing fractions"}', 2),
  (56, 15, '0.2 + 0.3', 'text', 1, 'Add decimals', '{"why":"Place value addition","sol":"Step 1: Align decimal points\nStep 2: 0.2 + 0.3\nStep 3: 0.5","steps":["Step 1: Align decimal points","Step 2: 0.2 + 0.3","Step 3: 0.5"],"options":[],"conceptId":"math_fractions_decimals","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Decimals"}', 0),
  (57, 15, 'Convert 0.6 to fraction', 'text', 1, 'Write over 10', '{"why":"Simplifying fractions","sol":"Step 1: 0.6 = 6/10\nStep 2: Simplify\nStep 3: 3/5","steps":["Step 1: 0.6 = 6/10","Step 2: Simplify","Step 3: 3/5"],"options":[],"conceptId":"math_fractions_decimals","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Decimals"}', 1),
  (58, 15, '1.5 + 2.25', 'text', 1, 'Align decimals', '{"why":"Decimal addition rules","sol":"Step 1: 1.50 + 2.25\nStep 2: Add\nStep 3: 3.75","steps":["Step 1: 1.50 + 2.25","Step 2: Add","Step 3: 3.75"],"options":[],"conceptId":"math_fractions_decimals","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Decimals"}', 2),
  (59, 16, 'Convert 0.666... into fraction form', 'text', 1, 'recurring decimal', '{"why":"Recurring decimals are solved using elimination of repeating part","sol":"Step 1: Let x = 0.666...\nStep 2: Multiply both sides by 10 → 10x = 6.666...\nStep 3: Subtract x from 10x\nStep 4: 9x = 6\nStep 5: Solve for x","steps":["Step 1: Let x = 0.666...","Step 2: Multiply both sides by 10 → 10x = 6.666...","Step 3: Subtract x from 10x","Step 4: 9x = 6","Step 5: Solve for x"],"options":[],"conceptId":"math_fractions_fractions_to_decimals","skillId":"math_fractions","subskillId":"math_fractions_q1","subject":"math","chapter":"fractions","topic":"Fractions to decimals"}', 0),
  (60, 16, 'Convert 0.121212... into fraction form', 'text', 1, 'two-digit repeating block', '{"why":"Repeating blocks are eliminated using powers of 10","sol":"Step 1: Let x = 0.121212...\nStep 2: Multiply both sides by 100 → 100x = 12.121212...\nStep 3: Subtract x from 100x\nStep 4: 99x = 12\nStep 5: Solve for x","steps":["Step 1: Let x = 0.121212...","Step 2: Multiply both sides by 100 → 100x = 12.121212...","Step 3: Subtract x from 100x","Step 4: 99x = 12","Step 5: Solve for x"],"options":[],"conceptId":"math_fractions_fractions_to_decimals","skillId":"math_fractions","subskillId":"math_fractions_q2","subject":"math","chapter":"fractions","topic":"Fractions to decimals"}', 1),
  (61, 16, 'Convert 0.444... into fraction form', 'text', 1, 'single repeating digit', '{"why":"Single repeating digits simplify into ninths","sol":"Step 1: Let x = 0.444...\nStep 2: Multiply both sides by 10 → 10x = 4.444...\nStep 3: Subtract x from 10x\nStep 4: 9x = 4\nStep 5: Solve for x","steps":["Step 1: Let x = 0.444...","Step 2: Multiply both sides by 10 → 10x = 4.444...","Step 3: Subtract x from 10x","Step 4: 9x = 4","Step 5: Solve for x"],"options":[],"conceptId":"math_fractions_fractions_to_decimals","skillId":"math_fractions","subskillId":"math_fractions_q3","subject":"math","chapter":"fractions","topic":"Fractions to decimals"}', 2),
  (62, 16, 'Convert 0.777... into fraction form', 'text', 1, 'recurring decimal', '{"why":"Recurring decimals convert into fraction using elimination method","sol":"Step 1: Let x = 0.777...\nStep 2: Multiply both sides by 10 → 10x = 7.777...\nStep 3: Subtract x from 10x\nStep 4: 9x = 7\nStep 5: Solve for x","steps":["Step 1: Let x = 0.777...","Step 2: Multiply both sides by 10 → 10x = 7.777...","Step 3: Subtract x from 10x","Step 4: 9x = 7","Step 5: Solve for x"],"options":[],"conceptId":"math_fractions_fractions_to_decimals","skillId":"math_fractions","subskillId":"math_fractions_q4","subject":"math","chapter":"fractions","topic":"Fractions to decimals"}', 3),
  (63, 16, 'Convert 0.090909... into fraction form', 'text', 1, 'two-digit repetition', '{"why":"Repeating patterns convert into simplified fractions using algebra","sol":"Step 1: Let x = 0.090909...\nStep 2: Multiply both sides by 100 → 100x = 9.090909...\nStep 3: Subtract x from 100x\nStep 4: 99x = 9\nStep 5: Solve for x","steps":["Step 1: Let x = 0.090909...","Step 2: Multiply both sides by 100 → 100x = 9.090909...","Step 3: Subtract x from 100x","Step 4: 99x = 9","Step 5: Solve for x"],"options":[],"conceptId":"math_fractions_fractions_to_decimals","skillId":"math_fractions","subskillId":"math_fractions_q5","subject":"math","chapter":"fractions","topic":"Fractions to decimals"}', 4),
  (64, 17, 'Find area of rectangle 8 × 2', 'text', 1, 'Multiply length and width', '{"why":"Area formula for rectangle","sol":"Step 1: Area = length × width\nStep 2: 8 × 2\nStep 3: 16","steps":["Step 1: Area = length × width","Step 2: 8 × 2","Step 3: 16"],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of rectangles and squares"}', 0),
  (65, 17, 'Find area of square with side 7', 'text', 1, 'Side × side', '{"why":"Square area rule","sol":"Step 1: 7 × 7\nStep 2: 49","steps":["Step 1: 7 × 7","Step 2: 49"],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of rectangles and squares"}', 1),
  (66, 17, 'Rectangle has length 9 and width 5. Find area', 'text', 1, 'Multiply', '{"why":"Direct formula application","sol":"Step 1: 9 × 5\nStep 2: 45","steps":["Step 1: 9 × 5","Step 2: 45"],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of rectangles and squares"}', 2),
  (67, 17, 'Square side 10. Find area', 'text', 1, 'Square rule', '{"why":"Side squared","sol":"Step 1: 10 × 10\nStep 2: 100","steps":["Step 1: 10 × 10","Step 2: 100"],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q4","subject":"math","chapter":"measurement","topic":"Area of rectangles and squares"}', 3),
  (68, 17, 'Which is correct formula for rectangle area?', 'text', 1, 'length and width', '{"why":"Definition of rectangle area","sol":"Step 1: Identify rectangle formula\nStep 2: Multiply length × width","steps":["Step 1: Identify rectangle formula","Step 2: Multiply length × width"],"options":[],"conceptId":"math_measurement_area_of_rectangles_and_squares","skillId":"math_measurement","subskillId":"math_measurement_q5","subject":"math","chapter":"measurement","topic":"Area of rectangles and squares"}', 4),
  (69, 18, 'Base 12 height 4', 'text', 1, 'Half × base × height', '{"why":"Triangle area rule","sol":"Step 1: 1/2 × 12 × 4\nStep 2: 24","steps":["Step 1: 1/2 × 12 × 4","Step 2: 24"],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Area of triangles"}', 0),
  (70, 18, 'Base 14 height 6', 'text', 1, 'Use formula', '{"why":"Standard area calculation","sol":"Step 1: 1/2 × 14 × 6\nStep 2: 7 × 6\nStep 3: 42","steps":["Step 1: 1/2 × 14 × 6","Step 2: 7 × 6","Step 3: 42"],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Area of triangles"}', 1),
  (71, 18, 'Area = 40, base = 10 find height', 'text', 1, 'Rearrange formula', '{"why":"Rearranged formula","sol":"Step 1: A = 1/2 b h\nStep 2: 40 = 1/2 × 10 × h\nStep 3: 40 = 5h\nStep 4: h = 8","steps":["Step 1: A = 1/2 b h","Step 2: 40 = 1/2 × 10 × h","Step 3: 40 = 5h","Step 4: h = 8"],"options":[],"conceptId":"math_measurement_area_of_triangles","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Area of triangles"}', 2),
  (72, 19, 'Find volume of a cube with side 4', 'text', 1, 'side³', '{"why":"4 × 4 × 4 = 64, so the volume is 64 cubic units","sol":"Step 1: Identify key concept: Define the required principles for Volume of cubes and cuboids.\nStep 2: Apply governing rule: 4 × 4 × 4 = 64, so the volume is 64 cubic units\nStep 3: State the final conclusion: 64 cm³","steps":["Step 1: Identify key concept: Define the required principles for Volume of cubes and cuboids.","Step 2: Apply governing rule: 4 × 4 × 4 = 64, so the volume is 64 cubic units","Step 3: State the final conclusion: 64 cm³"],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Volume of cubes and cuboids"}', 0),
  (73, 19, 'What is the formula for cuboid volume?', 'text', 1, '3 dimensions', '{"why":"A cuboid’s volume is found by multiplying its three dimensions","sol":"Step 1: Identify key concept: Define the required principles for Volume of cubes and cuboids.\nStep 2: Apply governing rule: A cuboid’s volume is found by multiplying its three dimensions\nStep 3: State the final conclusion: length × width × height","steps":["Step 1: Identify key concept: Define the required principles for Volume of cubes and cuboids.","Step 2: Apply governing rule: A cuboid’s volume is found by multiplying its three dimensions","Step 3: State the final conclusion: length × width × height"],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Volume of cubes and cuboids"}', 1),
  (74, 19, 'What does volume measure?', 'text', 1, 'inside capacity', '{"why":"Volume tells us how much space an object can hold","sol":"Step 1: Identify key concept: Define the required principles for Volume of cubes and cuboids.\nStep 2: Apply governing rule: Volume tells us how much space an object can hold\nStep 3: State the final conclusion: Space inside a 3D shape","steps":["Step 1: Identify key concept: Define the required principles for Volume of cubes and cuboids.","Step 2: Apply governing rule: Volume tells us how much space an object can hold","Step 3: State the final conclusion: Space inside a 3D shape"],"options":[],"conceptId":"math_measurement_volume_of_cubes_and_cuboids","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Volume of cubes and cuboids"}', 2),
  (75, 20, 'Find surface area of a cube with side 5', 'text', 1, '6 × side²', '{"why":"6 × 5² = 6 × 25 = 150, so total surface area is 150 cm²","sol":"Step 1: Identify key concept: Define the required principles for Surface area basics.\nStep 2: Apply governing rule: 6 × 5² = 6 × 25 = 150, so total surface area is 150 cm²\nStep 3: State the final conclusion: 150 cm²","steps":["Step 1: Identify key concept: Define the required principles for Surface area basics.","Step 2: Apply governing rule: 6 × 5² = 6 × 25 = 150, so total surface area is 150 cm²","Step 3: State the final conclusion: 150 cm²"],"options":[],"conceptId":"math_measurement_surface_area_basics","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Surface area basics"}', 0),
  (76, 20, 'What does surface area measure?', 'text', 1, 'outside faces', '{"why":"Surface area is the total area of all outer faces of a solid","sol":"Step 1: Identify key concept: Define the required principles for Surface area basics.\nStep 2: Apply governing rule: Surface area is the total area of all outer faces of a solid\nStep 3: State the final conclusion: Outer covering of a 3D shape","steps":["Step 1: Identify key concept: Define the required principles for Surface area basics.","Step 2: Apply governing rule: Surface area is the total area of all outer faces of a solid","Step 3: State the final conclusion: Outer covering of a 3D shape"],"options":[],"conceptId":"math_measurement_surface_area_basics","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Surface area basics"}', 1),
  (77, 20, 'What is the formula for cube surface area?', 'text', 1, '6 faces', '{"why":"A cube has 6 equal square faces, so we multiply one face area by 6","sol":"Step 1: Identify key concept: Define the required principles for Surface area basics.\nStep 2: Apply governing rule: A cube has 6 equal square faces, so we multiply one face area by 6\nStep 3: State the final conclusion: 6 × side²","steps":["Step 1: Identify key concept: Define the required principles for Surface area basics.","Step 2: Apply governing rule: A cube has 6 equal square faces, so we multiply one face area by 6","Step 3: State the final conclusion: 6 × side²"],"options":[],"conceptId":"math_measurement_surface_area_basics","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Surface area basics"}', 2),
  (78, 21, 'Why is volume important in real life?', 'text', 1, 'think containers', '{"why":"Volume tells us how much space an object can hold, such as water in a tank","sol":"Step 1: Identify key concept: Define the required principles for Real life applications.\nStep 2: Apply governing rule: Volume tells us how much space an object can hold, such as water in a tank\nStep 3: State the final conclusion: It measures storage capacity","steps":["Step 1: Identify key concept: Define the required principles for Real life applications.","Step 2: Apply governing rule: Volume tells us how much space an object can hold, such as water in a tank","Step 3: State the final conclusion: It measures storage capacity"],"options":[],"conceptId":"math_measurement_real_life_applications","skillId":"math_measurement","subskillId":"math_measurement_q1","subject":"math","chapter":"measurement","topic":"Real life applications"}', 0),
  (79, 21, 'When do we use area in real life?', 'text', 1, '2D spaces', '{"why":"Area is used for surfaces like land, floors, and walls","sol":"Step 1: Identify key concept: Define the required principles for Real life applications.\nStep 2: Apply governing rule: Area is used for surfaces like land, floors, and walls\nStep 3: State the final conclusion: To measure flat surfaces","steps":["Step 1: Identify key concept: Define the required principles for Real life applications.","Step 2: Apply governing rule: Area is used for surfaces like land, floors, and walls","Step 3: State the final conclusion: To measure flat surfaces"],"options":[],"conceptId":"math_measurement_real_life_applications","skillId":"math_measurement","subskillId":"math_measurement_q2","subject":"math","chapter":"measurement","topic":"Real life applications"}', 1),
  (80, 21, 'What is the difference between area and volume?', 'text', 1, 'dimensions', '{"why":"Area measures flat surfaces, while volume measures space inside objects","sol":"Step 1: Identify key concept: Define the required principles for Real life applications.\nStep 2: Apply governing rule: Area measures flat surfaces, while volume measures space inside objects\nStep 3: State the final conclusion: Area is 2D, volume is 3D","steps":["Step 1: Identify key concept: Define the required principles for Real life applications.","Step 2: Apply governing rule: Area measures flat surfaces, while volume measures space inside objects","Step 3: State the final conclusion: Area is 2D, volume is 3D"],"options":[],"conceptId":"math_measurement_real_life_applications","skillId":"math_measurement","subskillId":"math_measurement_q3","subject":"math","chapter":"measurement","topic":"Real life applications"}', 2),
  (81, 22, 'Find the distance between points (2,3) and (6,7)', 'text', 1, 'distance formula', '{"why":"Distance between two points is found using Euclidean formula","sol":"Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)\nStep 2: Substitute values (6−2) and (7−3)\nStep 3: Compute 4² and 4²\nStep 4: Add results\nStep 5: Take square root","steps":["Step 1: Use d = √((x₂ − x₁)² + (y₂ − y₁)²)","Step 2: Substitute values (6−2) and (7−3)","Step 3: Compute 4² and 4²","Step 4: Add results","Step 5: Take square root"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 0),
  (82, 22, 'Find midpoint of (2,4) and (8,10)', 'text', 1, 'midpoint formula', '{"why":"Midpoint is average of coordinates","sol":"Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)\nStep 2: Substitute values\nStep 3: Compute x-coordinate\nStep 4: Compute y-coordinate\nStep 5: Form midpoint","steps":["Step 1: Use M = ((x₁ + x₂)/2, (y₁ + y₂)/2)","Step 2: Substitute values","Step 3: Compute x-coordinate","Step 4: Compute y-coordinate","Step 5: Form midpoint"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 1),
  (83, 22, 'Determine the coordinates after moving from (3,5) by +4 in x and −2 in y', 'text', 1, 'translation', '{"why":"Translation shifts points by vector addition","sol":"Step 1: Start at (3,5)\nStep 2: Add 4 to x-coordinate\nStep 3: Subtract 2 from y-coordinate\nStep 4: Write new coordinates","steps":["Step 1: Start at (3,5)","Step 2: Add 4 to x-coordinate","Step 3: Subtract 2 from y-coordinate","Step 4: Write new coordinates"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 2),
  (84, 22, 'Find slope between points (1,2) and (5,10)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change between two points","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute numerator 8\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute numerator 8","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 3),
  (85, 22, 'Find equation of line passing through (0,0) with slope 3', 'text', 1, 'y = mx + c', '{"why":"Line equation is determined by slope and intercept","sol":"Step 1: Use y = mx + c\nStep 2: Substitute m = 3\nStep 3: Use point (0,0) to find c\nStep 4: Solve for c\nStep 5: Write final equation","steps":["Step 1: Use y = mx + c","Step 2: Substitute m = 3","Step 3: Use point (0,0) to find c","Step 4: Solve for c","Step 5: Write final equation"],"options":[],"conceptId":"math_graphs_coordinate_plane_basics","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Coordinate plane basics"}', 4),
  (86, 23, 'Locate the point (3, -2) on a coordinate plane and describe its movement from origin', 'text', 1, 'x then y movement', '{"why":"Coordinates represent horizontal (x) and vertical (y) displacement from origin","sol":"Step 1: Start at origin (0,0)\nStep 2: Move +3 units along x-axis\nStep 3: Move −2 units along y-axis\nStep 4: Mark final position on plane","steps":["Step 1: Start at origin (0,0)","Step 2: Move +3 units along x-axis","Step 3: Move −2 units along y-axis","Step 4: Mark final position on plane"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Plotting points"}', 0),
  (87, 23, 'Find coordinates after moving 5 units right and 4 units up from origin', 'text', 1, 'directional movement', '{"why":"Positive x and y values place the point in the first quadrant","sol":"Step 1: Start at (0,0)\nStep 2: Move +5 along x-axis\nStep 3: Move +4 along y-axis\nStep 4: Plot final point","steps":["Step 1: Start at (0,0)","Step 2: Move +5 along x-axis","Step 3: Move +4 along y-axis","Step 4: Plot final point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Plotting points"}', 1),
  (88, 23, 'Determine location of point (0, -6) on coordinate plane', 'text', 1, 'axis identification', '{"why":"x = 0 means the point lies directly on the y-axis","sol":"Step 1: Check x = 0\nStep 2: Move only along y-axis\nStep 3: Locate negative direction\nStep 4: Identify axis position","steps":["Step 1: Check x = 0","Step 2: Move only along y-axis","Step 3: Locate negative direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Plotting points"}', 2),
  (89, 23, 'Determine location of point (4, 0) on coordinate plane', 'text', 1, 'axis rule', '{"why":"y = 0 means the point lies on the x-axis","sol":"Step 1: Check y = 0\nStep 2: Move only along x-axis\nStep 3: Locate positive direction\nStep 4: Identify axis position","steps":["Step 1: Check y = 0","Step 2: Move only along x-axis","Step 3: Locate positive direction","Step 4: Identify axis position"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Plotting points"}', 3),
  (90, 23, 'Identify the reference starting point for all coordinate plotting', 'text', 1, 'origin concept', '{"why":"All coordinates are measured from the origin","sol":"Step 1: Locate intersection of axes\nStep 2: Identify x = 0 and y = 0\nStep 3: Mark central reference point","steps":["Step 1: Locate intersection of axes","Step 2: Identify x = 0 and y = 0","Step 3: Mark central reference point"],"options":[],"conceptId":"math_graphs_plotting_points","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Plotting points"}', 4),
  (91, 24, 'Plot a line graph for points (1,2), (2,3), (3,5)', 'text', 1, 'coordinate plotting', '{"why":"Increasing y-values show upward trend","sol":"Step 1: Draw x-axis and y-axis\nStep 2: Plot (1,2), (2,3), (3,5)\nStep 3: Check correct positions on plane\nStep 4: Join points in order with straight lines","steps":["Step 1: Draw x-axis and y-axis","Step 2: Plot (1,2), (2,3), (3,5)","Step 3: Check correct positions on plane","Step 4: Join points in order with straight lines"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Line graphs"}', 0),
  (92, 24, 'Identify change when graph goes from (1,5) to (3,5)', 'text', 1, 'constant value', '{"why":"Equal y-values form a horizontal line","sol":"Step 1: Compare y-values at both points\nStep 2: 5 and 5 are equal\nStep 3: Determine slope behavior\nStep 4: Classify trend","steps":["Step 1: Compare y-values at both points","Step 2: 5 and 5 are equal","Step 3: Determine slope behavior","Step 4: Classify trend"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Line graphs"}', 1),
  (93, 24, 'Determine trend of points (1,4), (2,3), (3,2)', 'text', 1, 'decreasing pattern', '{"why":"Y-values reduce as x increases","sol":"Step 1: Observe y-values\nStep 2: 4 → 3 → 2\nStep 3: Check direction of change\nStep 4: Classify graph behavior","steps":["Step 1: Observe y-values","Step 2: 4 → 3 → 2","Step 3: Check direction of change","Step 4: Classify graph behavior"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Line graphs"}', 2),
  (94, 24, 'Find slope between points (1,1) and (4,7)', 'text', 1, 'rise over run', '{"why":"Slope measures rate of change in a line graph","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values\nStep 3: Compute 7 − 1 = 6\nStep 4: Compute 4 − 1 = 3\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values","Step 3: Compute 7 − 1 = 6","Step 4: Compute 4 − 1 = 3","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Line graphs"}', 3),
  (95, 24, 'Find missing point pattern if graph is linear: (1,2), (2,?), (3,6)', 'text', 1, 'linear pattern', '{"why":"Linear graphs have constant rate of change","sol":"Step 1: Observe change from 1 to 3 in x\nStep 2: Observe change from 2 to 6 in y\nStep 3: Determine pattern increase\nStep 4: Find middle value","steps":["Step 1: Observe change from 1 to 3 in x","Step 2: Observe change from 2 to 6 in y","Step 3: Determine pattern increase","Step 4: Find middle value"],"options":[],"conceptId":"math_graphs_line_graphs","skillId":"math_graphs","subskillId":"math_graphs_q5","subject":"math","chapter":"graphs","topic":"Line graphs"}', 4),
  (96, 25, 'Find gradient when rise = 12 and run = 3', 'text', 1, 'm = rise ÷ run', '{"why":"Gradient measures vertical change per unit horizontal change","sol":"Step 1: Write m = rise ÷ run\nStep 2: Substitute m = 12 ÷ 3\nStep 3: Compute division\nStep 4: Simplify result","steps":["Step 1: Write m = rise ÷ run","Step 2: Substitute m = 12 ÷ 3","Step 3: Compute division","Step 4: Simplify result"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Gradient"}', 0),
  (97, 25, 'Find gradient between points (2,5) and (6,1)', 'text', 1, 'use coordinate formula', '{"why":"Gradient is found using change in y over change in x","sol":"Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)\nStep 2: Substitute values (1 − 5)/(6 − 2)\nStep 3: Compute numerator −4\nStep 4: Compute denominator 4\nStep 5: Simplify fraction","steps":["Step 1: Use m = (y₂ − y₁)/(x₂ − x₁)","Step 2: Substitute values (1 − 5)/(6 − 2)","Step 3: Compute numerator −4","Step 4: Compute denominator 4","Step 5: Simplify fraction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Gradient"}', 1),
  (98, 25, 'Interpret gradient m = -3 in a line', 'text', 1, 'direction', '{"why":"Negative gradient shows downward movement from left to right","sol":"Step 1: Identify sign of gradient\nStep 2: m < 0 indicates negative slope\nStep 3: For each 1 step right, y decreases by 3\nStep 4: Describe direction","steps":["Step 1: Identify sign of gradient","Step 2: m < 0 indicates negative slope","Step 3: For each 1 step right, y decreases by 3","Step 4: Describe direction"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Gradient"}', 2),
  (99, 25, 'Interpret gradient m = 0', 'text', 1, 'flat line', '{"why":"Zero gradient means constant y-value across x","sol":"Step 1: Check gradient value\nStep 2: m = 0 means no vertical change\nStep 3: y-value remains constant\nStep 4: Describe graph","steps":["Step 1: Check gradient value","Step 2: m = 0 means no vertical change","Step 3: y-value remains constant","Step 4: Describe graph"],"options":[],"conceptId":"math_graphs_gradient","skillId":"math_graphs","subskillId":"math_graphs_q4","subject":"math","chapter":"graphs","topic":"Gradient"}', 3),
  (100, 26, 'Why are graphs important?', 'text', 1, 'show data visually', '{"why":"Graphs convert numerical data into visual form, making patterns and trends easier to understand","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand\nStep 3: State the final conclusion: data visualization","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs convert numerical data into visual form, making patterns and trends easier to understand","Step 3: State the final conclusion: data visualization"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q1","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 0),
  (101, 26, 'What do graphs help us identify?', 'text', 1, 'look at shape of graph', '{"why":"Graphs show how data changes over time or categories, revealing hidden patterns","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns\nStep 3: State the final conclusion: patterns and trends","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs show how data changes over time or categories, revealing hidden patterns","Step 3: State the final conclusion: patterns and trends"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q2","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 1),
  (102, 26, 'Give one real-life use of graphs', 'text', 1, 'daily applications', '{"why":"Graphs are widely used to analyze weather, sales, population, and scientific data","sol":"Step 1: Identify key concept: Define the required principles for Applications of graphs.\nStep 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data\nStep 3: State the final conclusion: weather forecasting or business analysis","steps":["Step 1: Identify key concept: Define the required principles for Applications of graphs.","Step 2: Apply governing rule: Graphs are widely used to analyze weather, sales, population, and scientific data","Step 3: State the final conclusion: weather forecasting or business analysis"],"options":[],"conceptId":"math_graphs_applications_of_graphs","skillId":"math_graphs","subskillId":"math_graphs_q3","subject":"math","chapter":"graphs","topic":"Applications of graphs"}', 2),
  (103, 27, 'Simplify the ratio 24:36', 'text', 1, 'HCF method', '{"why":"Ratios are simplified by dividing both terms by their highest common factor","sol":"Step 1: Find HCF of 24 and 36\nStep 2: HCF = 12\nStep 3: Divide both terms by 12\nStep 4: 24 ÷ 12 and 36 ÷ 12\nStep 5: Write simplified ratio","steps":["Step 1: Find HCF of 24 and 36","Step 2: HCF = 12","Step 3: Divide both terms by 12","Step 4: 24 ÷ 12 and 36 ÷ 12","Step 5: Write simplified ratio"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 0),
  (104, 27, 'Divide 60 in the ratio 2:3', 'text', 1, 'total parts method', '{"why":"Total is split according to ratio parts","sol":"Step 1: Add ratio parts 2 + 3 = 5\nStep 2: Divide 60 by 5\nStep 3: One part = 12\nStep 4: Multiply 2 × 12 and 3 × 12\nStep 5: Find each share","steps":["Step 1: Add ratio parts 2 + 3 = 5","Step 2: Divide 60 by 5","Step 3: One part = 12","Step 4: Multiply 2 × 12 and 3 × 12","Step 5: Find each share"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 1),
  (105, 27, 'Find ratio of 45 to 15 in simplest form', 'text', 1, 'divide both terms', '{"why":"Simplification reduces ratio to smallest whole numbers","sol":"Step 1: Write ratio 45:15\nStep 2: Find HCF = 15\nStep 3: Divide both terms by 15\nStep 4: Simplify result","steps":["Step 1: Write ratio 45:15","Step 2: Find HCF = 15","Step 3: Divide both terms by 15","Step 4: Simplify result"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 2),
  (106, 27, 'Check if ratios 4:6 and 2:3 are equivalent', 'text', 1, 'compare simplified forms', '{"why":"Equivalent ratios reduce to the same simplest form","sol":"Step 1: Simplify 4:6\nStep 2: Divide both by 2 → 2:3\nStep 3: Compare with 2:3\nStep 4: Conclude equivalence","steps":["Step 1: Simplify 4:6","Step 2: Divide both by 2 → 2:3","Step 3: Compare with 2:3","Step 4: Conclude equivalence"],"options":[],"conceptId":"math_ratio_ratio_basics","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Ratio basics"}', 3),
  (107, 28, 'Divide 120 in the ratio 3:2', 'text', 1, 'total parts method', '{"why":"Total is distributed proportionally using ratio parts","sol":"Step 1: Add ratio parts 3 + 2 = 5\nStep 2: Divide 120 by 5\nStep 3: One part = 24\nStep 4: Multiply 3 × 24\nStep 5: Multiply 2 × 24\nStep 6: Write final split","steps":["Step 1: Add ratio parts 3 + 2 = 5","Step 2: Divide 120 by 5","Step 3: One part = 24","Step 4: Multiply 3 × 24","Step 5: Multiply 2 × 24","Step 6: Write final split"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 0),
  (108, 28, 'Divide 250 in the ratio 5:3', 'text', 1, 'part value method', '{"why":"Each share is proportional to its ratio weight","sol":"Step 1: Add ratio parts 5 + 3 = 8\nStep 2: Divide 250 by 8\nStep 3: One part = 31.25\nStep 4: Multiply 5 × 31.25\nStep 5: Multiply 3 × 31.25\nStep 6: Write final values","steps":["Step 1: Add ratio parts 5 + 3 = 8","Step 2: Divide 250 by 8","Step 3: One part = 31.25","Step 4: Multiply 5 × 31.25","Step 5: Multiply 3 × 31.25","Step 6: Write final values"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 1),
  (109, 28, 'Check if 40:60 simplifies correctly to 2:3', 'text', 1, 'simplification check', '{"why":"Both ratios represent the same proportional relationship","sol":"Step 1: Write ratio 40:60\nStep 2: Find HCF = 20\nStep 3: Divide both terms by 20\nStep 4: Get simplified form\nStep 5: Compare with 2:3","steps":["Step 1: Write ratio 40:60","Step 2: Find HCF = 20","Step 3: Divide both terms by 20","Step 4: Get simplified form","Step 5: Compare with 2:3"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 2),
  (110, 28, 'Find value of one part if 84 is divided in ratio 2:5', 'text', 1, 'total parts method', '{"why":"Each unit of ratio is found by dividing total by sum of parts","sol":"Step 1: Add ratio parts 2 + 5 = 7\nStep 2: Divide 84 by 7\nStep 3: One part = 12\nStep 4: Use part value for distribution","steps":["Step 1: Add ratio parts 2 + 5 = 7","Step 2: Divide 84 by 7","Step 3: One part = 12","Step 4: Use part value for distribution"],"options":[],"conceptId":"math_ratio_dividing_in_ratio","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Dividing in ratio"}', 3),
  (111, 29, 'Solve for x: 6:9 = x:27', 'text', 1, 'cross multiplication', '{"why":"Cross multiplication removes ratios and forms a solvable equation","sol":"Step 1: Write proportion 6/9 = x/27\nStep 2: Cross multiply → 6 × 27 = 9x\nStep 3: Compute 162 = 9x\nStep 4: Divide both sides by 9\nStep 5: Solve for x","steps":["Step 1: Write proportion 6/9 = x/27","Step 2: Cross multiply → 6 × 27 = 9x","Step 3: Compute 162 = 9x","Step 4: Divide both sides by 9","Step 5: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Proportion"}', 0),
  (112, 29, 'Solve for x: 8:12 = 20:x', 'text', 1, 'diagonal multiplication', '{"why":"Proportions are solved by equating cross products","sol":"Step 1: Write 8/12 = 20/x\nStep 2: Cross multiply → 8x = 240\nStep 3: Divide both sides by 8\nStep 4: Solve for x","steps":["Step 1: Write 8/12 = 20/x","Step 2: Cross multiply → 8x = 240","Step 3: Divide both sides by 8","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Proportion"}', 1),
  (113, 29, 'Check if 3:5 and 12:20 form a proportion', 'text', 1, 'simplify ratio', '{"why":"Equivalent ratios form a valid proportion","sol":"Step 1: Simplify 12:20 by dividing by 4\nStep 2: Get 3:5\nStep 3: Compare both ratios\nStep 4: Confirm equality","steps":["Step 1: Simplify 12:20 by dividing by 4","Step 2: Get 3:5","Step 3: Compare both ratios","Step 4: Confirm equality"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Proportion"}', 2),
  (114, 29, 'What is the value of x in 7/ x = 14/28', 'text', 1, 'cross multiply', '{"why":"Cross multiplication converts proportion into linear equation","sol":"Step 1: Cross multiply → 7 × 28 = 14x\nStep 2: Compute 196 = 14x\nStep 3: Divide both sides by 14\nStep 4: Solve for x","steps":["Step 1: Cross multiply → 7 × 28 = 14x","Step 2: Compute 196 = 14x","Step 3: Divide both sides by 14","Step 4: Solve for x"],"options":[],"conceptId":"math_ratio_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Proportion"}', 3),
  (115, 30, 'If 6 notebooks cost 90, find the cost of 1 notebook', 'text', 1, 'unit rate', '{"why":"Unit cost is found by dividing total cost by number of items","sol":"Step 1: Write total cost = 90 and quantity = 6\nStep 2: Compute 90 ÷ 6\nStep 3: Find cost per notebook\nStep 4: State unit price","steps":["Step 1: Write total cost = 90 and quantity = 6","Step 2: Compute 90 ÷ 6","Step 3: Find cost per notebook","Step 4: State unit price"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 0),
  (116, 30, 'Find k if y = kx, when y = 36 and x = 9', 'text', 1, 'constant of proportionality', '{"why":"k represents constant ratio between y and x","sol":"Step 1: Write y = kx\nStep 2: Substitute 36 = k × 9\nStep 3: Divide both sides by 9\nStep 4: Solve for k","steps":["Step 1: Write y = kx","Step 2: Substitute 36 = k × 9","Step 3: Divide both sides by 9","Step 4: Solve for k"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 1),
  (117, 30, 'If y = 5x, find y when x = 7', 'text', 1, 'substitution', '{"why":"Direct proportion uses substitution into linear equation","sol":"Step 1: Write equation y = 5x\nStep 2: Substitute x = 7\nStep 3: Multiply 5 × 7\nStep 4: Compute y value","steps":["Step 1: Write equation y = 5x","Step 2: Substitute x = 7","Step 3: Multiply 5 × 7","Step 4: Compute y value"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 2),
  (118, 30, 'If x doubles in y = 3x, what happens to y when x changes from 4 to 8?', 'text', 1, 'scaling', '{"why":"In direct proportion, scaling x scales y by same factor","sol":"Step 1: Compute y when x = 4 → y = 3 × 4\nStep 2: Compute y when x = 8 → y = 3 × 8\nStep 3: Compare both results\nStep 4: Identify relationship","steps":["Step 1: Compute y when x = 4 → y = 3 × 4","Step 2: Compute y when x = 8 → y = 3 × 8","Step 3: Compare both results","Step 4: Identify relationship"],"options":[],"conceptId":"math_ratio_direct_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Direct proportion"}', 3),
  (119, 31, 'If y is inversely proportional to x and x = 6, y = 12, find k in x × y = k', 'text', 1, 'constant of inverse proportion', '{"why":"In inverse proportion, the product of x and y stays constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute values k = 6 × 12\nStep 3: Multiply to find k","steps":["Step 1: Write k = x × y","Step 2: Substitute values k = 6 × 12","Step 3: Multiply to find k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q1","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 0),
  (120, 31, 'If x = 9 and y = 8 in an inverse proportion, find k', 'text', 1, 'multiply values', '{"why":"Inverse proportion means x × y remains constant","sol":"Step 1: Write k = x × y\nStep 2: Substitute k = 9 × 8\nStep 3: Compute product","steps":["Step 1: Write k = x × y","Step 2: Substitute k = 9 × 8","Step 3: Compute product"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q2","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 1),
  (121, 31, 'If y is inversely proportional to x and x = 3, y = 20, find k', 'text', 1, 'constant product rule', '{"why":"The product of variables remains unchanged in inverse proportion","sol":"Step 1: Use k = x × y\nStep 2: Substitute 3 × 20\nStep 3: Calculate k","steps":["Step 1: Use k = x × y","Step 2: Substitute 3 × 20","Step 3: Calculate k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q3","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 2),
  (122, 31, 'If x = 5 and y = 14 in inverse proportion, determine k', 'text', 1, 'multiply', '{"why":"Inverse proportion keeps product of variables constant","sol":"Step 1: Write formula k = x × y\nStep 2: Substitute values 5 × 14\nStep 3: Compute result","steps":["Step 1: Write formula k = x × y","Step 2: Substitute values 5 × 14","Step 3: Compute result"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q4","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 3),
  (123, 31, 'If y is inversely proportional to x and x = 2, y = 30, find k', 'text', 1, 'constant product', '{"why":"Inverse proportion is defined by a constant product relationship","sol":"Step 1: Write k = x × y\nStep 2: Substitute 2 × 30\nStep 3: Multiply to get k","steps":["Step 1: Write k = x × y","Step 2: Substitute 2 × 30","Step 3: Multiply to get k"],"options":[],"conceptId":"math_ratio_inverse_proportion","skillId":"math_ratio","subskillId":"math_ratio_q5","subject":"math","chapter":"ratio","topic":"Inverse proportion"}', 4),
  (124, 32, 'Find frequency of 7 in data: 7, 2, 7, 5, 7, 1', 'text', 1, 'count occurrences', '{"why":"Frequency is the number of times a value appears in a dataset","sol":"Step 1: Scan the dataset\nStep 2: Identify all occurrences of 7\nStep 3: Count each appearance\nStep 4: Write total frequency","steps":["Step 1: Scan the dataset","Step 2: Identify all occurrences of 7","Step 3: Count each appearance","Step 4: Write total frequency"],"options":[],"conceptId":"math_statistics_data_frequency_tables","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Data & frequency tables"}', 0),
  (125, 32, 'Find frequency of 3 in data: 1, 3, 3, 3, 4, 5, 3', 'text', 1, 'tally method', '{"why":"Counting repeated values gives frequency","sol":"Step 1: Go through each value one by one\nStep 2: Mark every occurrence of 3\nStep 3: Count all marks\nStep 4: Record final frequency","steps":["Step 1: Go through each value one by one","Step 2: Mark every occurrence of 3","Step 3: Count all marks","Step 4: Record final frequency"],"options":[],"conceptId":"math_statistics_data_frequency_tables","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Data & frequency tables"}', 1),
  (126, 32, 'Find frequency of even numbers in: 2, 4, 5, 6, 8, 9, 2, 4', 'text', 1, 'filter then count', '{"why":"Frequency can apply to a condition, not just one value","sol":"Step 1: Identify even numbers (2, 4, 6, 8)\nStep 2: List occurrences: 2,4,6,8 in dataset\nStep 3: Count total even values\nStep 4: Compute frequency","steps":["Step 1: Identify even numbers (2, 4, 6, 8)","Step 2: List occurrences: 2,4,6,8 in dataset","Step 3: Count total even values","Step 4: Compute frequency"],"options":[],"conceptId":"math_statistics_data_frequency_tables","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Data & frequency tables"}', 2),
  (127, 32, 'What is the frequency of values greater than 5 in: 3, 6, 7, 2, 9, 5, 8', 'text', 1, 'condition-based counting', '{"why":"Frequency can measure how often a condition is satisfied in data","sol":"Step 1: Identify values greater than 5 (6, 7, 9, 8)\nStep 2: Count each occurrence\nStep 3: Total the count\nStep 4: Write final frequency","steps":["Step 1: Identify values greater than 5 (6, 7, 9, 8)","Step 2: Count each occurrence","Step 3: Total the count","Step 4: Write final frequency"],"options":[],"conceptId":"math_statistics_data_frequency_tables","skillId":"math_statistics","subskillId":"math_statistics_q4","subject":"math","chapter":"statistics","topic":"Data & frequency tables"}', 3),
  (128, 32, 'Find frequency of 10 in data: 1, 2, 3, 4, 5', 'text', 1, 'absence check', '{"why":"If a value does not appear, its frequency is zero","sol":"Step 1: Scan dataset for 10\nStep 2: Confirm if it appears\nStep 3: Count occurrences\nStep 4: Record result","steps":["Step 1: Scan dataset for 10","Step 2: Confirm if it appears","Step 3: Count occurrences","Step 4: Record result"],"options":[],"conceptId":"math_statistics_data_frequency_tables","skillId":"math_statistics","subskillId":"math_statistics_q5","subject":"math","chapter":"statistics","topic":"Data & frequency tables"}', 4),
  (129, 33, 'Find mean of 5, 7, 9, 3', 'text', 1, 'sum ÷ number of values', '{"why":"Mean is total sum divided by number of values","sol":"Step 1: Add all values 5 + 7 + 9 + 3\nStep 2: Compute total sum = 24\nStep 3: Count number of values = 4\nStep 4: Divide 24 ÷ 4\nStep 5: Write final mean","steps":["Step 1: Add all values 5 + 7 + 9 + 3","Step 2: Compute total sum = 24","Step 3: Count number of values = 4","Step 4: Divide 24 ÷ 4","Step 5: Write final mean"],"options":[],"conceptId":"math_statistics_mean","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Mean"}', 0),
  (130, 33, 'Find mean of 12, 15, 9, 24', 'text', 1, 'average calculation', '{"why":"Mean balances all values into a single representative number","sol":"Step 1: Add values 12 + 15 + 9 + 24\nStep 2: Compute sum = 60\nStep 3: Count values = 4\nStep 4: Divide 60 ÷ 4\nStep 5: Get mean","steps":["Step 1: Add values 12 + 15 + 9 + 24","Step 2: Compute sum = 60","Step 3: Count values = 4","Step 4: Divide 60 ÷ 4","Step 5: Get mean"],"options":[],"conceptId":"math_statistics_mean","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Mean"}', 1),
  (131, 33, 'A dataset has values 10, 10, 10, 50. Find the mean and explain effect of outlier', 'text', 1, 'outlier impact', '{"why":"A single large value increases the mean significantly","sol":"Step 1: Add values 10 + 10 + 10 + 50\nStep 2: Compute sum = 80\nStep 3: Divide by 4 values\nStep 4: Mean = 20\nStep 5: Compare with typical value 10","steps":["Step 1: Add values 10 + 10 + 10 + 50","Step 2: Compute sum = 80","Step 3: Divide by 4 values","Step 4: Mean = 20","Step 5: Compare with typical value 10"],"options":[],"conceptId":"math_statistics_mean","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Mean"}', 2),
  (132, 33, 'If mean of 4 numbers is 8, what is their total sum?', 'text', 1, 'reverse formula', '{"why":"Rearranging mean formula gives total sum directly","sol":"Step 1: Use formula mean = sum ÷ n\nStep 2: Rearrange sum = mean × n\nStep 3: Substitute sum = 8 × 4\nStep 4: Compute result","steps":["Step 1: Use formula mean = sum ÷ n","Step 2: Rearrange sum = mean × n","Step 3: Substitute sum = 8 × 4","Step 4: Compute result"],"options":[],"conceptId":"math_statistics_mean","skillId":"math_statistics","subskillId":"math_statistics_q4","subject":"math","chapter":"statistics","topic":"Mean"}', 3),
  (133, 33, 'Find mean of 2, 4, 6, 8, 10', 'text', 1, 'arithmetic mean', '{"why":"Mean represents central value of a balanced dataset","sol":"Step 1: Add all values\nStep 2: 2 + 4 + 6 + 8 + 10 = 30\nStep 3: Count values = 5\nStep 4: Divide 30 ÷ 5\nStep 5: Final answer","steps":["Step 1: Add all values","Step 2: 2 + 4 + 6 + 8 + 10 = 30","Step 3: Count values = 5","Step 4: Divide 30 ÷ 5","Step 5: Final answer"],"options":[],"conceptId":"math_statistics_mean","skillId":"math_statistics","subskillId":"math_statistics_q5","subject":"math","chapter":"statistics","topic":"Mean"}', 4),
  (134, 34, 'Find the median of 7, 3, 12, 5, 9', 'text', 1, 'sort first', '{"why":"Median is the central value of an ordered dataset","sol":"Step 1: Arrange numbers in ascending order\nStep 2: 3, 5, 7, 9, 12\nStep 3: Identify middle position\nStep 4: Pick the middle value","steps":["Step 1: Arrange numbers in ascending order","Step 2: 3, 5, 7, 9, 12","Step 3: Identify middle position","Step 4: Pick the middle value"],"options":[],"conceptId":"math_statistics_median","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Median"}', 0),
  (135, 34, 'Find the median of 4, 8, 2, 10, 6, 12', 'text', 1, 'even number of values', '{"why":"Even datasets use the mean of two middle values","sol":"Step 1: Arrange in order\nStep 2: 2, 4, 6, 8, 10, 12\nStep 3: Identify two middle values\nStep 4: Take average of 6 and 8\nStep 5: Compute result","steps":["Step 1: Arrange in order","Step 2: 2, 4, 6, 8, 10, 12","Step 3: Identify two middle values","Step 4: Take average of 6 and 8","Step 5: Compute result"],"options":[],"conceptId":"math_statistics_median","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Median"}', 1),
  (136, 34, 'Find median of 15, 3, 9, 21, 11', 'text', 1, 'ordering method', '{"why":"Median is the middle number after ordering","sol":"Step 1: Sort values\nStep 2: 3, 9, 11, 15, 21\nStep 3: Locate central value\nStep 4: Select median","steps":["Step 1: Sort values","Step 2: 3, 9, 11, 15, 21","Step 3: Locate central value","Step 4: Select median"],"options":[],"conceptId":"math_statistics_median","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Median"}', 2),
  (137, 34, 'Find median of 1, 2, 3, 4', 'text', 1, 'two middle numbers', '{"why":"Median of even dataset is average of middle values","sol":"Step 1: Arrange in order\nStep 2: Identify middle values 2 and 3\nStep 3: Add 2 + 3 = 5\nStep 4: Divide by 2\nStep 5: Compute median","steps":["Step 1: Arrange in order","Step 2: Identify middle values 2 and 3","Step 3: Add 2 + 3 = 5","Step 4: Divide by 2","Step 5: Compute median"],"options":[],"conceptId":"math_statistics_median","skillId":"math_statistics","subskillId":"math_statistics_q4","subject":"math","chapter":"statistics","topic":"Median"}', 3),
  (138, 35, 'Find the mode of 6, 3, 6, 2, 6, 3', 'text', 1, 'count frequency', '{"why":"Mode is the value that appears most frequently","sol":"Step 1: List each value in the dataset\nStep 2: Count occurrences of each number\nStep 3: 6 appears 3 times, 3 appears 2 times, 2 appears 1 time\nStep 4: Identify highest frequency\nStep 5: Select value with highest count","steps":["Step 1: List each value in the dataset","Step 2: Count occurrences of each number","Step 3: 6 appears 3 times, 3 appears 2 times, 2 appears 1 time","Step 4: Identify highest frequency","Step 5: Select value with highest count"],"options":[],"conceptId":"math_statistics_mode","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Mode"}', 0),
  (139, 35, 'Find the mode of 5, 1, 5, 2, 2, 3', 'text', 1, 'multiple highest frequencies', '{"why":"A dataset can have more than one mode if frequencies are equal","sol":"Step 1: Count frequency of each value\nStep 2: 5 appears 2 times, 2 appears 2 times\nStep 3: Identify highest frequency\nStep 4: List all values with same highest count","steps":["Step 1: Count frequency of each value","Step 2: 5 appears 2 times, 2 appears 2 times","Step 3: Identify highest frequency","Step 4: List all values with same highest count"],"options":[],"conceptId":"math_statistics_mode","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Mode"}', 1),
  (140, 35, 'Find mode of 8, 9, 10, 11', 'text', 1, 'no repetition', '{"why":"If all values occur only once, there is no mode","sol":"Step 1: Count frequency of each value\nStep 2: Check if any value repeats\nStep 3: Compare frequencies\nStep 4: Determine mode","steps":["Step 1: Count frequency of each value","Step 2: Check if any value repeats","Step 3: Compare frequencies","Step 4: Determine mode"],"options":[],"conceptId":"math_statistics_mode","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Mode"}', 2),
  (141, 35, 'Find mode of 12, 12, 15, 15, 18, 18', 'text', 1, 'equal frequency', '{"why":"All values share the same highest frequency","sol":"Step 1: Count occurrences\nStep 2: 12 = 2 times, 15 = 2 times, 18 = 2 times\nStep 3: Identify highest frequency\nStep 4: List all modes","steps":["Step 1: Count occurrences","Step 2: 12 = 2 times, 15 = 2 times, 18 = 2 times","Step 3: Identify highest frequency","Step 4: List all modes"],"options":[],"conceptId":"math_statistics_mode","skillId":"math_statistics","subskillId":"math_statistics_q4","subject":"math","chapter":"statistics","topic":"Mode"}', 3),
  (142, 36, 'In a dataset: Apples = 5, Mangoes = 9, Bananas = 3, Grapes = 7. Which category has the highest value?', 'text', 1, 'compare values', '{"why":"Bar graphs represent data using height, so the largest value has the tallest bar","sol":"Step 1: List all values\nStep 2: Apples = 5, Mangoes = 9, Bananas = 3, Grapes = 7\nStep 3: Compare magnitudes\nStep 4: Identify the largest value","steps":["Step 1: List all values","Step 2: Apples = 5, Mangoes = 9, Bananas = 3, Grapes = 7","Step 3: Compare magnitudes","Step 4: Identify the largest value"],"options":[],"conceptId":"math_statistics_bar_graphs","skillId":"math_statistics","subskillId":"math_statistics_q1","subject":"math","chapter":"statistics","topic":"Bar graphs"}', 0),
  (143, 36, 'In a bar chart, values are 2, 6, 4, 10. Find the difference between highest and lowest bars', 'text', 1, 'range', '{"why":"Difference between bar heights shows range of data","sol":"Step 1: Identify highest value = 10\nStep 2: Identify lowest value = 2\nStep 3: Subtract 10 − 2\nStep 4: Compute result","steps":["Step 1: Identify highest value = 10","Step 2: Identify lowest value = 2","Step 3: Subtract 10 − 2","Step 4: Compute result"],"options":[],"conceptId":"math_statistics_bar_graphs","skillId":"math_statistics","subskillId":"math_statistics_q2","subject":"math","chapter":"statistics","topic":"Bar graphs"}', 1),
  (144, 36, 'If a bar represents 12 units and another represents 5 units, how many more units does the first represent?', 'text', 1, 'subtraction', '{"why":"Bar comparison uses difference in heights","sol":"Step 1: Identify values 12 and 5\nStep 2: Subtract 12 − 5\nStep 3: Compute difference\nStep 4: Interpret result","steps":["Step 1: Identify values 12 and 5","Step 2: Subtract 12 − 5","Step 3: Compute difference","Step 4: Interpret result"],"options":[],"conceptId":"math_statistics_bar_graphs","skillId":"math_statistics","subskillId":"math_statistics_q3","subject":"math","chapter":"statistics","topic":"Bar graphs"}', 2),
  (145, 36, 'If total value in a bar chart is 40 and one category is 15, what is the remaining total?', 'text', 1, 'total minus part', '{"why":"Bar charts can represent parts of a whole using subtraction","sol":"Step 1: Identify total = 40\nStep 2: Identify part = 15\nStep 3: Subtract 40 − 15\nStep 4: Compute remaining value","steps":["Step 1: Identify total = 40","Step 2: Identify part = 15","Step 3: Subtract 40 − 15","Step 4: Compute remaining value"],"options":[],"conceptId":"math_statistics_bar_graphs","skillId":"math_statistics","subskillId":"math_statistics_q4","subject":"math","chapter":"statistics","topic":"Bar graphs"}', 3),
  (146, 36, 'Which statement is true about bar graphs?', 'text', 1, 'representation', '{"why":"Bar graphs convert numbers into visual lengths for comparison","sol":"Step 1: Understand bar height meaning\nStep 2: Compare different categories\nStep 3: Interpret visual data","steps":["Step 1: Understand bar height meaning","Step 2: Compare different categories","Step 3: Interpret visual data"],"options":[],"conceptId":"math_statistics_bar_graphs","skillId":"math_statistics","subskillId":"math_statistics_q5","subject":"math","chapter":"statistics","topic":"Bar graphs"}', 4),
  (147, 37, 'A bag contains 5 red balls and 3 blue balls. What is the probability of picking a blue ball?', 'text', 1, 'favorable ÷ total', '{"why":"Probability is calculated as favorable outcomes divided by total outcomes","sol":"Step 1: Identify total number of balls = 5 + 3 = 8\nStep 2: Identify favorable outcomes (blue balls) = 3\nStep 3: Write probability formula P = favorable / total\nStep 4: Substitute P = 3 / 8\nStep 5: Simplify if possible","steps":["Step 1: Identify total number of balls = 5 + 3 = 8","Step 2: Identify favorable outcomes (blue balls) = 3","Step 3: Write probability formula P = favorable / total","Step 4: Substitute P = 3 / 8","Step 5: Simplify if possible"],"options":[],"conceptId":"math_probability_basic_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Basic probability"}', 0),
  (148, 37, 'A bag has 6 red balls and 4 blue balls. What is the probability of NOT picking red?', 'text', 1, 'complement rule', '{"why":"Not picking red means selecting from all non-red outcomes","sol":"Step 1: Find total balls = 6 + 4 = 10\nStep 2: Identify non-red outcomes = blue balls = 4\nStep 3: Write probability P = favorable / total\nStep 4: Substitute P = 4 / 10\nStep 5: Simplify fraction","steps":["Step 1: Find total balls = 6 + 4 = 10","Step 2: Identify non-red outcomes = blue balls = 4","Step 3: Write probability P = favorable / total","Step 4: Substitute P = 4 / 10","Step 5: Simplify fraction"],"options":[],"conceptId":"math_probability_basic_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Basic probability"}', 1),
  (149, 37, 'A fair dice is rolled. What is the probability of getting an even number?', 'text', 1, 'count favorable outcomes', '{"why":"Probability depends on ratio of favorable to total outcomes","sol":"Step 1: List sample space = {1,2,3,4,5,6}\nStep 2: Identify even numbers = {2,4,6}\nStep 3: Count favorable outcomes = 3\nStep 4: Count total outcomes = 6\nStep 5: Compute probability = 3/6","steps":["Step 1: List sample space = {1,2,3,4,5,6}","Step 2: Identify even numbers = {2,4,6}","Step 3: Count favorable outcomes = 3","Step 4: Count total outcomes = 6","Step 5: Compute probability = 3/6"],"options":[],"conceptId":"math_probability_basic_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Basic probability"}', 2),
  (150, 37, 'What is the probability of getting a number greater than 4 on a fair dice?', 'text', 1, 'sample space filtering', '{"why":"Probability is favorable outcomes divided by total outcomes","sol":"Step 1: List outcomes = {1,2,3,4,5,6}\nStep 2: Identify numbers > 4 = {5,6}\nStep 3: Count favorable outcomes = 2\nStep 4: Total outcomes = 6\nStep 5: Write probability = 2/6","steps":["Step 1: List outcomes = {1,2,3,4,5,6}","Step 2: Identify numbers > 4 = {5,6}","Step 3: Count favorable outcomes = 2","Step 4: Total outcomes = 6","Step 5: Write probability = 2/6"],"options":[],"conceptId":"math_probability_basic_probability","skillId":"math_probability","subskillId":"math_probability_q4","subject":"math","chapter":"probability","topic":"Basic probability"}', 3),
  (151, 37, 'What is the probability range of any event?', 'text', 1, 'limits', '{"why":"Probability values always lie between impossible (0) and certain (1)","sol":"Step 1: Identify impossible event = 0\nStep 2: Identify certain event = 1\nStep 3: Understand probability scale\nStep 4: Define range","steps":["Step 1: Identify impossible event = 0","Step 2: Identify certain event = 1","Step 3: Understand probability scale","Step 4: Define range"],"options":[],"conceptId":"math_probability_basic_probability","skillId":"math_probability","subskillId":"math_probability_q5","subject":"math","chapter":"probability","topic":"Basic probability"}', 4),
  (152, 38, 'A fair die is rolled. What is the probability of getting a number less than 4?', 'text', 1, 'filter outcomes', '{"why":"Probability is favorable outcomes divided by total outcomes","sol":"Step 1: Write sample space S = {1,2,3,4,5,6}\nStep 2: Identify outcomes < 4 = {1,2,3}\nStep 3: Count favorable outcomes = 3\nStep 4: Total outcomes = 6\nStep 5: Compute probability = 3/6\nStep 6: Simplify fraction","steps":["Step 1: Write sample space S = {1,2,3,4,5,6}","Step 2: Identify outcomes < 4 = {1,2,3}","Step 3: Count favorable outcomes = 3","Step 4: Total outcomes = 6","Step 5: Compute probability = 3/6","Step 6: Simplify fraction"],"options":[],"conceptId":"math_probability_dice_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Dice probability"}', 0),
  (153, 38, 'A fair die is rolled. What is the probability of getting an even number?', 'text', 1, 'even numbers', '{"why":"Even numbers are half of all outcomes on a fair die","sol":"Step 1: Write sample space S = {1,2,3,4,5,6}\nStep 2: Identify even outcomes = {2,4,6}\nStep 3: Count favorable outcomes = 3\nStep 4: Total outcomes = 6\nStep 5: Compute probability = 3/6\nStep 6: Simplify fraction","steps":["Step 1: Write sample space S = {1,2,3,4,5,6}","Step 2: Identify even outcomes = {2,4,6}","Step 3: Count favorable outcomes = 3","Step 4: Total outcomes = 6","Step 5: Compute probability = 3/6","Step 6: Simplify fraction"],"options":[],"conceptId":"math_probability_dice_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Dice probability"}', 1),
  (154, 38, 'A fair die is rolled. What is the probability of getting a multiple of 3?', 'text', 1, 'multiples', '{"why":"Probability is based on count of favorable outcomes over total outcomes","sol":"Step 1: Write sample space S = {1,2,3,4,5,6}\nStep 2: Identify multiples of 3 = {3,6}\nStep 3: Count favorable outcomes = 2\nStep 4: Total outcomes = 6\nStep 5: Compute probability = 2/6\nStep 6: Simplify fraction","steps":["Step 1: Write sample space S = {1,2,3,4,5,6}","Step 2: Identify multiples of 3 = {3,6}","Step 3: Count favorable outcomes = 2","Step 4: Total outcomes = 6","Step 5: Compute probability = 2/6","Step 6: Simplify fraction"],"options":[],"conceptId":"math_probability_dice_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Dice probability"}', 2),
  (155, 38, 'A fair die is rolled. What is the probability of getting a number that is not a prime?', 'text', 1, 'complement', '{"why":"Non-prime outcomes are the complement of prime outcomes","sol":"Step 1: Write sample space S = {1,2,3,4,5,6}\nStep 2: Identify primes = {2,3,5}\nStep 3: Identify non-primes = {1,4,6}\nStep 4: Count favorable outcomes = 3\nStep 5: Total outcomes = 6\nStep 6: Compute probability = 3/6\nStep 7: Simplify fraction","steps":["Step 1: Write sample space S = {1,2,3,4,5,6}","Step 2: Identify primes = {2,3,5}","Step 3: Identify non-primes = {1,4,6}","Step 4: Count favorable outcomes = 3","Step 5: Total outcomes = 6","Step 6: Compute probability = 3/6","Step 7: Simplify fraction"],"options":[],"conceptId":"math_probability_dice_probability","skillId":"math_probability","subskillId":"math_probability_q4","subject":"math","chapter":"probability","topic":"Dice probability"}', 3),
  (156, 38, 'A fair die is rolled. What is the probability of getting 6?', 'text', 1, 'single outcome', '{"why":"Single outcomes have probability 1 over total sample space","sol":"Step 1: Write sample space S = {1,2,3,4,5,6}\nStep 2: Identify favorable outcome = {6}\nStep 3: Count favorable outcomes = 1\nStep 4: Total outcomes = 6\nStep 5: Compute probability = 1/6","steps":["Step 1: Write sample space S = {1,2,3,4,5,6}","Step 2: Identify favorable outcome = {6}","Step 3: Count favorable outcomes = 1","Step 4: Total outcomes = 6","Step 5: Compute probability = 1/6"],"options":[],"conceptId":"math_probability_dice_probability","skillId":"math_probability","subskillId":"math_probability_q5","subject":"math","chapter":"probability","topic":"Dice probability"}', 4),
  (157, 39, 'A coin is tossed once. Find the probability of getting a head', 'text', 1, 'equally likely outcomes', '{"why":"Probability is favorable outcomes divided by total equally likely outcomes","sol":"Step 1: Write sample space S = {H, T}\nStep 2: Identify favorable outcome = {H}\nStep 3: Count favorable outcomes = 1\nStep 4: Count total outcomes = 2\nStep 5: Compute probability = 1/2","steps":["Step 1: Write sample space S = {H, T}","Step 2: Identify favorable outcome = {H}","Step 3: Count favorable outcomes = 1","Step 4: Count total outcomes = 2","Step 5: Compute probability = 1/2"],"options":[],"conceptId":"math_probability_coin_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Coin probability"}', 0),
  (158, 39, 'A coin is tossed twice. Find the probability of getting two heads', 'text', 1, 'independent events', '{"why":"Independent events multiply probabilities: 1/2 × 1/2","sol":"Step 1: List sample space = {HH, HT, TH, TT}\nStep 2: Identify favorable outcome = {HH}\nStep 3: Count favorable outcomes = 1\nStep 4: Count total outcomes = 4\nStep 5: Compute probability = 1/4","steps":["Step 1: List sample space = {HH, HT, TH, TT}","Step 2: Identify favorable outcome = {HH}","Step 3: Count favorable outcomes = 1","Step 4: Count total outcomes = 4","Step 5: Compute probability = 1/4"],"options":[],"conceptId":"math_probability_coin_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Coin probability"}', 1),
  (159, 39, 'A coin is tossed twice. Find the probability of getting exactly one head', 'text', 1, 'favorable outcomes', '{"why":"Exactly one head occurs in two of the four equally likely outcomes","sol":"Step 1: List sample space = {HH, HT, TH, TT}\nStep 2: Identify outcomes with one head = {HT, TH}\nStep 3: Count favorable outcomes = 2\nStep 4: Count total outcomes = 4\nStep 5: Compute probability = 2/4\nStep 6: Simplify fraction","steps":["Step 1: List sample space = {HH, HT, TH, TT}","Step 2: Identify outcomes with one head = {HT, TH}","Step 3: Count favorable outcomes = 2","Step 4: Count total outcomes = 4","Step 5: Compute probability = 2/4","Step 6: Simplify fraction"],"options":[],"conceptId":"math_probability_coin_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Coin probability"}', 2),
  (160, 39, 'What is the probability of getting at least one tail in two coin tosses?', 'text', 1, 'complement method', '{"why":"Complement rule simplifies probability of complex events","sol":"Step 1: List sample space = {HH, HT, TH, TT}\nStep 2: Identify complement event = no tails = {HH}\nStep 3: Compute P(no tail) = 1/4\nStep 4: Use complement rule 1 − P(no tail)\nStep 5: Calculate 1 − 1/4","steps":["Step 1: List sample space = {HH, HT, TH, TT}","Step 2: Identify complement event = no tails = {HH}","Step 3: Compute P(no tail) = 1/4","Step 4: Use complement rule 1 − P(no tail)","Step 5: Calculate 1 − 1/4"],"options":[],"conceptId":"math_probability_coin_probability","skillId":"math_probability","subskillId":"math_probability_q4","subject":"math","chapter":"probability","topic":"Coin probability"}', 3),
  (161, 39, 'Why is probability of head in a fair coin 1/2?', 'text', 1, 'symmetry', '{"why":"A fair coin has symmetric outcomes with equal probability","sol":"Step 1: Identify outcomes = {H, T}\nStep 2: Check fairness (equal likelihood)\nStep 3: Assign equal probability to each outcome\nStep 4: Divide 1 outcome by 2 total outcomes","steps":["Step 1: Identify outcomes = {H, T}","Step 2: Check fairness (equal likelihood)","Step 3: Assign equal probability to each outcome","Step 4: Divide 1 outcome by 2 total outcomes"],"options":[],"conceptId":"math_probability_coin_probability","skillId":"math_probability","subskillId":"math_probability_q5","subject":"math","chapter":"probability","topic":"Coin probability"}', 4),
  (162, 40, 'A coin is tossed and a die is rolled. Find P(tail and 3)', 'text', 1, 'independent events multiply', '{"why":"Coin toss and die roll are independent events","sol":"Step 1: P(tail) = 1/2\nStep 2: P(3 on die) = 1/6\nStep 3: Multiply 1/2 × 1/6\nStep 4: Compute result = 1/12","steps":["Step 1: P(tail) = 1/2","Step 2: P(3 on die) = 1/6","Step 3: Multiply 1/2 × 1/6","Step 4: Compute result = 1/12"],"options":[],"conceptId":"math_probability_combined_events","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Combined events"}', 0),
  (163, 40, 'A coin is tossed and a die is rolled. Find P(head and even number)', 'text', 1, 'find even probability first', '{"why":"Independent events are multiplied","sol":"Step 1: P(head) = 1/2\nStep 2: Even numbers = {2,4,6} so P(even) = 3/6 = 1/2\nStep 3: Multiply 1/2 × 1/2\nStep 4: Compute result = 1/4","steps":["Step 1: P(head) = 1/2","Step 2: Even numbers = {2,4,6} so P(even) = 3/6 = 1/2","Step 3: Multiply 1/2 × 1/2","Step 4: Compute result = 1/4"],"options":[],"conceptId":"math_probability_combined_events","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Combined events"}', 1),
  (164, 40, 'A coin is tossed and a die is rolled. Find P(head and number greater than 4)', 'text', 1, 'identify sample space', '{"why":"Each event is independent so probabilities multiply","sol":"Step 1: P(head) = 1/2\nStep 2: Numbers > 4 = {5,6} so P = 2/6 = 1/3\nStep 3: Multiply 1/2 × 1/3\nStep 4: Compute result = 1/6","steps":["Step 1: P(head) = 1/2","Step 2: Numbers > 4 = {5,6} so P = 2/6 = 1/3","Step 3: Multiply 1/2 × 1/3","Step 4: Compute result = 1/6"],"options":[],"conceptId":"math_probability_combined_events","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Combined events"}', 2),
  (165, 40, 'A coin is tossed twice. Find P(head on first toss and tail on second toss)', 'text', 1, 'list outcomes', '{"why":"Each coin toss is independent","sol":"Step 1: P(head) = 1/2\nStep 2: P(tail) = 1/2\nStep 3: Multiply 1/2 × 1/2\nStep 4: Compute result = 1/4","steps":["Step 1: P(head) = 1/2","Step 2: P(tail) = 1/2","Step 3: Multiply 1/2 × 1/2","Step 4: Compute result = 1/4"],"options":[],"conceptId":"math_probability_combined_events","skillId":"math_probability","subskillId":"math_probability_q4","subject":"math","chapter":"probability","topic":"Combined events"}', 3),
  (166, 40, 'A coin is tossed and a die is rolled. Find P(tail and prime number)', 'text', 1, 'prime numbers on a die', '{"why":"Both events are independent","sol":"Step 1: P(tail) = 1/2\nStep 2: Prime numbers = {2,3,5} so P = 3/6 = 1/2\nStep 3: Multiply 1/2 × 1/2\nStep 4: Compute result = 1/4","steps":["Step 1: P(tail) = 1/2","Step 2: Prime numbers = {2,3,5} so P = 3/6 = 1/2","Step 3: Multiply 1/2 × 1/2","Step 4: Compute result = 1/4"],"options":[],"conceptId":"math_probability_combined_events","skillId":"math_probability","subskillId":"math_probability_q5","subject":"math","chapter":"probability","topic":"Combined events"}', 4),
  (167, 40, 'A coin is tossed and a die is rolled. Find P(head and not 6)', 'text', 1, 'complement on die', '{"why":"Independent events multiply probabilities","sol":"Step 1: P(head) = 1/2\nStep 2: P(not 6) = 5/6\nStep 3: Multiply 1/2 × 5/6\nStep 4: Compute result = 5/12","steps":["Step 1: P(head) = 1/2","Step 2: P(not 6) = 5/6","Step 3: Multiply 1/2 × 5/6","Step 4: Compute result = 5/12"],"options":[],"conceptId":"math_probability_combined_events","skillId":"math_probability","subskillId":"math_probability_q6","subject":"math","chapter":"probability","topic":"Combined events"}', 5),
  (168, 41, 'A disease affects 1% of a population. A test has 90% accuracy for detecting the disease when it is present. What is P(Disease ∩ Positive)?', 'text', 1, 'use multiplication rule', '{"why":"Joint probability combines prior probability with likelihood of evidence","sol":"Step 1: P(Disease) = 0.01\nStep 2: P(Positive | Disease) = 0.90\nStep 3: Apply Bayes building block: P(A ∩ B) = P(A) × P(B|A)\nStep 4: Multiply 0.01 × 0.90\nStep 5: Compute result = 0.009","steps":["Step 1: P(Disease) = 0.01","Step 2: P(Positive | Disease) = 0.90","Step 3: Apply Bayes building block: P(A ∩ B) = P(A) × P(B|A)","Step 4: Multiply 0.01 × 0.90","Step 5: Compute result = 0.009"],"options":[],"conceptId":"math_probability_bayes_theorem","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Bayes Theorem"}', 0),
  (169, 41, 'A test detects a condition with probability 0.8 if the condition is present. If 5% of people have the condition, find P(Condition ∩ Positive)', 'text', 1, 'joint probability', '{"why":"Bayes framework starts with prior probability then updates using evidence likelihood","sol":"Step 1: P(C) = 0.05\nStep 2: P(P+ | C) = 0.8\nStep 3: Multiply P(C) × P(P+ | C)\nStep 4: 0.05 × 0.8\nStep 5: Compute result = 0.04","steps":["Step 1: P(C) = 0.05","Step 2: P(P+ | C) = 0.8","Step 3: Multiply P(C) × P(P+ | C)","Step 4: 0.05 × 0.8","Step 5: Compute result = 0.04"],"options":[],"conceptId":"math_probability_bayes_theorem","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Bayes Theorem"}', 1),
  (170, 41, 'In a system, 2% of items are defective. A detector correctly flags defective items 95% of the time. Find probability of defective AND flagged', 'text', 1, 'conditional probability', '{"why":"We combine prior defect rate with detection accuracy","sol":"Step 1: P(D) = 0.02\nStep 2: P(Flag | D) = 0.95\nStep 3: Multiply 0.02 × 0.95\nStep 4: Compute result = 0.019","steps":["Step 1: P(D) = 0.02","Step 2: P(Flag | D) = 0.95","Step 3: Multiply 0.02 × 0.95","Step 4: Compute result = 0.019"],"options":[],"conceptId":"math_probability_bayes_theorem","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Bayes Theorem"}', 2),
  (171, 41, 'A rare condition occurs in 1 out of 200 people. A test detects it with 98% accuracy. Find P(Condition ∩ Positive)', 'text', 1, 'convert fraction to probability', '{"why":"Rare prior probability is updated using strong evidence likelihood","sol":"Step 1: P(C) = 1/200 = 0.005\nStep 2: P(Pos | C) = 0.98\nStep 3: Multiply 0.005 × 0.98\nStep 4: Compute result = 0.0049","steps":["Step 1: P(C) = 1/200 = 0.005","Step 2: P(Pos | C) = 0.98","Step 3: Multiply 0.005 × 0.98","Step 4: Compute result = 0.0049"],"options":[],"conceptId":"math_probability_bayes_theorem","skillId":"math_probability","subskillId":"math_probability_q4","subject":"math","chapter":"probability","topic":"Bayes Theorem"}', 3),
  (172, 41, 'A spam filter correctly identifies spam emails 85% of the time. If 30% of emails are spam, find P(Spam ∩ Detected)', 'text', 1, 'multiply probability and accuracy', '{"why":"Bayes reasoning combines base rate with detection likelihood","sol":"Step 1: P(Spam) = 0.30\nStep 2: P(Detected | Spam) = 0.85\nStep 3: Multiply 0.30 × 0.85\nStep 4: Compute result = 0.255","steps":["Step 1: P(Spam) = 0.30","Step 2: P(Detected | Spam) = 0.85","Step 3: Multiply 0.30 × 0.85","Step 4: Compute result = 0.255"],"options":[],"conceptId":"math_probability_bayes_theorem","skillId":"math_probability","subskillId":"math_probability_q5","subject":"math","chapter":"probability","topic":"Bayes Theorem"}', 4),
  (173, 42, 'A game gives you 10 if you win with probability 0.3 and 0 if you lose with probability 0.7. Find the expected value', 'text', 1, 'use E(X) = Σ xP(x)', '{"why":"Expected value is the weighted average of all possible outcomes","sol":"Step 1: List outcomes: win = 10, lose = 0\nStep 2: Assign probabilities: P(win)=0.3, P(lose)=0.7\nStep 3: Multiply outcomes: 10 × 0.3 = 3\nStep 4: Multiply loss outcome: 0 × 0.7 = 0\nStep 5: Add results: 3 + 0","steps":["Step 1: List outcomes: win = 10, lose = 0","Step 2: Assign probabilities: P(win)=0.3, P(lose)=0.7","Step 3: Multiply outcomes: 10 × 0.3 = 3","Step 4: Multiply loss outcome: 0 × 0.7 = 0","Step 5: Add results: 3 + 0"],"options":[],"conceptId":"math_probability_expected_value","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Expected Value"}', 0),
  (174, 42, 'A dice game pays 6 when you roll a 6 and 0 otherwise. Find expected value', 'text', 1, 'probability of 6 is 1/6', '{"why":"Expected value combines all outcomes weighted by probability","sol":"Step 1: Outcome 6 pays 6, probability = 1/6\nStep 2: All other outcomes pay 0, probability = 5/6\nStep 3: Compute 6 × 1/6 = 1\nStep 4: Compute 0 × 5/6 = 0\nStep 5: Add results = 1","steps":["Step 1: Outcome 6 pays 6, probability = 1/6","Step 2: All other outcomes pay 0, probability = 5/6","Step 3: Compute 6 × 1/6 = 1","Step 4: Compute 0 × 5/6 = 0","Step 5: Add results = 1"],"options":[],"conceptId":"math_probability_expected_value","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Expected Value"}', 1),
  (175, 42, 'A lottery gives 100 with probability 0.05 and 0 otherwise. Find expected value', 'text', 1, 'weighted mean', '{"why":"Expected value represents long-term average winnings","sol":"Step 1: Identify outcomes: 100 and 0\nStep 2: Assign probabilities: 0.05 and 0.95\nStep 3: Compute 100 × 0.05 = 5\nStep 4: Compute 0 × 0.95 = 0\nStep 5: Add results","steps":["Step 1: Identify outcomes: 100 and 0","Step 2: Assign probabilities: 0.05 and 0.95","Step 3: Compute 100 × 0.05 = 5","Step 4: Compute 0 × 0.95 = 0","Step 5: Add results"],"options":[],"conceptId":"math_probability_expected_value","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Expected Value"}', 2),
  (176, 43, 'What does probability measure?', 'text', 1, 'chance', '{"why":"Probability tells how likely something is to occur, from 0 (impossible) to 1 (certain)","sol":"Step 1: Identify key concept: Define the required principles for Real life probability.\nStep 2: Apply governing rule: Probability tells how likely something is to occur, from 0 (impossible) to 1 (certain)\nStep 3: State the final conclusion: likelihood of an event happening","steps":["Step 1: Identify key concept: Define the required principles for Real life probability.","Step 2: Apply governing rule: Probability tells how likely something is to occur, from 0 (impossible) to 1 (certain)","Step 3: State the final conclusion: likelihood of an event happening"],"options":[],"conceptId":"math_probability_real_life_probability","skillId":"math_probability","subskillId":"math_probability_q1","subject":"math","chapter":"probability","topic":"Real life probability"}', 0),
  (177, 43, 'What does 0.7 probability mean?', 'text', 1, 'convert to percentage', '{"why":"0.7 means 70 out of 100 chances the event will happen","sol":"Step 1: Identify key concept: Define the required principles for Real life probability.\nStep 2: Apply governing rule: 0.7 means 70 out of 100 chances the event will happen\nStep 3: State the final conclusion: 70% chance of occurrence","steps":["Step 1: Identify key concept: Define the required principles for Real life probability.","Step 2: Apply governing rule: 0.7 means 70 out of 100 chances the event will happen","Step 3: State the final conclusion: 70% chance of occurrence"],"options":[],"conceptId":"math_probability_real_life_probability","skillId":"math_probability","subskillId":"math_probability_q2","subject":"math","chapter":"probability","topic":"Real life probability"}', 1),
  (178, 43, 'Where is probability used in real life?', 'text', 1, 'prediction systems', '{"why":"It helps model uncertainty in real-world decisions","sol":"Step 1: Identify key concept: Define the required principles for Real life probability.\nStep 2: Apply governing rule: It helps model uncertainty in real-world decisions\nStep 3: State the final conclusion: weather, insurance, sports, business","steps":["Step 1: Identify key concept: Define the required principles for Real life probability.","Step 2: Apply governing rule: It helps model uncertainty in real-world decisions","Step 3: State the final conclusion: weather, insurance, sports, business"],"options":[],"conceptId":"math_probability_real_life_probability","skillId":"math_probability","subskillId":"math_probability_q3","subject":"math","chapter":"probability","topic":"Real life probability"}', 2),
  (179, 43, 'What does probability close to 1 mean?', 'text', 1, 'almost certain', '{"why":"Values near 1 indicate high chance of happening","sol":"Step 1: Identify key concept: Define the required principles for Real life probability.\nStep 2: Apply governing rule: Values near 1 indicate high chance of happening\nStep 3: State the final conclusion: very likely event","steps":["Step 1: Identify key concept: Define the required principles for Real life probability.","Step 2: Apply governing rule: Values near 1 indicate high chance of happening","Step 3: State the final conclusion: very likely event"],"options":[],"conceptId":"math_probability_real_life_probability","skillId":"math_probability","subskillId":"math_probability_q4","subject":"math","chapter":"probability","topic":"Real life probability"}', 3),
  (180, 43, 'What does probability close to 0 mean?', 'text', 1, 'rare event', '{"why":"Values near 0 indicate low chance of happening","sol":"Step 1: Identify key concept: Define the required principles for Real life probability.\nStep 2: Apply governing rule: Values near 0 indicate low chance of happening\nStep 3: State the final conclusion: very unlikely event","steps":["Step 1: Identify key concept: Define the required principles for Real life probability.","Step 2: Apply governing rule: Values near 0 indicate low chance of happening","Step 3: State the final conclusion: very unlikely event"],"options":[],"conceptId":"math_probability_real_life_probability","skillId":"math_probability","subskillId":"math_probability_q5","subject":"math","chapter":"probability","topic":"Real life probability"}', 4),
  (181, 44, 'What is i defined as?', 'text', 1, 'square root', '{"why":"It extends the number system beyond real numbers","sol":"Step 1: The imaginary unit i satisfies i² = -1\nStep 2: Therefore i = √(-1)","steps":["Step 1: The imaginary unit i satisfies i² = -1","Step 2: Therefore i = √(-1)"],"options":[],"conceptId":"math_complex_numbers_imaginary_unit_and_basic_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q1","subject":"math","chapter":"complex_numbers","topic":"Imaginary Unit and Basic Complex Numbers"}', 0),
  (182, 44, 'Find real and imaginary parts of 5 + 3i', 'text', 1, 'separate terms', '{"why":"Complex number a + bi splits into real part a and imaginary part bi","sol":"Step 1: Real part = 5\nStep 2: Imaginary part = 3i\nStep 3: Combine as 5 + 3i","steps":["Step 1: Real part = 5","Step 2: Imaginary part = 3i","Step 3: Combine as 5 + 3i"],"options":[],"conceptId":"math_complex_numbers_imaginary_unit_and_basic_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q2","subject":"math","chapter":"complex_numbers","topic":"Imaginary Unit and Basic Complex Numbers"}', 1),
  (183, 44, 'Simplify 2i + 4i', 'text', 1, 'combine like terms', '{"why":"Imaginary terms combine by adding coefficients, yielding 6i","sol":"Step 1: Combine like terms: 2i + 4i\nStep 2: Add coefficients: 2 + 4 = 6\nStep 3: Result = 6i","steps":["Step 1: Combine like terms: 2i + 4i","Step 2: Add coefficients: 2 + 4 = 6","Step 3: Result = 6i"],"options":[],"conceptId":"math_complex_numbers_imaginary_unit_and_basic_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q3","subject":"math","chapter":"complex_numbers","topic":"Imaginary Unit and Basic Complex Numbers"}', 2),
  (184, 44, 'What type of number is a + bi?', 'text', 1, 'name of system', '{"why":"A complex number combines a real part (a) and an imaginary part (bi) into a single number of the form a + bi.","sol":"Step 1: Identify the form a + bi\nStep 2: Recognize that a is the real part and bi is the imaginary part\nStep 3: Any number of the form a + bi belongs to the complex number system\nStep 4: Therefore, a + bi is a complex number","steps":["Step 1: Identify the form a + bi","Step 2: Recognize that a is the real part and bi is the imaginary part","Step 3: Any number of the form a + bi belongs to the complex number system","Step 4: Therefore, a + bi is a complex number"],"options":[],"conceptId":"math_complex_numbers_imaginary_unit_and_basic_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q4","subject":"math","chapter":"complex_numbers","topic":"Imaginary Unit and Basic Complex Numbers"}', 3),
  (185, 44, 'What happens when i² is calculated?', 'text', 1, 'negative result', '{"why":"The imaginary unit i is defined so that i² = -1. This is the fundamental property of complex numbers.","sol":"Step 1: Define the imaginary unit: i = √(-1)\nStep 2: Square both sides: i² = (√(-1))²\nStep 3: Simplify the square and square root: (√(-1))² = -1\nStep 4: Therefore, i² = -1","steps":["Step 1: Define the imaginary unit: i = √(-1)","Step 2: Square both sides: i² = (√(-1))²","Step 3: Simplify the square and square root: (√(-1))² = -1","Step 4: Therefore, i² = -1"],"options":[],"conceptId":"math_complex_numbers_imaginary_unit_and_basic_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q5","subject":"math","chapter":"complex_numbers","topic":"Imaginary Unit and Basic Complex Numbers"}', 4),
  (186, 45, 'What axis represents the imaginary part?', 'text', 1, 'vertical axis', '{"why":"In z = a + bi, b maps to the y-axis (vertical), a maps to the x-axis (horizontal)","sol":"Step 1: In z = a + bi, the imaginary part is b\nStep 2: On the Argand plane, b is plotted on the vertical axis\nStep 3: ∴ Imaginary part → y-axis","steps":["Step 1: In z = a + bi, the imaginary part is b","Step 2: On the Argand plane, b is plotted on the vertical axis","Step 3: ∴ Imaginary part → y-axis"],"options":[],"conceptId":"math_complex_numbers_argand_diagram_complex_plane","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q1","subject":"math","chapter":"complex_numbers","topic":"Argand Diagram (Complex Plane)"}', 0),
  (187, 45, 'Plot z = 2 + 5i as a point', 'text', 1, 'real then imaginary', '{"why":"z = a + bi maps to the coordinate (a, b), so 2 + 5i → (2, 5)","sol":"Step 1: z = 2 + 5i → a = 2, b = 5\nStep 2: Plot (a, b) = (2, 5) on the Argand plane\nStep 3: ∴ z = 2 + 5i → point (2, 5)","steps":["Step 1: z = 2 + 5i → a = 2, b = 5","Step 2: Plot (a, b) = (2, 5) on the Argand plane","Step 3: ∴ z = 2 + 5i → point (2, 5)"],"options":[],"conceptId":"math_complex_numbers_argand_diagram_complex_plane","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q2","subject":"math","chapter":"complex_numbers","topic":"Argand Diagram (Complex Plane)"}', 1),
  (188, 45, 'What does z = a + bi represent on the Argand plane?', 'text', 1, 'coordinate system', '{"why":"Every complex number z = a + bi corresponds to a unique point (a, b) on the 2D Argand plane","sol":"Step 1: z = a + bi → real part = a, imaginary part = b\nStep 2: Map a to x-axis, b to y-axis\nStep 3: ∴ z = a + bi ↔ point (a, b) in 2D","steps":["Step 1: z = a + bi → real part = a, imaginary part = b","Step 2: Map a to x-axis, b to y-axis","Step 3: ∴ z = a + bi ↔ point (a, b) in 2D"],"options":[],"conceptId":"math_complex_numbers_argand_diagram_complex_plane","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q3","subject":"math","chapter":"complex_numbers","topic":"Argand Diagram (Complex Plane)"}', 2),
  (189, 45, 'Where is the real part plotted?', 'text', 1, 'horizontal axis', '{"why":"In z = a + bi, a maps to the x-axis (horizontal), just like the x-coordinate in Cartesian geometry","sol":"Step 1: In z = a + bi, the real part is a\nStep 2: On the Argand plane, a is measured along the horizontal axis\nStep 3: ∴ Real part → x-axis","steps":["Step 1: In z = a + bi, the real part is a","Step 2: On the Argand plane, a is measured along the horizontal axis","Step 3: ∴ Real part → x-axis"],"options":[],"conceptId":"math_complex_numbers_argand_diagram_complex_plane","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q4","subject":"math","chapter":"complex_numbers","topic":"Argand Diagram (Complex Plane)"}', 3),
  (190, 45, 'What is the point for z = -3 + 2i?', 'text', 1, 'negative real', '{"why":"Negative real moves left, positive imaginary moves up","sol":"Step 1: Real = -3 (left)\nStep 2: Imaginary = 2 (up)\nStep 3: Coordinate = (-3, 2)","steps":["Step 1: Real = -3 (left)","Step 2: Imaginary = 2 (up)","Step 3: Coordinate = (-3, 2)"],"options":[],"conceptId":"math_complex_numbers_argand_diagram_complex_plane","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q5","subject":"math","chapter":"complex_numbers","topic":"Argand Diagram (Complex Plane)"}', 4),
  (191, 45, 'Why is Argand diagram useful?', 'text', 1, 'visual representation', '{"why":"Mapping z = a + bi to (a, b) lets us visualize addition as vector sums and multiplication as rotation + scaling","sol":"Step 1: z = a + bi is algebraic → hard to visualize\nStep 2: Argand plane maps z → point (a, b) in 2D\nStep 3: Operations like addition become vector addition on the plane\nStep 4: ∴ The diagram turns algebra into geometry","steps":["Step 1: z = a + bi is algebraic → hard to visualize","Step 2: Argand plane maps z → point (a, b) in 2D","Step 3: Operations like addition become vector addition on the plane","Step 4: ∴ The diagram turns algebra into geometry"],"options":[],"conceptId":"math_complex_numbers_argand_diagram_complex_plane","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q6","subject":"math","chapter":"complex_numbers","topic":"Argand Diagram (Complex Plane)"}', 5),
  (192, 46, 'What is i² equal to?', 'text', 1, 'definition of i', '{"why":"i = √(−1), so i² = (√(−1))² = −1. This is the foundational identity of complex numbers.","sol":"Step 1: By definition, i = √(−1)\nStep 2: Square both sides: i² = (√(−1))²\nStep 3: (√(−1))² = −1\nStep 4: ∴ i² = −1","steps":["Step 1: By definition, i = √(−1)","Step 2: Square both sides: i² = (√(−1))²","Step 3: (√(−1))² = −1","Step 4: ∴ i² = −1"],"options":[],"conceptId":"math_complex_numbers_operations_on_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q1","subject":"math","chapter":"complex_numbers","topic":"Operations on Complex Numbers"}', 0),
  (193, 46, 'Simplify i² + 5', 'text', 1, 'replace i²', '{"why":"i² = −1 by definition, so i² + 5 = −1 + 5 = 4","sol":"Step 1: i² + 5\nStep 2: Replace i² with −1: (−1) + 5\nStep 3: −1 + 5 = 4","steps":["Step 1: i² + 5","Step 2: Replace i² with −1: (−1) + 5","Step 3: −1 + 5 = 4"],"options":[],"conceptId":"math_complex_numbers_operations_on_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q2","subject":"math","chapter":"complex_numbers","topic":"Operations on Complex Numbers"}', 1),
  (194, 46, 'Multiply (1 + i)(1 + i)', 'text', 1, 'FOIL method', '{"why":"FOIL: (1+i)(1+i) = 1 + 2i + i² = 1 + 2i − 1 = 2i","sol":"Step 1: (1 + i)(1 + i) → use FOIL\nStep 2: First: 1×1 = 1\nStep 3: Outer: 1×i = i\nStep 4: Inner: i×1 = i\nStep 5: Last: i×i = i² = −1\nStep 6: Combine: 1 + i + i + (−1) = 1 + 2i − 1\nStep 7: = 2i","steps":["Step 1: (1 + i)(1 + i) → use FOIL","Step 2: First: 1×1 = 1","Step 3: Outer: 1×i = i","Step 4: Inner: i×1 = i","Step 5: Last: i×i = i² = −1","Step 6: Combine: 1 + i + i + (−1) = 1 + 2i − 1","Step 7: = 2i"],"options":[],"conceptId":"math_complex_numbers_operations_on_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q3","subject":"math","chapter":"complex_numbers","topic":"Operations on Complex Numbers"}', 2),
  (195, 46, 'Find (3 + 2i) + (1 + 4i)', 'text', 1, 'add like terms', '{"why":"(a + bi) + (c + di) = (a+c) + (b+d)i, so (3+1) + (2+4)i = 4 + 6i","sol":"Step 1: (3 + 2i) + (1 + 4i)\nStep 2: Group real parts: 3 + 1 = 4\nStep 3: Group imaginary parts: 2i + 4i = 6i\nStep 4: ∴ (3 + 2i) + (1 + 4i) = 4 + 6i","steps":["Step 1: (3 + 2i) + (1 + 4i)","Step 2: Group real parts: 3 + 1 = 4","Step 3: Group imaginary parts: 2i + 4i = 6i","Step 4: ∴ (3 + 2i) + (1 + 4i) = 4 + 6i"],"options":[],"conceptId":"math_complex_numbers_operations_on_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q4","subject":"math","chapter":"complex_numbers","topic":"Operations on Complex Numbers"}', 3),
  (196, 46, 'Why do we replace i² with -1?', 'text', 1, 'definition', '{"why":"i = √(−1) ∴ i² = −1. Replacing i² converts imaginary expressions into real numbers.","sol":"Step 1: The imaginary unit is defined as i = √(−1)\nStep 2: Squaring: i² = (√(−1))² = −1\nStep 3: So whenever i² appears, substitute −1\nStep 4: This converts imaginary terms into real terms for simplification","steps":["Step 1: The imaginary unit is defined as i = √(−1)","Step 2: Squaring: i² = (√(−1))² = −1","Step 3: So whenever i² appears, substitute −1","Step 4: This converts imaginary terms into real terms for simplification"],"options":[],"conceptId":"math_complex_numbers_operations_on_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q5","subject":"math","chapter":"complex_numbers","topic":"Operations on Complex Numbers"}', 4),
  (197, 46, 'What method is used for multiplying complex numbers?', 'text', 1, 'FOIL', '{"why":"FOIL expands (a+bi)(c+di) = (ac−bd) + (ad+bc)i, then i² = −1 simplifies the result","sol":"Step 1: (a + bi)(c + di) → expand using FOIL\nStep 2: = ac + adi + bci + bdi²\nStep 3: Replace i² = −1: = ac + adi + bci − bd\nStep 4: Group: = (ac − bd) + (ad + bc)i","steps":["Step 1: (a + bi)(c + di) → expand using FOIL","Step 2: = ac + adi + bci + bdi²","Step 3: Replace i² = −1: = ac + adi + bci − bd","Step 4: Group: = (ac − bd) + (ad + bc)i"],"options":[],"conceptId":"math_complex_numbers_operations_on_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q6","subject":"math","chapter":"complex_numbers","topic":"Operations on Complex Numbers"}', 5),
  (198, 47, 'What does r represent in polar form?', 'text', 1, 'distance from origin', '{"why":"r = √(a² + b²) gives the distance from origin to (a,b), i.e. the modulus |z|","sol":"Step 1: z = r(cosθ + i sinθ), where r = √(a² + b²)\nStep 2: r is the distance from the origin (0,0) to the point (a, b)\nStep 3: ∴ r = |z| = magnitude of z","steps":["Step 1: z = r(cosθ + i sinθ), where r = √(a² + b²)","Step 2: r is the distance from the origin (0,0) to the point (a, b)","Step 3: ∴ r = |z| = magnitude of z"],"options":[],"conceptId":"math_complex_numbers_polar_form_of_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q1","subject":"math","chapter":"complex_numbers","topic":"Polar Form of Complex Numbers"}', 0),
  (199, 47, 'What does θ represent in polar form?', 'text', 1, 'angle', '{"why":"θ = tan⁻¹(b/a) measures the direction from the positive x-axis to the vector (a, b)","sol":"Step 1: z = r(cosθ + i sinθ)\nStep 2: θ = tan⁻¹(b/a), the angle from the positive real axis\nStep 3: ∴ θ = argument of z = direction of z in the complex plane","steps":["Step 1: z = r(cosθ + i sinθ)","Step 2: θ = tan⁻¹(b/a), the angle from the positive real axis","Step 3: ∴ θ = argument of z = direction of z in the complex plane"],"options":[],"conceptId":"math_complex_numbers_polar_form_of_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q2","subject":"math","chapter":"complex_numbers","topic":"Polar Form of Complex Numbers"}', 1),
  (200, 47, 'Convert (3,4) into polar form: find r', 'text', 1, 'use Pythagoras', '{"why":"r = √(3² + 4²) = √(9+16) = √25 = 5 (Pythagorean theorem)","sol":"Step 1: r = √(a² + b²) = √(3² + 4²)\nStep 2: = √(9 + 16) = √25\nStep 3: r = 5","steps":["Step 1: r = √(a² + b²) = √(3² + 4²)","Step 2: = √(9 + 16) = √25","Step 3: r = 5"],"options":[],"conceptId":"math_complex_numbers_polar_form_of_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q3","subject":"math","chapter":"complex_numbers","topic":"Polar Form of Complex Numbers"}', 2),
  (201, 47, 'Why is polar form useful?', 'text', 1, 'simplifies operations', '{"why":"z₁·z₂ = r₁r₂ cis(θ₁+θ₂): just multiply |z| and add angles, no FOIL needed","sol":"Step 1: In Cartesian form, (a+bi)(c+di) requires FOIL expansion\nStep 2: In polar form: z₁·z₂ = r₁r₂ [cos(θ₁+θ₂) + i sin(θ₁+θ₂)]\nStep 3: Multiplication becomes: multiply magnitudes, add angles\nStep 4: ∴ Polar form simplifies multiplication and division of complex numbers","steps":["Step 1: In Cartesian form, (a+bi)(c+di) requires FOIL expansion","Step 2: In polar form: z₁·z₂ = r₁r₂ [cos(θ₁+θ₂) + i sin(θ₁+θ₂)]","Step 3: Multiplication becomes: multiply magnitudes, add angles","Step 4: ∴ Polar form simplifies multiplication and division of complex numbers"],"options":[],"conceptId":"math_complex_numbers_polar_form_of_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q4","subject":"math","chapter":"complex_numbers","topic":"Polar Form of Complex Numbers"}', 3),
  (202, 47, 'What is the general polar form of a complex number?', 'text', 1, 'formula', '{"why":"z = a + bi converts to z = r(cosθ + i sinθ) where r = |z| and θ = arg(z)","sol":"Step 1: For z = a + bi, compute r = √(a² + b²)\nStep 2: Compute θ = tan⁻¹(b/a)\nStep 3: Write z = r(cosθ + i sinθ)\nStep 4: Also written as z = r cis(θ)","steps":["Step 1: For z = a + bi, compute r = √(a² + b²)","Step 2: Compute θ = tan⁻¹(b/a)","Step 3: Write z = r(cosθ + i sinθ)","Step 4: Also written as z = r cis(θ)"],"options":[],"conceptId":"math_complex_numbers_polar_form_of_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q5","subject":"math","chapter":"complex_numbers","topic":"Polar Form of Complex Numbers"}', 4),
  (203, 47, 'What is the first step when converting to polar form?', 'text', 1, 'distance', '{"why":"r = √(a² + b²) must be calculated first because it defines the magnitude before the angle","sol":"Step 1: Given z = a + bi, first find r = √(a² + b²)\nStep 2: Then find θ = tan⁻¹(b/a)\nStep 3: Assemble: z = r(cosθ + i sinθ)","steps":["Step 1: Given z = a + bi, first find r = √(a² + b²)","Step 2: Then find θ = tan⁻¹(b/a)","Step 3: Assemble: z = r(cosθ + i sinθ)"],"options":[],"conceptId":"math_complex_numbers_polar_form_of_complex_numbers","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q6","subject":"math","chapter":"complex_numbers","topic":"Polar Form of Complex Numbers"}', 5),
  (204, 48, 'What happens to angle in De Moivre’s theorem?', 'text', 1, 'power effect', '{"why":"(cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ) → the angle becomes n×θ","sol":"Step 1: De Moivre’s theorem: (cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ)\nStep 2: The angle θ is multiplied by the exponent n\nStep 3: ∴ New angle = nθ","steps":["Step 1: De Moivre’s theorem: (cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ)","Step 2: The angle θ is multiplied by the exponent n","Step 3: ∴ New angle = nθ"],"options":[],"conceptId":"math_complex_numbers_de_moivre_s_theorem","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q1","subject":"math","chapter":"complex_numbers","topic":"De Moivre’s Theorem"}', 0),
  (205, 48, 'Evaluate (cos45° + i sin45°)^2', 'text', 1, 'use De Moivre’s theorem', '{"why":"(cos45° + i sin45°)² = cos(90°) + i sin(90°) = 0 + i = i","sol":"Step 1: Apply (cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ)\nStep 2: n = 2, θ = 45° → nθ = 2 × 45° = 90°\nStep 3: = cos90° + i sin90°\nStep 4: cos90° = 0, sin90° = 1\nStep 5: = 0 + i(1) = i","steps":["Step 1: Apply (cosθ + i sinθ)ⁿ = cos(nθ) + i sin(nθ)","Step 2: n = 2, θ = 45° → nθ = 2 × 45° = 90°","Step 3: = cos90° + i sin90°","Step 4: cos90° = 0, sin90° = 1","Step 5: = 0 + i(1) = i"],"options":[],"conceptId":"math_complex_numbers_de_moivre_s_theorem","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q2","subject":"math","chapter":"complex_numbers","topic":"De Moivre’s Theorem"}', 1),
  (206, 48, 'What does De Moivre’s theorem represent?', 'text', 1, 'geometry meaning', '{"why":"zⁿ = cos(nθ) + i sin(nθ): each power rotates the point n times around the unit circle","sol":"Step 1: z = cosθ + i sinθ is a point on the unit circle at angle θ\nStep 2: zⁿ = cos(nθ) + i sin(nθ) moves to angle nθ\nStep 3: ∴ Raising to power n rotates the point by n×θ on the unit circle","steps":["Step 1: z = cosθ + i sinθ is a point on the unit circle at angle θ","Step 2: zⁿ = cos(nθ) + i sin(nθ) moves to angle nθ","Step 3: ∴ Raising to power n rotates the point by n×θ on the unit circle"],"options":[],"conceptId":"math_complex_numbers_de_moivre_s_theorem","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q3","subject":"math","chapter":"complex_numbers","topic":"De Moivre’s Theorem"}', 2),
  (207, 48, 'What is the effect of raising a complex number to a power?', 'text', 1, 'think angle', '{"why":"zⁿ = rⁿ cis(nθ): magnitude → rⁿ, angle → n×θ","sol":"Step 1: Let z = r(cosθ + i sinθ)\nStep 2: zⁿ = rⁿ(cos(nθ) + i sin(nθ))\nStep 3: Magnitude becomes rⁿ, angle becomes nθ\nStep 4: ∴ Power n multiplies the angle by n and raises magnitude to n","steps":["Step 1: Let z = r(cosθ + i sinθ)","Step 2: zⁿ = rⁿ(cos(nθ) + i sin(nθ))","Step 3: Magnitude becomes rⁿ, angle becomes nθ","Step 4: ∴ Power n multiplies the angle by n and raises magnitude to n"],"options":[],"conceptId":"math_complex_numbers_de_moivre_s_theorem","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q4","subject":"math","chapter":"complex_numbers","topic":"De Moivre’s Theorem"}', 3),
  (208, 48, 'Evaluate (cos60° + i sin60°)^3', 'text', 1, 'multiply angle', '{"why":"(cos60° + i sin60°)³ = cos180° + i sin180° = −1 + 0i = −1","sol":"Step 1: Apply De Moivre’s: (cosθ + i sinθ)³ = cos(3θ) + i sin(3θ)\nStep 2: θ = 60° → 3 × 60° = 180°\nStep 3: = cos180° + i sin180°\nStep 4: cos180° = −1, sin180° = 0\nStep 5: = −1 + i(0) = −1","steps":["Step 1: Apply De Moivre’s: (cosθ + i sinθ)³ = cos(3θ) + i sin(3θ)","Step 2: θ = 60° → 3 × 60° = 180°","Step 3: = cos180° + i sin180°","Step 4: cos180° = −1, sin180° = 0","Step 5: = −1 + i(0) = −1"],"options":[],"conceptId":"math_complex_numbers_de_moivre_s_theorem","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q5","subject":"math","chapter":"complex_numbers","topic":"De Moivre’s Theorem"}', 4),
  (209, 48, 'Why is De Moivre''s theorem useful?', 'text', 1, 'It makes powers easier.', '{"why":"Instead of multiplying a complex number many times, De Moivre''s theorem uses a simple formula.","sol":"Step 1: Finding zⁿ by repeated multiplication is long and difficult.\nStep 2: De Moivre''s theorem gives zⁿ = rⁿ(cos nθ + i sin nθ).\nStep 3: Multiply only the angle by n.\nStep 4: This saves time and reduces calculations.","steps":["Step 1: Finding zⁿ by repeated multiplication is long and difficult.","Step 2: De Moivre''s theorem gives zⁿ = rⁿ(cos nθ + i sin nθ).","Step 3: Multiply only the angle by n.","Step 4: This saves time and reduces calculations."],"options":[],"conceptId":"math_complex_numbers_de_moivre_s_theorem","skillId":"math_complex_numbers","subskillId":"math_complex_numbers_q6","subject":"math","chapter":"complex_numbers","topic":"De Moivre’s Theorem"}', 5),
  (210, 49, 'Maximize Z = 3x + 2y subject to x + y ≤ 10, x ≥ 0, y ≥ 0', 'text', 1, 'corner point method', '{"why":"Linear programming solutions occur at vertices of feasible region","sol":"Step 1: Identify constraints x + y ≤ 10, x ≥ 0, y ≥ 0\nStep 2: Find corner points of feasible region\nStep 3: Corner points are (0,0), (10,0), (0,10)\nStep 4: Evaluate Z at each point\nStep 5: Compute Z(0,0), Z(10,0), Z(0,10)","steps":["Step 1: Identify constraints x + y ≤ 10, x ≥ 0, y ≥ 0","Step 2: Find corner points of feasible region","Step 3: Corner points are (0,0), (10,0), (0,10)","Step 4: Evaluate Z at each point","Step 5: Compute Z(0,0), Z(10,0), Z(0,10)"],"options":[],"conceptId":"math_linear_programming_introduction_to_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Introduction to Linear Programming"}', 0),
  (211, 49, 'Maximize Z = 5x + 4y subject to x + 2y ≤ 8, x ≥ 0, y ≥ 0', 'text', 1, 'substitute corner points', '{"why":"Maximum occurs at feasible region vertex","sol":"Step 1: Find intercepts of x + 2y = 8\nStep 2: Set x = 0 → y = 4\nStep 3: Set y = 0 → x = 8\nStep 4: Corner points are (0,0), (8,0), (0,4)\nStep 5: Evaluate Z at each point","steps":["Step 1: Find intercepts of x + 2y = 8","Step 2: Set x = 0 → y = 4","Step 3: Set y = 0 → x = 8","Step 4: Corner points are (0,0), (8,0), (0,4)","Step 5: Evaluate Z at each point"],"options":[],"conceptId":"math_linear_programming_introduction_to_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Introduction to Linear Programming"}', 1),
  (212, 49, 'Minimize C = 2x + 3y subject to x + y ≥ 6, x ≥ 0, y ≥ 0', 'text', 1, 'corner evaluation', '{"why":"Minimum occurs at boundary vertex","sol":"Step 1: Convert boundary x + y = 6\nStep 2: Find intercepts (6,0) and (0,6)\nStep 3: Identify feasible corner points\nStep 4: Evaluate C at (6,0) and (0,6)","steps":["Step 1: Convert boundary x + y = 6","Step 2: Find intercepts (6,0) and (0,6)","Step 3: Identify feasible corner points","Step 4: Evaluate C at (6,0) and (0,6)"],"options":[],"conceptId":"math_linear_programming_introduction_to_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Introduction to Linear Programming"}', 2),
  (213, 49, 'Find feasible region corner points for x + y ≤ 5, x ≥ 0, y ≥ 0', 'text', 1, 'graph intercepts', '{"why":"Feasible region is bounded by axes and constraint line","sol":"Step 1: Set x + y = 5\nStep 2: Find x-intercept (5,0)\nStep 3: Find y-intercept (0,5)\nStep 4: Include origin (0,0)\nStep 5: List all vertices","steps":["Step 1: Set x + y = 5","Step 2: Find x-intercept (5,0)","Step 3: Find y-intercept (0,5)","Step 4: Include origin (0,0)","Step 5: List all vertices"],"options":[],"conceptId":"math_linear_programming_introduction_to_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q4","subject":"math","chapter":"linear_programming","topic":"Introduction to Linear Programming"}', 3),
  (214, 49, 'Evaluate Z = 4x + y at feasible region vertices (0,0), (3,2), (5,0)', 'text', 1, 'substitution method', '{"why":"Optimal solution occurs at vertex with highest value","sol":"Step 1: Substitute (0,0) into Z\nStep 2: Substitute (3,2) into Z\nStep 3: Substitute (5,0) into Z\nStep 4: Compare all results","steps":["Step 1: Substitute (0,0) into Z","Step 2: Substitute (3,2) into Z","Step 3: Substitute (5,0) into Z","Step 4: Compare all results"],"options":[],"conceptId":"math_linear_programming_introduction_to_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q5","subject":"math","chapter":"linear_programming","topic":"Introduction to Linear Programming"}', 4),
  (215, 50, 'Evaluate Z = 3x + 2y at corner points of x + y ≤ 6, x ≥ 0, y ≥ 0', 'text', 1, 'vertex evaluation', '{"why":"Maximum occurs at a vertex of feasible region","sol":"Step 1: Convert x + y ≤ 6 into x + y = 6\nStep 2: Find intercepts (6,0) and (0,6)\nStep 3: Include origin (0,0)\nStep 4: Evaluate Z at (0,0), (6,0), (0,6)\nStep 5: Compute Z values","steps":["Step 1: Convert x + y ≤ 6 into x + y = 6","Step 2: Find intercepts (6,0) and (0,6)","Step 3: Include origin (0,0)","Step 4: Evaluate Z at (0,0), (6,0), (0,6)","Step 5: Compute Z values"],"options":[],"conceptId":"math_linear_programming_graphical_method","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Graphical Method"}', 0),
  (216, 50, 'Find boundary line equation for x + y ≤ 5', 'text', 1, 'convert inequality', '{"why":"Boundary is formed by equality case of inequality","sol":"Step 1: Replace ≤ with =\nStep 2: Write equation x + y = 5\nStep 3: Find intercepts (5,0) and (0,5)\nStep 4: Plot straight line","steps":["Step 1: Replace ≤ with =","Step 2: Write equation x + y = 5","Step 3: Find intercepts (5,0) and (0,5)","Step 4: Plot straight line"],"options":[],"conceptId":"math_linear_programming_graphical_method","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Graphical Method"}', 1),
  (217, 50, 'Find feasible region for x ≥ 0 and y ≥ 0 in coordinate plane', 'text', 1, 'quadrant identification', '{"why":"Only points with both coordinates non-negative satisfy conditions","sol":"Step 1: Set x ≥ 0 (right half-plane)\nStep 2: Set y ≥ 0 (upper half-plane)\nStep 3: Intersect both regions\nStep 4: Identify common region","steps":["Step 1: Set x ≥ 0 (right half-plane)","Step 2: Set y ≥ 0 (upper half-plane)","Step 3: Intersect both regions","Step 4: Identify common region"],"options":[],"conceptId":"math_linear_programming_graphical_method","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Graphical Method"}', 2),
  (218, 50, 'Test whether point (0,0) satisfies x + y ≤ 4, 2x + y ≤ 6', 'text', 1, 'substitution check', '{"why":"Point lies inside feasible region","sol":"Step 1: Substitute x = 0, y = 0 into x + y ≤ 4\nStep 2: Verify 0 ≤ 4\nStep 3: Substitute into 2x + y ≤ 6\nStep 4: Verify 0 ≤ 6\nStep 5: Confirm validity","steps":["Step 1: Substitute x = 0, y = 0 into x + y ≤ 4","Step 2: Verify 0 ≤ 4","Step 3: Substitute into 2x + y ≤ 6","Step 4: Verify 0 ≤ 6","Step 5: Confirm validity"],"options":[],"conceptId":"math_linear_programming_graphical_method","skillId":"math_linear_programming","subskillId":"math_linear_programming_q4","subject":"math","chapter":"linear_programming","topic":"Graphical Method"}', 3),
  (219, 50, 'Evaluate Z = 2x + 3y at (0,0), (4,0), (0,4)', 'text', 1, 'corner substitution', '{"why":"Optimal solution occurs at highest vertex value","sol":"Step 1: Compute Z(0,0)\nStep 2: Compute Z(4,0)\nStep 3: Compute Z(0,4)\nStep 4: Compare all values","steps":["Step 1: Compute Z(0,0)","Step 2: Compute Z(4,0)","Step 3: Compute Z(0,4)","Step 4: Compare all values"],"options":[],"conceptId":"math_linear_programming_graphical_method","skillId":"math_linear_programming","subskillId":"math_linear_programming_q5","subject":"math","chapter":"linear_programming","topic":"Graphical Method"}', 4),
  (220, 51, 'Find intercepts and boundary points for x + y ≤ 5', 'text', 1, 'set variables to zero', '{"why":"Boundary line is defined by its intercepts","sol":"Step 1: Convert inequality to equation x + y = 5\nStep 2: Set x = 0 → y = 5\nStep 3: Set y = 0 → x = 5\nStep 4: Write intercept points","steps":["Step 1: Convert inequality to equation x + y = 5","Step 2: Set x = 0 → y = 5","Step 3: Set y = 0 → x = 5","Step 4: Write intercept points"],"options":[],"conceptId":"math_linear_programming_inequality_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Inequality Constraints"}', 0),
  (221, 51, 'Determine all points satisfying x ≥ 0 and y ≥ 0 in coordinate plane', 'text', 1, 'sign conditions', '{"why":"Intersection of non-negative half-planes defines region","sol":"Step 1: Solve x ≥ 0 → x ∈ [0, ∞)\nStep 2: Solve y ≥ 0 → y ∈ [0, ∞)\nStep 3: Combine conditions using intersection\nStep 4: Express solution set","steps":["Step 1: Solve x ≥ 0 → x ∈ [0, ∞)","Step 2: Solve y ≥ 0 → y ∈ [0, ∞)","Step 3: Combine conditions using intersection","Step 4: Express solution set"],"options":[],"conceptId":"math_linear_programming_inequality_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Inequality Constraints"}', 1),
  (222, 51, 'Test whether point (0,0) satisfies x + y ≤ 4 and 2x + y ≤ 6', 'text', 1, 'substitution', '{"why":"Point lies in feasible solution set","sol":"Step 1: Substitute (0,0) into x + y ≤ 4\nStep 2: Evaluate 0 ≤ 4\nStep 3: Substitute into 2x + y ≤ 6\nStep 4: Evaluate 0 ≤ 6\nStep 5: Confirm both conditions","steps":["Step 1: Substitute (0,0) into x + y ≤ 4","Step 2: Evaluate 0 ≤ 4","Step 3: Substitute into 2x + y ≤ 6","Step 4: Evaluate 0 ≤ 6","Step 5: Confirm both conditions"],"options":[],"conceptId":"math_linear_programming_inequality_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Inequality Constraints"}', 2),
  (223, 51, 'Draw feasible region for x ≥ 0, y ≥ 0, and 2x + 3y ≤ 12', 'text', 1, 'graph all constraints', '{"why":"Region satisfying all inequalities simultaneously","sol":"Step 1: Draw axes (x ≥ 0, y ≥ 0)\nStep 2: Convert 2x + 3y ≤ 12 to boundary 2x + 3y = 12\nStep 3: Find intercepts (6,0) and (0,4)\nStep 4: Draw line through intercepts\nStep 5: Shade region below line in first quadrant","steps":["Step 1: Draw axes (x ≥ 0, y ≥ 0)","Step 2: Convert 2x + 3y ≤ 12 to boundary 2x + 3y = 12","Step 3: Find intercepts (6,0) and (0,4)","Step 4: Draw line through intercepts","Step 5: Shade region below line in first quadrant"],"options":[],"conceptId":"math_linear_programming_inequality_constraints","skillId":"math_linear_programming","subskillId":"math_linear_programming_q4","subject":"math","chapter":"linear_programming","topic":"Inequality Constraints"}', 3),
  (224, 52, 'Find the set of all feasible points satisfying x ≥ 0 and y ≥ 0', 'text', 1, 'inequality intersection', '{"why":"Feasible region is intersection of all constraint sets","sol":"Step 1: Solve x ≥ 0 → x ∈ [0, ∞)\nStep 2: Solve y ≥ 0 → y ∈ [0, ∞)\nStep 3: Take intersection of both sets\nStep 4: Write ordered pair form","steps":["Step 1: Solve x ≥ 0 → x ∈ [0, ∞)","Step 2: Solve y ≥ 0 → y ∈ [0, ∞)","Step 3: Take intersection of both sets","Step 4: Write ordered pair form"],"options":[],"conceptId":"math_linear_programming_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Feasible Region"}', 0),
  (225, 52, 'Find intercept points of boundary line x + y = 4', 'text', 1, 'set variables to zero', '{"why":"Intercepts define geometry of boundary line","sol":"Step 1: Set x = 0 → y = 4\nStep 2: Set y = 0 → x = 4\nStep 3: Write coordinate points\nStep 4: Define line segment between points","steps":["Step 1: Set x = 0 → y = 4","Step 2: Set y = 0 → x = 4","Step 3: Write coordinate points","Step 4: Define line segment between points"],"options":[],"conceptId":"math_linear_programming_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Feasible Region"}', 1),
  (226, 52, 'Determine region defined by x + y ≤ 4 in first quadrant', 'text', 1, 'inequality region', '{"why":"Intersection of inequality and axes forms triangle","sol":"Step 1: Convert boundary x + y = 4\nStep 2: Identify intercepts (4,0), (0,4)\nStep 3: Restrict to x ≥ 0, y ≥ 0\nStep 4: Describe bounded region","steps":["Step 1: Convert boundary x + y = 4","Step 2: Identify intercepts (4,0), (0,4)","Step 3: Restrict to x ≥ 0, y ≥ 0","Step 4: Describe bounded region"],"options":[],"conceptId":"math_linear_programming_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Feasible Region"}', 2),
  (227, 52, 'Draw the feasible region for 2x + 3y ≤ 12, x ≥ 0, y ≥ 0', 'text', 1, 'graph bounded region', '{"why":"Feasible region is bounded area satisfying all constraints","sol":"Step 1: Draw axes\nStep 2: Find intercepts of 2x + 3y = 12: (6,0) and (0,4)\nStep 3: Draw line through intercepts\nStep 4: Shade region satisfying all inequalities\nStep 5: Identify vertices of region","steps":["Step 1: Draw axes","Step 2: Find intercepts of 2x + 3y = 12: (6,0) and (0,4)","Step 3: Draw line through intercepts","Step 4: Shade region satisfying all inequalities","Step 5: Identify vertices of region"],"options":[],"conceptId":"math_linear_programming_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q4","subject":"math","chapter":"linear_programming","topic":"Feasible Region"}', 3),
  (228, 52, 'Determine the feasible region for constraints 3x + 2y ≤ 12, x ≥ 0, y ≥ 0', 'text', 1, 'graph bounded triangular region', '{"why":"Region below line 3x + 2y = 12 in the first quadrant","sol":"Step 1: Draw axes for x ≥ 0, y ≥ 0\nStep 2: Find intercepts for 3x + 2y = 12: x=4 when y=0, y=6 when x=0\nStep 3: Draw line connecting (4,0) and (0,6)\nStep 4: Test point (0,0) → 0 ≤ 12 is true\nStep 5: Shade region toward origin (bounded triangle)","steps":["Step 1: Draw axes for x ≥ 0, y ≥ 0","Step 2: Find intercepts for 3x + 2y = 12: x=4 when y=0, y=6 when x=0","Step 3: Draw line connecting (4,0) and (0,6)","Step 4: Test point (0,0) → 0 ≤ 12 is true","Step 5: Shade region toward origin (bounded triangle)"],"options":[],"conceptId":"math_linear_programming_feasible_region","skillId":"math_linear_programming","subskillId":"math_linear_programming_q5","subject":"math","chapter":"linear_programming","topic":"Feasible Region"}', 4),
  (229, 53, 'Evaluate Z = 3x + 5y at (2,4), (0,6), (5,0)', 'text', 1, 'substitute points', '{"why":"Objective function is evaluated at vertices to find optimum","sol":"Step 1: Substitute (2,4) → Z = 3(2) + 5(4)\nStep 2: Compute Z = 6 + 20\nStep 3: Z(2,4) = 26\nStep 4: Substitute (0,6) → Z = 3(0) + 5(6)\nStep 5: Z(0,6) = 30\nStep 6: Substitute (5,0) → Z = 3(5) + 5(0)\nStep 7: Z(5,0) = 15\nStep 8: Compare all values","steps":["Step 1: Substitute (2,4) → Z = 3(2) + 5(4)","Step 2: Compute Z = 6 + 20","Step 3: Z(2,4) = 26","Step 4: Substitute (0,6) → Z = 3(0) + 5(6)","Step 5: Z(0,6) = 30","Step 6: Substitute (5,0) → Z = 3(5) + 5(0)","Step 7: Z(5,0) = 15","Step 8: Compare all values"],"options":[],"conceptId":"math_linear_programming_applications_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q1","subject":"math","chapter":"linear_programming","topic":"Applications of Linear Programming"}', 0),
  (230, 53, 'Maximize Z = 4x + 2y subject to x + y ≤ 6', 'text', 1, 'corner point evaluation', '{"why":"Linear objective reaches extreme at boundary vertices","sol":"Step 1: Convert x + y ≤ 6 to x + y = 6\nStep 2: Find intercepts (6,0) and (0,6)\nStep 3: Include origin (0,0)\nStep 4: Evaluate Z at all points\nStep 5: Compare results","steps":["Step 1: Convert x + y ≤ 6 to x + y = 6","Step 2: Find intercepts (6,0) and (0,6)","Step 3: Include origin (0,0)","Step 4: Evaluate Z at all points","Step 5: Compare results"],"options":[],"conceptId":"math_linear_programming_applications_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q2","subject":"math","chapter":"linear_programming","topic":"Applications of Linear Programming"}', 1),
  (231, 53, 'Find objective function value for C = 10x + 3y at x = 4, y = 5', 'text', 1, 'direct substitution', '{"why":"Objective function evaluates performance of given solution","sol":"Step 1: Write C = 10x + 3y\nStep 2: Substitute x = 4, y = 5\nStep 3: Compute 10×4\nStep 4: Compute 3×5\nStep 5: Add results","steps":["Step 1: Write C = 10x + 3y","Step 2: Substitute x = 4, y = 5","Step 3: Compute 10×4","Step 4: Compute 3×5","Step 5: Add results"],"options":[],"conceptId":"math_linear_programming_applications_of_linear_programming","skillId":"math_linear_programming","subskillId":"math_linear_programming_q3","subject":"math","chapter":"linear_programming","topic":"Applications of Linear Programming"}', 2),
  (232, 54, 'What are the dimensions (order) of a matrix with 4 rows and 3 columns, and how many total elements does it contain?', 'text', 1, 'order is written as m × n and total elements = m × n', '{"why":"A matrix with m rows and n columns has dimension m × n and holds m × n total entries.","sol":"Step 1: Identify number of rows m = 4\nStep 2: Identify number of columns n = 3\nStep 3: Write dimension in m × n notation → 4 × 3\nStep 4: Calculate total elements = 4 × 3 = 12","steps":["Step 1: Identify number of rows m = 4","Step 2: Identify number of columns n = 3","Step 3: Write dimension in m × n notation → 4 × 3","Step 4: Calculate total elements = 4 × 3 = 12"],"options":[],"conceptId":"math_matrices_introduction_notation","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Introduction & Notation"}', 0),
  (233, 54, 'Given A = [[5, -2, 9], [1, 4, 8], [3, 0, -7]], find a₂₃ + a₃₁.', 'text', 1, 'a₂₃ is Row 2 Column 3; a₃₁ is Row 3 Column 1', '{"why":"Element indexing uses a_ij where i is row index and j is column index.","sol":"Step 1: Locate a₂₃ in Row 2, Column 3 → a₂₃ = 8\nStep 2: Locate a₃₁ in Row 3, Column 1 → a₃₁ = 3\nStep 3: Add the two values: 8 + 3 = 11","steps":["Step 1: Locate a₂₃ in Row 2, Column 3 → a₂₃ = 8","Step 2: Locate a₃₁ in Row 3, Column 1 → a₃₁ = 3","Step 3: Add the two values: 8 + 3 = 11"],"options":[],"conceptId":"math_matrices_introduction_notation","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Introduction & Notation"}', 1),
  (234, 54, 'Construct a 2 × 2 matrix B where b_ij = i² + 2j.', 'text', 1, 'evaluate formula for (i,j) ∈ {(1,1),(1,2),(2,1),(2,2)}', '{"why":"Matrix entries are calculated by evaluating the algebraic rule b_ij for each row-column index pair.","sol":"Step 1: b₁₁ = 1² + 2(1) = 1 + 2 = 3\nStep 2: b₁₂ = 1² + 2(2) = 1 + 4 = 5\nStep 3: b₂₁ = 2² + 2(1) = 4 + 2 = 6\nStep 4: b₂₂ = 2² + 2(2) = 4 + 4 = 8\nStep 5: Assemble matrix B = [[3, 5], [6, 8]]","steps":["Step 1: b₁₁ = 1² + 2(1) = 1 + 2 = 3","Step 2: b₁₂ = 1² + 2(2) = 1 + 4 = 5","Step 3: b₂₁ = 2² + 2(1) = 4 + 2 = 6","Step 4: b₂₂ = 2² + 2(2) = 4 + 4 = 8","Step 5: Assemble matrix B = [[3, 5], [6, 8]]"],"options":[],"conceptId":"math_matrices_introduction_notation","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Introduction & Notation"}', 2),
  (235, 54, 'Which type of matrix is square, has 1s on its main diagonal, and 0s everywhere else?', 'text', 1, 'it acts as the multiplicative identity in matrix algebra', '{"why":"An identity matrix is a diagonal matrix whose main diagonal entries are all equal to 1.","sol":"Step 1: Recall definition of square matrix with a_ii = 1 for all i\nStep 2: Verify non-diagonal elements a_ij = 0 (i ≠ j)\nStep 3: Identify matrix as the Identity Matrix (I)","steps":["Step 1: Recall definition of square matrix with a_ii = 1 for all i","Step 2: Verify non-diagonal elements a_ij = 0 (i ≠ j)","Step 3: Identify matrix as the Identity Matrix (I)"],"options":[],"conceptId":"math_matrices_introduction_notation","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Introduction & Notation"}', 3),
  (236, 54, 'Why is a 3 × 1 matrix called a column matrix?', 'text', 1, 'examine its number of columns', '{"why":"A matrix consisting of a single vertical column is termed a column matrix.","sol":"Step 1: Observe that the matrix has 3 rows\nStep 2: Observe that the matrix has only 1 column\nStep 3: Any matrix with exactly 1 column is defined as a column matrix (or column vector)","steps":["Step 1: Observe that the matrix has 3 rows","Step 2: Observe that the matrix has only 1 column","Step 3: Any matrix with exactly 1 column is defined as a column matrix (or column vector)"],"options":[],"conceptId":"math_matrices_introduction_notation","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Introduction & Notation"}', 4),
  (237, 55, 'If A = [[4, 1], [-2, 3]] and B = [[1, 5], [6, -1]], find A + B.', 'text', 1, 'add corresponding elements at matching row and column positions', '{"why":"Matrix addition is performed by adding corresponding entries of equal-dimensional matrices.","sol":"Step 1: Verify dimensions → both are 2 × 2 matrices\nStep 2: First row: (4+1, 1+5) = (5, 6)\nStep 3: Second row: (-2+6, 3+(-1)) = (4, 2)\nStep 4: Combine into matrix [[5, 6], [4, 2]]","steps":["Step 1: Verify dimensions → both are 2 × 2 matrices","Step 2: First row: (4+1, 1+5) = (5, 6)","Step 3: Second row: (-2+6, 3+(-1)) = (4, 2)","Step 4: Combine into matrix [[5, 6], [4, 2]]"],"options":[],"conceptId":"math_matrices_basic_matrix_operations","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Basic Matrix Operations"}', 0),
  (238, 55, 'Find 4 × [[2, -3], [0, 5]].', 'text', 1, 'multiply every entry inside the matrix by scalar 4', '{"why":"Scalar multiplication scales every individual element of the matrix by the scalar factor.","sol":"Step 1: Multiply row 1 entries: 4 × 2 = 8, 4 × (-3) = -12\nStep 2: Multiply row 2 entries: 4 × 0 = 0, 4 × 5 = 20\nStep 3: Combine into matrix [[8, -12], [0, 20]]","steps":["Step 1: Multiply row 1 entries: 4 × 2 = 8, 4 × (-3) = -12","Step 2: Multiply row 2 entries: 4 × 0 = 0, 4 × 5 = 20","Step 3: Combine into matrix [[8, -12], [0, 20]]"],"options":[],"conceptId":"math_matrices_basic_matrix_operations","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Basic Matrix Operations"}', 1),
  (239, 55, 'Solve for matrix X in the matrix equation 2X + A = B, where A = [[1, 4], [2, 0]] and B = [[5, 10], [6, 8]].', 'text', 1, 'isolate X: 2X = B - A, so X = (1/2)(B - A)', '{"why":"Matrix linear equations follow standard algebraic isolation rules, applying element-wise operations.","sol":"Step 1: Subtract A from B: B - A = [[5-1, 10-4], [6-2, 8-0]] = [[4, 6], [4, 8]]\nStep 2: Divide each element by 2 (multiply by 1/2): X = (1/2)[[4, 6], [4, 8]]\nStep 3: Calculate X = [[2, 3], [2, 4]]","steps":["Step 1: Subtract A from B: B - A = [[5-1, 10-4], [6-2, 8-0]] = [[4, 6], [4, 8]]","Step 2: Divide each element by 2 (multiply by 1/2): X = (1/2)[[4, 6], [4, 8]]","Step 3: Calculate X = [[2, 3], [2, 4]]"],"options":[],"conceptId":"math_matrices_basic_matrix_operations","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Basic Matrix Operations"}', 2),
  (240, 55, 'Why is the matrix operation [[1, 2], [3, 4]] - [[5, 6]] invalid?', 'text', 1, 'compare matrix dimensions', '{"why":"Matrix subtraction requires both matrices to possess identical row and column dimensions.","sol":"Step 1: Determine order of first matrix → 2 × 2\nStep 2: Determine order of second matrix → 1 × 2\nStep 3: Check matching condition → 2 × 2 ≠ 1 × 2\nStep 4: Conclude operation is undefined","steps":["Step 1: Determine order of first matrix → 2 × 2","Step 2: Determine order of second matrix → 1 × 2","Step 3: Check matching condition → 2 × 2 ≠ 1 × 2","Step 4: Conclude operation is undefined"],"options":[],"conceptId":"math_matrices_basic_matrix_operations","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Basic Matrix Operations"}', 3),
  (241, 55, 'Given matrix M, what is the result of M + (-1)M?', 'text', 1, 'apply distributive property M - M', '{"why":"Adding a matrix to its additive inverse yields the zero matrix of matching dimension.","sol":"Step 1: Recognize (-1)M = -M (the additive inverse)\nStep 2: Perform M + (-M) = M - M\nStep 3: Every entry m_ij - m_ij = 0\nStep 4: The result is the Zero Matrix (O)","steps":["Step 1: Recognize (-1)M = -M (the additive inverse)","Step 2: Perform M + (-M) = M - M","Step 3: Every entry m_ij - m_ij = 0","Step 4: The result is the Zero Matrix (O)"],"options":[],"conceptId":"math_matrices_basic_matrix_operations","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Basic Matrix Operations"}', 4),
  (242, 56, 'If matrix A is of order 3 × 2 and matrix B is of order 2 × 4, what is the order of the product matrix AB?', 'text', 1, 'check inner dimension match and outer dimension result (m × p)', '{"why":"Multiplying an m × n matrix by an n × p matrix yields a product matrix of dimension m × p.","sol":"Step 1: Identify dimensions: A(3 × 2), B(2 × 4)\nStep 2: Compare inner dimensions → 2 = 2 (multiplication valid)\nStep 3: Extract outer dimensions → 3 and 4\nStep 4: Conclude product matrix AB has dimension 3 × 4","steps":["Step 1: Identify dimensions: A(3 × 2), B(2 × 4)","Step 2: Compare inner dimensions → 2 = 2 (multiplication valid)","Step 3: Extract outer dimensions → 3 and 4","Step 4: Conclude product matrix AB has dimension 3 × 4"],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 0),
  (243, 56, 'Multiply A = [[1, 2], [3, 4]] by B = [[2, 0], [1, 3]].', 'text', 1, 'compute dot product of each row of A with each column of B', '{"why":"Matrix multiplication computes row-by-column dot products across all index pairs.","sol":"Step 1: c₁₁ = (1×2) + (2×1) = 2 + 2 = 4\nStep 2: c₁₂ = (1×0) + (2×3) = 0 + 6 = 6\nStep 3: c₂₁ = (3×2) + (4×1) = 6 + 4 = 10\nStep 4: c₂₂ = (3×0) + (4×3) = 0 + 12 = 12\nStep 5: Form matrix [[4, 6], [10, 12]]","steps":["Step 1: c₁₁ = (1×2) + (2×1) = 2 + 2 = 4","Step 2: c₁₂ = (1×0) + (2×3) = 0 + 6 = 6","Step 3: c₂₁ = (3×2) + (4×1) = 6 + 4 = 10","Step 4: c₂₂ = (3×0) + (4×3) = 0 + 12 = 12","Step 5: Form matrix [[4, 6], [10, 12]]"],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 1),
  (244, 56, 'Multiply row vector R = [[2, -1, 4]] by column vector C = [[3], [5], [1]].', 'text', 1, 'compute (1×3) × (3×1) resulting in a single scalar (1×1)', '{"why":"The dot product of a row vector and column vector yields a single scalar value.","sol":"Step 1: Multiply corresponding entries: 2×3 = 6, (-1)×5 = -5, 4×1 = 4\nStep 2: Sum results: 6 + (-5) + 4 = 5\nStep 3: Write result as 1 × 1 matrix [[5]] or scalar 5","steps":["Step 1: Multiply corresponding entries: 2×3 = 6, (-1)×5 = -5, 4×1 = 4","Step 2: Sum results: 6 + (-5) + 4 = 5","Step 3: Write result as 1 × 1 matrix [[5]] or scalar 5"],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 2),
  (245, 56, 'Why is matrix multiplication AB generally not equal to BA?', 'text', 1, 'matrix multiplication depends on row-column orientation order', '{"why":"Unlike real number multiplication, matrix multiplication order dictates row-column combinations, making AB ≠ BA in general.","sol":"Step 1: Observe that swapping matrix order changes row-column pairing\nStep 2: Dimensions of AB and BA may not even be identical\nStep 3: Conclude matrix multiplication is non-commutative","steps":["Step 1: Observe that swapping matrix order changes row-column pairing","Step 2: Dimensions of AB and BA may not even be identical","Step 3: Conclude matrix multiplication is non-commutative"],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 3),
  (246, 56, 'Given matrix M, what is the result of multiplying M by the Identity Matrix I of matching size?', 'text', 1, 'identity matrix acts as multiplicative identity', '{"why":"Multiplying any matrix by the identity matrix leaves the original matrix unchanged.","sol":"Step 1: Recall identity property M × I = M\nStep 2: Every row dot product with identity columns preserves original row entries\nStep 3: Result equals M unchanged","steps":["Step 1: Recall identity property M × I = M","Step 2: Every row dot product with identity columns preserves original row entries","Step 3: Result equals M unchanged"],"options":[],"conceptId":"math_matrices_matrix_multiplication","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Matrix Multiplication"}', 4),
  (247, 57, 'Calculate the determinant of matrix A = [[6, 4], [2, 5]].', 'text', 1, 'apply formula det(A) = ad - bc', '{"why":"Determinant of a 2 × 2 matrix is computed via ad - bc.","sol":"Step 1: Identify a = 6, b = 4, c = 2, d = 5\nStep 2: Compute ad = 6 × 5 = 30\nStep 3: Compute bc = 4 × 2 = 8\nStep 4: Subtract 30 - 8 = 22","steps":["Step 1: Identify a = 6, b = 4, c = 2, d = 5","Step 2: Compute ad = 6 × 5 = 30","Step 3: Compute bc = 4 × 2 = 8","Step 4: Subtract 30 - 8 = 22"],"options":[],"conceptId":"math_matrices_determinants_inverses_2x2","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Determinants & Inverses (2x2)"}', 0),
  (248, 57, 'Find the transpose of matrix B = [[1, 7], [-3, 9]].', 'text', 1, 'interchange rows into columns', '{"why":"Transposing a matrix swaps its row and column indices (a_ij → a_ji).","sol":"Step 1: Row 1 [1, 7] becomes Column 1 [1; -3]\nStep 2: Row 2 [-3, 9] becomes Column 2 [7; 9]\nStep 3: Form transpose matrix [[1, -3], [7, 9]]","steps":["Step 1: Row 1 [1, 7] becomes Column 1 [1; -3]","Step 2: Row 2 [-3, 9] becomes Column 2 [7; 9]","Step 3: Form transpose matrix [[1, -3], [7, 9]]"],"options":[],"conceptId":"math_matrices_determinants_inverses_2x2","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Determinants & Inverses (2x2)"}', 1),
  (249, 57, 'Find the inverse of matrix A = [[4, 7], [1, 2]].', 'text', 1, 'det = ad - bc; inverse = (1/det)[[d, -b], [-c, a]]', '{"why":"The inverse of a 2×2 matrix uses the scaled adjugate formula A⁻¹ = (1/det)[[d,-b],[-c,a]].","sol":"Step 1: Compute det(A) = (4×2) - (7×1) = 8 - 7 = 1\nStep 2: Swap main diagonal: d=2, a=4\nStep 3: Negate off-diagonal: -b=-7, -c=-1\nStep 4: Inverse = (1/1)[[2, -7], [-1, 4]] = [[2, -7], [-1, 4]]","steps":["Step 1: Compute det(A) = (4×2) - (7×1) = 8 - 7 = 1","Step 2: Swap main diagonal: d=2, a=4","Step 3: Negate off-diagonal: -b=-7, -c=-1","Step 4: Inverse = (1/1)[[2, -7], [-1, 4]] = [[2, -7], [-1, 4]]"],"options":[],"conceptId":"math_matrices_determinants_inverses_2x2","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Determinants & Inverses (2x2)"}', 2),
  (250, 57, 'For what value of x is the matrix [[x, 8], [2, 4]] singular?', 'text', 1, 'set determinant ad - bc = 0', '{"why":"A matrix is singular if and only if its determinant equals zero.","sol":"Step 1: Set up determinant equation: (x × 4) - (8 × 2) = 0\nStep 2: Simplify: 4x - 16 = 0\nStep 3: Solve for x: 4x = 16 → x = 4","steps":["Step 1: Set up determinant equation: (x × 4) - (8 × 2) = 0","Step 2: Simplify: 4x - 16 = 0","Step 3: Solve for x: 4x = 16 → x = 4"],"options":[],"conceptId":"math_matrices_determinants_inverses_2x2","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Determinants & Inverses (2x2)"}', 3);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (251, 57, 'If det(A) = 5, what is the determinant of A⁻¹?', 'text', 1, 'apply det(A⁻¹) = 1 / det(A)', '{"why":"The determinant of an inverse matrix equals the reciprocal of the original determinant.","sol":"Step 1: Recall property det(A⁻¹) = 1 / det(A)\nStep 2: Substitute det(A) = 5 → 1/5 = 0.2","steps":["Step 1: Recall property det(A⁻¹) = 1 / det(A)","Step 2: Substitute det(A) = 5 → 1/5 = 0.2"],"options":[],"conceptId":"math_matrices_determinants_inverses_2x2","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Determinants & Inverses (2x2)"}', 4),
  (252, 58, 'What is matrix form of linear equations AX = B and how is X found?', 'text', 1, 'use inverse method', '{"why":"Multiplying by inverse isolates the variable matrix","sol":"Step 1: Write system in matrix form AX = B\nStep 2: Multiply both sides by A⁻¹\nStep 3: A⁻¹AX = A⁻¹B\nStep 4: I·X = A⁻¹B\nStep 5: X = A⁻¹B","steps":["Step 1: Write system in matrix form AX = B","Step 2: Multiply both sides by A⁻¹","Step 3: A⁻¹AX = A⁻¹B","Step 4: I·X = A⁻¹B","Step 5: X = A⁻¹B"],"options":[],"conceptId":"math_matrices_application_to_linear_equations","skillId":"math_matrices","subskillId":"math_matrices_q1","subject":"math","chapter":"matrices","topic":"Application to Linear Equations"}', 0),
  (253, 58, 'Solve for X when A = [[2,1],[1,3]] and B = [[5],[7]]', 'text', 1, 'use inverse of 2×2 matrix', '{"why":"Inverse matrix converts system into direct computation","sol":"Step 1: Compute determinant of A: (2×3 − 1×1) = 5\nStep 2: Find inverse A⁻¹ = (1/5)[[3, -1],[-1, 2]]\nStep 3: Multiply A⁻¹ by B\nStep 4: [[3, -1],[-1, 2]] × [[5],[7]]\nStep 5: = [[(15 - 7)], [(-5 + 14)]]\nStep 6: Multiply by 1/5\nStep 7: X = [[8/5],[9/5]]","steps":["Step 1: Compute determinant of A: (2×3 − 1×1) = 5","Step 2: Find inverse A⁻¹ = (1/5)[[3, -1],[-1, 2]]","Step 3: Multiply A⁻¹ by B","Step 4: [[3, -1],[-1, 2]] × [[5],[7]]","Step 5: = [[(15 - 7)], [(-5 + 14)]]","Step 6: Multiply by 1/5","Step 7: X = [[8/5],[9/5]]"],"options":[],"conceptId":"math_matrices_application_to_linear_equations","skillId":"math_matrices","subskillId":"math_matrices_q2","subject":"math","chapter":"matrices","topic":"Application to Linear Equations"}', 1),
  (254, 58, 'When does a system AX = B have no solution using determinants?', 'text', 1, 'determinant condition', '{"why":"Singular matrices cannot produce unique solutions","sol":"Step 1: Compute det(A)\nStep 2: Check if det(A) = 0\nStep 3: If det(A) = 0, check consistency\nStep 4: If inconsistent → no solution","steps":["Step 1: Compute det(A)","Step 2: Check if det(A) = 0","Step 3: If det(A) = 0, check consistency","Step 4: If inconsistent → no solution"],"options":[],"conceptId":"math_matrices_application_to_linear_equations","skillId":"math_matrices","subskillId":"math_matrices_q3","subject":"math","chapter":"matrices","topic":"Application to Linear Equations"}', 2),
  (255, 58, 'What happens when det(A) = 0 in AX = B?', 'text', 1, 'singular matrix', '{"why":"Zero determinant removes invertibility","sol":"Step 1: Compute det(A)\nStep 2: If det(A) = 0, matrix is singular\nStep 3: Try row reduction\nStep 4: Check if system reduces to contradiction or dependency","steps":["Step 1: Compute det(A)","Step 2: If det(A) = 0, matrix is singular","Step 3: Try row reduction","Step 4: Check if system reduces to contradiction or dependency"],"options":[],"conceptId":"math_matrices_application_to_linear_equations","skillId":"math_matrices","subskillId":"math_matrices_q4","subject":"math","chapter":"matrices","topic":"Application to Linear Equations"}', 3),
  (256, 58, 'Find X if A⁻¹ = [[1,0],[0,1]] and B = [[4],[6]]', 'text', 1, 'identity inverse case', '{"why":"Identity matrix does not change any vector","sol":"Step 1: Recognize A⁻¹ is identity matrix\nStep 2: Multiply I × B\nStep 3: Result equals B unchanged","steps":["Step 1: Recognize A⁻¹ is identity matrix","Step 2: Multiply I × B","Step 3: Result equals B unchanged"],"options":[],"conceptId":"math_matrices_application_to_linear_equations","skillId":"math_matrices","subskillId":"math_matrices_q5","subject":"math","chapter":"matrices","topic":"Application to Linear Equations"}', 4),
  (257, 59, 'Convert (-3, 7) into i and j vector form', 'text', 1, 'split components', '{"why":"Each coordinate is written along its axis direction","sol":"Step 1: Identify x-component = -3\nStep 2: Identify y-component = 7\nStep 3: Multiply x by i → -3i\nStep 4: Multiply y by j → 7j\nStep 5: Combine components","steps":["Step 1: Identify x-component = -3","Step 2: Identify y-component = 7","Step 3: Multiply x by i → -3i","Step 4: Multiply y by j → 7j","Step 5: Combine components"],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 0),
  (258, 59, 'Convert (0, 6) into i and j form', 'text', 1, 'x is zero', '{"why":"Zero x-component removes i term","sol":"Step 1: Identify x-component = 0\nStep 2: Identify y-component = 6\nStep 3: 0i contributes nothing\nStep 4: Write remaining j component","steps":["Step 1: Identify x-component = 0","Step 2: Identify y-component = 6","Step 3: 0i contributes nothing","Step 4: Write remaining j component"],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 1),
  (259, 59, 'Convert 8i - 5j into coordinate form', 'text', 1, 'extract components', '{"why":"i corresponds to x-axis and j corresponds to y-axis","sol":"Step 1: Identify i coefficient = 8\nStep 2: Identify j coefficient = -5\nStep 3: Write x = 8\nStep 4: Write y = -5\nStep 5: Form coordinate pair","steps":["Step 1: Identify i coefficient = 8","Step 2: Identify j coefficient = -5","Step 3: Write x = 8","Step 4: Write y = -5","Step 5: Form coordinate pair"],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 2),
  (260, 59, 'Add vectors (2i + 3j) + (4i - j)', 'text', 1, 'combine like terms', '{"why":"Vector addition is done component-wise","sol":"Step 1: Group i terms → 2i + 4i\nStep 2: Group j terms → 3j - j\nStep 3: Add i components → 6i\nStep 4: Add j components → 2j","steps":["Step 1: Group i terms → 2i + 4i","Step 2: Group j terms → 3j - j","Step 3: Add i components → 6i","Step 4: Add j components → 2j"],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 3),
  (261, 59, 'Subtract vectors (7i + 2j) - (3i + 5j)', 'text', 1, 'distribute minus sign', '{"why":"Subtraction changes signs of second vector","sol":"Step 1: Expand subtraction → 7i + 2j - 3i - 5j\nStep 2: Group i terms → 7i - 3i\nStep 3: Group j terms → 2j - 5j\nStep 4: Simplify components","steps":["Step 1: Expand subtraction → 7i + 2j - 3i - 5j","Step 2: Group i terms → 7i - 3i","Step 3: Group j terms → 2j - 5j","Step 4: Simplify components"],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 4),
  (262, 59, 'Find resultant of (5i + 1j) + (-2i + 6j)', 'text', 1, 'component addition', '{"why":"Resultant vector is sum of components","sol":"Step 1: Add i components → 5 + (-2)\nStep 2: Add j components → 1 + 6\nStep 3: Simplify each component\nStep 4: Write final vector form","steps":["Step 1: Add i components → 5 + (-2)","Step 2: Add j components → 1 + 6","Step 3: Simplify each component","Step 4: Write final vector form"],"options":[],"conceptId":"math_vectors_vector_notation","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Vector Notation"}', 5),
  (263, 60, 'Find magnitude of vector v = 3i - 4j', 'text', 1, 'Pythagoras theorem', '{"why":"Magnitude is the length of vector, calculated using Pythagorean theorem","sol":"Step 1: Identify components: x = 3, y = -4\nStep 2: Square each component: 3² = 9, (-4)² = 16\nStep 3: Add the squares: 9 + 16 = 25\nStep 4: Take square root of sum\nStep 5: Final magnitude = √25","steps":["Step 1: Identify components: x = 3, y = -4","Step 2: Square each component: 3² = 9, (-4)² = 16","Step 3: Add the squares: 9 + 16 = 25","Step 4: Take square root of sum","Step 5: Final magnitude = √25"],"options":[],"conceptId":"math_vectors_magnitude_and_direction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Magnitude and Direction"}', 0),
  (264, 60, 'Find direction angle of vector v = 1i + 1j', 'text', 1, 'tan inverse', '{"why":"Direction angle shows orientation from positive x-axis","sol":"Step 1: Identify components: x = 1, y = 1\nStep 2: Calculate tangent: tan(θ) = y/x = 1/1 = 1\nStep 3: Use arctan to find angle\nStep 4: θ = tan⁻¹(1)\nStep 5: Final angle = 45°","steps":["Step 1: Identify components: x = 1, y = 1","Step 2: Calculate tangent: tan(θ) = y/x = 1/1 = 1","Step 3: Use arctan to find angle","Step 4: θ = tan⁻¹(1)","Step 5: Final angle = 45°"],"options":[],"conceptId":"math_vectors_magnitude_and_direction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Magnitude and Direction"}', 1),
  (265, 60, 'What is magnitude of a vector that goes 3 units right and 4 units down?', 'text', 1, 'direct Pythagorean application', '{"why":"Same as Example 1, just phrased differently","sol":"Step 1: Interpret \"right\" as +x → 3\nStep 2: Interpret \"down\" as -y → -4\nStep 3: Square components: 3² = 9, (-4)² = 16\nStep 4: Add squared values: 9 + 16 = 25\nStep 5: Take square root","steps":["Step 1: Interpret \"right\" as +x → 3","Step 2: Interpret \"down\" as -y → -4","Step 3: Square components: 3² = 9, (-4)² = 16","Step 4: Add squared values: 9 + 16 = 25","Step 5: Take square root"],"options":[],"conceptId":"math_vectors_magnitude_and_direction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Magnitude and Direction"}', 2),
  (266, 60, 'Why is magnitude always positive?', 'text', 1, 'square root property', '{"why":"Mathematical definition ensures magnitude represents length","sol":"Step 1: Recall magnitude formula: √(x² + y²)\nStep 2: x² and y² are always ≥ 0\nStep 3: Their sum is also ≥ 0\nStep 4: Square root of non-negative is always non-negative\nStep 5: Therefore magnitude is always positive","steps":["Step 1: Recall magnitude formula: √(x² + y²)","Step 2: x² and y² are always ≥ 0","Step 3: Their sum is also ≥ 0","Step 4: Square root of non-negative is always non-negative","Step 5: Therefore magnitude is always positive"],"options":[],"conceptId":"math_vectors_magnitude_and_direction","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Magnitude and Direction"}', 3),
  (267, 60, 'Find magnitude and direction of vector v = 2i + 2√3 j', 'text', 1, 'special triangle 1:√3:2', '{"why":"Components form a 30-60-90 triangle with sides 2, 2√3, and hypotenuse 4","sol":"Step 1: Identify components: x = 2, y = 2√3\nStep 2: Square components: 2² = 4, (2√3)² = 12\nStep 3: Add: 4 + 12 = 16\nStep 4: Take square root: √16 = 4 (magnitude)\nStep 5: Calculate angle: tan(θ) = 2√3 / 2 = √3\nStep 6: θ = 60° (recognize 30-60-90 triangle)","steps":["Step 1: Identify components: x = 2, y = 2√3","Step 2: Square components: 2² = 4, (2√3)² = 12","Step 3: Add: 4 + 12 = 16","Step 4: Take square root: √16 = 4 (magnitude)","Step 5: Calculate angle: tan(θ) = 2√3 / 2 = √3","Step 6: θ = 60° (recognize 30-60-90 triangle)"],"options":[],"conceptId":"math_vectors_magnitude_and_direction","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Magnitude and Direction"}', 4),
  (268, 60, 'If magnitude is 5 and direction is 0°, what is vector form?', 'text', 1, 'cosine and sine', '{"why":"0° direction means vector points purely along positive x-axis","sol":"Step 1: Use formulas: x = |v|cos(θ), y = |v|sin(θ)\nStep 2: Substitute values: x = 5cos(0°), y = 5sin(0°)\nStep 3: Evaluate trigonometric functions: cos(0°) = 1, sin(0°) = 0\nStep 4: Calculate components: x = 5×1 = 5, y = 5×0 = 0\nStep 5: Write vector form","steps":["Step 1: Use formulas: x = |v|cos(θ), y = |v|sin(θ)","Step 2: Substitute values: x = 5cos(0°), y = 5sin(0°)","Step 3: Evaluate trigonometric functions: cos(0°) = 1, sin(0°) = 0","Step 4: Calculate components: x = 5×1 = 5, y = 5×0 = 0","Step 5: Write vector form"],"options":[],"conceptId":"math_vectors_magnitude_and_direction","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Magnitude and Direction"}', 5),
  (269, 61, 'Add vectors (3,4) + (1,2)', 'text', 1, 'add x and y separately', '{"why":"Vector addition combines corresponding components","sol":"Step 1: Add x-components: 3 + 1\nStep 2: Add y-components: 4 + 2\nStep 3: Combine results","steps":["Step 1: Add x-components: 3 + 1","Step 2: Add y-components: 4 + 2","Step 3: Combine results"],"options":[],"conceptId":"math_vectors_vector_addition_and_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Vector Addition and Subtraction"}', 0),
  (270, 61, 'Subtract vectors (6,8) - (2,3)', 'text', 1, 'subtract components', '{"why":"Subtraction works same way as addition but with minus signs","sol":"Step 1: Subtract x-components: 6 - 2\nStep 2: Subtract y-components: 8 - 3\nStep 3: Combine results","steps":["Step 1: Subtract x-components: 6 - 2","Step 2: Subtract y-components: 8 - 3","Step 3: Combine results"],"options":[],"conceptId":"math_vectors_vector_addition_and_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Vector Addition and Subtraction"}', 1),
  (271, 61, 'Find resultant of (2i + 3j) + (4i - 2j)', 'text', 1, 'group i and j', '{"why":"Like terms are added together just like regular algebra","sol":"Step 1: Combine i terms: 2i + 4i\nStep 2: Combine j terms: 3j - 2j\nStep 3: Write final vector","steps":["Step 1: Combine i terms: 2i + 4i","Step 2: Combine j terms: 3j - 2j","Step 3: Write final vector"],"options":[],"conceptId":"math_vectors_vector_addition_and_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Vector Addition and Subtraction"}', 2),
  (272, 61, 'Subtract vectors in i,j form: (8i - 3j) - (4i + 5j)', 'text', 1, 'distribute negative', '{"why":"Distributing the subtraction changes signs of second vector","sol":"Step 1: Expand: 8i - 3j - 4i - 5j\nStep 2: Group i terms: 8i - 4i\nStep 3: Group j terms: -3j - 5j\nStep 4: Simplify","steps":["Step 1: Expand: 8i - 3j - 4i - 5j","Step 2: Group i terms: 8i - 4i","Step 3: Group j terms: -3j - 5j","Step 4: Simplify"],"options":[],"conceptId":"math_vectors_vector_addition_and_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Vector Addition and Subtraction"}', 3),
  (273, 61, 'Add three vectors: (1,1) + (2,2) + (3,3)', 'text', 1, 'add all x, all y', '{"why":"Can add any number of vectors by summing components","sol":"Step 1: Add all x-components: 1 + 2 + 3\nStep 2: Add all y-components: 1 + 2 + 3\nStep 3: Combine","steps":["Step 1: Add all x-components: 1 + 2 + 3","Step 2: Add all y-components: 1 + 2 + 3","Step 3: Combine"],"options":[],"conceptId":"math_vectors_vector_addition_and_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Vector Addition and Subtraction"}', 4),
  (274, 61, 'If v = (x,y), what is v - v?', 'text', 1, 'same vector subtracted from itself', '{"why":"Any vector subtracted from itself equals zero vector","sol":"Step 1: Set up subtraction: (x-x, y-y)\nStep 2: Simplify components","steps":["Step 1: Set up subtraction: (x-x, y-y)","Step 2: Simplify components"],"options":[],"conceptId":"math_vectors_vector_addition_and_subtraction","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Vector Addition and Subtraction"}', 5),
  (275, 62, 'Find dot product of (2,3) · (4,5)', 'text', 1, 'multiply corresponding components then add', '{"why":"Dot product measures alignment of vectors","sol":"Step 1: Multiply x-components: 2 × 4\nStep 2: Multiply y-components: 3 × 5\nStep 3: Add the products\nStep 4: Final result is scalar","steps":["Step 1: Multiply x-components: 2 × 4","Step 2: Multiply y-components: 3 × 5","Step 3: Add the products","Step 4: Final result is scalar"],"options":[],"conceptId":"math_vectors_dot_product_scalar_product","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Dot Product (Scalar Product)"}', 0),
  (276, 62, 'Are vectors (1,2) and (-2,1) perpendicular?', 'text', 1, 'check if dot product is zero', '{"why":"Perpendicular vectors have zero dot product","sol":"Step 1: Compute dot product of (1,2) and (-2,1)\nStep 2: (1×-2) + (2×1) = -2 + 2 = 0\nStep 3: Result is 0, so they''re perpendicular","steps":["Step 1: Compute dot product of (1,2) and (-2,1)","Step 2: (1×-2) + (2×1) = -2 + 2 = 0","Step 3: Result is 0, so they''re perpendicular"],"options":[],"conceptId":"math_vectors_dot_product_scalar_product","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Dot Product (Scalar Product)"}', 1),
  (277, 62, 'Calculate dot product for v = 3i - 4j and w = 4i + 3j', 'text', 1, 'convert to coordinate form first', '{"why":"Vectors are perpendicular (opposite directions)","sol":"Step 1: Convert to coordinate form: v=(3,-4), w=(4,3)\nStep 2: Multiply components: (3×4) + (-4×3)\nStep 3: 12 - 12 = 0\nStep 4: Final result is scalar","steps":["Step 1: Convert to coordinate form: v=(3,-4), w=(4,3)","Step 2: Multiply components: (3×4) + (-4×3)","Step 3: 12 - 12 = 0","Step 4: Final result is scalar"],"options":[],"conceptId":"math_vectors_dot_product_scalar_product","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Dot Product (Scalar Product)"}', 2),
  (278, 62, 'How does dot product change if one vector is doubled?', 'text', 1, 'multiply both components by 2', '{"why":"Linear property: a(u·v) = (au)·v","sol":"Step 1: Let original be (x,y)\nStep 2: New vector is (2x, 2y)\nStep 3: Dot product becomes x(2x) + y(2y) = 2(x²+y²)\nStep 4: Result is doubled","steps":["Step 1: Let original be (x,y)","Step 2: New vector is (2x, 2y)","Step 3: Dot product becomes x(2x) + y(2y) = 2(x²+y²)","Step 4: Result is doubled"],"options":[],"conceptId":"math_vectors_dot_product_scalar_product","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Dot Product (Scalar Product)"}', 3),
  (279, 62, 'Find dot product of zero vector (0,0) with any vector', 'text', 1, 'multiply by zero', '{"why":"Zero vector has no magnitude, so dot product is always zero","sol":"Step 1: Let vector be (x,y)\nStep 2: Dot product is (0×x) + (0×y)\nStep 3: 0 + 0 = 0\nStep 4: Result is always zero","steps":["Step 1: Let vector be (x,y)","Step 2: Dot product is (0×x) + (0×y)","Step 3: 0 + 0 = 0","Step 4: Result is always zero"],"options":[],"conceptId":"math_vectors_dot_product_scalar_product","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Dot Product (Scalar Product)"}', 4),
  (280, 62, 'If a · b = 0, what is angle between vectors?', 'text', 1, 'perpendicular condition', '{"why":"Zero dot product means vectors are perpendicular","sol":"Step 1: Recall dot product formula: |a||b|cos(θ) = 0\nStep 2: If |a| and |b| are nonzero, then cos(θ) must be 0\nStep 3: cos(θ) = 0 when θ = 90° or 270°\nStep 4: These correspond to perpendicular vectors","steps":["Step 1: Recall dot product formula: |a||b|cos(θ) = 0","Step 2: If |a| and |b| are nonzero, then cos(θ) must be 0","Step 3: cos(θ) = 0 when θ = 90° or 270°","Step 4: These correspond to perpendicular vectors"],"options":[],"conceptId":"math_vectors_dot_product_scalar_product","skillId":"math_vectors","subskillId":"math_vectors_q6","subject":"math","chapter":"vectors","topic":"Dot Product (Scalar Product)"}', 5),
  (281, 63, 'How do you add two vectors (2i + 3j) + (4i + 5j)?', 'text', 1, 'add like components', '{"why":"Vector addition is performed component-wise","sol":"Step 1: Group i components → 2i + 4i\nStep 2: Group j components → 3j + 5j\nStep 3: Add i components → 6i\nStep 4: Add j components → 8j\nStep 5: Combine results","steps":["Step 1: Group i components → 2i + 4i","Step 2: Group j components → 3j + 5j","Step 3: Add i components → 6i","Step 4: Add j components → 8j","Step 5: Combine results"],"options":[],"conceptId":"math_vectors_applications_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q1","subject":"math","chapter":"vectors","topic":"Applications of Vectors"}', 0),
  (282, 63, 'How do you subtract vectors (6i + 7j) - (2i + 3j)?', 'text', 1, 'distribute minus sign', '{"why":"Subtraction is done component-wise after distributing minus","sol":"Step 1: Expand subtraction → 6i + 7j - 2i - 3j\nStep 2: Group i components → 6i - 2i\nStep 3: Group j components → 7j - 3j\nStep 4: Simplify components","steps":["Step 1: Expand subtraction → 6i + 7j - 2i - 3j","Step 2: Group i components → 6i - 2i","Step 3: Group j components → 7j - 3j","Step 4: Simplify components"],"options":[],"conceptId":"math_vectors_applications_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q2","subject":"math","chapter":"vectors","topic":"Applications of Vectors"}', 1),
  (283, 63, 'Find resultant of vectors (5i + 2j) + (-3i + 6j)', 'text', 1, 'combine components', '{"why":"Resultant is obtained by adding corresponding components","sol":"Step 1: Add i components → 5 + (-3)\nStep 2: Add j components → 2 + 6\nStep 3: Simplify each component\nStep 4: Write final vector","steps":["Step 1: Add i components → 5 + (-3)","Step 2: Add j components → 2 + 6","Step 3: Simplify each component","Step 4: Write final vector"],"options":[],"conceptId":"math_vectors_applications_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q3","subject":"math","chapter":"vectors","topic":"Applications of Vectors"}', 2),
  (284, 63, 'What is the zero vector in i and j form?', 'text', 1, 'no magnitude', '{"why":"Zero vector has no magnitude or direction","sol":"Step 1: Identify zero movement in x-direction → 0i\nStep 2: Identify zero movement in y-direction → 0j\nStep 3: Combine both components","steps":["Step 1: Identify zero movement in x-direction → 0i","Step 2: Identify zero movement in y-direction → 0j","Step 3: Combine both components"],"options":[],"conceptId":"math_vectors_applications_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q4","subject":"math","chapter":"vectors","topic":"Applications of Vectors"}', 3),
  (285, 63, 'Find the resultant of (3i - 4j) and (-3i + 4j)', 'text', 1, 'opposites cancel', '{"why":"Opposite vectors cancel each other out completely","sol":"Step 1: Add i components → 3 + (-3)\nStep 2: Add j components → -4 + 4\nStep 3: Simplify both results\nStep 4: Write final vector","steps":["Step 1: Add i components → 3 + (-3)","Step 2: Add j components → -4 + 4","Step 3: Simplify both results","Step 4: Write final vector"],"options":[],"conceptId":"math_vectors_applications_of_vectors","skillId":"math_vectors","subskillId":"math_vectors_q5","subject":"math","chapter":"vectors","topic":"Applications of Vectors"}', 4),
  (286, 64, 'Evaluate lim x→3 of (2x + 1)', 'text', 1, 'direct substitution', '{"why":"Polynomials are continuous, so limit equals direct substitution","sol":"Step 1: Identify the function f(x) = 2x + 1\nStep 2: Substitute x = 3 into the expression\nStep 3: Compute 2(3) + 1\nStep 4: Simplify result","steps":["Step 1: Identify the function f(x) = 2x + 1","Step 2: Substitute x = 3 into the expression","Step 3: Compute 2(3) + 1","Step 4: Simplify result"],"options":[],"conceptId":"math_limits_concept_of_limits","skillId":"math_limits","subskillId":"math_limits_q1","subject":"math","chapter":"limits","topic":"Concept of Limits"}', 0),
  (287, 64, 'Evaluate lim x→5 of (x² - 9)', 'text', 1, 'substitute directly', '{"why":"Continuous functions allow direct substitution in limits","sol":"Step 1: Identify expression f(x) = x² - 9\nStep 2: Substitute x = 5\nStep 3: Compute 5² - 9\nStep 4: Simplify result","steps":["Step 1: Identify expression f(x) = x² - 9","Step 2: Substitute x = 5","Step 3: Compute 5² - 9","Step 4: Simplify result"],"options":[],"conceptId":"math_limits_concept_of_limits","skillId":"math_limits","subskillId":"math_limits_q2","subject":"math","chapter":"limits","topic":"Concept of Limits"}', 1),
  (288, 64, 'Find lim x→2 of (3x - 4)', 'text', 1, 'plug in value', '{"why":"Linear functions are continuous, so limit equals function value","sol":"Step 1: Write function f(x) = 3x - 4\nStep 2: Substitute x = 2\nStep 3: Compute 3(2) - 4\nStep 4: Simplify","steps":["Step 1: Write function f(x) = 3x - 4","Step 2: Substitute x = 2","Step 3: Compute 3(2) - 4","Step 4: Simplify"],"options":[],"conceptId":"math_limits_concept_of_limits","skillId":"math_limits","subskillId":"math_limits_q3","subject":"math","chapter":"limits","topic":"Concept of Limits"}', 2),
  (289, 64, 'Find lim x→4 of (x² + 2x)', 'text', 1, 'substitute x', '{"why":"Polynomials are continuous so direct substitution applies","sol":"Step 1: Identify function f(x) = x² + 2x\nStep 2: Substitute x = 4\nStep 3: Compute 4² + 2(4)\nStep 4: Simplify expression","steps":["Step 1: Identify function f(x) = x² + 2x","Step 2: Substitute x = 4","Step 3: Compute 4² + 2(4)","Step 4: Simplify expression"],"options":[],"conceptId":"math_limits_concept_of_limits","skillId":"math_limits","subskillId":"math_limits_q4","subject":"math","chapter":"limits","topic":"Concept of Limits"}', 3),
  (290, 64, 'Evaluate lim x→1 of (5x + 3)', 'text', 1, 'direct substitution method', '{"why":"Linear functions are continuous at all points","sol":"Step 1: Identify function f(x) = 5x + 3\nStep 2: Substitute x = 1\nStep 3: Compute 5(1) + 3\nStep 4: Simplify","steps":["Step 1: Identify function f(x) = 5x + 3","Step 2: Substitute x = 1","Step 3: Compute 5(1) + 3","Step 4: Simplify"],"options":[],"conceptId":"math_limits_concept_of_limits","skillId":"math_limits","subskillId":"math_limits_q5","subject":"math","chapter":"limits","topic":"Concept of Limits"}', 4),
  (291, 65, 'Find lim x→2 of (3x + 1) using one-sided limits', 'text', 1, 'check both sides', '{"why":"Both one-sided limits are equal, so limit exists","sol":"Step 1: Compute lim x→2⁻ (3x + 1)\nStep 2: Substitute x = 2 → 3(2) + 1\nStep 3: Compute left-hand limit = 7\nStep 4: Compute lim x→2⁺ (3x + 1)\nStep 5: Substitute x = 2 → 3(2) + 1 = 7\nStep 6: Compare both sides","steps":["Step 1: Compute lim x→2⁻ (3x + 1)","Step 2: Substitute x = 2 → 3(2) + 1","Step 3: Compute left-hand limit = 7","Step 4: Compute lim x→2⁺ (3x + 1)","Step 5: Substitute x = 2 → 3(2) + 1 = 7","Step 6: Compare both sides"],"options":[],"conceptId":"math_limits_left_hand_and_right_hand_limits","skillId":"math_limits","subskillId":"math_limits_q1","subject":"math","chapter":"limits","topic":"Left-Hand and Right-Hand Limits"}', 0),
  (292, 65, 'Determine if lim x→1 exists for f(x) = {2x if x<1, x+1 if x>1}', 'text', 1, 'piecewise function', '{"why":"Both sides give same approaching value","sol":"Step 1: Compute left-hand limit → 2(1) = 2\nStep 2: Compute right-hand limit → 1 + 1 = 2\nStep 3: Compare LHL and RHL\nStep 4: Check equality condition","steps":["Step 1: Compute left-hand limit → 2(1) = 2","Step 2: Compute right-hand limit → 1 + 1 = 2","Step 3: Compare LHL and RHL","Step 4: Check equality condition"],"options":[],"conceptId":"math_limits_left_hand_and_right_hand_limits","skillId":"math_limits","subskillId":"math_limits_q2","subject":"math","chapter":"limits","topic":"Left-Hand and Right-Hand Limits"}', 1),
  (293, 65, 'Find lim x→4 of f(x) = {x² if x<4, 10 if x>4}', 'text', 1, 'check discontinuity', '{"why":"Left and right limits are not equal","sol":"Step 1: Compute LHL → 4² = 16\nStep 2: Compute RHL → 10\nStep 3: Compare 16 and 10\nStep 4: Check equality condition","steps":["Step 1: Compute LHL → 4² = 16","Step 2: Compute RHL → 10","Step 3: Compare 16 and 10","Step 4: Check equality condition"],"options":[],"conceptId":"math_limits_left_hand_and_right_hand_limits","skillId":"math_limits","subskillId":"math_limits_q3","subject":"math","chapter":"limits","topic":"Left-Hand and Right-Hand Limits"}', 2),
  (294, 65, 'Find lim x→0 of (x² + 5x) using substitution check', 'text', 1, 'approach from both sides', '{"why":"Both sides approach same value","sol":"Step 1: Compute lim x→0⁻ (x² + 5x)\nStep 2: Substitute values close to 0 → result approaches 0\nStep 3: Compute lim x→0⁺ (x² + 5x)\nStep 4: Substitute values close to 0 → result approaches 0\nStep 5: Compare both sides","steps":["Step 1: Compute lim x→0⁻ (x² + 5x)","Step 2: Substitute values close to 0 → result approaches 0","Step 3: Compute lim x→0⁺ (x² + 5x)","Step 4: Substitute values close to 0 → result approaches 0","Step 5: Compare both sides"],"options":[],"conceptId":"math_limits_left_hand_and_right_hand_limits","skillId":"math_limits","subskillId":"math_limits_q4","subject":"math","chapter":"limits","topic":"Left-Hand and Right-Hand Limits"}', 3),
  (295, 65, 'Evaluate lim x→3 of (x² - 9)/(x - 3)', 'text', 1, 'factorization needed', '{"why":"After simplification, direct substitution is possible","sol":"Step 1: Factor numerator → (x - 3)(x + 3)\nStep 2: Simplify expression → cancel (x - 3)\nStep 3: New expression becomes (x + 3)\nStep 4: Substitute x = 3\nStep 5: Compute 3 + 3","steps":["Step 1: Factor numerator → (x - 3)(x + 3)","Step 2: Simplify expression → cancel (x - 3)","Step 3: New expression becomes (x + 3)","Step 4: Substitute x = 3","Step 5: Compute 3 + 3"],"options":[],"conceptId":"math_limits_left_hand_and_right_hand_limits","skillId":"math_limits","subskillId":"math_limits_q5","subject":"math","chapter":"limits","topic":"Left-Hand and Right-Hand Limits"}', 4),
  (296, 65, 'Check if lim x→2 exists for f(x) = {x+2 if x<2, 5 if x>2}', 'text', 1, 'compare LHL and RHL', '{"why":"Left and right limits are different","sol":"Step 1: Compute LHL → 2 + 2 = 4\nStep 2: Compute RHL → 5\nStep 3: Compare 4 and 5\nStep 4: Determine continuity","steps":["Step 1: Compute LHL → 2 + 2 = 4","Step 2: Compute RHL → 5","Step 3: Compare 4 and 5","Step 4: Determine continuity"],"options":[],"conceptId":"math_limits_left_hand_and_right_hand_limits","skillId":"math_limits","subskillId":"math_limits_q6","subject":"math","chapter":"limits","topic":"Left-Hand and Right-Hand Limits"}', 5),
  (297, 66, 'Evaluate lim (x → 2) (x² - 4)/(x - 2)', 'text', 1, 'factor and cancel', '{"why":"Factoring removes the indeterminate form and reveals the simplified function","sol":"Step 1: Substitute x = 2 → (4 - 4)/(0) = 0/0 (indeterminate form)\nStep 2: Factor numerator → x² - 4 = (x - 2)(x + 2)\nStep 3: Rewrite expression → [(x - 2)(x + 2)] / (x - 2)\nStep 4: Cancel common factor (x - 2)\nStep 5: Simplify → x + 2\nStep 6: Substitute x = 2 → 2 + 2","steps":["Step 1: Substitute x = 2 → (4 - 4)/(0) = 0/0 (indeterminate form)","Step 2: Factor numerator → x² - 4 = (x - 2)(x + 2)","Step 3: Rewrite expression → [(x - 2)(x + 2)] / (x - 2)","Step 4: Cancel common factor (x - 2)","Step 5: Simplify → x + 2","Step 6: Substitute x = 2 → 2 + 2"],"options":[],"conceptId":"math_limits_indeterminate_forms","skillId":"math_limits","subskillId":"math_limits_q1","subject":"math","chapter":"limits","topic":"Indeterminate Forms"}', 0),
  (298, 66, 'Evaluate lim (x → 1) (x² - 1)/(x - 1)', 'text', 1, 'difference of squares', '{"why":"The expression simplifies after cancelling the common factor","sol":"Step 1: Substitute x = 1 → (1 - 1)/(0) = 0/0\nStep 2: Factor numerator → x² - 1 = (x - 1)(x + 1)\nStep 3: Rewrite → [(x - 1)(x + 1)] / (x - 1)\nStep 4: Cancel (x - 1)\nStep 5: Simplify → x + 1\nStep 6: Substitute x = 1 → 1 + 1","steps":["Step 1: Substitute x = 1 → (1 - 1)/(0) = 0/0","Step 2: Factor numerator → x² - 1 = (x - 1)(x + 1)","Step 3: Rewrite → [(x - 1)(x + 1)] / (x - 1)","Step 4: Cancel (x - 1)","Step 5: Simplify → x + 1","Step 6: Substitute x = 1 → 1 + 1"],"options":[],"conceptId":"math_limits_indeterminate_forms","skillId":"math_limits","subskillId":"math_limits_q2","subject":"math","chapter":"limits","topic":"Indeterminate Forms"}', 1),
  (299, 66, 'Evaluate lim (x → 3) (x² - 9)/(x - 3)', 'text', 1, 'factor quadratic', '{"why":"Indeterminate form resolves after factoring and cancellation","sol":"Step 1: Substitute x = 3 → (9 - 9)/(0) = 0/0\nStep 2: Factor numerator → x² - 9 = (x - 3)(x + 3)\nStep 3: Rewrite → [(x - 3)(x + 3)] / (x - 3)\nStep 4: Cancel (x - 3)\nStep 5: Simplify → x + 3\nStep 6: Substitute x = 3 → 3 + 3","steps":["Step 1: Substitute x = 3 → (9 - 9)/(0) = 0/0","Step 2: Factor numerator → x² - 9 = (x - 3)(x + 3)","Step 3: Rewrite → [(x - 3)(x + 3)] / (x - 3)","Step 4: Cancel (x - 3)","Step 5: Simplify → x + 3","Step 6: Substitute x = 3 → 3 + 3"],"options":[],"conceptId":"math_limits_indeterminate_forms","skillId":"math_limits","subskillId":"math_limits_q3","subject":"math","chapter":"limits","topic":"Indeterminate Forms"}', 2),
  (300, 66, 'Evaluate lim (x → 4) (x² - 16)/(x - 4)', 'text', 1, 'difference of squares', '{"why":"Canceling the common factor removes the indeterminate form","sol":"Step 1: Substitute x = 4 → (16 - 16)/(0) = 0/0\nStep 2: Factor numerator → x² - 16 = (x - 4)(x + 4)\nStep 3: Cancel (x - 4)\nStep 4: Simplify → x + 4\nStep 5: Substitute x = 4 → 4 + 4","steps":["Step 1: Substitute x = 4 → (16 - 16)/(0) = 0/0","Step 2: Factor numerator → x² - 16 = (x - 4)(x + 4)","Step 3: Cancel (x - 4)","Step 4: Simplify → x + 4","Step 5: Substitute x = 4 → 4 + 4"],"options":[],"conceptId":"math_limits_indeterminate_forms","skillId":"math_limits","subskillId":"math_limits_q4","subject":"math","chapter":"limits","topic":"Indeterminate Forms"}', 3),
  (301, 66, 'Evaluate lim (x → 5) (x² - 25)/(x - 5)', 'text', 1, 'factorization', '{"why":"Factorization resolves the indeterminate expression","sol":"Step 1: Substitute x = 5 → (25 - 25)/(0) = 0/0\nStep 2: Factor numerator → x² - 25 = (x - 5)(x + 5)\nStep 3: Cancel (x - 5)\nStep 4: Simplify → x + 5\nStep 5: Substitute x = 5 → 5 + 5","steps":["Step 1: Substitute x = 5 → (25 - 25)/(0) = 0/0","Step 2: Factor numerator → x² - 25 = (x - 5)(x + 5)","Step 3: Cancel (x - 5)","Step 4: Simplify → x + 5","Step 5: Substitute x = 5 → 5 + 5"],"options":[],"conceptId":"math_limits_indeterminate_forms","skillId":"math_limits","subskillId":"math_limits_q5","subject":"math","chapter":"limits","topic":"Indeterminate Forms"}', 4),
  (302, 67, 'When does lim x→a f(x) exist using one-sided limits?', 'text', 1, 'compare both sides', '{"why":"A limit exists only when both directional values are equal","sol":"Step 1: Compute lim x→a⁻ f(x)\nStep 2: Compute lim x→a⁺ f(x)\nStep 3: Let left-hand limit = L\nStep 4: Let right-hand limit = R\nStep 5: Compare L and R\nStep 6: If L = R, limit exists","steps":["Step 1: Compute lim x→a⁻ f(x)","Step 2: Compute lim x→a⁺ f(x)","Step 3: Let left-hand limit = L","Step 4: Let right-hand limit = R","Step 5: Compare L and R","Step 6: If L = R, limit exists"],"options":[],"conceptId":"math_limits_one_sided_limit_problems","skillId":"math_limits","subskillId":"math_limits_q1","subject":"math","chapter":"limits","topic":"One-Sided Limit Problems"}', 0),
  (303, 67, 'Determine whether a limit exists if lim x→2⁻ f(x) = 5 and lim x→2⁺ f(x) = 5', 'text', 1, 'compare values', '{"why":"Both one-sided limits are equal","sol":"Step 1: Identify left-hand limit = 5\nStep 2: Identify right-hand limit = 5\nStep 3: Compare both values\nStep 4: Check equality condition\nStep 5: Conclude result","steps":["Step 1: Identify left-hand limit = 5","Step 2: Identify right-hand limit = 5","Step 3: Compare both values","Step 4: Check equality condition","Step 5: Conclude result"],"options":[],"conceptId":"math_limits_one_sided_limit_problems","skillId":"math_limits","subskillId":"math_limits_q2","subject":"math","chapter":"limits","topic":"One-Sided Limit Problems"}', 1),
  (304, 67, 'Determine limit existence if lim x→3⁻ f(x) = 4 and lim x→3⁺ f(x) = 7', 'text', 1, 'check discontinuity', '{"why":"Unequal one-sided limits indicate a jump discontinuity","sol":"Step 1: Left-hand limit = 4\nStep 2: Right-hand limit = 7\nStep 3: Compare 4 and 7\nStep 4: Identify inequality\nStep 5: Conclude limit behavior","steps":["Step 1: Left-hand limit = 4","Step 2: Right-hand limit = 7","Step 3: Compare 4 and 7","Step 4: Identify inequality","Step 5: Conclude limit behavior"],"options":[],"conceptId":"math_limits_one_sided_limit_problems","skillId":"math_limits","subskillId":"math_limits_q3","subject":"math","chapter":"limits","topic":"One-Sided Limit Problems"}', 2),
  (305, 67, 'Find result when lim x→5⁻ f(x) = 10 and lim x→5⁺ f(x) = 10', 'text', 1, 'equal sides', '{"why":"Equal one-sided limits confirm continuity at that point","sol":"Step 1: Left-hand limit = 10\nStep 2: Right-hand limit = 10\nStep 3: Compare values\nStep 4: Confirm equality\nStep 5: State final result","steps":["Step 1: Left-hand limit = 10","Step 2: Right-hand limit = 10","Step 3: Compare values","Step 4: Confirm equality","Step 5: State final result"],"options":[],"conceptId":"math_limits_one_sided_limit_problems","skillId":"math_limits","subskillId":"math_limits_q4","subject":"math","chapter":"limits","topic":"One-Sided Limit Problems"}', 3),
  (306, 68, 'Why are limits important?', 'text', 1, 'used in derivatives and integrals', '{"why":"Limits define both differentiation and integration, forming the core of calculus.","sol":"Step 1: Identify key concept: Define the required principles for Applications of Limits.\nStep 2: Apply governing rule: Limits define both differentiation and integration, forming the core of calculus.\nStep 3: State the final conclusion: foundation of calculus","steps":["Step 1: Identify key concept: Define the required principles for Applications of Limits.","Step 2: Apply governing rule: Limits define both differentiation and integration, forming the core of calculus.","Step 3: State the final conclusion: foundation of calculus"],"options":[],"conceptId":"math_limits_applications_of_limits","skillId":"math_limits","subskillId":"math_limits_q1","subject":"math","chapter":"limits","topic":"Applications of Limits"}', 0),
  (307, 68, 'Give one real-world use of limits', 'text', 1, 'motion', '{"why":"Limits are used to calculate velocity at a specific moment in time.","sol":"Step 1: Identify key concept: Define the required principles for Applications of Limits.\nStep 2: Apply governing rule: Limits are used to calculate velocity at a specific moment in time.\nStep 3: State the final conclusion: instantaneous speed","steps":["Step 1: Identify key concept: Define the required principles for Applications of Limits.","Step 2: Apply governing rule: Limits are used to calculate velocity at a specific moment in time.","Step 3: State the final conclusion: instantaneous speed"],"options":[],"conceptId":"math_limits_applications_of_limits","skillId":"math_limits","subskillId":"math_limits_q2","subject":"math","chapter":"limits","topic":"Applications of Limits"}', 1),
  (308, 68, 'What does lim x→a f(x) mean?', 'text', 1, 'approaching value', '{"why":"It represents the value a function gets close to near a specific input.","sol":"Step 1: Identify key concept: Define the required principles for Applications of Limits.\nStep 2: Apply governing rule: It represents the value a function gets close to near a specific input.\nStep 3: State the final conclusion: value f(x) approaches as x nears a","steps":["Step 1: Identify key concept: Define the required principles for Applications of Limits.","Step 2: Apply governing rule: It represents the value a function gets close to near a specific input.","Step 3: State the final conclusion: value f(x) approaches as x nears a"],"options":[],"conceptId":"math_limits_applications_of_limits","skillId":"math_limits","subskillId":"math_limits_q3","subject":"math","chapter":"limits","topic":"Applications of Limits"}', 2),
  (309, 69, 'Find gradient of curve using dy/dx at a point', 'text', 1, 'differentiate then substitute', '{"why":"Gradient of a curve is found using differentiation at a specific point","sol":"Step 1: Start with function y = f(x)\nStep 2: Differentiate to find dy/dx\nStep 3: Substitute the given x-value\nStep 4: Compute gradient at that point","steps":["Step 1: Start with function y = f(x)","Step 2: Differentiate to find dy/dx","Step 3: Substitute the given x-value","Step 4: Compute gradient at that point"],"options":[],"conceptId":"math_differentiation_gradient_of_a_curve","skillId":"math_differentiation","subskillId":"math_differentiation_q1","subject":"math","chapter":"differentiation","topic":"Gradient of a Curve"}', 0),
  (310, 69, 'Find dy/dx for y = x² and evaluate at x = 3', 'text', 1, 'power rule', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 3\nStep 3: Compute 2 × 3\nStep 4: Get final gradient","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 3","Step 3: Compute 2 × 3","Step 4: Get final gradient"],"options":[],"conceptId":"math_differentiation_gradient_of_a_curve","skillId":"math_differentiation","subskillId":"math_differentiation_q2","subject":"math","chapter":"differentiation","topic":"Gradient of a Curve"}', 1),
  (311, 69, 'Find gradient of y = 2x + 3', 'text', 1, 'linear function rule', '{"why":"In linear equations, gradient is the coefficient of x","sol":"Step 1: Identify equation y = mx + c\nStep 2: Recognize coefficient of x\nStep 3: Extract m value\nStep 4: State gradient","steps":["Step 1: Identify equation y = mx + c","Step 2: Recognize coefficient of x","Step 3: Extract m value","Step 4: State gradient"],"options":[],"conceptId":"math_differentiation_gradient_of_a_curve","skillId":"math_differentiation","subskillId":"math_differentiation_q3","subject":"math","chapter":"differentiation","topic":"Gradient of a Curve"}', 2),
  (312, 69, 'Find dy/dx of y = 3x² at x = 2', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = 3x² → dy/dx = 6x\nStep 2: Substitute x = 2\nStep 3: Multiply 6 × 2\nStep 4: Compute gradient","steps":["Step 1: Differentiate y = 3x² → dy/dx = 6x","Step 2: Substitute x = 2","Step 3: Multiply 6 × 2","Step 4: Compute gradient"],"options":[],"conceptId":"math_differentiation_gradient_of_a_curve","skillId":"math_differentiation","subskillId":"math_differentiation_q4","subject":"math","chapter":"differentiation","topic":"Gradient of a Curve"}', 3),
  (313, 70, 'Find rate of change of y with respect to x for y = 3x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Rate of change is found using differentiation and substitution","sol":"Step 1: Start with y = 3x²\nStep 2: Differentiate → dy/dx = 6x\nStep 3: Substitute x = 2\nStep 4: Compute 6 × 2\nStep 5: Final value of rate of change","steps":["Step 1: Start with y = 3x²","Step 2: Differentiate → dy/dx = 6x","Step 3: Substitute x = 2","Step 4: Compute 6 × 2","Step 5: Final value of rate of change"],"options":[],"conceptId":"math_differentiation_rate_of_change","skillId":"math_differentiation","subskillId":"math_differentiation_q1","subject":"math","chapter":"differentiation","topic":"Rate of Change"}', 0),
  (314, 70, 'Find dy/dx for y = 5x at any point', 'text', 1, 'linear rule', '{"why":"Linear functions have constant rate of change equal to slope","sol":"Step 1: Identify y = mx form\nStep 2: Differentiate → dy/dx = 5\nStep 3: Note constant slope\nStep 4: State rate of change","steps":["Step 1: Identify y = mx form","Step 2: Differentiate → dy/dx = 5","Step 3: Note constant slope","Step 4: State rate of change"],"options":[],"conceptId":"math_differentiation_rate_of_change","skillId":"math_differentiation","subskillId":"math_differentiation_q2","subject":"math","chapter":"differentiation","topic":"Rate of Change"}', 1),
  (315, 70, 'A car travels distance s = 4t². Find speed at t = 3', 'text', 1, 'differentiate distance', '{"why":"Speed is rate of change of distance with respect to time","sol":"Step 1: Start with s = 4t²\nStep 2: Differentiate → ds/dt = 8t\nStep 3: Substitute t = 3\nStep 4: Compute 8 × 3\nStep 5: Final speed value","steps":["Step 1: Start with s = 4t²","Step 2: Differentiate → ds/dt = 8t","Step 3: Substitute t = 3","Step 4: Compute 8 × 3","Step 5: Final speed value"],"options":[],"conceptId":"math_differentiation_rate_of_change","skillId":"math_differentiation","subskillId":"math_differentiation_q3","subject":"math","chapter":"differentiation","topic":"Rate of Change"}', 2),
  (316, 70, 'Find rate of change of y = x³ at x = 1', 'text', 1, 'power rule', '{"why":"Derivative gives instantaneous rate of change","sol":"Step 1: Differentiate y = x³ → dy/dx = 3x²\nStep 2: Substitute x = 1\nStep 3: Compute 3 × 1²\nStep 4: Final value","steps":["Step 1: Differentiate y = x³ → dy/dx = 3x²","Step 2: Substitute x = 1","Step 3: Compute 3 × 1²","Step 4: Final value"],"options":[],"conceptId":"math_differentiation_rate_of_change","skillId":"math_differentiation","subskillId":"math_differentiation_q4","subject":"math","chapter":"differentiation","topic":"Rate of Change"}', 3),
  (317, 71, 'Find turning point and determine maximum/minimum for y = -x² + 6x - 5', 'text', 1, 'differentiate and classify', '{"why":"Negative x² means the parabola opens downward, giving a maximum","sol":"Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6\nStep 2: Set dy/dx = 0 → -2x + 6 = 0\nStep 3: Solve → 2x = 6\nStep 4: x = 3\nStep 5: Since coefficient of x² is negative, curve opens downward\nStep 6: Therefore turning point is a maximum","steps":["Step 1: Differentiate y = -x² + 6x - 5 → dy/dx = -2x + 6","Step 2: Set dy/dx = 0 → -2x + 6 = 0","Step 3: Solve → 2x = 6","Step 4: x = 3","Step 5: Since coefficient of x² is negative, curve opens downward","Step 6: Therefore turning point is a maximum"],"options":[],"conceptId":"math_differentiation_maxima_and_minima","skillId":"math_differentiation","subskillId":"math_differentiation_q1","subject":"math","chapter":"differentiation","topic":"Maxima and Minima"}', 0),
  (318, 71, 'Find maximum point of y = -2x² + 8x + 1', 'text', 1, 'dy/dx = 0', '{"why":"Vertex gives highest value because parabola opens downward","sol":"Step 1: Differentiate → dy/dx = -4x + 8\nStep 2: Set dy/dx = 0 → -4x + 8 = 0\nStep 3: Solve → 4x = 8\nStep 4: x = 2\nStep 5: Substitute into original function → y = -2(2²) + 8(2) + 1\nStep 6: y = -8 + 16 + 1 = 9","steps":["Step 1: Differentiate → dy/dx = -4x + 8","Step 2: Set dy/dx = 0 → -4x + 8 = 0","Step 3: Solve → 4x = 8","Step 4: x = 2","Step 5: Substitute into original function → y = -2(2²) + 8(2) + 1","Step 6: y = -8 + 16 + 1 = 9"],"options":[],"conceptId":"math_differentiation_maxima_and_minima","skillId":"math_differentiation","subskillId":"math_differentiation_q2","subject":"math","chapter":"differentiation","topic":"Maxima and Minima"}', 1),
  (319, 71, 'Find minimum point of y = x² + 8x + 12', 'text', 1, 'complete or differentiate', '{"why":"Positive x² means parabola opens upward giving a minimum","sol":"Step 1: Differentiate → dy/dx = 2x + 8\nStep 2: Set dy/dx = 0 → 2x + 8 = 0\nStep 3: Solve → 2x = -8\nStep 4: x = -4\nStep 5: Substitute into function → y = (-4)² + 8(-4) + 12\nStep 6: y = 16 - 32 + 12 = -4","steps":["Step 1: Differentiate → dy/dx = 2x + 8","Step 2: Set dy/dx = 0 → 2x + 8 = 0","Step 3: Solve → 2x = -8","Step 4: x = -4","Step 5: Substitute into function → y = (-4)² + 8(-4) + 12","Step 6: y = 16 - 32 + 12 = -4"],"options":[],"conceptId":"math_differentiation_maxima_and_minima","skillId":"math_differentiation","subskillId":"math_differentiation_q3","subject":"math","chapter":"differentiation","topic":"Maxima and Minima"}', 2),
  (320, 71, 'Find stationary point of y = x² - 10x + 25 and classify it', 'text', 1, 'perfect square form', '{"why":"Perfect square quadratic always has a minimum vertex","sol":"Step 1: Differentiate → dy/dx = 2x - 10\nStep 2: Set dy/dx = 0 → 2x - 10 = 0\nStep 3: Solve → 2x = 10\nStep 4: x = 5\nStep 5: Substitute → y = 25 - 50 + 25 = 0\nStep 6: Since coefficient of x² is positive, it is a minimum","steps":["Step 1: Differentiate → dy/dx = 2x - 10","Step 2: Set dy/dx = 0 → 2x - 10 = 0","Step 3: Solve → 2x = 10","Step 4: x = 5","Step 5: Substitute → y = 25 - 50 + 25 = 0","Step 6: Since coefficient of x² is positive, it is a minimum"],"options":[],"conceptId":"math_differentiation_maxima_and_minima","skillId":"math_differentiation","subskillId":"math_differentiation_q4","subject":"math","chapter":"differentiation","topic":"Maxima and Minima"}', 3),
  (321, 71, 'Find maximum value of y = 3x - x²', 'text', 1, 'rearrange quadratic', '{"why":"Negative x² ensures a maximum at vertex","sol":"Step 1: Rewrite y = -x² + 3x\nStep 2: Differentiate → dy/dx = -2x + 3\nStep 3: Set dy/dx = 0 → -2x + 3 = 0\nStep 4: Solve → 2x = 3\nStep 5: x = 3/2\nStep 6: Substitute → y = 3(3/2) - (3/2)²\nStep 7: y = 9/2 - 9/4 = 9/4","steps":["Step 1: Rewrite y = -x² + 3x","Step 2: Differentiate → dy/dx = -2x + 3","Step 3: Set dy/dx = 0 → -2x + 3 = 0","Step 4: Solve → 2x = 3","Step 5: x = 3/2","Step 6: Substitute → y = 3(3/2) - (3/2)²","Step 7: y = 9/2 - 9/4 = 9/4"],"options":[],"conceptId":"math_differentiation_maxima_and_minima","skillId":"math_differentiation","subskillId":"math_differentiation_q5","subject":"math","chapter":"differentiation","topic":"Maxima and Minima"}', 4),
  (322, 72, 'Find slope of tangent to y = x² at x = 4', 'text', 1, 'differentiate and substitute', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 4\nStep 3: Compute 2 × 4\nStep 4: Final slope value","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 4","Step 3: Compute 2 × 4","Step 4: Final slope value"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q1","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 0),
  (323, 72, 'If tangent slope is 3, what is slope of normal?', 'text', 1, 'negative reciprocal', '{"why":"Perpendicular lines have slopes that multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Use formula slope(normal) = -1/m\nStep 3: Compute -1/3\nStep 4: Final result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Use formula slope(normal) = -1/m","Step 3: Compute -1/3","Step 4: Final result"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q2","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 1),
  (324, 72, 'Find equation of tangent to y = x² at (2, 4)', 'text', 1, 'point-slope form', '{"why":"Tangent is a straight line touching the curve at a point","sol":"Step 1: Differentiate to find slope at x = 2\nStep 2: dy/dx = 2x → slope = 4\nStep 3: Use point (2, 4) and slope 4\nStep 4: Equation: y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate to find slope at x = 2","Step 2: dy/dx = 2x → slope = 4","Step 3: Use point (2, 4) and slope 4","Step 4: Equation: y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q3","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 2),
  (325, 72, 'Find equation of tangent slope for y = x² at x = 2', 'text', 1, 'differentiate then substitute', '{"why":"Tangent slope is found using derivative at a point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2\nStep 3: Compute 2 × 2\nStep 4: Tangent slope = 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2","Step 3: Compute 2 × 2","Step 4: Tangent slope = 4"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q4","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 3),
  (326, 72, 'Find equation of normal slope if tangent slope is 3', 'text', 1, 'negative reciprocal', '{"why":"Normal is perpendicular to tangent, so slopes multiply to -1","sol":"Step 1: Identify tangent slope m = 3\nStep 2: Apply normal formula = -1/m\nStep 3: Substitute values → -1/3\nStep 4: Simplify result","steps":["Step 1: Identify tangent slope m = 3","Step 2: Apply normal formula = -1/m","Step 3: Substitute values → -1/3","Step 4: Simplify result"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q5","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 4),
  (327, 72, 'Find slope of tangent for y = 3x² + 2x at x = 1', 'text', 1, 'differentiate first', '{"why":"Derivative gives slope of tangent at a point","sol":"Step 1: Differentiate y → dy/dx = 6x + 2\nStep 2: Substitute x = 1\nStep 3: Compute 6(1) + 2\nStep 4: Final slope = 8","steps":["Step 1: Differentiate y → dy/dx = 6x + 2","Step 2: Substitute x = 1","Step 3: Compute 6(1) + 2","Step 4: Final slope = 8"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q6","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 5),
  (328, 72, 'Find normal slope if tangent slope is -5', 'text', 1, 'negative reciprocal rule', '{"why":"Normal is perpendicular so slope is negative reciprocal","sol":"Step 1: Tangent slope m = -5\nStep 2: Apply formula -1/m\nStep 3: Compute -1 / (-5)\nStep 4: Simplify result","steps":["Step 1: Tangent slope m = -5","Step 2: Apply formula -1/m","Step 3: Compute -1 / (-5)","Step 4: Simplify result"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q7","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 6),
  (329, 72, 'Find equation of tangent to y = x² at point (2, 4)', 'text', 1, 'first find slope, then use point-slope form', '{"why":"Tangent is a line touching curve at a point; its slope is the derivative value at that point","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: Substitute x = 2 → slope m = 4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation becomes y - 4 = 4(x - 2)\nStep 5: Simplify → y = 4x - 4","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: Substitute x = 2 → slope m = 4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation becomes y - 4 = 4(x - 2)","Step 5: Simplify → y = 4x - 4"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q8","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 7),
  (330, 72, 'Find equation of normal to y = x² at (2, 4)', 'text', 1, 'use perpendicular slope', '{"why":"Normal is perpendicular to tangent at the same point, hence negative reciprocal slope","sol":"Step 1: Slope of tangent at x = 2 is m = 4\nStep 2: Normal slope is perpendicular → -1/4\nStep 3: Use point (2, 4) in y - y₁ = m(x - x₁)\nStep 4: Equation: y - 4 = -1/4(x - 2)\nStep 5: Simplify to standard form","steps":["Step 1: Slope of tangent at x = 2 is m = 4","Step 2: Normal slope is perpendicular → -1/4","Step 3: Use point (2, 4) in y - y₁ = m(x - x₁)","Step 4: Equation: y - 4 = -1/4(x - 2)","Step 5: Simplify to standard form"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q9","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 8),
  (331, 72, 'Find x-intercept of tangent to y = x² at x = 3', 'text', 1, 'first find tangent equation', '{"why":"The tangent line has a specific slope and passes through the point, allowing its intercepts to be calculated","sol":"Step 1: Differentiate y = x² → dy/dx = 2x\nStep 2: At x = 3, slope m = 2(3) = 6\nStep 3: Point is (3, 3²) = (3, 9)\nStep 4: Tangent equation: y - 9 = 6(x - 3)\nStep 5: Set y = 0 to find x-intercept → -9 = 6x - 18\nStep 6: Solve for x → x = 9/6 = 3/2","steps":["Step 1: Differentiate y = x² → dy/dx = 2x","Step 2: At x = 3, slope m = 2(3) = 6","Step 3: Point is (3, 3²) = (3, 9)","Step 4: Tangent equation: y - 9 = 6(x - 3)","Step 5: Set y = 0 to find x-intercept → -9 = 6x - 18","Step 6: Solve for x → x = 9/6 = 3/2"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q10","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 9),
  (332, 72, 'At what x-value is tangent to y = x² parallel to line y = 4x + 1?', 'text', 1, 'slopes must be equal', '{"why":"Parallel lines have equal slopes, so we equate tangent slope to line slope and solve for x","sol":"Step 1: Slope of given line is 4\nStep 2: Slope of tangent is derivative dy/dx = 2x\nStep 3: Set slopes equal → 2x = 4\nStep 4: Solve for x → x = 2","steps":["Step 1: Slope of given line is 4","Step 2: Slope of tangent is derivative dy/dx = 2x","Step 3: Set slopes equal → 2x = 4","Step 4: Solve for x → x = 2"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q11","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 10),
  (333, 72, 'Find the perpendicular distance from origin (0, 0) to tangent of y = x² at x = 4', 'text', 1, 'find tangent equation first', '{"why":"Perpendicular distance formula is used to find distance from origin to the calculated tangent line","sol":"Step 1: At x = 4, slope m = 2(4) = 8\nStep 2: Point is (4, 4²) = (4, 16)\nStep 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0\nStep 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)\nStep 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)\nStep 6: Simplify → distance = 16 / sqrt(65)","steps":["Step 1: At x = 4, slope m = 2(4) = 8","Step 2: Point is (4, 4²) = (4, 16)","Step 3: Tangent equation: y - 16 = 8(x - 4) → 8x - y - 16 = 0","Step 4: Use distance formula from point (x₀, y₀) to line Ax + By + C = 0: distance = |Ax₀ + By₀ + C| / sqrt(A² + B²)","Step 5: For origin (0, 0) and line 8x - y - 16 = 0 → distance = |-16| / sqrt(8² + (-1)²)","Step 6: Simplify → distance = 16 / sqrt(65)"],"options":[],"conceptId":"math_differentiation_tangents_and_normals","skillId":"math_differentiation","subskillId":"math_differentiation_q12","subject":"math","chapter":"differentiation","topic":"Tangents and Normals"}', 11),
  (334, 73, 'Why is differentiation important?', 'text', 1, 'rate of change', '{"why":"It quantifies how one variable changes with respect to another","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It quantifies how one variable changes with respect to another\nStep 3: State the final conclusion: measures change","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It quantifies how one variable changes with respect to another","Step 3: State the final conclusion: measures change"],"options":[],"conceptId":"math_differentiation_applications_of_differentiation","skillId":"math_differentiation","subskillId":"math_differentiation_q1","subject":"math","chapter":"differentiation","topic":"Applications of Differentiation"}', 0),
  (335, 73, 'Give real-life use', 'text', 1, 'motion or business', '{"why":"Used in physics for velocity and in economics for maximizing profit","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit\nStep 3: State the final conclusion: speed or profit optimization","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: Used in physics for velocity and in economics for maximizing profit","Step 3: State the final conclusion: speed or profit optimization"],"options":[],"conceptId":"math_differentiation_applications_of_differentiation","skillId":"math_differentiation","subskillId":"math_differentiation_q2","subject":"math","chapter":"differentiation","topic":"Applications of Differentiation"}', 1),
  (336, 73, 'What does f''(x) represent?', 'text', 1, 'derivative meaning', '{"why":"It represents instantaneous rate of change of a function","sol":"Step 1: Identify key concept: Define the required principles for Applications of Differentiation.\nStep 2: Apply governing rule: It represents instantaneous rate of change of a function\nStep 3: State the final conclusion: rate of change or slope","steps":["Step 1: Identify key concept: Define the required principles for Applications of Differentiation.","Step 2: Apply governing rule: It represents instantaneous rate of change of a function","Step 3: State the final conclusion: rate of change or slope"],"options":[],"conceptId":"math_differentiation_applications_of_differentiation","skillId":"math_differentiation","subskillId":"math_differentiation_q3","subject":"math","chapter":"differentiation","topic":"Applications of Differentiation"}', 2),
  (337, 74, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_integration_area_under_a_curve","skillId":"math_integration","subskillId":"math_integration_q1","subject":"math","chapter":"integration","topic":"Area Under a Curve"}', 0),
  (338, 74, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_integration_area_under_a_curve","skillId":"math_integration","subskillId":"math_integration_q2","subject":"math","chapter":"integration","topic":"Area Under a Curve"}', 1),
  (339, 74, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_integration_area_under_a_curve","skillId":"math_integration","subskillId":"math_integration_q3","subject":"math","chapter":"integration","topic":"Area Under a Curve"}', 2),
  (340, 74, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_integration_area_under_a_curve","skillId":"math_integration","subskillId":"math_integration_q4","subject":"math","chapter":"integration","topic":"Area Under a Curve"}', 3),
  (341, 75, 'Evaluate ∫ x dx', 'text', 1, 'power rule integration', '{"why":"Integration is reverse of differentiation using power rule","sol":"Step 1: Increase power of x by 1 → x¹ becomes x²\nStep 2: Divide by new power → x² / 2\nStep 3: Add constant of integration C\nStep 4: Final expression","steps":["Step 1: Increase power of x by 1 → x¹ becomes x²","Step 2: Divide by new power → x² / 2","Step 3: Add constant of integration C","Step 4: Final expression"],"options":[],"conceptId":"math_integration_indefinite_integrals","skillId":"math_integration","subskillId":"math_integration_q1","subject":"math","chapter":"integration","topic":"Indefinite Integrals"}', 0),
  (342, 75, 'Evaluate ∫ x² dx', 'text', 1, 'increase power', '{"why":"Power rule: add 1 to exponent then divide","sol":"Step 1: Increase exponent → x² becomes x³\nStep 2: Divide by new exponent → x³ / 3\nStep 3: Add constant C\nStep 4: Write final result","steps":["Step 1: Increase exponent → x² becomes x³","Step 2: Divide by new exponent → x³ / 3","Step 3: Add constant C","Step 4: Write final result"],"options":[],"conceptId":"math_integration_indefinite_integrals","skillId":"math_integration","subskillId":"math_integration_q2","subject":"math","chapter":"integration","topic":"Indefinite Integrals"}', 1),
  (343, 75, 'Evaluate definite integral ∫ from 0 to 2 of x dx', 'text', 1, 'area under curve', '{"why":"Definite integrals give net area under curve","sol":"Step 1: Find integral of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 0 → 0²/2 = 0\nStep 4: Subtract upper - lower → 2 - 0\nStep 5: Final answer","steps":["Step 1: Find integral of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 0 → 0²/2 = 0","Step 4: Subtract upper - lower → 2 - 0","Step 5: Final answer"],"options":[],"conceptId":"math_integration_indefinite_integrals","skillId":"math_integration","subskillId":"math_integration_q3","subject":"math","chapter":"integration","topic":"Indefinite Integrals"}', 2),
  (344, 75, 'Evaluate ∫ 3x² dx', 'text', 1, 'constant multiple rule', '{"why":"Constant multiples remain unchanged in integration","sol":"Step 1: Keep constant 3 outside\nStep 2: Integrate x² → x³/3\nStep 3: Multiply → 3 × (x³/3)\nStep 4: Simplify expression\nStep 5: Add +C","steps":["Step 1: Keep constant 3 outside","Step 2: Integrate x² → x³/3","Step 3: Multiply → 3 × (x³/3)","Step 4: Simplify expression","Step 5: Add +C"],"options":[],"conceptId":"math_integration_indefinite_integrals","skillId":"math_integration","subskillId":"math_integration_q4","subject":"math","chapter":"integration","topic":"Indefinite Integrals"}', 3),
  (345, 75, 'Why does integration represent area under a curve?', 'text', 1, 'limit of rectangles', '{"why":"Integration is the limit of summing thin rectangles","sol":"Step 1: Divide area under curve into small rectangles\nStep 2: Approximate each rectangle’s area\nStep 3: Increase number of rectangles\nStep 4: Make width approach zero\nStep 5: Sum becomes exact area","steps":["Step 1: Divide area under curve into small rectangles","Step 2: Approximate each rectangle’s area","Step 3: Increase number of rectangles","Step 4: Make width approach zero","Step 5: Sum becomes exact area"],"options":[],"conceptId":"math_integration_indefinite_integrals","skillId":"math_integration","subskillId":"math_integration_q5","subject":"math","chapter":"integration","topic":"Indefinite Integrals"}', 4),
  (346, 76, 'Evaluate definite integral ∫ from 1 to 2 of x dx', 'text', 1, 'definite integral with limits', '{"why":"Definite integrals calculate net area under a curve between two points","sol":"Step 1: Find antiderivative of x → x²/2\nStep 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2\nStep 3: Substitute lower limit 1 → (1²)/2 = 1/2\nStep 4: Subtract upper limit value from lower limit value\nStep 5: Result = 2 - 1/2 = 3/2","steps":["Step 1: Find antiderivative of x → x²/2","Step 2: Substitute upper limit 2 → (2²)/2 = 4/2 = 2","Step 3: Substitute lower limit 1 → (1²)/2 = 1/2","Step 4: Subtract upper limit value from lower limit value","Step 5: Result = 2 - 1/2 = 3/2"],"options":[],"conceptId":"math_integration_definite_integrals","skillId":"math_integration","subskillId":"math_integration_q1","subject":"math","chapter":"integration","topic":"Definite Integrals"}', 0),
  (347, 76, 'Find area under y = x² from 0 to 3', 'text', 1, 'use definite integral', '{"why":"Definite integral of a function over an interval gives the area under that curve","sol":"Step 1: Set up integral ∫ from 0 to 3 of x² dx\nStep 2: Integrate x² → x³/3\nStep 3: Apply limits → (3³/3) - (0³/3)\nStep 4: Simplify → 27/3 - 0\nStep 5: Final area = 9","steps":["Step 1: Set up integral ∫ from 0 to 3 of x² dx","Step 2: Integrate x² → x³/3","Step 3: Apply limits → (3³/3) - (0³/3)","Step 4: Simplify → 27/3 - 0","Step 5: Final area = 9"],"options":[],"conceptId":"math_integration_definite_integrals","skillId":"math_integration","subskillId":"math_integration_q2","subject":"math","chapter":"integration","topic":"Definite Integrals"}', 1),
  (348, 76, 'Evaluate ∫ from 0 to 1 of (2x + 1) dx', 'text', 1, 'integrate term by term', '{"why":"Integrate each term separately and evaluate over the given interval","sol":"Step 1: Integrate 2x → x²\nStep 2: Integrate 1 → x\nStep 3: Combine → x² + x\nStep 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)\nStep 5: Result = 2 - 0 = 2","steps":["Step 1: Integrate 2x → x²","Step 2: Integrate 1 → x","Step 3: Combine → x² + x","Step 4: Apply limits [0, 1] → (1² + 1) - (0² + 0)","Step 5: Result = 2 - 0 = 2"],"options":[],"conceptId":"math_integration_definite_integrals","skillId":"math_integration","subskillId":"math_integration_q3","subject":"math","chapter":"integration","topic":"Definite Integrals"}', 2),
  (349, 76, 'What is difference between ∫ x dx and ∫₀¹ x dx?', 'text', 1, 'limits vs no limits', '{"why":"Limits define the interval and produce a single value instead of a function","sol":"Step 1: ∫ x dx has no limits\nStep 2: Result is family of functions → x²/2 + C\nStep 3: ∫₀¹ x dx has limits\nStep 4: Result is numerical value → 1/2\nStep 5: Compare both results","steps":["Step 1: ∫ x dx has no limits","Step 2: Result is family of functions → x²/2 + C","Step 3: ∫₀¹ x dx has limits","Step 4: Result is numerical value → 1/2","Step 5: Compare both results"],"options":[],"conceptId":"math_integration_definite_integrals","skillId":"math_integration","subskillId":"math_integration_q4","subject":"math","chapter":"integration","topic":"Definite Integrals"}', 3),
  (350, 77, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_integration_integration_as_reverse_of_differentiation","skillId":"math_integration","subskillId":"math_integration_q1","subject":"math","chapter":"integration","topic":"Integration as Reverse of Differentiation"}', 0),
  (351, 77, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_integration_integration_as_reverse_of_differentiation","skillId":"math_integration","subskillId":"math_integration_q2","subject":"math","chapter":"integration","topic":"Integration as Reverse of Differentiation"}', 1),
  (352, 77, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_integration_integration_as_reverse_of_differentiation","skillId":"math_integration","subskillId":"math_integration_q3","subject":"math","chapter":"integration","topic":"Integration as Reverse of Differentiation"}', 2),
  (353, 77, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_integration_integration_as_reverse_of_differentiation","skillId":"math_integration","subskillId":"math_integration_q4","subject":"math","chapter":"integration","topic":"Integration as Reverse of Differentiation"}', 3),
  (354, 78, 'Find ∫ (2x) dx and verify relationship with differentiation', 'text', 1, 'reverse of derivative', '{"why":"Integration reverses differentiation","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Apply integration rule → increase power of x\nStep 3: ∫ 2x dx = x² + C\nStep 4: Differentiate result → d/dx(x² + C)\nStep 5: Get 2x (original function)","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Apply integration rule → increase power of x","Step 3: ∫ 2x dx = x² + C","Step 4: Differentiate result → d/dx(x² + C)","Step 5: Get 2x (original function)"],"options":[],"conceptId":"math_integration_applications_of_integration","skillId":"math_integration","subskillId":"math_integration_q1","subject":"math","chapter":"integration","topic":"Applications of Integration"}', 0),
  (355, 78, 'Find function if ∫ f(x) dx = x³/3 + C', 'text', 1, 'differentiate result', '{"why":"Differentiation reverses integration","sol":"Step 1: Differentiate both sides\nStep 2: d/dx (x³/3 + C)\nStep 3: Apply power rule → (3x²)/3\nStep 4: Simplify result\nStep 5: Get f(x)","steps":["Step 1: Differentiate both sides","Step 2: d/dx (x³/3 + C)","Step 3: Apply power rule → (3x²)/3","Step 4: Simplify result","Step 5: Get f(x)"],"options":[],"conceptId":"math_integration_applications_of_integration","skillId":"math_integration","subskillId":"math_integration_q2","subject":"math","chapter":"integration","topic":"Applications of Integration"}', 1),
  (356, 78, 'Show that integration adds a constant using ∫ 0 dx', 'text', 1, 'constant rule', '{"why":"Derivative removes constants, integration restores them","sol":"Step 1: Integrate 0 → ∫ 0 dx\nStep 2: Result is constant C\nStep 3: Differentiate C\nStep 4: d/dx(C) = 0\nStep 5: Confirm relationship","steps":["Step 1: Integrate 0 → ∫ 0 dx","Step 2: Result is constant C","Step 3: Differentiate C","Step 4: d/dx(C) = 0","Step 5: Confirm relationship"],"options":[],"conceptId":"math_integration_applications_of_integration","skillId":"math_integration","subskillId":"math_integration_q3","subject":"math","chapter":"integration","topic":"Applications of Integration"}', 2),
  (357, 78, 'If d/dx (x² + 5) = 2x, find integral of 2x', 'text', 1, 'inverse process', '{"why":"Integration reconstructs original function up to a constant","sol":"Step 1: Recognize 2x as derivative of x²\nStep 2: Integrate 2x → x²\nStep 3: Add constant C\nStep 4: Final expression","steps":["Step 1: Recognize 2x as derivative of x²","Step 2: Integrate 2x → x²","Step 3: Add constant C","Step 4: Final expression"],"options":[],"conceptId":"math_integration_applications_of_integration","skillId":"math_integration","subskillId":"math_integration_q4","subject":"math","chapter":"integration","topic":"Applications of Integration"}', 3),
  (358, 79, 'Is 4,572 divisible by 3?', 'text', 1, 'Sum the digits', '{"why":"A number is divisible by 3 if the sum of its digits is divisible by 3 (4 + 5 + 7 + 2 = 18 = 3 × 6).","sol":"Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18\nStep 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)\nStep 3: Conclude: 4,572 is divisible by 3","steps":["Step 1: Compute sum of digits: 4 + 5 + 7 + 2 = 18","Step 2: Check if 18 is divisible by 3: 18 ÷ 3 = 6 (no remainder)","Step 3: Conclude: 4,572 is divisible by 3"],"options":[],"conceptId":"math_number_theory_divisibility_rules","skillId":"math_number_theory","subskillId":"math_number_theory_q1","subject":"math","chapter":"number_theory","topic":"Divisibility Rules"}', 0),
  (359, 79, 'Determine if 3,524 is divisible by 4.', 'text', 1, 'Check last two digits', '{"why":"A number is divisible by 4 if the number formed by its last two digits is divisible by 4 (24 ÷ 4 = 6).","sol":"Step 1: Identify the last two digits: 24\nStep 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6\nStep 3: Conclude: 3,524 is divisible by 4","steps":["Step 1: Identify the last two digits: 24","Step 2: Check if 24 is divisible by 4: 24 ÷ 4 = 6","Step 3: Conclude: 3,524 is divisible by 4"],"options":[],"conceptId":"math_number_theory_divisibility_rules","skillId":"math_number_theory","subskillId":"math_number_theory_q2","subject":"math","chapter":"number_theory","topic":"Divisibility Rules"}', 1),
  (360, 79, 'Is 1,236 divisible by 6?', 'text', 1, 'Check divisibility by both 2 and 3', '{"why":"Divisibility by 6 requires the number to be even and the sum of its digits to be a multiple of 3.","sol":"Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2\nStep 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3\nStep 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6","steps":["Step 1: Check divisibility by 2: last digit is 6 (even) → divisible by 2","Step 2: Check divisibility by 3: 1 + 2 + 3 + 6 = 12, and 12 ÷ 3 = 4 → divisible by 3","Step 3: Conclude: Since divisible by both 2 and 3, it is divisible by 6"],"options":[],"conceptId":"math_number_theory_divisibility_rules","skillId":"math_number_theory","subskillId":"math_number_theory_q3","subject":"math","chapter":"number_theory","topic":"Divisibility Rules"}', 2),
  (361, 79, 'Find the smallest single digit x such that 5,3x2 is divisible by 9.', 'text', 1, 'Sum of digits must be a multiple of 9', '{"why":"Sum of digits is 5 + 3 + x + 2 = 10 + x. The smallest single digit making this divisible by 9 is x = 8 (sum = 18).","sol":"Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10\nStep 2: Set equation: 10 + x = 18 (next multiple of 9)\nStep 3: Solve for x: x = 18 - 10 = 8","steps":["Step 1: Calculate sum of known digits: 5 + 3 + 2 = 10","Step 2: Set equation: 10 + x = 18 (next multiple of 9)","Step 3: Solve for x: x = 18 - 10 = 8"],"options":[],"conceptId":"math_number_theory_divisibility_rules","skillId":"math_number_theory","subskillId":"math_number_theory_q4","subject":"math","chapter":"number_theory","topic":"Divisibility Rules"}', 3),
  (362, 80, 'Calculate 17 mod 5.', 'text', 1, 'Find remainder when 17 is divided by 5', '{"why":"17 divided by 5 yields quotient 3 with remainder 2.","sol":"Step 1: Divide 17 by 5: 17 = 5 × 3 + 2\nStep 2: Identify quotient (3) and remainder (2)\nStep 3: Conclude: 17 mod 5 = 2","steps":["Step 1: Divide 17 by 5: 17 = 5 × 3 + 2","Step 2: Identify quotient (3) and remainder (2)","Step 3: Conclude: 17 mod 5 = 2"],"options":[],"conceptId":"math_number_theory_modular_arithmetic","skillId":"math_number_theory","subskillId":"math_number_theory_q1","subject":"math","chapter":"number_theory","topic":"Modular Arithmetic"}', 0),
  (363, 80, 'Evaluate (14 + 23) mod 6.', 'text', 1, 'Add then take modulo, or take modulo first', '{"why":"14 + 23 = 37. 37 = 6 × 6 + 1, so 37 mod 6 = 1.","sol":"Step 1: 14 mod 6 = 2, and 23 mod 6 = 5\nStep 2: Add remainders: 2 + 5 = 7\nStep 3: Reduce modulo 6: 7 mod 6 = 1","steps":["Step 1: 14 mod 6 = 2, and 23 mod 6 = 5","Step 2: Add remainders: 2 + 5 = 7","Step 3: Reduce modulo 6: 7 mod 6 = 1"],"options":[],"conceptId":"math_number_theory_modular_arithmetic","skillId":"math_number_theory","subskillId":"math_number_theory_q2","subject":"math","chapter":"number_theory","topic":"Modular Arithmetic"}', 1),
  (364, 80, 'Find (7 × 8) mod 5.', 'text', 1, 'Multiply then divide by 5', '{"why":"56 divided by 5 gives remainder 1.","sol":"Step 1: Compute product: 7 × 8 = 56\nStep 2: Divide 56 by 5: 56 = 5 × 11 + 1\nStep 3: Conclude: 56 mod 5 = 1","steps":["Step 1: Compute product: 7 × 8 = 56","Step 2: Divide 56 by 5: 56 = 5 × 11 + 1","Step 3: Conclude: 56 mod 5 = 1"],"options":[],"conceptId":"math_number_theory_modular_arithmetic","skillId":"math_number_theory","subskillId":"math_number_theory_q3","subject":"math","chapter":"number_theory","topic":"Modular Arithmetic"}', 2),
  (365, 80, 'Find 3^4 mod 7.', 'text', 1, 'Compute powers step by step', '{"why":"3^4 = 81. 81 = 7 × 11 + 4, so 81 mod 7 = 4.","sol":"Step 1: 3^2 = 9 ≡ 2 (mod 7)\nStep 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)\nStep 3: 2^2 = 4 (mod 7)","steps":["Step 1: 3^2 = 9 ≡ 2 (mod 7)","Step 2: 3^4 = (3^2)^2 ≡ 2^2 (mod 7)","Step 3: 2^2 = 4 (mod 7)"],"options":[],"conceptId":"math_number_theory_modular_arithmetic","skillId":"math_number_theory","subskillId":"math_number_theory_q4","subject":"math","chapter":"number_theory","topic":"Modular Arithmetic"}', 3),
  (366, 81, 'What is the only even prime number?', 'text', 1, 'Smallest prime', '{"why":"2 is the smallest prime and the only even prime number, because any larger even number is divisible by 2.","sol":"Step 1: Check even numbers: 2, 4, 6, 8...\nStep 2: 2 has only divisors 1 and 2 → prime\nStep 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime","steps":["Step 1: Check even numbers: 2, 4, 6, 8...","Step 2: 2 has only divisors 1 and 2 → prime","Step 3: Any even number > 2 is divisible by 2 → composite. ∴ 2 is the only even prime"],"options":[],"conceptId":"math_number_theory_prime_numbers","skillId":"math_number_theory","subskillId":"math_number_theory_q1","subject":"math","chapter":"number_theory","topic":"Prime Numbers"}', 0),
  (367, 81, 'Find the prime factorization of 60.', 'text', 1, 'Break into prime factors', '{"why":"60 = 4 × 15 = (2 × 2) × (3 × 5) = 2² × 3 × 5.","sol":"Step 1: 60 = 2 × 30\nStep 2: 30 = 2 × 15\nStep 3: 15 = 3 × 5\nStep 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5","steps":["Step 1: 60 = 2 × 30","Step 2: 30 = 2 × 15","Step 3: 15 = 3 × 5","Step 4: Combine prime factors: 2 × 2 × 3 × 5 = 2² × 3 × 5"],"options":[],"conceptId":"math_number_theory_prime_numbers","skillId":"math_number_theory","subskillId":"math_number_theory_q2","subject":"math","chapter":"number_theory","topic":"Prime Numbers"}', 1),
  (368, 81, 'Is 29 a prime or composite number?', 'text', 1, 'Check divisibility by primes ≤ √29 ≈ 5.38 (2, 3, 5)', '{"why":"29 has no divisors other than 1 and itself, making it prime.","sol":"Step 1: Check primes up to √29: 2, 3, 5\nStep 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)\nStep 3: Conclude: 29 has no divisors other than 1 and 29 → Prime","steps":["Step 1: Check primes up to √29: 2, 3, 5","Step 2: 29 is not divisible by 2 (odd), 3 (2+9=11), or 5 (ends in 9)","Step 3: Conclude: 29 has no divisors other than 1 and 29 → Prime"],"options":[],"conceptId":"math_number_theory_prime_numbers","skillId":"math_number_theory","subskillId":"math_number_theory_q3","subject":"math","chapter":"number_theory","topic":"Prime Numbers"}', 2),
  (369, 81, 'Find the greatest common divisor (GCD) of 24 and 36 using prime factorization.', 'text', 1, 'Take lowest power of common prime factors', '{"why":"GCD(24, 36) = 2² × 3 = 12.","sol":"Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²\nStep 2: Identify common prime factors: 2 and 3\nStep 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12","steps":["Step 1: Prime factorize: 24 = 2³ × 3¹, 36 = 2² × 3²","Step 2: Identify common prime factors: 2 and 3","Step 3: Take minimum powers: 2² × 3¹ = 4 × 3 = 12"],"options":[],"conceptId":"math_number_theory_prime_numbers","skillId":"math_number_theory","subskillId":"math_number_theory_q4","subject":"math","chapter":"number_theory","topic":"Prime Numbers"}', 3),
  (370, 82, 'Solve the linear congruence: 2x ≡ 6 (mod 8) for 0 ≤ x < 8.', 'text', 1, 'Check integers 0 through 7 or divide by gcd', '{"why":"2(3) = 6 ≡ 6 (mod 8) and 2(7) = 14 ≡ 6 (mod 8).","sol":"Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions\nStep 2: Divide congruence by 2: x ≡ 3 (mod 4)\nStep 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7","steps":["Step 1: Note gcd(2, 8) = 2. Since 2 divides 6, there are 2 incongruent solutions","Step 2: Divide congruence by 2: x ≡ 3 (mod 4)","Step 3: Find values in range 0 ≤ x < 8: x = 3 and x = 3 + 4 = 7"],"options":[],"conceptId":"math_number_theory_congruence_relations","skillId":"math_number_theory","subskillId":"math_number_theory_q1","subject":"math","chapter":"number_theory","topic":"Congruence Relations"}', 0),
  (371, 82, 'Is 38 ≡ 14 (mod 8)?', 'text', 1, 'Check if (38 - 14) is divisible by 8', '{"why":"38 - 14 = 24, which is a multiple of 8 (8 × 3 = 24).","sol":"Step 1: Calculate difference: 38 - 14 = 24\nStep 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)\nStep 3: Conclude: 38 ≡ 14 (mod 8) is True","steps":["Step 1: Calculate difference: 38 - 14 = 24","Step 2: Check divisibility by 8: 24 ÷ 8 = 3 (exact integer)","Step 3: Conclude: 38 ≡ 14 (mod 8) is True"],"options":[],"conceptId":"math_number_theory_congruence_relations","skillId":"math_number_theory","subskillId":"math_number_theory_q2","subject":"math","chapter":"number_theory","topic":"Congruence Relations"}', 1),
  (372, 82, 'Find the modular inverse of 3 modulo 7.', 'text', 1, 'Find integer x such that 3x ≡ 1 (mod 7)', '{"why":"3 × 5 = 15 ≡ 1 (mod 7), so 5 is the modular multiplicative inverse of 3 modulo 7.","sol":"Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12\nStep 2: 12 mod 7 = 5; next test 3(5) = 15\nStep 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5","steps":["Step 1: Test multiples of 3 modulo 7: 3(1)=3, 3(2)=6, 3(3)=9 ≡ 2, 3(4)=12","Step 2: 12 mod 7 = 5; next test 3(5) = 15","Step 3: 15 mod 7 = 1 (since 15 = 2 × 7 + 1). ∴ inverse is 5"],"options":[],"conceptId":"math_number_theory_congruence_relations","skillId":"math_number_theory","subskillId":"math_number_theory_q3","subject":"math","chapter":"number_theory","topic":"Congruence Relations"}', 2),
  (373, 83, 'Encrypt the letter ''D'' using a Caesar cipher with shift k = 3.', 'text', 1, 'D is letter 3 (A=0, B=1, C=2, D=3). Add shift modulo 26', '{"why":"Shifting ''D'' forward by 3 alphabet positions yields ''G''.","sol":"Step 1: Represent ''D'' as an integer: A=0, B=1, C=2, D=3\nStep 2: Apply shift: E(3) = (3 + 3) mod 26 = 6\nStep 3: Convert 6 back to letter: 0=A, 1=B, 2=C, 3=D, 4=E, 5=F, 6=G","steps":["Step 1: Represent ''D'' as an integer: A=0, B=1, C=2, D=3","Step 2: Apply shift: E(3) = (3 + 3) mod 26 = 6","Step 3: Convert 6 back to letter: 0=A, 1=B, 2=C, 3=D, 4=E, 5=F, 6=G"],"options":[],"conceptId":"math_number_theory_cryptography_basics","skillId":"math_number_theory","subskillId":"math_number_theory_q1","subject":"math","chapter":"number_theory","topic":"Cryptography Basics"}', 0),
  (374, 83, 'What mathematical branch provides the foundation for RSA public key cryptography?', 'text', 1, 'Study of integers and primes', '{"why":"RSA cryptography is based on number theory principles, specifically modular arithmetic and prime factorization.","sol":"Step 1: RSA relies on the difficulty of factoring large composite numbers into prime factors\nStep 2: It uses Euler''s totient theorem and modular arithmetic\nStep 3: Conclude: Number Theory","steps":["Step 1: RSA relies on the difficulty of factoring large composite numbers into prime factors","Step 2: It uses Euler''s totient theorem and modular arithmetic","Step 3: Conclude: Number Theory"],"options":[],"conceptId":"math_number_theory_cryptography_basics","skillId":"math_number_theory","subskillId":"math_number_theory_q2","subject":"math","chapter":"number_theory","topic":"Cryptography Basics"}', 1),
  (375, 83, 'Decrypt the letter ''K'' with Caesar shift k = 4.', 'text', 1, 'Shift backward by 4 positions', '{"why":"Shifting ''K'' backward by 4 positions gives ''G'' (G, H, I, J, K).","sol":"Step 1: Identify alphabet position of ''K'': K is the 11th letter (index 10, A=0)\nStep 2: Shift backwards by 4: (10 - 4) mod 26 = 6\nStep 3: Convert index 6 back to letter: Index 6 corresponds to ''G''","steps":["Step 1: Identify alphabet position of ''K'': K is the 11th letter (index 10, A=0)","Step 2: Shift backwards by 4: (10 - 4) mod 26 = 6","Step 3: Convert index 6 back to letter: Index 6 corresponds to ''G''"],"options":[],"conceptId":"math_number_theory_cryptography_basics","skillId":"math_number_theory","subskillId":"math_number_theory_q3","subject":"math","chapter":"number_theory","topic":"Cryptography Basics"}', 2),
  (376, 84, 'A person walks 10 m forward and 10 m back. Find distance and displacement.', 'text', 1, 'Distance = total path, Displacement = change in position', '{"why":"Distance is total path covered, while displacement depends on change in position.","sol":"Step 1: Forward distance = 10 m\nStep 2: Backward distance = 10 m\nStep 3: Total distance = 10 + 10 = 20 m\nStep 4: Final position = starting point\nStep 5: Displacement = 0 m","steps":["Step 1: Forward distance = 10 m","Step 2: Backward distance = 10 m","Step 3: Total distance = 10 + 10 = 20 m","Step 4: Final position = starting point","Step 5: Displacement = 0 m"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 0),
  (377, 84, 'Why can displacement be zero but distance not?', 'text', 1, 'starting and ending point', '{"why":"If you return to the starting point, displacement becomes zero but distance still adds up.","sol":"Step 1: Identify key concept: Define the required principles for Displacement & Distance.\nStep 2: Apply governing rule: If you return to the starting point, displacement becomes zero but distance still adds up.\nStep 3: State the final conclusion: Because distance measures total path travelled, while displacement depends only on initial and final position.","steps":["Step 1: Identify key concept: Define the required principles for Displacement & Distance.","Step 2: Apply governing rule: If you return to the starting point, displacement becomes zero but distance still adds up.","Step 3: State the final conclusion: Because distance measures total path travelled, while displacement depends only on initial and final position."],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 1),
  (378, 84, 'A car moves 30 m east and then 40 m east. Find distance and displacement.', 'text', 1, 'same direction → add directly', '{"why":"When motion is in one direction, distance equals displacement.","sol":"Step 1: Distance = 30 + 40 = 70 m\nStep 2: Both in same direction (east)\nStep 3: Displacement = 70 m east","steps":["Step 1: Distance = 30 + 40 = 70 m","Step 2: Both in same direction (east)","Step 3: Displacement = 70 m east"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 2),
  (379, 84, 'A person walks 15 m north then 5 m south. Find distance and displacement.', 'text', 1, 'opposite directions → subtract', '{"why":"Displacement depends on net movement, not total path.","sol":"Step 1: Distance = 15 + 5 = 20 m\nStep 2: Net movement = 15 - 5 = 10 m\nStep 3: Direction = north","steps":["Step 1: Distance = 15 + 5 = 20 m","Step 2: Net movement = 15 - 5 = 10 m","Step 3: Direction = north"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 3),
  (380, 84, 'A car travels 100 m east, then 100 m west. Find distance and displacement.', 'text', 1, 'returns to start', '{"why":"Opposite equal movements cancel displacement.","sol":"Step 1: Distance = 100 + 100 = 200 m\nStep 2: Final position = starting point\nStep 3: Displacement = 0 m","steps":["Step 1: Distance = 100 + 100 = 200 m","Step 2: Final position = starting point","Step 3: Displacement = 0 m"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 4),
  (381, 84, 'A person walks 8 m east, then 6 m west. Find displacement.', 'text', 1, 'subtract opposite directions', '{"why":"Displacement is the net movement considering direction.","sol":"Step 1: Identify directions → east and west\nStep 2: Subtract → 8 - 6 = 2\nStep 3: Direction = east","steps":["Step 1: Identify directions → east and west","Step 2: Subtract → 8 - 6 = 2","Step 3: Direction = east"],"options":[],"conceptId":"physics_motion_displacement_distance","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Displacement & Distance"}', 5),
  (382, 85, 'A runner covers 200 m in 25 s. Find speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Speed is the rate of covering distance per unit time.","sol":"Step 1: Identify values → s = 200 m, t = 25 s\nStep 2: Substitute → v = 200 ÷ 25\nStep 3: Calculate → v = 8 m/s","steps":["Step 1: Identify values → s = 200 m, t = 25 s","Step 2: Substitute → v = 200 ÷ 25","Step 3: Calculate → v = 8 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Speed"}', 0),
  (383, 85, 'A car travels 360 km in 6 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed in km/h is calculated using total distance divided by total time.","sol":"Step 1: s = 360 km, t = 6 h\nStep 2: v = 360 ÷ 6\nStep 3: v = 60 km/h","steps":["Step 1: s = 360 km, t = 6 h","Step 2: v = 360 ÷ 6","Step 3: v = 60 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Speed"}', 1),
  (384, 85, 'A body moves 500 m in 50 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed measures how fast distance is covered.","sol":"Step 1: s = 500 m, t = 50 s\nStep 2: v = 500 ÷ 50\nStep 3: v = 10 m/s","steps":["Step 1: s = 500 m, t = 50 s","Step 2: v = 500 ÷ 50","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Speed"}', 2),
  (385, 85, 'A cyclist moves 120 km in 4 hours. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed is distance divided by time.","sol":"Step 1: s = 120 km, t = 4 h\nStep 2: v = 120 ÷ 4\nStep 3: v = 30 km/h","steps":["Step 1: s = 120 km, t = 4 h","Step 2: v = 120 ÷ 4","Step 3: v = 30 km/h"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Speed"}', 3),
  (386, 85, 'A car travels 75 m in 5 s. Find speed.', 'text', 1, 'v = s / t', '{"why":"Speed is proportional to distance and inversely proportional to time.","sol":"Step 1: s = 75 m, t = 5 s\nStep 2: v = 75 ÷ 5\nStep 3: v = 15 m/s","steps":["Step 1: s = 75 m, t = 5 s","Step 2: v = 75 ÷ 5","Step 3: v = 15 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Speed"}', 4),
  (387, 85, 'A train covers 900 m in 30 s. Find speed.', 'text', 1, 'distance ÷ time', '{"why":"Speed measures how quickly distance is covered.","sol":"Step 1: s = 900 m, t = 30 s\nStep 2: v = 900 ÷ 30\nStep 3: v = 30 m/s","steps":["Step 1: s = 900 m, t = 30 s","Step 2: v = 900 ÷ 30","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Speed"}', 5),
  (388, 85, 'A car covers 1.2 km in 60 s. Find speed in m/s.', 'text', 1, 'convert km to m first', '{"why":"Always convert distance into SI units before calculating speed.","sol":"Step 1: Convert 1.2 km → 1200 m\nStep 2: t = 60 s\nStep 3: v = 1200 ÷ 60\nStep 4: v = 20 m/s","steps":["Step 1: Convert 1.2 km → 1200 m","Step 2: t = 60 s","Step 3: v = 1200 ÷ 60","Step 4: v = 20 m/s"],"options":[],"conceptId":"physics_motion_speed","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Speed"}', 6),
  (389, 86, 'A car travels 150 m in 5 s. Find its velocity.', 'text', 1, 'Use v = distance ÷ time', '{"why":"Velocity is the rate of change of displacement with time.","sol":"Step 1: Identify values → s = 150 m, t = 5 s\nStep 2: Substitute into formula → v = 150 ÷ 5\nStep 3: Calculate → v = 30 m/s","steps":["Step 1: Identify values → s = 150 m, t = 5 s","Step 2: Substitute into formula → v = 150 ÷ 5","Step 3: Calculate → v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Velocity"}', 0),
  (390, 86, 'A runner covers 100 m in 20 s. Find velocity.', 'text', 1, 'Use v = s / t', '{"why":"Velocity tells how fast and in what direction an object moves.","sol":"Step 1: s = 100 m, t = 20 s\nStep 2: v = 100 ÷ 20\nStep 3: v = 5 m/s","steps":["Step 1: s = 100 m, t = 20 s","Step 2: v = 100 ÷ 20","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Velocity"}', 1),
  (391, 86, 'A body moves with velocity 12 m/s for 8 s. Find distance covered.', 'text', 1, 'Use s = v × t', '{"why":"Distance is product of velocity and time when motion is uniform.","sol":"Step 1: v = 12 m/s, t = 8 s\nStep 2: s = 12 × 8\nStep 3: s = 96 m","steps":["Step 1: v = 12 m/s, t = 8 s","Step 2: s = 12 × 8","Step 3: s = 96 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Velocity"}', 2),
  (392, 86, 'A train moves 300 m in 10 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity depends on displacement per time.","sol":"Step 1: s = 300 m, t = 10 s\nStep 2: v = 300 ÷ 10\nStep 3: v = 30 m/s","steps":["Step 1: s = 300 m, t = 10 s","Step 2: v = 300 ÷ 10","Step 3: v = 30 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Velocity"}', 3),
  (393, 86, 'A car covers 240 m in 12 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity shows rate of motion.","sol":"Step 1: s = 240 m, t = 12 s\nStep 2: v = 240 ÷ 12\nStep 3: v = 20 m/s","steps":["Step 1: s = 240 m, t = 12 s","Step 2: v = 240 ÷ 12","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Velocity"}', 4),
  (394, 86, 'A cyclist moves 60 m in 6 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is constant motion over time.","sol":"Step 1: s = 60 m, t = 6 s\nStep 2: v = 60 ÷ 6\nStep 3: v = 10 m/s","steps":["Step 1: s = 60 m, t = 6 s","Step 2: v = 60 ÷ 6","Step 3: v = 10 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Velocity"}', 5),
  (395, 86, 'A body travels 500 m in 25 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 500 m, t = 25 s\nStep 2: v = 500 ÷ 25\nStep 3: v = 20 m/s","steps":["Step 1: s = 500 m, t = 25 s","Step 2: v = 500 ÷ 25","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Velocity"}', 6),
  (396, 86, 'A car moves at 15 m/s for 10 s. Find distance.', 'text', 1, 's = vt', '{"why":"Distance is product of velocity and time.","sol":"Step 1: v = 15 m/s, t = 10 s\nStep 2: s = 15 × 10\nStep 3: s = 150 m","steps":["Step 1: v = 15 m/s, t = 10 s","Step 2: s = 15 × 10","Step 3: s = 150 m"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Velocity"}', 7),
  (397, 86, 'A runner moves 200 m in 40 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity measures how fast distance is covered.","sol":"Step 1: s = 200 m, t = 40 s\nStep 2: v = 200 ÷ 40\nStep 3: v = 5 m/s","steps":["Step 1: s = 200 m, t = 40 s","Step 2: v = 200 ÷ 40","Step 3: v = 5 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Velocity"}', 8),
  (398, 86, 'A vehicle covers 360 m in 18 s. Find velocity.', 'text', 1, 'v = s / t', '{"why":"Velocity is displacement per time.","sol":"Step 1: s = 360 m, t = 18 s\nStep 2: v = 360 ÷ 18\nStep 3: v = 20 m/s","steps":["Step 1: s = 360 m, t = 18 s","Step 2: v = 360 ÷ 18","Step 3: v = 20 m/s"],"options":[],"conceptId":"physics_motion_velocity","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Velocity"}', 9),
  (399, 87, 'A car speeds up from 0 m/s to 20 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Acceleration measures change in velocity per unit time.","sol":"Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s\nStep 2: Substitute into formula → a = (20 - 0) / 5\nStep 3: Calculate → a = 4 m/s²","steps":["Step 1: Identify values → u = 0 m/s, v = 20 m/s, t = 5 s","Step 2: Substitute into formula → a = (20 - 0) / 5","Step 3: Calculate → a = 4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Acceleration"}', 0),
  (400, 87, 'A car slows from 30 m/s to 10 m/s in 5 s. Find acceleration.', 'text', 1, 'Use a = (v - u) / t', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: u = 30 m/s, v = 10 m/s, t = 5 s\nStep 2: a = (10 - 30) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 30 m/s, v = 10 m/s, t = 5 s","Step 2: a = (10 - 30) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Acceleration"}', 1),
  (401, 87, 'A bike increases speed from 5 m/s to 25 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The bike is speeding up uniformly.","sol":"Step 1: u = 5, v = 25, t = 10\nStep 2: a = (25 - 5) / 10\nStep 3: a = 20 / 10\nStep 4: a = 2 m/s²","steps":["Step 1: u = 5, v = 25, t = 10","Step 2: a = (25 - 5) / 10","Step 3: a = 20 / 10","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Acceleration"}', 2),
  (402, 87, 'A train slows from 40 m/s to 20 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"The train is decelerating.","sol":"Step 1: u = 40, v = 20, t = 8\nStep 2: a = (20 - 40) / 8\nStep 3: a = -20 / 8\nStep 4: a = -2.5 m/s²","steps":["Step 1: u = 40, v = 20, t = 8","Step 2: a = (20 - 40) / 8","Step 3: a = -20 / 8","Step 4: a = -2.5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Acceleration"}', 3),
  (403, 87, 'A car accelerates from 10 m/s to 30 m/s in 4 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily over time.","sol":"Step 1: u = 10, v = 30, t = 4\nStep 2: a = (30 - 10) / 4\nStep 3: a = 20 / 4\nStep 4: a = 5 m/s²","steps":["Step 1: u = 10, v = 30, t = 4","Step 2: a = (30 - 10) / 4","Step 3: a = 20 / 4","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Acceleration"}', 4),
  (404, 87, 'A body slows from 50 m/s to 10 m/s in 8 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Large negative acceleration shows rapid slowing.","sol":"Step 1: u = 50, v = 10, t = 8\nStep 2: a = (10 - 50) / 8\nStep 3: a = -40 / 8\nStep 4: a = -5 m/s²","steps":["Step 1: u = 50, v = 10, t = 8","Step 2: a = (10 - 50) / 8","Step 3: a = -40 / 8","Step 4: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Acceleration"}', 5),
  (405, 87, 'A motorcycle increases speed from 12 m/s to 24 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Acceleration is constant during motion.","sol":"Step 1: u = 12, v = 24, t = 6\nStep 2: a = (24 - 12) / 6\nStep 3: a = 12 / 6\nStep 4: a = 2 m/s²","steps":["Step 1: u = 12, v = 24, t = 6","Step 2: a = (24 - 12) / 6","Step 3: a = 12 / 6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Acceleration"}', 6),
  (406, 87, 'A bus slows from 60 m/s to 30 m/s in 10 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Bus is decelerating uniformly.","sol":"Step 1: u = 60, v = 30, t = 10\nStep 2: a = (30 - 60) / 10\nStep 3: a = -30 / 10\nStep 4: a = -3 m/s²","steps":["Step 1: u = 60, v = 30, t = 10","Step 2: a = (30 - 60) / 10","Step 3: a = -30 / 10","Step 4: a = -3 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Acceleration"}', 7),
  (407, 87, 'A car increases speed from 8 m/s to 32 m/s in 12 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Speed increases steadily.","sol":"Step 1: u = 8, v = 32, t = 12\nStep 2: a = (32 - 8) / 12\nStep 3: a = 24 / 12\nStep 4: a = 2 m/s²","steps":["Step 1: u = 8, v = 32, t = 12","Step 2: a = (32 - 8) / 12","Step 3: a = 24 / 12","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Acceleration"}', 8),
  (408, 87, 'A train slows from 70 m/s to 40 m/s in 15 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Train slows down steadily.","sol":"Step 1: u = 70, v = 40, t = 15\nStep 2: a = (40 - 70) / 15\nStep 3: a = -30 / 15\nStep 4: a = -2 m/s²","steps":["Step 1: u = 70, v = 40, t = 15","Step 2: a = (40 - 70) / 15","Step 3: a = -30 / 15","Step 4: a = -2 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Acceleration"}', 9),
  (409, 87, 'A car goes from 15 m/s to 45 m/s in 6 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Car gains speed quickly.","sol":"Step 1: u = 15, v = 45, t = 6\nStep 2: a = (45 - 15) / 6\nStep 3: a = 30 / 6\nStep 4: a = 5 m/s²","steps":["Step 1: u = 15, v = 45, t = 6","Step 2: a = (45 - 15) / 6","Step 3: a = 30 / 6","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Acceleration"}', 10),
  (410, 87, 'A vehicle slows from 25 m/s to 5 m/s in 5 s. Find acceleration.', 'text', 1, 'a = (v - u) / t', '{"why":"Vehicle is slowing down steadily.","sol":"Step 1: u = 25, v = 5, t = 5\nStep 2: a = (5 - 25) / 5\nStep 3: a = -20 / 5\nStep 4: a = -4 m/s²","steps":["Step 1: u = 25, v = 5, t = 5","Step 2: a = (5 - 25) / 5","Step 3: a = -20 / 5","Step 4: a = -4 m/s²"],"options":[],"conceptId":"physics_motion_acceleration","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Acceleration"}', 11),
  (411, 88, 'A body starts from rest and accelerates at 2 m/s² for 6 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time from rest.","sol":"Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s\nStep 2: Substitute → v = 0 + (2 × 6)\nStep 3: Multiply → v = 12 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 2 m/s², t = 6 s","Step 2: Substitute → v = 0 + (2 × 6)","Step 3: Multiply → v = 12 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q1","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 0),
  (412, 88, 'A car moves with u = 5 m/s, a = 3 m/s², t = 4 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration adds to initial velocity over time.","sol":"Step 1: Identify values → u = 5, a = 3, t = 4\nStep 2: Multiply → a × t = 12\nStep 3: Add → v = 5 + 12 = 17 m/s","steps":["Step 1: Identify values → u = 5, a = 3, t = 4","Step 2: Multiply → a × t = 12","Step 3: Add → v = 5 + 12 = 17 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q2","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 1),
  (413, 88, 'A body has u = 20 m/s, a = -2 m/s², t = 5 s. Find final velocity.', 'text', 1, 'Negative acceleration means deceleration', '{"why":"Negative acceleration reduces velocity over time.","sol":"Step 1: u = 20, a = -2, t = 5\nStep 2: Multiply → -2 × 5 = -10\nStep 3: v = 20 - 10 = 10 m/s","steps":["Step 1: u = 20, a = -2, t = 5","Step 2: Multiply → -2 × 5 = -10","Step 3: v = 20 - 10 = 10 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q3","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 2),
  (414, 88, 'A body has u = 0 m/s, a = 4 m/s², t = 3 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement increases as object accelerates from rest.","sol":"Step 1: u = 0, a = 4, t = 3\nStep 2: ut = 0\nStep 3: t² = 9\nStep 4: s = 1/2 × 4 × 9\nStep 5: s = 2 × 9 = 18 m","steps":["Step 1: u = 0, a = 4, t = 3","Step 2: ut = 0","Step 3: t² = 9","Step 4: s = 1/2 × 4 × 9","Step 5: s = 2 × 9 = 18 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q4","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 3),
  (415, 88, 'A body moves with u = 8 m/s, a = 2 m/s², t = 5 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement is total distance covered under acceleration.","sol":"Step 1: ut = 8 × 5 = 40\nStep 2: t² = 25\nStep 3: 1/2 × 2 × 25 = 25\nStep 4: s = 40 + 25 = 65 m","steps":["Step 1: ut = 8 × 5 = 40","Step 2: t² = 25","Step 3: 1/2 × 2 × 25 = 25","Step 4: s = 40 + 25 = 65 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q5","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 4),
  (416, 88, 'A body has u = 10 m/s, v = 30 m/s, a = 4 m/s². Find time.', 'text', 1, 'Use v = u + at', '{"why":"Time is found from change in velocity divided by acceleration.","sol":"Step 1: v = 30, u = 10, a = 4\nStep 2: v - u = 20\nStep 3: t = 20 / 4\nStep 4: t = 5 s","steps":["Step 1: v = 30, u = 10, a = 4","Step 2: v - u = 20","Step 3: t = 20 / 4","Step 4: t = 5 s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q6","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 5),
  (417, 88, 'A body has u = 4 m/s, v = 20 m/s, s = 24 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"This equation links velocity change with displacement and acceleration.","sol":"Step 1: 20² = 400\nStep 2: 4² = 16\nStep 3: 400 = 16 + 2a(24)\nStep 4: 400 - 16 = 384\nStep 5: 384 = 48a\nStep 6: a = 8 m/s²","steps":["Step 1: 20² = 400","Step 2: 4² = 16","Step 3: 400 = 16 + 2a(24)","Step 4: 400 - 16 = 384","Step 5: 384 = 48a","Step 6: a = 8 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q7","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 6),
  (418, 88, 'A body has u = 15 m/s, v = 5 m/s, s = 20 m. Find acceleration.', 'text', 1, 'Use v² = u² + 2as', '{"why":"Negative acceleration means the object is slowing down.","sol":"Step 1: 5² = 25\nStep 2: 15² = 225\nStep 3: 25 = 225 + 2a(20)\nStep 4: 25 - 225 = 40a\nStep 5: -200 = 40a\nStep 6: a = -5 m/s²","steps":["Step 1: 5² = 25","Step 2: 15² = 225","Step 3: 25 = 225 + 2a(20)","Step 4: 25 - 225 = 40a","Step 5: -200 = 40a","Step 6: a = -5 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q8","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 7),
  (419, 88, 'A body starts from rest and travels 50 m in 5 s. Find acceleration.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Used when initial velocity is zero.","sol":"Step 1: u = 0, s = 50, t = 5\nStep 2: s = 1/2 a t²\nStep 3: 50 = 1/2 a × 25\nStep 4: 50 = 12.5a\nStep 5: a = 4 m/s²","steps":["Step 1: u = 0, s = 50, t = 5","Step 2: s = 1/2 a t²","Step 3: 50 = 1/2 a × 25","Step 4: 50 = 12.5a","Step 5: a = 4 m/s²"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q9","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 8),
  (420, 88, 'A body has u = 6 m/s, a = 2 m/s², t = 8 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Final velocity depends on initial velocity plus acceleration effect.","sol":"Step 1: a × t = 16\nStep 2: v = 6 + 16\nStep 3: v = 22 m/s","steps":["Step 1: a × t = 16","Step 2: v = 6 + 16","Step 3: v = 22 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q10","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 9),
  (421, 88, 'A car starts from rest and accelerates at 3 m/s² for 5 s. Find final velocity.', 'text', 1, 'Use v = u + at', '{"why":"Acceleration increases velocity over time, so final velocity depends on initial velocity plus change due to acceleration.","sol":"Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s\nStep 2: Substitute into formula → v = 0 + (3 × 5)\nStep 3: Multiply → v = 15 m/s","steps":["Step 1: Identify values → u = 0 m/s, a = 3 m/s², t = 5 s","Step 2: Substitute into formula → v = 0 + (3 × 5)","Step 3: Multiply → v = 15 m/s"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q11","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 10),
  (422, 88, 'A body moves with u = 10 m/s, a = 2 m/s², t = 4 s. Find displacement.', 'text', 1, 'Use s = ut + 1/2 at²', '{"why":"Displacement under acceleration includes both initial motion and extra distance due to speeding up.","sol":"Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s\nStep 2: Calculate first term → ut = 10 × 4 = 40\nStep 3: Calculate second term → 1/2 × 2 × 4²\nStep 4: Square time → 4² = 16\nStep 5: Multiply → 1/2 × 2 × 16 = 16\nStep 6: Add both terms → 40 + 16 = 56 m","steps":["Step 1: Identify values → u = 10 m/s, a = 2 m/s², t = 4 s","Step 2: Calculate first term → ut = 10 × 4 = 40","Step 3: Calculate second term → 1/2 × 2 × 4²","Step 4: Square time → 4² = 16","Step 5: Multiply → 1/2 × 2 × 16 = 16","Step 6: Add both terms → 40 + 16 = 56 m"],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q12","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 11),
  (423, 88, 'When do we use v² = u² + 2as?', 'text', 1, 'no time given', '{"why":"This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","sol":"Step 1: Identify key concept: Define the required principles for Equations of Motion.\nStep 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.\nStep 3: State the final conclusion: When time is not given in the problem.","steps":["Step 1: Identify key concept: Define the required principles for Equations of Motion.","Step 2: Apply governing rule: This equation is used when you need to relate velocity, acceleration, and displacement without involving time.","Step 3: State the final conclusion: When time is not given in the problem."],"options":[],"conceptId":"physics_motion_equations_of_motion","skillId":"physics_motion","subskillId":"physics_motion_q13","subject":"physics","chapter":"motion","topic":"Equations of Motion"}', 12),
  (424, 89, 'What is the role of friction when walking?', 'text', 1, 'grip between surfaces', '{"why":"Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.\nStep 3: State the final conclusion: It provides grip between shoe and ground, preventing slipping and allowing forward movement.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction acts opposite to slipping and allows the foot to push against the ground, enabling forward motion.","Step 3: State the final conclusion: It provides grip between shoe and ground, preventing slipping and allowing forward movement."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Friction"}', 0),
  (425, 89, 'Why do smooth surfaces have less friction?', 'text', 1, 'surface irregularities', '{"why":"Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.\nStep 3: State the final conclusion: Because they have fewer irregularities, so surfaces slide more easily.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction is caused by microscopic bumps on surfaces. Smoother surfaces reduce interlocking between these bumps.","Step 3: State the final conclusion: Because they have fewer irregularities, so surfaces slide more easily."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Friction"}', 1),
  (426, 89, 'Is friction always bad? Explain.', 'text', 1, 'useful and harmful effects', '{"why":"Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.","sol":"Step 1: Identify key concept: Define the required principles for Friction.\nStep 2: Apply governing rule: Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.\nStep 3: State the final conclusion: No, friction is necessary for walking, braking, writing, and many daily activities.","steps":["Step 1: Identify key concept: Define the required principles for Friction.","Step 2: Apply governing rule: Friction is both useful (movement control) and harmful (wear and energy loss), depending on the situation.","Step 3: State the final conclusion: No, friction is necessary for walking, braking, writing, and many daily activities."],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Friction"}', 2),
  (427, 89, 'A force of 50 N is applied to move a box, and friction force is 20 N. Find the resultant force.', 'text', 1, 'net force = applied force − friction', '{"why":"Friction opposes motion, reducing the effective force.","sol":"Step 1: Identify values → applied force = 50 N, friction = 20 N\nStep 2: Apply formula → F_net = 50 − 20\nStep 3: Calculate → F_net = 30 N","steps":["Step 1: Identify values → applied force = 50 N, friction = 20 N","Step 2: Apply formula → F_net = 50 − 20","Step 3: Calculate → F_net = 30 N"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Friction"}', 3),
  (428, 89, 'A 10 kg object is pulled with a force of 15 N against friction. Will it move?', 'text', 1, 'compare forces', '{"why":"An object moves only when applied force exceeds friction.","sol":"Step 1: Identify applied force = 15 N\nStep 2: Compare with friction (assume friction = 15 N threshold)\nStep 3: If equal or less → no acceleration\nStep 4: Conclusion → object is just about to move or stays at rest","steps":["Step 1: Identify applied force = 15 N","Step 2: Compare with friction (assume friction = 15 N threshold)","Step 3: If equal or less → no acceleration","Step 4: Conclusion → object is just about to move or stays at rest"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Friction"}', 4),
  (429, 89, 'A box is pushed with 25 N and friction is 10 N. Find net force and motion direction.', 'text', 1, 'net force = difference', '{"why":"Net force determines both magnitude and direction of motion.","sol":"Step 1: Applied force = 25 N, friction = 10 N\nStep 2: F_net = 25 − 10\nStep 3: F_net = 15 N\nStep 4: Direction is same as applied force","steps":["Step 1: Applied force = 25 N, friction = 10 N","Step 2: F_net = 25 − 10","Step 3: F_net = 15 N","Step 4: Direction is same as applied force"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Friction"}', 5),
  (430, 89, 'A surface has friction of 6 N. A force of 6 N is applied. What happens?', 'text', 1, 'balanced forces', '{"why":"When forces are balanced, there is no change in motion.","sol":"Step 1: Applied = 6 N, friction = 6 N\nStep 2: F_net = 6 − 6\nStep 3: F_net = 0 N\nStep 4: No acceleration occurs","steps":["Step 1: Applied = 6 N, friction = 6 N","Step 2: F_net = 6 − 6","Step 3: F_net = 0 N","Step 4: No acceleration occurs"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Friction"}', 6),
  (431, 89, 'A 5 kg object is pushed with 40 N and friction is 15 N. Find acceleration (take g not needed).', 'text', 1, 'F = ma and net force first', '{"why":"Acceleration depends on net force after friction is considered.","sol":"Step 1: Find net force → 40 − 15 = 25 N\nStep 2: Use F = ma\nStep 3: a = F/m = 25/5\nStep 4: a = 5 m/s²","steps":["Step 1: Find net force → 40 − 15 = 25 N","Step 2: Use F = ma","Step 3: a = F/m = 25/5","Step 4: a = 5 m/s²"],"options":[],"conceptId":"physics_forces_friction","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Friction"}', 7),
  (432, 90, 'A mass of 8 kg is hanging on a rope. Find its weight.', 'text', 1, 'Use W = mg', '{"why":"Weight is the gravitational force acting on a mass.","sol":"Step 1: Identify values → m = 8 kg, g = 10 m/s²\nStep 2: Substitute → W = 8 × 10\nStep 3: Multiply → W = 80 N","steps":["Step 1: Identify values → m = 8 kg, g = 10 m/s²","Step 2: Substitute → W = 8 × 10","Step 3: Multiply → W = 80 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 0),
  (433, 90, 'What happens to weight on the Moon?', 'text', 1, 'gravity is weaker', '{"why":"Mass stays constant, but weight changes because it depends on gravitational field strength.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Mass stays constant, but weight changes because it depends on gravitational field strength.\nStep 3: State the final conclusion: Weight decreases because gravitational field strength is lower.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Mass stays constant, but weight changes because it depends on gravitational field strength.","Step 3: State the final conclusion: Weight decreases because gravitational field strength is lower."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 1),
  (434, 90, 'What direction does tension act?', 'text', 1, 'along rope', '{"why":"Tension is a pulling force transmitted through a string, rope, or cable.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Tension is a pulling force transmitted through a string, rope, or cable.\nStep 3: State the final conclusion: Along the rope, always pulling away from the object.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Tension is a pulling force transmitted through a string, rope, or cable.","Step 3: State the final conclusion: Along the rope, always pulling away from the object."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 2),
  (435, 90, 'A 5 kg object is on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight increases directly with mass.","sol":"Step 1: m = 5 kg, g = 10 m/s²\nStep 2: W = 5 × 10\nStep 3: W = 50 N","steps":["Step 1: m = 5 kg, g = 10 m/s²","Step 2: W = 5 × 10","Step 3: W = 50 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 3),
  (436, 90, 'A 12 kg object is lifted on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight is the force due to gravity acting on a mass.","sol":"Step 1: m = 12 kg, g = 10 m/s²\nStep 2: W = 12 × 10\nStep 3: W = 120 N","steps":["Step 1: m = 12 kg, g = 10 m/s²","Step 2: W = 12 × 10","Step 3: W = 120 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 4),
  (437, 90, 'A 3 kg object is on the Moon where g = 1.6 m/s². Find its weight.', 'text', 1, 'use W = mg', '{"why":"Weight depends on gravitational field strength.","sol":"Step 1: m = 3 kg, g = 1.6 m/s²\nStep 2: W = 3 × 1.6\nStep 3: W = 4.8 N","steps":["Step 1: m = 3 kg, g = 1.6 m/s²","Step 2: W = 3 × 1.6","Step 3: W = 4.8 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 5),
  (438, 90, 'A 6 kg object experiences a force of 60 N. Find acceleration.', 'text', 1, 'Use F = ma', '{"why":"Acceleration depends on force and mass.","sol":"Step 1: F = 60 N, m = 6 kg\nStep 2: a = F / m\nStep 3: a = 60 / 6\nStep 4: a = 10 m/s²","steps":["Step 1: F = 60 N, m = 6 kg","Step 2: a = F / m","Step 3: a = 60 / 6","Step 4: a = 10 m/s²"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 6),
  (439, 90, 'A 10 kg object has weight 100 N. Find gravitational field strength.', 'text', 1, 'g = W / m', '{"why":"Gravitational field strength is weight per unit mass.","sol":"Step 1: W = 100 N, m = 10 kg\nStep 2: g = 100 / 10\nStep 3: g = 10 m/s²","steps":["Step 1: W = 100 N, m = 10 kg","Step 2: g = 100 / 10","Step 3: g = 10 m/s²"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 7),
  (440, 90, 'Why do objects fall towards Earth?', 'text', 1, 'attractive force', '{"why":"Gravity pulls all objects with mass toward the center of the Earth.","sol":"Step 1: Identify key concept: Define the required principles for Tension & Weight.\nStep 2: Apply governing rule: Gravity pulls all objects with mass toward the center of the Earth.\nStep 3: State the final conclusion: Because Earth exerts a gravitational force on all objects.","steps":["Step 1: Identify key concept: Define the required principles for Tension & Weight.","Step 2: Apply governing rule: Gravity pulls all objects with mass toward the center of the Earth.","Step 3: State the final conclusion: Because Earth exerts a gravitational force on all objects."],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 8),
  (441, 90, 'A 2 kg object is taken to a planet where g = 5 m/s². Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight changes with gravitational field strength.","sol":"Step 1: m = 2 kg, g = 5 m/s²\nStep 2: W = 2 × 5\nStep 3: W = 10 N","steps":["Step 1: m = 2 kg, g = 5 m/s²","Step 2: W = 2 × 5","Step 3: W = 10 N"],"options":[],"conceptId":"physics_forces_tension_weight","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Tension & Weight"}', 9),
  (442, 91, 'What force keeps a car moving in a circular path?', 'text', 1, 'towards centre', '{"why":"Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.\nStep 3: State the final conclusion: Friction provides centripetal force.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Friction between the tyres and the road acts towards the centre of the circle, keeping the car in circular motion.","Step 3: State the final conclusion: Friction provides centripetal force."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 0),
  (443, 91, 'What provides centripetal force for a satellite?', 'text', 1, 'Earth attraction', '{"why":"The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.\nStep 3: State the final conclusion: Gravity.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: The gravitational force between Earth and the satellite acts as the centripetal force that keeps it in orbit.","Step 3: State the final conclusion: Gravity."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 1),
  (444, 91, 'Why are roads banked on curves?', 'text', 1, 'safe turning', '{"why":"Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.\nStep 3: State the final conclusion: To reduce reliance on friction and help vehicles turn safely at higher speeds.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Banking provides an additional component of normal reaction force towards the centre, reducing dependence on friction.","Step 3: State the final conclusion: To reduce reliance on friction and help vehicles turn safely at higher speeds."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 2),
  (445, 91, 'What happens if a string holding a rotating stone breaks?', 'text', 1, 'inertia', '{"why":"When the centripetal force is removed, the stone continues in the direction it was moving at that instant.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: When the centripetal force is removed, the stone continues in the direction it was moving at that instant.\nStep 3: State the final conclusion: The stone moves in a straight line due to inertia.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: When the centripetal force is removed, the stone continues in the direction it was moving at that instant.","Step 3: State the final conclusion: The stone moves in a straight line due to inertia."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 3),
  (446, 91, 'A car moves in a circle of radius 10 m at a speed of 5 m/s. Find centripetal acceleration.', 'text', 1, 'use a = v²/r', '{"why":"Centripetal acceleration depends on speed and radius of the circular path.","sol":"Step 1: Identify values → v = 5 m/s, r = 10 m\nStep 2: Apply formula → a = v² / r\nStep 3: Square velocity → 5² = 25\nStep 4: Substitute → a = 25 / 10\nStep 5: Calculate → a = 2.5 m/s²","steps":["Step 1: Identify values → v = 5 m/s, r = 10 m","Step 2: Apply formula → a = v² / r","Step 3: Square velocity → 5² = 25","Step 4: Substitute → a = 25 / 10","Step 5: Calculate → a = 2.5 m/s²"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 4),
  (447, 91, 'A stone of mass 2 kg moves in a circle of radius 4 m at speed 3 m/s. Find centripetal force.', 'text', 1, 'use F = mv²/r', '{"why":"Centripetal force increases with mass and speed, and decreases with radius.","sol":"Step 1: m = 2 kg, v = 3 m/s, r = 4 m\nStep 2: Square velocity → 3² = 9\nStep 3: Apply formula → F = (2 × 9) / 4\nStep 4: Multiply → F = 18 / 4\nStep 5: Final answer → F = 4.5 N","steps":["Step 1: m = 2 kg, v = 3 m/s, r = 4 m","Step 2: Square velocity → 3² = 9","Step 3: Apply formula → F = (2 × 9) / 4","Step 4: Multiply → F = 18 / 4","Step 5: Final answer → F = 4.5 N"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 5),
  (448, 91, 'A satellite orbits Earth at constant speed. If gravity is 800 N, what force keeps it in orbit?', 'text', 1, 'centripetal = gravity', '{"why":"For satellites, gravity alone provides the centripetal force.","sol":"Step 1: Identify forces acting → gravity acts inward\nStep 2: Recognize circular motion condition\nStep 3: Centripetal force equals gravitational force\nStep 4: Therefore F = 800 N","steps":["Step 1: Identify forces acting → gravity acts inward","Step 2: Recognize circular motion condition","Step 3: Centripetal force equals gravitational force","Step 4: Therefore F = 800 N"],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 6),
  (449, 91, 'Why does an object in circular motion need a force?', 'text', 1, 'changing direction', '{"why":"Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.","sol":"Step 1: Identify key concept: Define the required principles for Circular Motion.\nStep 2: Apply governing rule: Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.\nStep 3: State the final conclusion: Because its direction is constantly changing.","steps":["Step 1: Identify key concept: Define the required principles for Circular Motion.","Step 2: Apply governing rule: Even if speed is constant, velocity changes due to continuous change in direction, requiring centripetal force.","Step 3: State the final conclusion: Because its direction is constantly changing."],"options":[],"conceptId":"physics_forces_circular_motion","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Circular Motion"}', 7),
  (450, 92, 'What is the value of g on Earth?', 'text', 1, 'acceleration due to gravity', '{"why":"The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.\nStep 3: State the final conclusion: 10 m/s² (approx)","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: The standard value of gravitational acceleration on Earth is approximately 9.8 m/s², often rounded to 10 m/s² in basic calculations.","Step 3: State the final conclusion: 10 m/s² (approx)"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Gravitation"}', 0),
  (451, 92, 'What happens to gravitational force when distance increases?', 'text', 1, 'inverse square law', '{"why":"Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.\nStep 3: State the final conclusion: It decreases rapidly (inverse square law).","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravitational force is inversely proportional to the square of the distance between two masses, meaning it becomes weaker as distance increases.","Step 3: State the final conclusion: It decreases rapidly (inverse square law)."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Gravitation"}', 1),
  (452, 92, 'Is gravity only on Earth? Explain.', 'text', 1, 'universal force', '{"why":"Gravity is a universal force that attracts all objects with mass, not just those on Earth.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravity is a universal force that attracts all objects with mass, not just those on Earth.\nStep 3: State the final conclusion: No, gravity exists between all objects with mass in the universe.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravity is a universal force that attracts all objects with mass, not just those on Earth.","Step 3: State the final conclusion: No, gravity exists between all objects with mass in the universe."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Gravitation"}', 2),
  (453, 92, 'A mass of 2 kg is acted on by gravity. Find its weight on Earth.', 'text', 1, 'use W = mg', '{"why":"Weight is the gravitational force acting on an object.","sol":"Step 1: Identify values → m = 2 kg, g = 10 m/s²\nStep 2: Apply formula → W = m × g\nStep 3: Substitute → W = 2 × 10\nStep 4: Calculate → W = 20 N","steps":["Step 1: Identify values → m = 2 kg, g = 10 m/s²","Step 2: Apply formula → W = m × g","Step 3: Substitute → W = 2 × 10","Step 4: Calculate → W = 20 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Gravitation"}', 3),
  (454, 92, 'A 5 kg object is on Earth. Find its weight.', 'text', 1, 'W = mg', '{"why":"Weight increases with mass.","sol":"Step 1: m = 5 kg, g = 10 m/s²\nStep 2: W = 5 × 10\nStep 3: W = 50 N","steps":["Step 1: m = 5 kg, g = 10 m/s²","Step 2: W = 5 × 10","Step 3: W = 50 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Gravitation"}', 4),
  (455, 92, 'A 3 kg object is taken to the Moon where g = 1.6 m/s². Find weight.', 'text', 1, 'W = mg', '{"why":"Weight depends on gravitational field strength.","sol":"Step 1: m = 3 kg, g = 1.6 m/s²\nStep 2: W = 3 × 1.6\nStep 3: W = 4.8 N","steps":["Step 1: m = 3 kg, g = 1.6 m/s²","Step 2: W = 3 × 1.6","Step 3: W = 4.8 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Gravitation"}', 5),
  (456, 92, 'A planet has g = 20 m/s². Find weight of a 2 kg object.', 'text', 1, 'W = mg', '{"why":"Stronger gravity produces greater weight.","sol":"Step 1: m = 2 kg, g = 20 m/s²\nStep 2: W = 2 × 20\nStep 3: W = 40 N","steps":["Step 1: m = 2 kg, g = 20 m/s²","Step 2: W = 2 × 20","Step 3: W = 40 N"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Gravitation"}', 6),
  (457, 92, 'Why do objects fall towards Earth?', 'text', 1, 'attractive force', '{"why":"Gravity pulls all objects with mass towards the center of Earth.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Gravity pulls all objects with mass towards the center of Earth.\nStep 3: State the final conclusion: Because Earth exerts a gravitational force on all objects.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Gravity pulls all objects with mass towards the center of Earth.","Step 3: State the final conclusion: Because Earth exerts a gravitational force on all objects."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Gravitation"}', 7),
  (458, 92, 'What is the difference between mass and weight?', 'text', 1, 'gravity dependence', '{"why":"Mass is the amount of matter, while weight is the force due to gravity.","sol":"Step 1: Identify key concept: Define the required principles for Gravitation.\nStep 2: Apply governing rule: Mass is the amount of matter, while weight is the force due to gravity.\nStep 3: State the final conclusion: Mass is constant, weight depends on gravity.","steps":["Step 1: Identify key concept: Define the required principles for Gravitation.","Step 2: Apply governing rule: Mass is the amount of matter, while weight is the force due to gravity.","Step 3: State the final conclusion: Mass is constant, weight depends on gravity."],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Gravitation"}', 8),
  (459, 92, 'A 4 kg object is taken from Earth (g = 10 m/s²) to a planet where g = 5 m/s². Find change in weight.', 'text', 1, 'W = mg', '{"why":"Weight decreases when gravitational field strength decreases.","sol":"Step 1: Earth weight → W₁ = 4 × 10 = 40 N\nStep 2: New weight → W₂ = 4 × 5 = 20 N\nStep 3: Change in weight → 40 - 20\nStep 4: Result → 20 N decrease","steps":["Step 1: Earth weight → W₁ = 4 × 10 = 40 N","Step 2: New weight → W₂ = 4 × 5 = 20 N","Step 3: Change in weight → 40 - 20","Step 4: Result → 20 N decrease"],"options":[],"conceptId":"physics_forces_gravitation","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Gravitation"}', 9),
  (460, 93, 'State Newton’s First Law of Motion.', 'text', 1, 'inertia', '{"why":"This law is also called the law of inertia because objects resist changes in their state of motion.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: This law is also called the law of inertia because objects resist changes in their state of motion.\nStep 3: State the final conclusion: An object remains at rest or in uniform motion unless acted upon by a net external force.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: This law is also called the law of inertia because objects resist changes in their state of motion.","Step 3: State the final conclusion: An object remains at rest or in uniform motion unless acted upon by a net external force."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q1","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 0),
  (461, 93, 'What is the formula for Newton’s Second Law?', 'text', 1, 'force, mass, acceleration', '{"why":"Force is directly proportional to mass and acceleration of an object.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Force is directly proportional to mass and acceleration of an object.\nStep 3: State the final conclusion: F = ma","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Force is directly proportional to mass and acceleration of an object.","Step 3: State the final conclusion: F = ma"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q2","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 1),
  (462, 93, 'Why do rockets move upward?', 'text', 1, 'action-reaction', '{"why":"Newton’s Third Law explains rocket propulsion through equal and opposite forces.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Newton’s Third Law explains rocket propulsion through equal and opposite forces.\nStep 3: State the final conclusion: Because of action-reaction: gases are pushed downward, and the rocket is pushed upward.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Newton’s Third Law explains rocket propulsion through equal and opposite forces.","Step 3: State the final conclusion: Because of action-reaction: gases are pushed downward, and the rocket is pushed upward."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q3","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 2),
  (463, 93, 'A force of 10N acts on a mass of 2kg. Find acceleration.', 'text', 1, 'use F = ma', '{"why":"Acceleration increases when force increases or mass decreases.","sol":"Step 1: Write values → F = 10N, m = 2kg\nStep 2: Apply formula → a = F/m\nStep 3: Substitute → a = 10/2\nStep 4: Calculate → a = 5 m/s²","steps":["Step 1: Write values → F = 10N, m = 2kg","Step 2: Apply formula → a = F/m","Step 3: Substitute → a = 10/2","Step 4: Calculate → a = 5 m/s²"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q4","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 3),
  (464, 93, 'A 4kg object accelerates at 3 m/s². Find force.', 'text', 1, 'F = ma', '{"why":"Force depends on both mass and acceleration.","sol":"Step 1: m = 4kg, a = 3 m/s²\nStep 2: Substitute → F = 4 × 3\nStep 3: Calculate → F = 12N","steps":["Step 1: m = 4kg, a = 3 m/s²","Step 2: Substitute → F = 4 × 3","Step 3: Calculate → F = 12N"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q5","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 4),
  (465, 93, 'What does Newton’s Third Law state?', 'text', 1, 'action-reaction', '{"why":"Forces always occur in pairs acting on different objects.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: Forces always occur in pairs acting on different objects.\nStep 3: State the final conclusion: For every action, there is an equal and opposite reaction.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: Forces always occur in pairs acting on different objects.","Step 3: State the final conclusion: For every action, there is an equal and opposite reaction."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q6","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 5),
  (466, 93, 'A 6kg object is acted on by a 12N force. Find acceleration.', 'text', 1, 'F = ma', '{"why":"Acceleration is directly proportional to force.","sol":"Step 1: F = 12N, m = 6kg\nStep 2: a = F/m\nStep 3: a = 12/6\nStep 4: a = 2 m/s²","steps":["Step 1: F = 12N, m = 6kg","Step 2: a = F/m","Step 3: a = 12/6","Step 4: a = 2 m/s²"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q7","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 6),
  (467, 93, 'Why do passengers move forward when a bus stops suddenly?', 'text', 1, 'inertia', '{"why":"The lower part stops with the bus, but the upper body continues moving.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: The lower part stops with the bus, but the upper body continues moving.\nStep 3: State the final conclusion: Because of inertia, their bodies continue moving forward.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: The lower part stops with the bus, but the upper body continues moving.","Step 3: State the final conclusion: Because of inertia, their bodies continue moving forward."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q8","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 7),
  (468, 93, 'A force of 30N produces an acceleration of 5 m/s². Find mass.', 'text', 1, 'rearrange F = ma', '{"why":"Mass is resistance to acceleration.","sol":"Step 1: F = 30N, a = 5 m/s²\nStep 2: m = F/a\nStep 3: m = 30/5\nStep 4: m = 6kg","steps":["Step 1: F = 30N, a = 5 m/s²","Step 2: m = F/a","Step 3: m = 30/5","Step 4: m = 6kg"],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q9","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 8),
  (469, 93, 'What is inertia?', 'text', 1, 'resistance to change', '{"why":"More mass means more inertia.","sol":"Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.\nStep 2: Apply governing rule: More mass means more inertia.\nStep 3: State the final conclusion: The tendency of an object to resist changes in its state of motion.","steps":["Step 1: Identify key concept: Define the required principles for Newton''s Laws of Motion.","Step 2: Apply governing rule: More mass means more inertia.","Step 3: State the final conclusion: The tendency of an object to resist changes in its state of motion."],"options":[],"conceptId":"physics_forces_newton_s_laws_of_motion","skillId":"physics_forces","subskillId":"physics_forces_q10","subject":"physics","chapter":"forces","topic":"Newton''s Laws of Motion"}', 9),
  (470, 94, 'A force of 20N moves an object 3m. Find work done.', 'text', 1, 'Use W = F × d', '{"why":"Work is done when a force causes displacement in its direction.","sol":"Step 1: Identify values → F = 20 N, d = 3 m\nStep 2: Write formula → W = F × d\nStep 3: Substitute values → W = 20 × 3\nStep 4: Calculate → W = 60 J","steps":["Step 1: Identify values → F = 20 N, d = 3 m","Step 2: Write formula → W = F × d","Step 3: Substitute values → W = 20 × 3","Step 4: Calculate → W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Work"}', 0),
  (471, 94, 'Why is no work done when pushing a wall?', 'text', 1, 'no movement', '{"why":"Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.","sol":"Step 1: Identify key concept: Define the required principles for Work.\nStep 2: Apply governing rule: Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.\nStep 3: State the final conclusion: Because there is no displacement, so work done is zero.","steps":["Step 1: Identify key concept: Define the required principles for Work.","Step 2: Apply governing rule: Work requires both force and movement in the direction of the force. A wall does not move, so displacement is zero.","Step 3: State the final conclusion: Because there is no displacement, so work done is zero."],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Work"}', 1),
  (472, 94, 'Do machines reduce total work done? Explain.', 'text', 1, 'energy conservation', '{"why":"Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.","sol":"Step 1: Identify key concept: Define the required principles for Work.\nStep 2: Apply governing rule: Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.\nStep 3: State the final conclusion: No, machines only change force and distance; total work remains the same (ignoring losses).","steps":["Step 1: Identify key concept: Define the required principles for Work.","Step 2: Apply governing rule: Machines make work easier by changing force and distance, but they do not reduce total energy required due to conservation of energy.","Step 3: State the final conclusion: No, machines only change force and distance; total work remains the same (ignoring losses)."],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Work"}', 2),
  (473, 94, 'A force of 10N moves an object 6m. Find work done.', 'text', 1, 'W = F × d', '{"why":"Work increases when force or distance increases.","sol":"Step 1: F = 10 N, d = 6 m\nStep 2: W = 10 × 6\nStep 3: W = 60 J","steps":["Step 1: F = 10 N, d = 6 m","Step 2: W = 10 × 6","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Work"}', 3),
  (474, 94, 'A force of 15N moves an object 4m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work depends directly on force and displacement.","sol":"Step 1: F = 15 N, d = 4 m\nStep 2: W = 15 × 4\nStep 3: W = 60 J","steps":["Step 1: F = 15 N, d = 4 m","Step 2: W = 15 × 4","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Work"}', 4),
  (475, 94, 'A force of 25N moves an object 2m. Find work done.', 'text', 1, 'W = F × d', '{"why":"Work increases with force applied.","sol":"Step 1: F = 25 N, d = 2 m\nStep 2: W = 25 × 2\nStep 3: W = 50 J","steps":["Step 1: F = 25 N, d = 2 m","Step 2: W = 25 × 2","Step 3: W = 50 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Work"}', 5),
  (476, 94, 'A force of 30N moves an object 5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"More force or distance means more work done.","sol":"Step 1: F = 30 N, d = 5 m\nStep 2: W = 30 × 5\nStep 3: W = 150 J","steps":["Step 1: F = 30 N, d = 5 m","Step 2: W = 30 × 5","Step 3: W = 150 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Work"}', 6),
  (477, 94, 'A force of 40N moves an object 1.5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work can involve decimal distances.","sol":"Step 1: F = 40 N, d = 1.5 m\nStep 2: W = 40 × 1.5\nStep 3: W = 60 J","steps":["Step 1: F = 40 N, d = 1.5 m","Step 2: W = 40 × 1.5","Step 3: W = 60 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Work"}', 7),
  (478, 94, 'A force of 12N moves an object 8m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Work depends on both force and displacement.","sol":"Step 1: F = 12 N, d = 8 m\nStep 2: W = 12 × 8\nStep 3: W = 96 J","steps":["Step 1: F = 12 N, d = 8 m","Step 2: W = 12 × 8","Step 3: W = 96 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Work"}', 8),
  (479, 94, 'A force of 50N moves an object 0.5m. Find work done.', 'text', 1, 'W = Fd', '{"why":"Even small distances produce work when force is large.","sol":"Step 1: F = 50 N, d = 0.5 m\nStep 2: W = 50 × 0.5\nStep 3: W = 25 J","steps":["Step 1: F = 50 N, d = 0.5 m","Step 2: W = 50 × 0.5","Step 3: W = 25 J"],"options":[],"conceptId":"physics_energy_work","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Work"}', 9),
  (480, 95, 'A machine uses 500J in 5s. Find power.', 'text', 1, 'Use P = W/t', '{"why":"Power is the rate of energy transfer per unit time.","sol":"Step 1: Identify values → W = 500 J, t = 5 s\nStep 2: Write formula → P = W / t\nStep 3: Substitute → P = 500 / 5\nStep 4: Calculate → P = 100 W","steps":["Step 1: Identify values → W = 500 J, t = 5 s","Step 2: Write formula → P = W / t","Step 3: Substitute → P = 500 / 5","Step 4: Calculate → P = 100 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Power"}', 0),
  (481, 95, 'What is the unit of power?', 'text', 1, 'SI unit', '{"why":"Power is measured in watts, where 1 watt = 1 joule per second.","sol":"Step 1: Identify key concept: Define the required principles for Power.\nStep 2: Apply governing rule: Power is measured in watts, where 1 watt = 1 joule per second.\nStep 3: State the final conclusion: Watt (W)","steps":["Step 1: Identify key concept: Define the required principles for Power.","Step 2: Apply governing rule: Power is measured in watts, where 1 watt = 1 joule per second.","Step 3: State the final conclusion: Watt (W)"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Power"}', 1),
  (482, 95, 'Why do power companies use high voltage transmission?', 'text', 1, 'reduce energy loss', '{"why":"Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.","sol":"Step 1: Identify key concept: Define the required principles for Power.\nStep 2: Apply governing rule: Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.\nStep 3: State the final conclusion: To reduce current and minimize energy loss (I²R losses).","steps":["Step 1: Identify key concept: Define the required principles for Power.","Step 2: Apply governing rule: Higher voltage reduces current, and since power loss in cables depends on I²R, lower current reduces energy wasted as heat.","Step 3: State the final conclusion: To reduce current and minimize energy loss (I²R losses)."],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Power"}', 2),
  (483, 95, 'A device uses 1200 J of energy in 6 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power measures how quickly energy is used.","sol":"Step 1: W = 1200 J, t = 6 s\nStep 2: P = 1200 / 6\nStep 3: P = 200 W","steps":["Step 1: W = 1200 J, t = 6 s","Step 2: P = 1200 / 6","Step 3: P = 200 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Power"}', 3),
  (484, 95, 'A motor does 3000 J of work in 10 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power shows energy transfer rate.","sol":"Step 1: W = 3000 J, t = 10 s\nStep 2: P = 3000 / 10\nStep 3: P = 300 W","steps":["Step 1: W = 3000 J, t = 10 s","Step 2: P = 3000 / 10","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Power"}', 4),
  (485, 95, 'A bulb uses 600 J in 3 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Electrical devices convert energy per second.","sol":"Step 1: W = 600 J, t = 3 s\nStep 2: P = 600 / 3\nStep 3: P = 200 W","steps":["Step 1: W = 600 J, t = 3 s","Step 2: P = 600 / 3","Step 3: P = 200 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Power"}', 5),
  (486, 95, 'A heater uses 4500 J in 15 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power depends on how fast energy is used.","sol":"Step 1: W = 4500 J, t = 15 s\nStep 2: P = 4500 / 15\nStep 3: P = 300 W","steps":["Step 1: W = 4500 J, t = 15 s","Step 2: P = 4500 / 15","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Power"}', 6),
  (487, 95, 'A machine uses 9000 J in 30 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power is energy per unit time.","sol":"Step 1: W = 9000 J, t = 30 s\nStep 2: P = 9000 / 30\nStep 3: P = 300 W","steps":["Step 1: W = 9000 J, t = 30 s","Step 2: P = 9000 / 30","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Power"}', 7),
  (488, 95, 'A motor transfers 1500 J in 5 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power is directly proportional to energy and inversely to time.","sol":"Step 1: W = 1500 J, t = 5 s\nStep 2: P = 1500 / 5\nStep 3: P = 300 W","steps":["Step 1: W = 1500 J, t = 5 s","Step 2: P = 1500 / 5","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Power"}', 8),
  (489, 95, 'A device uses 2400 J in 8 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power tells how fast energy is used.","sol":"Step 1: W = 2400 J, t = 8 s\nStep 2: P = 2400 / 8\nStep 3: P = 300 W","steps":["Step 1: W = 2400 J, t = 8 s","Step 2: P = 2400 / 8","Step 3: P = 300 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Power"}', 9),
  (490, 95, 'A generator produces 10000 J in 20 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Generators convert mechanical energy into electrical power.","sol":"Step 1: W = 10000 J, t = 20 s\nStep 2: P = 10000 / 20\nStep 3: P = 500 W","steps":["Step 1: W = 10000 J, t = 20 s","Step 2: P = 10000 / 20","Step 3: P = 500 W"],"options":[],"conceptId":"physics_energy_power","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Power"}', 10),
  (491, 96, 'What happens to energy when a car moves?', 'text', 1, 'fuel transformation', '{"why":"The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.\nStep 3: State the final conclusion: Chemical energy is converted into kinetic energy and heat.","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: The fuel in the car contains chemical energy which is released during combustion and transformed into motion (kinetic energy) and heat energy due to engine friction.","Step 3: State the final conclusion: Chemical energy is converted into kinetic energy and heat."],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 0),
  (492, 96, 'Is energy ever destroyed?', 'text', 1, 'law of conservation', '{"why":"According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.\nStep 3: State the final conclusion: No, energy is always conserved and only changes form.","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: According to the law of conservation of energy, energy cannot be created or destroyed, only transformed from one form to another.","Step 3: State the final conclusion: No, energy is always conserved and only changes form."],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 1),
  (493, 96, 'What energy change happens in a falling object?', 'text', 1, 'height to motion', '{"why":"As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.","sol":"Step 1: Identify key concept: Define the required principles for Energy Conversion.\nStep 2: Apply governing rule: As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.\nStep 3: State the final conclusion: Gravitational potential energy → kinetic energy","steps":["Step 1: Identify key concept: Define the required principles for Energy Conversion.","Step 2: Apply governing rule: As an object falls, its stored potential energy due to height is converted into kinetic energy as it gains speed.","Step 3: State the final conclusion: Gravitational potential energy → kinetic energy"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 2),
  (494, 96, 'A 2 kg object is lifted to a height of 5 m. Find its potential energy (g = 10 m/s²).', 'text', 1, 'Use PE = mgh', '{"why":"Potential energy depends on mass, height, and gravitational field strength.","sol":"Step 1: Identify values → m = 2 kg, g = 10 m/s², h = 5 m\nStep 2: Substitute into formula → PE = 2 × 10 × 5\nStep 3: Multiply → PE = 100 J","steps":["Step 1: Identify values → m = 2 kg, g = 10 m/s², h = 5 m","Step 2: Substitute into formula → PE = 2 × 10 × 5","Step 3: Multiply → PE = 100 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 3),
  (495, 96, 'A 3 kg object moves at 4 m/s. Find kinetic energy.', 'text', 1, 'Use KE = 1/2 mv²', '{"why":"Kinetic energy increases with velocity squared.","sol":"Step 1: m = 3 kg, v = 4 m/s\nStep 2: Square velocity → 4² = 16\nStep 3: Substitute → KE = 1/2 × 3 × 16\nStep 4: Multiply → KE = 24 J","steps":["Step 1: m = 3 kg, v = 4 m/s","Step 2: Square velocity → 4² = 16","Step 3: Substitute → KE = 1/2 × 3 × 16","Step 4: Multiply → KE = 24 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 4),
  (496, 96, 'A car engine does 5000 J of work in 10 seconds. Find power.', 'text', 1, 'Use P = W/t', '{"why":"Power is the rate of energy transfer per second.","sol":"Step 1: W = 5000 J, t = 10 s\nStep 2: Substitute → P = 5000 / 10\nStep 3: Calculate → P = 500 W","steps":["Step 1: W = 5000 J, t = 10 s","Step 2: Substitute → P = 5000 / 10","Step 3: Calculate → P = 500 W"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 5),
  (497, 96, 'A 4 kg object is lifted 3 m high. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Higher mass or height increases potential energy.","sol":"Step 1: m = 4 kg, g = 10 m/s², h = 3 m\nStep 2: Substitute → PE = 4 × 10 × 3\nStep 3: Multiply → PE = 120 J","steps":["Step 1: m = 4 kg, g = 10 m/s², h = 3 m","Step 2: Substitute → PE = 4 × 10 × 3","Step 3: Multiply → PE = 120 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 6),
  (498, 96, 'A 5 kg object moves at 2 m/s. Find kinetic energy.', 'text', 1, 'KE = 1/2 mv²', '{"why":"Even small velocity changes affect kinetic energy significantly.","sol":"Step 1: m = 5 kg, v = 2 m/s\nStep 2: v² = 4\nStep 3: KE = 1/2 × 5 × 4\nStep 4: KE = 10 J","steps":["Step 1: m = 5 kg, v = 2 m/s","Step 2: v² = 4","Step 3: KE = 1/2 × 5 × 4","Step 4: KE = 10 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 7),
  (499, 96, 'A machine converts 2000 J of energy in 4 s. Find power.', 'text', 1, 'P = W/t', '{"why":"Power measures how fast energy is used or transferred.","sol":"Step 1: W = 2000 J, t = 4 s\nStep 2: P = 2000 / 4\nStep 3: P = 500 W","steps":["Step 1: W = 2000 J, t = 4 s","Step 2: P = 2000 / 4","Step 3: P = 500 W"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 8),
  (500, 96, 'A 1 kg object falls from 10 m. Find potential energy before falling.', 'text', 1, 'PE = mgh', '{"why":"All potential energy becomes kinetic energy during fall.","sol":"Step 1: m = 1 kg, g = 10 m/s², h = 10 m\nStep 2: PE = 1 × 10 × 10\nStep 3: PE = 100 J","steps":["Step 1: m = 1 kg, g = 10 m/s², h = 10 m","Step 2: PE = 1 × 10 × 10","Step 3: PE = 100 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 9);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (501, 96, 'A system has 600 J of energy input and 150 J is lost as heat. Find useful energy output.', 'text', 1, 'useful = input - loss', '{"why":"Some energy is always lost, usually as heat or sound.","sol":"Step 1: Input = 600 J\nStep 2: Loss = 150 J\nStep 3: Useful = 600 - 150\nStep 4: Useful = 450 J","steps":["Step 1: Input = 600 J","Step 2: Loss = 150 J","Step 3: Useful = 600 - 150","Step 4: Useful = 450 J"],"options":[],"conceptId":"physics_energy_energy_conversion","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Energy Conversion"}', 10),
  (502, 97, 'A 2kg object falls from 5m. Find total energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"mgh = 2 × 10 × 5 = 100J","steps":["Step 1: Identify the given values: mass (m) = 2kg, height (h) = 5m, and gravitational acceleration (g) ≈ 10m/s².","Step 2: Recall the formula for gravitational potential energy: PE = m × g × h.","Step 3: Substitute the known values into the equation: PE = 2 × 10 × 5.","Step 4: Calculate the final value to find the total mechanical energy: 100 Joules (100J)."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 0),
  (503, 97, 'A 5kg object is lifted to a height of 8m. Calculate its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = mgh = 5 × 10 × 8 = 400J","steps":["Step 1: Identify the values: m = 5kg, h = 8m, g = 10m/s².","Step 2: Recall the formula PE = m × g × h.","Step 3: Substitute the values: PE = 5 × 10 × 8.","Step 4: Calculate the answer: 400 Joules."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 1),
  (504, 97, 'A 4kg object moves at 6m/s. Find its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½mv² = ½ × 4 × 6² = 72J","steps":["Step 1: Identify the mass (4kg) and velocity (6m/s).","Step 2: Recall the formula KE = ½mv².","Step 3: Square the velocity: 6² = 36.","Step 4: Calculate: ½ × 4 × 36 = 72J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 2),
  (505, 97, 'A car of mass 1000kg travels at 20m/s. Calculate its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 1000 × 20² = 200000J","steps":["Step 1: Identify m = 1000kg and v = 20m/s.","Step 2: Recall KE = ½mv².","Step 3: Square the speed: 20² = 400.","Step 4: Calculate: ½ × 1000 × 400 = 200000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 3),
  (506, 97, 'A 10N force moves an object through 6m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = Force × Distance = 10 × 6 = 60J","steps":["Step 1: Identify force = 10N and distance = 6m.","Step 2: Recall the formula Work = Force × Distance.","Step 3: Substitute the values: 10 × 6.","Step 4: Calculate the work done: 60J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 4),
  (507, 97, 'A machine does 500J of work in 10 seconds. Calculate its power.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = Work ÷ Time = 500 ÷ 10 = 50W","steps":["Step 1: Identify work = 500J and time = 10s.","Step 2: Recall the formula Power = Work ÷ Time.","Step 3: Substitute the values into the formula.","Step 4: Divide 500 by 10 to obtain 50W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 5),
  (508, 97, 'A 3kg object is raised 15m above the ground. Find its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 3 × 10 × 15 = 450J","steps":["Step 1: Identify m = 3kg, h = 15m, g = 10m/s².","Step 2: Recall PE = mgh.","Step 3: Substitute: 3 × 10 × 15.","Step 4: Calculate: 450J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 6),
  (509, 97, 'A 6kg object moves with a speed of 5m/s. Find its kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 6 × 5² = 75J","steps":["Step 1: Identify mass and velocity.","Step 2: Recall KE = ½mv².","Step 3: Square the velocity: 5² = 25.","Step 4: Calculate: ½ × 6 × 25 = 75J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q8","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 7),
  (510, 97, 'A 50N force pushes a box for 12m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = 50 × 12 = 600J","steps":["Step 1: Identify force = 50N and distance = 12m.","Step 2: Recall Work = Force × Distance.","Step 3: Multiply the given values.","Step 4: The work done is 600J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q9","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 8),
  (511, 97, 'A motor produces 2400J of work in 60 seconds. Find its power.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = 2400 ÷ 60 = 40W","steps":["Step 1: Identify work = 2400J and time = 60s.","Step 2: Recall Power = Work ÷ Time.","Step 3: Substitute the values.","Step 4: Divide 2400 by 60 to get 40W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q10","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 9),
  (512, 97, 'A 7kg object is placed 9m above the ground. Calculate its potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 7 × 10 × 9 = 630J","steps":["Step 1: Identify m = 7kg, h = 9m.","Step 2: Recall PE = mgh.","Step 3: Substitute the values using g = 10m/s².","Step 4: Calculate 630J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q11","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 10),
  (513, 97, 'A cyclist and bicycle have a combined mass of 80kg and move at 10m/s. Calculate the kinetic energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"KE = ½ × 80 × 10² = 4000J","steps":["Step 1: Identify mass = 80kg and velocity = 10m/s.","Step 2: Recall KE = ½mv².","Step 3: Square the velocity: 10² = 100.","Step 4: Calculate: ½ × 80 × 100 = 4000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q12","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 11),
  (514, 97, 'A crane lifts a 200kg load by 5m. Calculate the gain in potential energy.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"PE = 200 × 10 × 5 = 10000J","steps":["Step 1: Identify m = 200kg and h = 5m.","Step 2: Recall PE = mgh.","Step 3: Substitute the values.","Step 4: Calculate the gain in potential energy: 10000J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q13","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 12),
  (515, 97, 'A machine uses 1500J of energy in 30 seconds. Find its power output.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Power = 1500 ÷ 30 = 50W","steps":["Step 1: Identify work = 1500J and time = 30s.","Step 2: Recall Power = Work ÷ Time.","Step 3: Substitute the values.","Step 4: Divide 1500 by 30 to get 50W."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q14","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 13),
  (516, 97, 'A 12N force moves an object 15m. Calculate the work done.', 'text', 1, 'Focus on the core principle of Conservation of Energy.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Work = 12 × 15 = 180J","steps":["Step 1: Identify force = 12N and distance = 15m.","Step 2: Recall Work = Force × Distance.","Step 3: Substitute the values.","Step 4: Calculate: 180J."],"options":[],"conceptId":"physics_energy_conservation_of_energy","skillId":"physics_energy","subskillId":"physics_energy_q15","subject":"physics","chapter":"energy","topic":"Conservation of Energy"}', 14),
  (517, 98, 'A 2 kg object moves at 3 m/s. Find kinetic energy.', 'text', 1, 'Use KE = ½mv²', '{"why":"Kinetic energy depends on mass and the square of velocity.","sol":"Step 1: Identify values → m = 2 kg, v = 3 m/s\nStep 2: Substitute into formula → KE = 1/2 × 2 × 3²\nStep 3: Square velocity → 3² = 9\nStep 4: Multiply → KE = 1 × 9\nStep 5: Final answer → KE = 9 J","steps":["Step 1: Identify values → m = 2 kg, v = 3 m/s","Step 2: Substitute into formula → KE = 1/2 × 2 × 3²","Step 3: Square velocity → 3² = 9","Step 4: Multiply → KE = 1 × 9","Step 5: Final answer → KE = 9 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q1","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 0),
  (518, 98, 'A 3 kg object is raised to a height of 4 m. Find potential energy.', 'text', 1, 'Use PE = mgh', '{"why":"Potential energy depends on mass, height, and gravity.","sol":"Step 1: Identify values → m = 3 kg, g = 10 m/s², h = 4 m\nStep 2: Substitute → PE = 3 × 10 × 4\nStep 3: Multiply → PE = 120 J","steps":["Step 1: Identify values → m = 3 kg, g = 10 m/s², h = 4 m","Step 2: Substitute → PE = 3 × 10 × 4","Step 3: Multiply → PE = 120 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q2","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 1),
  (519, 98, 'What happens to potential energy when an object falls?', 'text', 1, 'energy conversion', '{"why":"As height decreases, potential energy is transformed into motion energy.","sol":"Step 1: Identify key concept: Define the required principles for Kinetic & Potential Energy.\nStep 2: Apply governing rule: As height decreases, potential energy is transformed into motion energy.\nStep 3: State the final conclusion: It is converted into kinetic energy.","steps":["Step 1: Identify key concept: Define the required principles for Kinetic & Potential Energy.","Step 2: Apply governing rule: As height decreases, potential energy is transformed into motion energy.","Step 3: State the final conclusion: It is converted into kinetic energy."],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q3","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 2),
  (520, 98, 'A 5 kg object moves at 4 m/s. Find kinetic energy.', 'text', 1, 'KE = ½mv²', '{"why":"Kinetic energy increases with mass and velocity squared.","sol":"Step 1: m = 5 kg, v = 4 m/s\nStep 2: Substitute → KE = 1/2 × 5 × 4²\nStep 3: 4² = 16\nStep 4: KE = 2.5 × 16\nStep 5: KE = 40 J","steps":["Step 1: m = 5 kg, v = 4 m/s","Step 2: Substitute → KE = 1/2 × 5 × 4²","Step 3: 4² = 16","Step 4: KE = 2.5 × 16","Step 5: KE = 40 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q4","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 3),
  (521, 98, 'A 2 kg object is lifted to 6 m. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Higher height increases potential energy.","sol":"Step 1: m = 2 kg, g = 10, h = 6 m\nStep 2: Substitute → PE = 2 × 10 × 6\nStep 3: Calculate → PE = 120 J","steps":["Step 1: m = 2 kg, g = 10, h = 6 m","Step 2: Substitute → PE = 2 × 10 × 6","Step 3: Calculate → PE = 120 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q5","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 4),
  (522, 98, 'A 4 kg object moves at 2 m/s. Find kinetic energy.', 'text', 1, 'KE = ½mv²', '{"why":"Kinetic energy depends on velocity squared.","sol":"Step 1: m = 4 kg, v = 2 m/s\nStep 2: Substitute → KE = 1/2 × 4 × 2²\nStep 3: 2² = 4\nStep 4: KE = 2 × 4\nStep 5: KE = 8 J","steps":["Step 1: m = 4 kg, v = 2 m/s","Step 2: Substitute → KE = 1/2 × 4 × 2²","Step 3: 2² = 4","Step 4: KE = 2 × 4","Step 5: KE = 8 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q6","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 5),
  (523, 98, 'A 1 kg object is lifted 10 m high. Find potential energy.', 'text', 1, 'PE = mgh', '{"why":"Potential energy increases with both height and mass because more work is needed to lift an object higher in a gravitational field.","sol":"Step 1: Identify values → m = 1 kg, g = 10 m/s², h = 10 m\nStep 2: Substitute into formula → PE = 1 × 10 × 10\nStep 3: Multiply → PE = 100 J","steps":["Step 1: Identify values → m = 1 kg, g = 10 m/s², h = 10 m","Step 2: Substitute into formula → PE = 1 × 10 × 10","Step 3: Multiply → PE = 100 J"],"options":[],"conceptId":"physics_energy_kinetic_potential_energy","skillId":"physics_energy","subskillId":"physics_energy_q7","subject":"physics","chapter":"energy","topic":"Kinetic & Potential Energy"}', 6),
  (524, 99, 'A wave travels at 15 m/s and has frequency 3 Hz. Find wavelength.', 'text', 1, 'Use v = fλ', '{"why":"Wavelength is found by dividing wave speed by frequency.","sol":"Step 1: Identify values → v = 15 m/s, f = 3 Hz\nStep 2: Use formula → λ = v / f\nStep 3: Substitute → λ = 15 / 3\nStep 4: Calculate → λ = 5 m","steps":["Step 1: Identify values → v = 15 m/s, f = 3 Hz","Step 2: Use formula → λ = v / f","Step 3: Substitute → λ = 15 / 3","Step 4: Calculate → λ = 5 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Wave properties"}', 0),
  (525, 99, 'A wave has wavelength 4 m and frequency 6 Hz. Find wave speed.', 'text', 1, 'Use v = fλ', '{"why":"Wave speed is the product of frequency and wavelength.","sol":"Step 1: Identify values → f = 6 Hz, λ = 4 m\nStep 2: Use formula → v = f × λ\nStep 3: Substitute → v = 6 × 4\nStep 4: Calculate → v = 24 m/s","steps":["Step 1: Identify values → f = 6 Hz, λ = 4 m","Step 2: Use formula → v = f × λ","Step 3: Substitute → v = 6 × 4","Step 4: Calculate → v = 24 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Wave properties"}', 1),
  (526, 99, 'Time period is 0.5 s. Find frequency.', 'text', 1, 'f = 1/T', '{"why":"Frequency is the number of waves per second.","sol":"Step 1: Identify time period → T = 0.5 s\nStep 2: Use formula → f = 1 / T\nStep 3: Substitute → f = 1 / 0.5\nStep 4: Calculate → f = 2 Hz","steps":["Step 1: Identify time period → T = 0.5 s","Step 2: Use formula → f = 1 / T","Step 3: Substitute → f = 1 / 0.5","Step 4: Calculate → f = 2 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Wave properties"}', 2),
  (527, 99, 'A wave has speed 40 m/s and wavelength 8 m. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency equals speed divided by wavelength.","sol":"Step 1: Identify values → v = 40 m/s, λ = 8 m\nStep 2: Use formula → f = v / λ\nStep 3: Substitute → f = 40 / 8\nStep 4: Calculate → f = 5 Hz","steps":["Step 1: Identify values → v = 40 m/s, λ = 8 m","Step 2: Use formula → f = v / λ","Step 3: Substitute → f = 40 / 8","Step 4: Calculate → f = 5 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Wave properties"}', 3),
  (528, 99, 'A wave has frequency 10 Hz and speed 50 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is speed divided by frequency.","sol":"Step 1: Identify values → v = 50 m/s, f = 10 Hz\nStep 2: Apply formula → λ = v / f\nStep 3: Substitute → λ = 50 / 10\nStep 4: Calculate → λ = 5 m","steps":["Step 1: Identify values → v = 50 m/s, f = 10 Hz","Step 2: Apply formula → λ = v / f","Step 3: Substitute → λ = 50 / 10","Step 4: Calculate → λ = 5 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Wave properties"}', 4),
  (529, 99, 'A wave takes 2 s to complete 1 cycle. Find frequency.', 'text', 1, 'T = 1/f', '{"why":"Frequency is inversely proportional to time period.","sol":"Step 1: Identify time period → T = 2 s\nStep 2: Use formula → f = 1 / T\nStep 3: Substitute → f = 1 / 2\nStep 4: Calculate → f = 0.5 Hz","steps":["Step 1: Identify time period → T = 2 s","Step 2: Use formula → f = 1 / T","Step 3: Substitute → f = 1 / 2","Step 4: Calculate → f = 0.5 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Wave properties"}', 5),
  (530, 99, 'A wave has wavelength 2 m and speed 12 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is found by dividing speed by wavelength.","sol":"Step 1: Identify values → v = 12 m/s, λ = 2 m\nStep 2: Apply formula → f = v / λ\nStep 3: Substitute → f = 12 / 2\nStep 4: Calculate → f = 6 Hz","steps":["Step 1: Identify values → v = 12 m/s, λ = 2 m","Step 2: Apply formula → f = v / λ","Step 3: Substitute → f = 12 / 2","Step 4: Calculate → f = 6 Hz"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Wave properties"}', 6),
  (531, 99, 'A wave has frequency 50 Hz and wavelength 0.2 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed equals frequency times wavelength.","sol":"Step 1: Identify values → f = 50 Hz, λ = 0.2 m\nStep 2: Apply formula → v = f × λ\nStep 3: Substitute → v = 50 × 0.2\nStep 4: Calculate → v = 10 m/s","steps":["Step 1: Identify values → f = 50 Hz, λ = 0.2 m","Step 2: Apply formula → v = f × λ","Step 3: Substitute → v = 50 × 0.2","Step 4: Calculate → v = 10 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Wave properties"}', 7),
  (532, 99, 'A wave travels 100 m in 5 s. Find its speed.', 'text', 1, 'speed = distance/time', '{"why":"Speed is distance divided by time.","sol":"Step 1: Identify values → d = 100 m, t = 5 s\nStep 2: Use formula → v = d / t\nStep 3: Substitute → v = 100 / 5\nStep 4: Calculate → v = 20 m/s","steps":["Step 1: Identify values → d = 100 m, t = 5 s","Step 2: Use formula → v = d / t","Step 3: Substitute → v = 100 / 5","Step 4: Calculate → v = 20 m/s"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Wave properties"}', 8),
  (533, 99, 'A wave has speed 30 m/s and frequency 5 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength equals speed divided by frequency.","sol":"Step 1: Identify values → v = 30 m/s, f = 5 Hz\nStep 2: Apply formula → λ = v / f\nStep 3: Substitute → λ = 30 / 5\nStep 4: Calculate → λ = 6 m","steps":["Step 1: Identify values → v = 30 m/s, f = 5 Hz","Step 2: Apply formula → λ = v / f","Step 3: Substitute → λ = 30 / 5","Step 4: Calculate → λ = 6 m"],"options":[],"conceptId":"physics_waves_wave_properties","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Wave properties"}', 9),
  (534, 100, 'A sound wave has frequency 200 Hz and wavelength 1.5 m. Find speed.', 'text', 1, 'Use v = fλ', '{"why":"Speed of sound is found by multiplying frequency and wavelength.","sol":"Step 1: Identify values → f = 200 Hz, λ = 1.5 m\nStep 2: Apply formula → v = fλ\nStep 3: Substitute → v = 200 × 1.5\nStep 4: Calculate → v = 300 m/s","steps":["Step 1: Identify values → f = 200 Hz, λ = 1.5 m","Step 2: Apply formula → v = fλ","Step 3: Substitute → v = 200 × 1.5","Step 4: Calculate → v = 300 m/s"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Sound waves"}', 0),
  (535, 100, 'A sound wave has frequency 100 Hz and wavelength 2 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed depends on both frequency and wavelength.","sol":"Step 1: f = 100 Hz, λ = 2 m\nStep 2: v = fλ\nStep 3: v = 100 × 2\nStep 4: v = 200 m/s","steps":["Step 1: f = 100 Hz, λ = 2 m","Step 2: v = fλ","Step 3: v = 100 × 2","Step 4: v = 200 m/s"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Sound waves"}', 1),
  (536, 100, 'A sound wave travels at 340 m/s and has frequency 170 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is speed divided by frequency.","sol":"Step 1: v = 340 m/s, f = 170 Hz\nStep 2: λ = v/f\nStep 3: λ = 340/170\nStep 4: λ = 2 m","steps":["Step 1: v = 340 m/s, f = 170 Hz","Step 2: λ = v/f","Step 3: λ = 340/170","Step 4: λ = 2 m"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Sound waves"}', 2),
  (537, 100, 'A sound wave has wavelength 0.5 m and speed 150 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is calculated by dividing speed by wavelength.","sol":"Step 1: v = 150 m/s, λ = 0.5 m\nStep 2: f = v/λ\nStep 3: f = 150/0.5\nStep 4: f = 300 Hz","steps":["Step 1: v = 150 m/s, λ = 0.5 m","Step 2: f = v/λ","Step 3: f = 150/0.5","Step 4: f = 300 Hz"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Sound waves"}', 3),
  (538, 100, 'Why can''t sound travel in space?', 'text', 1, 'no particles', '{"why":"Sound needs particles to vibrate, but space is a vacuum with no particles.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound needs particles to vibrate, but space is a vacuum with no particles.\nStep 3: State the final conclusion: Because there is no medium for sound waves to travel through.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound needs particles to vibrate, but space is a vacuum with no particles.","Step 3: State the final conclusion: Because there is no medium for sound waves to travel through."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Sound waves"}', 4),
  (539, 100, 'What determines loudness of sound?', 'text', 1, 'wave height', '{"why":"Greater amplitude means louder sound, lower amplitude means softer sound.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Greater amplitude means louder sound, lower amplitude means softer sound.\nStep 3: State the final conclusion: Amplitude","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Greater amplitude means louder sound, lower amplitude means softer sound.","Step 3: State the final conclusion: Amplitude"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Sound waves"}', 5),
  (540, 100, 'What determines pitch of sound?', 'text', 1, 'frequency', '{"why":"High frequency produces high pitch sound and low frequency produces low pitch.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: High frequency produces high pitch sound and low frequency produces low pitch.\nStep 3: State the final conclusion: Frequency","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: High frequency produces high pitch sound and low frequency produces low pitch.","Step 3: State the final conclusion: Frequency"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Sound waves"}', 6),
  (541, 100, 'What is a sound wave?', 'text', 1, 'vibration', '{"why":"Sound waves travel through air, liquids, or solids by particle vibration.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound waves travel through air, liquids, or solids by particle vibration.\nStep 3: State the final conclusion: A sound wave is a mechanical wave produced by vibrations of particles.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound waves travel through air, liquids, or solids by particle vibration.","Step 3: State the final conclusion: A sound wave is a mechanical wave produced by vibrations of particles."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Sound waves"}', 7),
  (542, 100, 'What type of wave is sound?', 'text', 1, 'mechanical', '{"why":"Sound requires a medium to travel, so it is a mechanical wave.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound requires a medium to travel, so it is a mechanical wave.\nStep 3: State the final conclusion: A mechanical wave","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound requires a medium to travel, so it is a mechanical wave.","Step 3: State the final conclusion: A mechanical wave"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Sound waves"}', 8),
  (543, 100, 'A sound wave has frequency 50 Hz and speed 340 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength depends on speed and frequency.","sol":"Step 1: v = 340 m/s, f = 50 Hz\nStep 2: λ = v/f\nStep 3: λ = 340/50\nStep 4: λ = 6.8 m","steps":["Step 1: v = 340 m/s, f = 50 Hz","Step 2: λ = v/f","Step 3: λ = 340/50","Step 4: λ = 6.8 m"],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Sound waves"}', 9),
  (544, 100, 'What is echo?', 'text', 1, 'reflection of sound', '{"why":"Sound reflects off surfaces and returns to the listener after a delay.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Sound reflects off surfaces and returns to the listener after a delay.\nStep 3: State the final conclusion: Echo is the reflection of sound waves.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Sound reflects off surfaces and returns to the listener after a delay.","Step 3: State the final conclusion: Echo is the reflection of sound waves."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q11","subject":"physics","chapter":"waves","topic":"Sound waves"}', 10),
  (545, 100, 'Why is sound faster in solids than in air?', 'text', 1, 'particle spacing', '{"why":"Closer particles transfer vibrations faster in solids than in gases.","sol":"Step 1: Identify key concept: Define the required principles for Sound waves.\nStep 2: Apply governing rule: Closer particles transfer vibrations faster in solids than in gases.\nStep 3: State the final conclusion: Because particles are closer together in solids.","steps":["Step 1: Identify key concept: Define the required principles for Sound waves.","Step 2: Apply governing rule: Closer particles transfer vibrations faster in solids than in gases.","Step 3: State the final conclusion: Because particles are closer together in solids."],"options":[],"conceptId":"physics_waves_sound_waves","skillId":"physics_waves","subskillId":"physics_waves_q12","subject":"physics","chapter":"waves","topic":"Sound waves"}', 11),
  (546, 101, 'A light wave has frequency 4 × 10^14 Hz and wavelength 7.5 × 10^-7 m. Find speed.', 'text', 1, 'Use v = fλ', '{"why":"Wave speed is the product of frequency and wavelength.","sol":"Step 1: Identify values → f = 4 × 10^14 Hz, λ = 7.5 × 10^-7 m\nStep 2: Write formula → v = fλ\nStep 3: Substitute → v = (4 × 10^14)(7.5 × 10^-7)\nStep 4: Multiply numbers → 4 × 7.5 = 30\nStep 5: Add powers → 10^14 × 10^-7 = 10^7\nStep 6: Final result → v = 3 × 10^8 m/s","steps":["Step 1: Identify values → f = 4 × 10^14 Hz, λ = 7.5 × 10^-7 m","Step 2: Write formula → v = fλ","Step 3: Substitute → v = (4 × 10^14)(7.5 × 10^-7)","Step 4: Multiply numbers → 4 × 7.5 = 30","Step 5: Add powers → 10^14 × 10^-7 = 10^7","Step 6: Final result → v = 3 × 10^8 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Light waves"}', 0),
  (547, 101, 'A wave has frequency 2 × 10^6 Hz and wavelength 0.15 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Speed is directly proportional to frequency and wavelength.","sol":"Step 1: f = 2 × 10^6 Hz, λ = 0.15 m\nStep 2: v = fλ\nStep 3: v = (2 × 10^6) × 0.15\nStep 4: 2 × 0.15 = 0.3\nStep 5: v = 0.3 × 10^6\nStep 6: v = 3 × 10^5 m/s","steps":["Step 1: f = 2 × 10^6 Hz, λ = 0.15 m","Step 2: v = fλ","Step 3: v = (2 × 10^6) × 0.15","Step 4: 2 × 0.15 = 0.3","Step 5: v = 0.3 × 10^6","Step 6: v = 3 × 10^5 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Light waves"}', 1),
  (548, 101, 'A wave travels at 340 m/s and has frequency 170 Hz. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength is found by dividing speed by frequency.","sol":"Step 1: Identify values → v = 340 m/s, f = 170 Hz\nStep 2: Write formula → λ = v/f\nStep 3: Substitute → λ = 340/170\nStep 4: Calculate → λ = 2 m","steps":["Step 1: Identify values → v = 340 m/s, f = 170 Hz","Step 2: Write formula → λ = v/f","Step 3: Substitute → λ = 340/170","Step 4: Calculate → λ = 2 m"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Light waves"}', 2),
  (549, 101, 'A wave has wavelength 0.5 m and speed 200 m/s. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency is speed divided by wavelength.","sol":"Step 1: v = 200 m/s, λ = 0.5 m\nStep 2: f = v/λ\nStep 3: f = 200/0.5\nStep 4: f = 400 Hz","steps":["Step 1: v = 200 m/s, λ = 0.5 m","Step 2: f = v/λ","Step 3: f = 200/0.5","Step 4: f = 400 Hz"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Light waves"}', 3),
  (550, 101, 'A wave has frequency 5 × 10^5 Hz and speed 1 × 10^8 m/s. Find wavelength.', 'text', 1, 'λ = v/f', '{"why":"Wavelength increases when frequency decreases.","sol":"Step 1: v = 1 × 10^8, f = 5 × 10^5\nStep 2: λ = v/f\nStep 3: λ = (1 × 10^8) / (5 × 10^5)\nStep 4: 1/5 = 0.2\nStep 5: 10^8 / 10^5 = 10^3\nStep 6: λ = 0.2 × 10^3 = 200 m","steps":["Step 1: v = 1 × 10^8, f = 5 × 10^5","Step 2: λ = v/f","Step 3: λ = (1 × 10^8) / (5 × 10^5)","Step 4: 1/5 = 0.2","Step 5: 10^8 / 10^5 = 10^3","Step 6: λ = 0.2 × 10^3 = 200 m"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Light waves"}', 4),
  (551, 101, 'A wave has wavelength 3 m and frequency 50 Hz. Find speed.', 'text', 1, 'v = fλ', '{"why":"Wave speed is product of frequency and wavelength.","sol":"Step 1: f = 50 Hz, λ = 3 m\nStep 2: v = fλ\nStep 3: v = 50 × 3\nStep 4: v = 150 m/s","steps":["Step 1: f = 50 Hz, λ = 3 m","Step 2: v = fλ","Step 3: v = 50 × 3","Step 4: v = 150 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Light waves"}', 5),
  (552, 101, 'A light wave has frequency 6 × 10^14 Hz and wavelength 5 × 10^-7 m. Find speed.', 'text', 1, 'v = fλ', '{"why":"Light speed in vacuum is constant.","sol":"Step 1: f = 6 × 10^14, λ = 5 × 10^-7\nStep 2: v = fλ\nStep 3: Multiply → 6 × 5 = 30\nStep 4: Add powers → 10^14 × 10^-7 = 10^7\nStep 5: v = 3 × 10^8 m/s","steps":["Step 1: f = 6 × 10^14, λ = 5 × 10^-7","Step 2: v = fλ","Step 3: Multiply → 6 × 5 = 30","Step 4: Add powers → 10^14 × 10^-7 = 10^7","Step 5: v = 3 × 10^8 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Light waves"}', 6),
  (553, 101, 'A wave travels 600 m in 3 seconds. Find its speed.', 'text', 1, 'v = d/t', '{"why":"Speed is distance divided by time.","sol":"Step 1: d = 600 m, t = 3 s\nStep 2: v = d/t\nStep 3: v = 600/3\nStep 4: v = 200 m/s","steps":["Step 1: d = 600 m, t = 3 s","Step 2: v = d/t","Step 3: v = 600/3","Step 4: v = 200 m/s"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Light waves"}', 7),
  (554, 101, 'A wave has speed 300 m/s and wavelength 0.6 m. Find frequency.', 'text', 1, 'f = v/λ', '{"why":"Frequency depends on speed and wavelength.","sol":"Step 1: v = 300 m/s, λ = 0.6 m\nStep 2: f = v/λ\nStep 3: f = 300/0.6\nStep 4: f = 500 Hz","steps":["Step 1: v = 300 m/s, λ = 0.6 m","Step 2: f = v/λ","Step 3: f = 300/0.6","Step 4: f = 500 Hz"],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Light waves"}', 8),
  (555, 101, 'Why can light travel in space?', 'text', 1, 'no medium required', '{"why":"Unlike sound, light can travel through a vacuum because it does not rely on particles.","sol":"Step 1: Identify key concept: Define the required principles for Light waves.\nStep 2: Apply governing rule: Unlike sound, light can travel through a vacuum because it does not rely on particles.\nStep 3: State the final conclusion: Because light is an electromagnetic wave that does not need a medium.","steps":["Step 1: Identify key concept: Define the required principles for Light waves.","Step 2: Apply governing rule: Unlike sound, light can travel through a vacuum because it does not rely on particles.","Step 3: State the final conclusion: Because light is an electromagnetic wave that does not need a medium."],"options":[],"conceptId":"physics_waves_light_waves","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Light waves"}', 9),
  (556, 102, 'Why does light bend in water?', 'text', 1, 'change of medium', '{"why":"When light passes from air into water, its speed decreases, causing it to change direction (refraction).","sol":"Step 1: Identify key concept: Define the required principles for Reflection & refraction.\nStep 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).\nStep 3: State the final conclusion: Because its speed changes when entering a different medium.","steps":["Step 1: Identify key concept: Define the required principles for Reflection & refraction.","Step 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).","Step 3: State the final conclusion: Because its speed changes when entering a different medium."],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 0),
  (557, 102, 'A ray of light hits a mirror at 60°. Find angle of reflection.', 'text', 1, 'law of reflection', '{"why":"The law of reflection states that the angle of incidence equals the angle of reflection.","sol":"Step 1: Identify angle of incidence → i = 60°\nStep 2: Use law of reflection → i = r\nStep 3: Substitute values → r = 60°","steps":["Step 1: Identify angle of incidence → i = 60°","Step 2: Use law of reflection → i = r","Step 3: Substitute values → r = 60°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 1),
  (558, 102, 'A light ray strikes a mirror at 30°. Calculate the angle of reflection.', 'text', 1, 'law of reflection', '{"why":"Reflection follows the law i = r, meaning angles are equal.","sol":"Step 1: Identify angle of incidence → i = 30°\nStep 2: Apply law of reflection → i = r\nStep 3: Substitute values → r = 30°","steps":["Step 1: Identify angle of incidence → i = 30°","Step 2: Apply law of reflection → i = r","Step 3: Substitute values → r = 30°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 2),
  (559, 102, 'A ray hits a mirror at 45°. What is the angle between the incident ray and reflected ray?', 'text', 1, 'sum of angles', '{"why":"The angle between incident and reflected rays equals twice the angle of incidence.","sol":"Step 1: Identify incidence angle → i = 45°\nStep 2: Reflection angle → r = 45°\nStep 3: Add angles → 45° + 45°\nStep 4: Result = 90°","steps":["Step 1: Identify incidence angle → i = 45°","Step 2: Reflection angle → r = 45°","Step 3: Add angles → 45° + 45°","Step 4: Result = 90°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q4","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 3),
  (560, 102, 'A light ray travels from air into glass and slows down. What happens to its direction?', 'text', 1, 'refraction effect', '{"why":"When light enters a denser medium, it slows down and bends towards the normal line.","sol":"Step 1: Light enters denser medium (air → glass)\nStep 2: Speed decreases\nStep 3: Ray bends towards the normal\nStep 4: New direction is closer to normal line","steps":["Step 1: Light enters denser medium (air → glass)","Step 2: Speed decreases","Step 3: Ray bends towards the normal","Step 4: New direction is closer to normal line"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 4),
  (561, 102, 'Why does light bend in water?', 'text', 1, 'change of medium', '{"why":"When light passes from air into water, its speed decreases, causing it to change direction (refraction).","sol":"Step 1: Identify key concept: Define the required principles for Reflection & refraction.\nStep 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).\nStep 3: State the final conclusion: Because its speed changes when entering a different medium.","steps":["Step 1: Identify key concept: Define the required principles for Reflection & refraction.","Step 2: Apply governing rule: When light passes from air into water, its speed decreases, causing it to change direction (refraction).","Step 3: State the final conclusion: Because its speed changes when entering a different medium."],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 5),
  (562, 102, 'A ray of light hits a mirror at 60°. Find the angle of reflection.', 'text', 1, 'law of reflection', '{"why":"The law of reflection states that angle of incidence equals angle of reflection.","sol":"Step 1: Identify angle of incidence → i = 60°\nStep 2: Apply law of reflection → i = r\nStep 3: Substitute values → r = 60°","steps":["Step 1: Identify angle of incidence → i = 60°","Step 2: Apply law of reflection → i = r","Step 3: Substitute values → r = 60°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q8","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 6),
  (563, 102, 'A ray of light strikes a plane mirror at 35°. Calculate the angle of reflection.', 'text', 1, 'i = r', '{"why":"Reflection obeys i = r at all times.","sol":"Step 1: Given angle of incidence → i = 35°\nStep 2: Apply law of reflection → r = i\nStep 3: Substitute → r = 35°","steps":["Step 1: Given angle of incidence → i = 35°","Step 2: Apply law of reflection → r = i","Step 3: Substitute → r = 35°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q9","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 7),
  (564, 102, 'A light ray is incident on a mirror at 40°. Find the angle between the incident ray and reflected ray.', 'text', 1, 'geometry of reflection', '{"why":"The geometry of reflection gives angle between incident and reflected rays as 2i.","sol":"Step 1: Identify incidence angle → i = 40°\nStep 2: Use relation → angle between rays = 2i\nStep 3: Substitute → 2 × 40°\nStep 4: Calculate → 80°","steps":["Step 1: Identify incidence angle → i = 40°","Step 2: Use relation → angle between rays = 2i","Step 3: Substitute → 2 × 40°","Step 4: Calculate → 80°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q10","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 8),
  (565, 102, 'A ray passes from air into glass. Refractive index of glass is 1.5. If angle of incidence is 30°, calculate angle of refraction.', 'text', 1, 'Snell’s law', '{"why":"Snell’s law relates angles of incidence and refraction using refractive indices.","sol":"Step 1: Identify values → n1 = 1 (air), n2 = 1.5, i = 30°\nStep 2: Apply Snell’s law → 1 × sin30° = 1.5 × sin r\nStep 3: Substitute → 0.5 = 1.5 sin r\nStep 4: Solve → sin r = 0.333\nStep 5: Find r → r ≈ 19.5°","steps":["Step 1: Identify values → n1 = 1 (air), n2 = 1.5, i = 30°","Step 2: Apply Snell’s law → 1 × sin30° = 1.5 × sin r","Step 3: Substitute → 0.5 = 1.5 sin r","Step 4: Solve → sin r = 0.333","Step 5: Find r → r ≈ 19.5°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q11","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 9),
  (566, 102, 'A ray enters glass (n = 1.5) from air at 45°. Find angle of refraction.', 'text', 1, 'Snell’s law', '{"why":"Light bends towards the normal when entering a denser medium.","sol":"Step 1: n1 = 1, n2 = 1.5, i = 45°\nStep 2: Apply formula → sin r = (1 × sin45°)/1.5\nStep 3: sin45° = 0.707\nStep 4: sin r = 0.707/1.5 = 0.471\nStep 5: r ≈ 28.1°","steps":["Step 1: n1 = 1, n2 = 1.5, i = 45°","Step 2: Apply formula → sin r = (1 × sin45°)/1.5","Step 3: sin45° = 0.707","Step 4: sin r = 0.707/1.5 = 0.471","Step 5: r ≈ 28.1°"],"options":[],"conceptId":"physics_waves_reflection_refraction","skillId":"physics_waves","subskillId":"physics_waves_q12","subject":"physics","chapter":"waves","topic":"Reflection & refraction"}', 10),
  (567, 103, 'Why does sound bend around corners?', 'text', 1, 'wave spreading', '{"why":"Diffraction is the spreading of waves when they pass around obstacles or through gaps.","sol":"Step 1: Identify wave type → sound is a wave\nStep 2: Waves can bend when passing obstacles\nStep 3: This bending is called diffraction\nStep 4: Apply concept → sound spreads around corners","steps":["Step 1: Identify wave type → sound is a wave","Step 2: Waves can bend when passing obstacles","Step 3: This bending is called diffraction","Step 4: Apply concept → sound spreads around corners"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q1","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 0),
  (568, 103, 'What happens in destructive interference?', 'text', 1, 'opposite phases', '{"why":"Destructive interference occurs when waves meet out of phase and reduce total amplitude.","sol":"Step 1: Two waves meet\nStep 2: One crest meets a trough\nStep 3: They cancel each other partially or fully\nStep 4: Resulting amplitude decreases","steps":["Step 1: Two waves meet","Step 2: One crest meets a trough","Step 3: They cancel each other partially or fully","Step 4: Resulting amplitude decreases"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q2","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 1),
  (569, 103, 'If two identical waves meet crest to crest, what happens?', 'text', 1, 'same phase', '{"why":"Constructive interference occurs when waves combine in phase, increasing total amplitude.","sol":"Step 1: Identify phase → crest meets crest\nStep 2: Waves are in phase\nStep 3: Add amplitudes\nStep 4: Result = increased amplitude","steps":["Step 1: Identify phase → crest meets crest","Step 2: Waves are in phase","Step 3: Add amplitudes","Step 4: Result = increased amplitude"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q3","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 2),
  (570, 103, 'Two identical waves each have amplitude 3 cm. They meet crest to crest. Find resultant amplitude.', 'text', 1, 'Use constructive interference (add amplitudes)', '{"why":"Constructive interference increases amplitude when waves meet in phase.","sol":"Step 1: Identify amplitudes → A1 = 3 cm, A2 = 3 cm\nStep 2: Waves meet crest to crest → constructive interference\nStep 3: Apply formula → A_result = A1 + A2\nStep 4: Substitute → A_result = 3 + 3\nStep 5: Calculate → A_result = 6 cm","steps":["Step 1: Identify amplitudes → A1 = 3 cm, A2 = 3 cm","Step 2: Waves meet crest to crest → constructive interference","Step 3: Apply formula → A_result = A1 + A2","Step 4: Substitute → A_result = 3 + 3","Step 5: Calculate → A_result = 6 cm"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q5","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 3),
  (571, 103, 'Two waves of amplitude 5 cm and 3 cm meet crest to trough. Find resultant amplitude.', 'text', 1, 'Use destructive interference (subtract amplitudes)', '{"why":"Destructive interference reduces amplitude when waves are out of phase.","sol":"Step 1: Identify amplitudes → A1 = 5 cm, A2 = 3 cm\nStep 2: Crest meets trough → destructive interference\nStep 3: Apply formula → A_result = A1 - A2\nStep 4: Substitute → A_result = 5 - 3\nStep 5: Calculate → A_result = 2 cm","steps":["Step 1: Identify amplitudes → A1 = 5 cm, A2 = 3 cm","Step 2: Crest meets trough → destructive interference","Step 3: Apply formula → A_result = A1 - A2","Step 4: Substitute → A_result = 5 - 3","Step 5: Calculate → A_result = 2 cm"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q6","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 4),
  (572, 103, 'A wave travels 340 m in 2 seconds. Find its speed.', 'text', 1, 'Use speed = distance ÷ time', '{"why":"Wave speed is distance covered per unit time.","sol":"Step 1: Identify values → d = 340 m, t = 2 s\nStep 2: Write formula → v = d / t\nStep 3: Substitute → v = 340 / 2\nStep 4: Calculate → v = 170 m/s","steps":["Step 1: Identify values → d = 340 m, t = 2 s","Step 2: Write formula → v = d / t","Step 3: Substitute → v = 340 / 2","Step 4: Calculate → v = 170 m/s"],"options":[],"conceptId":"physics_waves_diffraction_interference","skillId":"physics_waves","subskillId":"physics_waves_q7","subject":"physics","chapter":"waves","topic":"Diffraction & Interference"}', 5),
  (573, 104, 'A charge of 18C flows in 3s. Find current.', 'text', 1, 'Use I = Q / t', '{"why":"Current is the rate of flow of charge per unit time.","sol":"Step 1: Identify values → Q = 18C, t = 3s\nStep 2: Write formula → I = Q / t\nStep 3: Substitute values → I = 18 / 3\nStep 4: Calculate → I = 6A","steps":["Step 1: Identify values → Q = 18C, t = 3s","Step 2: Write formula → I = Q / t","Step 3: Substitute values → I = 18 / 3","Step 4: Calculate → I = 6A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 0),
  (574, 104, 'Find current if V = 12V and R = 3Ω.', 'text', 1, 'Use Ohm''s Law I = V / R', '{"why":"Ohm''s Law relates voltage, current, and resistance.","sol":"Step 1: Identify values → V = 12V, R = 3Ω\nStep 2: Write formula → I = V / R\nStep 3: Substitute values → I = 12 / 3\nStep 4: Calculate → I = 4A","steps":["Step 1: Identify values → V = 12V, R = 3Ω","Step 2: Write formula → I = V / R","Step 3: Substitute values → I = 12 / 3","Step 4: Calculate → I = 4A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 1),
  (575, 104, 'Find the resistance if V = 24V and I = 6A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance opposes the flow of electric current.","sol":"Step 1: Identify values → V = 24V, I = 6A\nStep 2: Write formula → R = V / I\nStep 3: Substitute values → R = 24 / 6\nStep 4: Calculate → R = 4Ω","steps":["Step 1: Identify values → V = 24V, I = 6A","Step 2: Write formula → R = V / I","Step 3: Substitute values → R = 24 / 6","Step 4: Calculate → R = 4Ω"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 2),
  (576, 104, 'Find the voltage if I = 5A and R = 8Ω.', 'text', 1, 'Use V = IR', '{"why":"Voltage is the electrical energy supplied per unit charge.","sol":"Step 1: Identify values → I = 5A, R = 8Ω\nStep 2: Write formula → V = IR\nStep 3: Substitute values → V = 5 × 8\nStep 4: Calculate → V = 40V","steps":["Step 1: Identify values → I = 5A, R = 8Ω","Step 2: Write formula → V = IR","Step 3: Substitute values → V = 5 × 8","Step 4: Calculate → V = 40V"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 3),
  (577, 104, 'A charge of 60C flows in 12s. Find the current.', 'text', 1, 'Use I = Q / t', '{"why":"Current tells us how much charge passes a point each second.","sol":"Step 1: Identify values → Q = 60C, t = 12s\nStep 2: Write formula → I = Q / t\nStep 3: Substitute values → I = 60 / 12\nStep 4: Calculate → I = 5A","steps":["Step 1: Identify values → Q = 60C, t = 12s","Step 2: Write formula → I = Q / t","Step 3: Substitute values → I = 60 / 12","Step 4: Calculate → I = 5A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 4),
  (578, 104, 'A bulb uses 120W at 240V. Find the current.', 'text', 1, 'Use P = VI', '{"why":"Power equals voltage multiplied by current.","sol":"Step 1: Identify values → P = 120W, V = 240V\nStep 2: Rearrange formula → I = P / V\nStep 3: Substitute values → I = 120 / 240\nStep 4: Calculate → I = 0.5A","steps":["Step 1: Identify values → P = 120W, V = 240V","Step 2: Rearrange formula → I = P / V","Step 3: Substitute values → I = 120 / 240","Step 4: Calculate → I = 0.5A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 5),
  (579, 104, 'A circuit has V = 18V and I = 3A. Find the power.', 'text', 1, 'Use P = VI', '{"why":"Electrical power is the rate at which electrical energy is used.","sol":"Step 1: Identify values → V = 18V, I = 3A\nStep 2: Write formula → P = VI\nStep 3: Substitute values → P = 18 × 3\nStep 4: Calculate → P = 54W","steps":["Step 1: Identify values → V = 18V, I = 3A","Step 2: Write formula → P = VI","Step 3: Substitute values → P = 18 × 3","Step 4: Calculate → P = 54W"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 6),
  (580, 104, 'An appliance uses 1000J of energy in 50s. Find the power.', 'text', 1, 'Use P = E / t', '{"why":"Power measures how quickly energy is transferred.","sol":"Step 1: Identify values → E = 1000J, t = 50s\nStep 2: Write formula → P = E / t\nStep 3: Substitute values → P = 1000 / 50\nStep 4: Calculate → P = 20W","steps":["Step 1: Identify values → E = 1000J, t = 50s","Step 2: Write formula → P = E / t","Step 3: Substitute values → P = 1000 / 50","Step 4: Calculate → P = 20W"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 7),
  (581, 104, 'A resistor of 5Ω carries a current of 4A. Find the voltage.', 'text', 1, 'Use V = IR', '{"why":"Voltage across a resistor depends on current and resistance.","sol":"Step 1: Identify values → I = 4A, R = 5Ω\nStep 2: Write formula → V = IR\nStep 3: Substitute values → V = 4 × 5\nStep 4: Calculate → V = 20V","steps":["Step 1: Identify values → I = 4A, R = 5Ω","Step 2: Write formula → V = IR","Step 3: Substitute values → V = 4 × 5","Step 4: Calculate → V = 20V"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 8),
  (582, 104, 'Find the resistance if V = 30V and I = 5A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance determines how much a material opposes current flow.","sol":"Step 1: Identify values → V = 30V, I = 5A\nStep 2: Write formula → R = V / I\nStep 3: Substitute values → R = 30 / 5\nStep 4: Calculate → R = 6Ω","steps":["Step 1: Identify values → V = 30V, I = 5A","Step 2: Write formula → R = V / I","Step 3: Substitute values → R = 30 / 5","Step 4: Calculate → R = 6Ω"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 9),
  (583, 104, 'A battery supplies 48V to a 12Ω resistor. Find the current.', 'text', 1, 'Use I = V / R', '{"why":"Current increases when voltage increases or resistance decreases.","sol":"Step 1: Identify values → V = 48V, R = 12Ω\nStep 2: Write formula → I = V / R\nStep 3: Substitute values → I = 48 / 12\nStep 4: Calculate → I = 4A","steps":["Step 1: Identify values → V = 48V, R = 12Ω","Step 2: Write formula → I = V / R","Step 3: Substitute values → I = 48 / 12","Step 4: Calculate → I = 4A"],"options":[],"conceptId":"physics_em_current_voltage","skillId":"physics_em","subskillId":"physics_em_q11","subject":"physics","chapter":"em","topic":"Current & Voltage"}', 10),
  (584, 105, 'In a parallel circuit, branch currents are 2A, 3A and 5A. Find total current.', 'text', 1, 'Add all branch currents', '{"why":"In parallel circuits, total current is the sum of currents in all branches.","sol":"I(total) = 2 + 3 + 5 = 10A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In parallel circuits, total current is the sum of currents in all branches.","Step 3: State the final conclusion: 10A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 0),
  (585, 105, 'A series circuit has a current of 3A. What is the current through each resistor?', 'text', 1, 'Series = same current everywhere', '{"why":"In a series circuit, current is the same at all points because there is only one path.","sol":"I1 = I2 = I3 = 3A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In a series circuit, current is the same at all points because there is only one path.","Step 3: State the final conclusion: 3A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 1),
  (586, 105, 'A voltage of 12V is applied across a resistor of 4Ω. Find the current.', 'text', 1, 'Use Ohm’s Law: I = V / R', '{"why":"Ohm’s Law states that current equals voltage divided by resistance.","sol":"I = 12 / 4 = 3A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Ohm’s Law states that current equals voltage divided by resistance.","Step 3: State the final conclusion: 3A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 2),
  (587, 105, 'Find resistance if voltage is 20V and current is 5A.', 'text', 1, 'Use R = V / I', '{"why":"Resistance is found by dividing voltage by current.","sol":"R = 20 / 5 = 4Ω","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Resistance is found by dividing voltage by current.","Step 3: State the final conclusion: 4Ω"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 3),
  (588, 105, 'A circuit has two branches carrying 1.5A and 2.5A. Find total current.', 'text', 1, 'Sum branch currents', '{"why":"Total current in a parallel circuit is the sum of all branch currents.","sol":"1.5 + 2.5 = 4A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current in a parallel circuit is the sum of all branch currents.","Step 3: State the final conclusion: 4A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 4),
  (589, 105, 'If a 9V battery pushes 3A through a circuit, find resistance.', 'text', 1, 'R = V / I', '{"why":"Divide voltage by current to get resistance.","sol":"R = 9 / 3 = 3Ω","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Divide voltage by current to get resistance.","Step 3: State the final conclusion: 3Ω"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 5),
  (590, 105, 'In a parallel circuit, total current is 8A. If one branch is 3A, find the other branch current.', 'text', 1, 'Subtract known current', '{"why":"Total current equals sum of branch currents, so subtract to find missing value.","sol":"8 - 3 = 5A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current equals sum of branch currents, so subtract to find missing value.","Step 3: State the final conclusion: 5A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 6),
  (591, 105, 'A resistor has 6Ω resistance and current of 2A. Find voltage.', 'text', 1, 'Use V = IR', '{"why":"Voltage equals current multiplied by resistance.","sol":"V = 2 × 6 = 12V","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Voltage equals current multiplied by resistance.","Step 3: State the final conclusion: 12V"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 7),
  (592, 105, 'Two identical bulbs in series each carry 1.5A. What is total current?', 'text', 1, 'Series current rule', '{"why":"In series circuits, current is constant throughout the circuit.","sol":"Same current flows in series circuit","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: In series circuits, current is constant throughout the circuit.","Step 3: State the final conclusion: 1.5A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 8),
  (593, 105, 'A circuit has 3 parallel branches carrying 2A, 2A and 6A. Find total current.', 'text', 1, 'Add all values', '{"why":"Total current in parallel circuits is the sum of branch currents.","sol":"2 + 2 + 6 = 10A","steps":["Step 1: Identify key concept: Define the required principles for Series & Parallel Circuits.","Step 2: Apply governing rule: Total current in parallel circuits is the sum of branch currents.","Step 3: State the final conclusion: 10A"],"options":[],"conceptId":"physics_em_series_parallel_circuits","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Series & Parallel Circuits"}', 9),
  (594, 106, 'What is a magnetic field?', 'text', 1, 'region of influence', '{"why":"Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.\nStep 3: State the final conclusion: A region around a magnet or current-carrying conductor where magnetic forces can be experienced.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Magnetic fields are invisible but can be detected through their effects on materials like iron or compass needles.","Step 3: State the final conclusion: A region around a magnet or current-carrying conductor where magnetic forces can be experienced."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 0),
  (595, 106, 'What do magnetic field lines show?', 'text', 1, 'direction + strength', '{"why":"Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.\nStep 3: State the final conclusion: They show the direction and strength of a magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Closer field lines indicate a stronger magnetic field, and the direction shows how a north pole would move.","Step 3: State the final conclusion: They show the direction and strength of a magnetic field."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 1),
  (596, 106, 'In which direction do magnetic field lines flow outside a magnet?', 'text', 1, 'N to S', '{"why":"Outside the magnet, field lines always go from North to South, and inside they return from South to North.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Outside the magnet, field lines always go from North to South, and inside they return from South to North.\nStep 3: State the final conclusion: From North pole to South pole.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Outside the magnet, field lines always go from North to South, and inside they return from South to North.","Step 3: State the final conclusion: From North pole to South pole."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 2),
  (597, 106, 'What are magnetic domains?', 'text', 1, 'tiny magnets', '{"why":"Each domain acts like a dipole, and their alignment determines whether a material is magnetised.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Each domain acts like a dipole, and their alignment determines whether a material is magnetised.\nStep 3: State the final conclusion: Small regions inside a material that behave like tiny magnets.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Each domain acts like a dipole, and their alignment determines whether a material is magnetised.","Step 3: State the final conclusion: Small regions inside a material that behave like tiny magnets."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 3),
  (598, 106, 'Why is a material unmagnetised?', 'text', 1, 'random orientation', '{"why":"Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.\nStep 3: State the final conclusion: Because its magnetic domains are randomly arranged.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Randomly arranged domains cancel each other’s magnetic effects, resulting in no overall magnetism.","Step 3: State the final conclusion: Because its magnetic domains are randomly arranged."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 4),
  (599, 106, 'What happens to magnetic domains when a material is magnetised?', 'text', 1, 'alignment', '{"why":"Aligned domains reinforce each other, producing a strong net magnetic field.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Aligned domains reinforce each other, producing a strong net magnetic field.\nStep 3: State the final conclusion: They align in the same direction.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Aligned domains reinforce each other, producing a strong net magnetic field.","Step 3: State the final conclusion: They align in the same direction."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 5),
  (600, 106, 'Why is repulsion the only sure test for polarity?', 'text', 1, 'attraction is not enough', '{"why":"Only repulsion confirms that two poles are the same type (N–N or S–S).","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Only repulsion confirms that two poles are the same type (N–N or S–S).\nStep 3: State the final conclusion: Because attraction can occur with both poles, but repulsion only occurs between like poles.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Only repulsion confirms that two poles are the same type (N–N or S–S).","Step 3: State the final conclusion: Because attraction can occur with both poles, but repulsion only occurs between like poles."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 6),
  (601, 106, 'What causes demagnetisation?', 'text', 1, 'heat, shock, AC', '{"why":"These disturb the alignment of magnetic domains, reducing or removing magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: These disturb the alignment of magnetic domains, reducing or removing magnetism.\nStep 3: State the final conclusion: Heat, hammering, or alternating current.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: These disturb the alignment of magnetic domains, reducing or removing magnetism.","Step 3: State the final conclusion: Heat, hammering, or alternating current."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 7),
  (602, 106, 'Why does a compass needle align north-south?', 'text', 1, 'Earth is a magnet', '{"why":"The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.\nStep 3: State the final conclusion: Because Earth has a magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: The compass aligns with Earth’s magnetic field, showing that Earth behaves like a giant magnet.","Step 3: State the final conclusion: Because Earth has a magnetic field."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 8),
  (603, 106, 'How does stroking magnetise a material?', 'text', 1, 'domain alignment', '{"why":"Repeated stroking forces domains to line up, creating a net magnetic field.","sol":"Step 1: Identify key concept: Define the required principles for Magnetic fields.\nStep 2: Apply governing rule: Repeated stroking forces domains to line up, creating a net magnetic field.\nStep 3: State the final conclusion: It aligns magnetic domains in one direction.","steps":["Step 1: Identify key concept: Define the required principles for Magnetic fields.","Step 2: Apply governing rule: Repeated stroking forces domains to line up, creating a net magnetic field.","Step 3: State the final conclusion: It aligns magnetic domains in one direction."],"options":[],"conceptId":"physics_em_magnetic_fields","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Magnetic fields"}', 9),
  (604, 107, 'What is electromagnetism?', 'text', 1, 'electricity + magnetism', '{"why":"Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.\nStep 3: State the final conclusion: Electromagnetism is the relationship between electric current and magnetic fields.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Electric current produces a magnetic field around a conductor, showing the link between electricity and magnetism.","Step 3: State the final conclusion: Electromagnetism is the relationship between electric current and magnetic fields."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 0),
  (605, 107, 'What happens when current flows in a wire?', 'text', 1, 'magnetic field forms', '{"why":"Moving electric charges (current) generate a magnetic field around the conductor.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Moving electric charges (current) generate a magnetic field around the conductor.\nStep 3: State the final conclusion: A magnetic field is produced around the wire.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Moving electric charges (current) generate a magnetic field around the conductor.","Step 3: State the final conclusion: A magnetic field is produced around the wire."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 1),
  (606, 107, 'Why is a solenoid stronger than a straight wire?', 'text', 1, 'many loops', '{"why":"Each loop produces a magnetic field and they add together, making the overall field stronger.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Each loop produces a magnetic field and they add together, making the overall field stronger.\nStep 3: State the final conclusion: Because magnetic fields from each coil turn combine.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Each loop produces a magnetic field and they add together, making the overall field stronger.","Step 3: State the final conclusion: Because magnetic fields from each coil turn combine."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 2),
  (607, 107, 'How do you increase the strength of an electromagnet?', 'text', 1, 'current, turns, core', '{"why":"All these factors increase the strength of the magnetic field produced.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: All these factors increase the strength of the magnetic field produced.\nStep 3: State the final conclusion: Increase current, increase number of coil turns, and use a soft iron core.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: All these factors increase the strength of the magnetic field produced.","Step 3: State the final conclusion: Increase current, increase number of coil turns, and use a soft iron core."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 3),
  (608, 107, 'What is the role of a soft iron core in an electromagnet?', 'text', 1, 'magnetic enhancement', '{"why":"Soft iron becomes magnetized easily and concentrates magnetic field lines.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Soft iron becomes magnetized easily and concentrates magnetic field lines.\nStep 3: State the final conclusion: It increases the strength of the magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Soft iron becomes magnetized easily and concentrates magnetic field lines.","Step 3: State the final conclusion: It increases the strength of the magnetic field."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 4),
  (609, 107, 'Why does reversing current reverse magnetic field direction?', 'text', 1, 'direction of charge flow', '{"why":"Changing current direction changes the motion of charges, reversing the field.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Changing current direction changes the motion of charges, reversing the field.\nStep 3: State the final conclusion: Because magnetic field direction depends on current direction.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Changing current direction changes the motion of charges, reversing the field.","Step 3: State the final conclusion: Because magnetic field direction depends on current direction."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 5),
  (610, 107, 'What is produced around a current-carrying conductor?', 'text', 1, 'invisible force field', '{"why":"Electric current generates a circular magnetic field around the conductor.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Electric current generates a circular magnetic field around the conductor.\nStep 3: State the final conclusion: A magnetic field.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Electric current generates a circular magnetic field around the conductor.","Step 3: State the final conclusion: A magnetic field."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 6),
  (611, 107, 'Why do electromagnets stop working when current is switched off?', 'text', 1, 'temporary magnet', '{"why":"Without current, moving charges stop, so the magnetic field disappears.","sol":"Step 1: Identify key concept: Define the required principles for Electromagnetism.\nStep 2: Apply governing rule: Without current, moving charges stop, so the magnetic field disappears.\nStep 3: State the final conclusion: Because the magnetic field depends on electric current.","steps":["Step 1: Identify key concept: Define the required principles for Electromagnetism.","Step 2: Apply governing rule: Without current, moving charges stop, so the magnetic field disappears.","Step 3: State the final conclusion: Because the magnetic field depends on electric current."],"options":[],"conceptId":"physics_em_electromagnetism","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Electromagnetism"}', 7),
  (612, 108, 'A voltage of 20V produces a current of 5A. Find the resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 20 / 5 = 4Ω","steps":["Step 1: Identify the given values: V = 20V and I = 5A.","Step 2: Recall Ohm''s Law for resistance: R = V / I.","Step 3: Substitute the values: R = 20 / 5.","Step 4: Calculate: R = 4Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q1","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 0),
  (613, 108, 'Find the current if V = 12V and R = 3Ω.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = V / R = 12 / 3 = 4A","steps":["Step 1: Identify the given values: V = 12V and R = 3Ω.","Step 2: Recall the formula: I = V / R.","Step 3: Substitute the values: I = 12 / 3.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q2","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 1),
  (614, 108, 'State Ohm''s Law.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Current is directly proportional to voltage provided the temperature remains constant.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Current is directly proportional to voltage provided the temperature remains constant."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q3","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 2),
  (615, 108, 'A battery supplies 24V to a resistor of 6Ω. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = V / R = 24 / 6 = 4A","steps":["Step 1: Identify V = 24V and R = 6Ω.","Step 2: Use the formula I = V / R.","Step 3: Substitute the values: I = 24 / 6.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q4","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 3),
  (616, 108, 'A current of 2A flows through a resistor of 10Ω. Find the voltage.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"V = IR = 2 × 10 = 20V","steps":["Step 1: Identify I = 2A and R = 10Ω.","Step 2: Recall the formula: V = IR.","Step 3: Substitute the values: V = 2 × 10.","Step 4: Calculate: V = 20V."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q5","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 4),
  (617, 108, 'A resistor has a voltage of 18V and a current of 3A. Find its resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 18 / 3 = 6Ω","steps":["Step 1: Identify V = 18V and I = 3A.","Step 2: Recall the formula: R = V / I.","Step 3: Substitute the values: R = 18 / 3.","Step 4: Calculate: R = 6Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q6","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 5),
  (618, 108, 'A charge of 40C passes through a conductor in 8 seconds. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = Q / t = 40 / 8 = 5A","steps":["Step 1: Identify Q = 40C and t = 8s.","Step 2: Recall the formula: I = Q / t.","Step 3: Substitute the values: I = 40 / 8.","Step 4: Calculate: I = 5A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q7","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 6),
  (619, 108, 'A charge of 72C flows for 9 seconds. Calculate the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = Q / t = 72 / 9 = 8A","steps":["Step 1: Identify Q = 72C and t = 9s.","Step 2: Recall the formula: I = Q / t.","Step 3: Substitute the values: I = 72 / 9.","Step 4: Calculate: I = 8A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q8","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 7),
  (620, 108, 'A current of 5A flows for 12 seconds. Find the charge transferred.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Q = It = 5 × 12 = 60C","steps":["Step 1: Identify I = 5A and t = 12s.","Step 2: Recall the formula: Q = It.","Step 3: Substitute the values: Q = 5 × 12.","Step 4: Calculate: Q = 60C."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q9","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 8),
  (621, 108, 'A current of 3A flows for 15 seconds. Calculate the charge.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Q = It = 3 × 15 = 45C","steps":["Step 1: Identify I = 3A and t = 15s.","Step 2: Recall the formula: Q = It.","Step 3: Substitute the values: Q = 3 × 15.","Step 4: Calculate: Q = 45C."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q10","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 9),
  (622, 108, 'An electric heater operates at 240V and draws a current of 5A. Find the power.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"P = VI = 240 × 5 = 1200W","steps":["Step 1: Identify V = 240V and I = 5A.","Step 2: Recall the formula: P = VI.","Step 3: Substitute the values: P = 240 × 5.","Step 4: Calculate: P = 1200W."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q11","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 10),
  (623, 108, 'A bulb operates at 12V and draws 2A. Calculate its power.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"P = VI = 12 × 2 = 24W","steps":["Step 1: Identify V = 12V and I = 2A.","Step 2: Recall the formula: P = VI.","Step 3: Substitute the values: P = 12 × 2.","Step 4: Calculate: P = 24W."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q12","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 11),
  (624, 108, 'A motor uses 600W from a 200V supply. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = P / V = 600 / 200 = 3A","steps":["Step 1: Identify P = 600W and V = 200V.","Step 2: Rearrange the power formula: I = P / V.","Step 3: Substitute the values: I = 600 / 200.","Step 4: Calculate: I = 3A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q13","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 12),
  (625, 108, 'An appliance consumes 1000W on a 250V supply. Find the current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"I = P / V = 1000 / 250 = 4A","steps":["Step 1: Identify P = 1000W and V = 250V.","Step 2: Use the formula: I = P / V.","Step 3: Substitute the values: I = 1000 / 250.","Step 4: Calculate: I = 4A."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q14","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 13),
  (626, 108, 'A resistor carries a current of 8A when connected to a 40V supply. Find the resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"R = V / I = 40 / 8 = 5Ω","steps":["Step 1: Identify V = 40V and I = 8A.","Step 2: Recall the formula: R = V / I.","Step 3: Substitute the values: R = 40 / 8.","Step 4: Calculate: R = 5Ω."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q15","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 14),
  (627, 108, 'What is electric current?', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: Electric current is the rate of flow of electric charge through a conductor.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: Electric current is the rate of flow of electric charge through a conductor."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q16","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 15),
  (628, 108, 'State the SI unit of electric current.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of electric current is the ampere (A).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of electric current is the ampere (A)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q17","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 16),
  (629, 108, 'State the SI unit of resistance.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of resistance is the ohm (Ω).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of resistance is the ohm (Ω)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q18","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 17),
  (630, 108, 'State the SI unit of voltage.', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: The SI unit of voltage is the volt (V).","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: The SI unit of voltage is the volt (V)."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q19","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 18),
  (631, 108, 'What instrument is used to measure electric current?', 'text', 1, 'Focus on the core principle of Ohm’s Law.', '{"why":"Demonstrate clear step-by-step reasoning.","sol":"Step 1: Identify key concept: Define the required principles for Ohm’s Law.\nStep 2: Apply governing rule: Analyze the relationship and given criteria.\nStep 3: State the final conclusion: An ammeter is used to measure electric current.","steps":["Step 1: Identify key concept: Define the required principles for Ohm’s Law.","Step 2: Apply governing rule: Analyze the relationship and given criteria.","Step 3: State the final conclusion: An ammeter is used to measure electric current."],"options":[],"conceptId":"physics_em_ohm_s_law","skillId":"physics_em","subskillId":"physics_em_q20","subject":"physics","chapter":"em","topic":"Ohm’s Law"}', 19),
  (632, 109, 'Why do ships float on water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"A floating object remains in equilibrium when the buoyant force equals its weight.","sol":"Step 1: Recall that water exerts an upward force called upthrust (buoyant force).\nStep 2: Compare the ship''s weight with the upthrust acting on it.\nStep 3: When the upthrust equals the weight of the ship, the ship floats.\nStep 4: The large hollow shape of a ship displaces enough water to produce sufficient upthrust.","steps":["Step 1: Recall that water exerts an upward force called upthrust (buoyant force).","Step 2: Compare the ship''s weight with the upthrust acting on it.","Step 3: When the upthrust equals the weight of the ship, the ship floats.","Step 4: The large hollow shape of a ship displaces enough water to produce sufficient upthrust."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q1","subject":"physics","chapter":"fluids","topic":"Fluids"}', 0),
  (633, 109, 'Why does a stone sink in water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"Objects sink when the downward force exceeds the buoyant force.","sol":"Step 1: Identify the weight of the stone acting downward.\nStep 2: Identify the upthrust provided by the water acting upward.\nStep 3: Compare the two forces.\nStep 4: Since the stone''s weight is greater than the upthrust, it sinks.","steps":["Step 1: Identify the weight of the stone acting downward.","Step 2: Identify the upthrust provided by the water acting upward.","Step 3: Compare the two forces.","Step 4: Since the stone''s weight is greater than the upthrust, it sinks."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q2","subject":"physics","chapter":"fluids","topic":"Fluids"}', 1),
  (634, 109, 'State Archimedes'' Principle.', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"This principle explains floating and sinking.","sol":"Step 1: Consider an object immersed in a fluid.\nStep 2: The object displaces some of the fluid.\nStep 3: The displaced fluid has weight.\nStep 4: The upthrust equals the weight of the displaced fluid.","steps":["Step 1: Consider an object immersed in a fluid.","Step 2: The object displaces some of the fluid.","Step 3: The displaced fluid has weight.","Step 4: The upthrust equals the weight of the displaced fluid."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q3","subject":"physics","chapter":"fluids","topic":"Fluids"}', 2),
  (635, 109, 'Why is it easier to swim in seawater than in fresh water?', 'text', 1, 'Focus on the core principle of Fluids.', '{"why":"Greater density increases the buoyant force.","sol":"Step 1: Compare the densities of seawater and fresh water.\nStep 2: Note that seawater is denser because of dissolved salts.\nStep 3: Denser water produces a greater upthrust.\nStep 4: Greater upthrust makes floating easier.","steps":["Step 1: Compare the densities of seawater and fresh water.","Step 2: Note that seawater is denser because of dissolved salts.","Step 3: Denser water produces a greater upthrust.","Step 4: Greater upthrust makes floating easier."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q4","subject":"physics","chapter":"fluids","topic":"Fluids"}', 3),
  (636, 109, 'A force of 200N acts on an area of 4m². Calculate the pressure.', 'text', 1, 'Pressure = Force ÷ Area', '{"why":"Pressure is the force acting per unit area.","sol":"Step 1: Identify the values: Force = 200N and Area = 4m².\nStep 2: Write the formula: P = F ÷ A.\nStep 3: Substitute the values: P = 200 ÷ 4.\nStep 4: Calculate: P = 50 Pa.","steps":["Step 1: Identify the values: Force = 200N and Area = 4m².","Step 2: Write the formula: P = F ÷ A.","Step 3: Substitute the values: P = 200 ÷ 4.","Step 4: Calculate: P = 50 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q5","subject":"physics","chapter":"fluids","topic":"Fluids"}', 4),
  (637, 109, 'A force of 150N acts on an area of 3m². Find the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure increases when force increases or area decreases.","sol":"Step 1: Identify Force = 150N and Area = 3m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 150 ÷ 3.\nStep 4: Calculate: P = 50 Pa.","steps":["Step 1: Identify Force = 150N and Area = 3m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 150 ÷ 3.","Step 4: Calculate: P = 50 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q6","subject":"physics","chapter":"fluids","topic":"Fluids"}', 5),
  (638, 109, 'A pressure of 80Pa acts over an area of 5m². Calculate the force.', 'text', 1, 'Force = Pressure × Area', '{"why":"Force equals pressure multiplied by area.","sol":"Step 1: Identify Pressure = 80Pa and Area = 5m².\nStep 2: Write the formula: F = PA.\nStep 3: Substitute: F = 80 × 5.\nStep 4: Calculate: F = 400N.","steps":["Step 1: Identify Pressure = 80Pa and Area = 5m².","Step 2: Write the formula: F = PA.","Step 3: Substitute: F = 80 × 5.","Step 4: Calculate: F = 400N."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q7","subject":"physics","chapter":"fluids","topic":"Fluids"}', 6),
  (639, 109, 'A pressure of 300Pa is produced by a force of 600N. Find the area.', 'text', 1, 'Area = Force ÷ Pressure', '{"why":"Area is obtained by dividing force by pressure.","sol":"Step 1: Identify Force = 600N and Pressure = 300Pa.\nStep 2: Rearrange the formula: A = F ÷ P.\nStep 3: Substitute: A = 600 ÷ 300.\nStep 4: Calculate: A = 2m².","steps":["Step 1: Identify Force = 600N and Pressure = 300Pa.","Step 2: Rearrange the formula: A = F ÷ P.","Step 3: Substitute: A = 600 ÷ 300.","Step 4: Calculate: A = 2m²."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q8","subject":"physics","chapter":"fluids","topic":"Fluids"}', 7),
  (640, 109, 'A force of 900N acts on an area of 9m². Calculate the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure is directly proportional to force and inversely proportional to area.","sol":"Step 1: Identify Force = 900N and Area = 9m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 900 ÷ 9.\nStep 4: Calculate: P = 100 Pa.","steps":["Step 1: Identify Force = 900N and Area = 9m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 900 ÷ 9.","Step 4: Calculate: P = 100 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q9","subject":"physics","chapter":"fluids","topic":"Fluids"}', 8),
  (641, 109, 'A pressure of 250Pa acts over an area of 8m². Find the force.', 'text', 1, 'Use F = PA', '{"why":"Increasing either pressure or area increases the force.","sol":"Step 1: Identify Pressure = 250Pa and Area = 8m².\nStep 2: Write the formula F = PA.\nStep 3: Substitute: F = 250 × 8.\nStep 4: Calculate: F = 2000N.","steps":["Step 1: Identify Pressure = 250Pa and Area = 8m².","Step 2: Write the formula F = PA.","Step 3: Substitute: F = 250 × 8.","Step 4: Calculate: F = 2000N."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q10","subject":"physics","chapter":"fluids","topic":"Fluids"}', 9),
  (642, 109, 'A force of 360N acts on an area of 12m². Find the pressure.', 'text', 1, 'Use P = F ÷ A', '{"why":"Pressure is measured in pascals (Pa).","sol":"Step 1: Identify Force = 360N and Area = 12m².\nStep 2: Write the formula P = F ÷ A.\nStep 3: Substitute: P = 360 ÷ 12.\nStep 4: Calculate: P = 30 Pa.","steps":["Step 1: Identify Force = 360N and Area = 12m².","Step 2: Write the formula P = F ÷ A.","Step 3: Substitute: P = 360 ÷ 12.","Step 4: Calculate: P = 30 Pa."],"options":[],"conceptId":"physics_fluids_fluids","skillId":"physics_fluids","subskillId":"physics_fluids_q11","subject":"physics","chapter":"fluids","topic":"Fluids"}', 10),
  (643, 110, 'What is radioactivity?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Unstable nuclei lose excess energy by emitting radiation to become more stable.","sol":"Step 1: Recall that some atomic nuclei are unstable.\nStep 2: An unstable nucleus emits radiation without any external influence.\nStep 3: This emission may include alpha particles, beta particles, or gamma rays.\nStep 4: The process continues until the nucleus becomes more stable.","steps":["Step 1: Recall that some atomic nuclei are unstable.","Step 2: An unstable nucleus emits radiation without any external influence.","Step 3: This emission may include alpha particles, beta particles, or gamma rays.","Step 4: The process continues until the nucleus becomes more stable."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q1","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 0),
  (644, 110, 'What is an alpha particle?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Alpha particles are emitted by heavy unstable nuclei.","sol":"Step 1: Recall the three common types of radioactive emissions.\nStep 2: Identify that an alpha particle contains protons and neutrons.\nStep 3: State its composition.\nStep 4: Give the definition.","steps":["Step 1: Recall the three common types of radioactive emissions.","Step 2: Identify that an alpha particle contains protons and neutrons.","Step 3: State its composition.","Step 4: Give the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q2","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 1),
  (645, 110, 'What is a beta particle?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Beta decay helps unstable nuclei achieve greater stability.","sol":"Step 1: Recall radioactive emissions.\nStep 2: Identify the beta particle as a fast-moving electron.\nStep 3: State that it is emitted from the nucleus.\nStep 4: Give the definition.","steps":["Step 1: Recall radioactive emissions.","Step 2: Identify the beta particle as a fast-moving electron.","Step 3: State that it is emitted from the nucleus.","Step 4: Give the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q3","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 2),
  (646, 110, 'What are gamma rays?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"Gamma rays carry excess energy away from unstable nuclei.","sol":"Step 1: Recall that gamma rays are a type of radiation.\nStep 2: Identify that they are electromagnetic waves.\nStep 3: Note that they have no mass and no charge.\nStep 4: State the definition.","steps":["Step 1: Recall that gamma rays are a type of radiation.","Step 2: Identify that they are electromagnetic waves.","Step 3: Note that they have no mass and no charge.","Step 4: State the definition."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q4","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 3),
  (647, 110, 'State one property of alpha particles.', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"They contain two positively charged protons.","sol":"Step 1: Recall the characteristics of alpha particles.\nStep 2: Identify one property.\nStep 3: State the property clearly.","steps":["Step 1: Recall the characteristics of alpha particles.","Step 2: Identify one property.","Step 3: State the property clearly."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q5","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 4),
  (648, 110, 'Why are gamma rays more penetrating than alpha particles?', 'text', 1, 'Focus on the core principle of Modern Physics.', '{"why":"They interact less with matter than charged particles.","sol":"Step 1: Compare the masses of alpha particles and gamma rays.\nStep 2: Recall that gamma rays have no mass or charge.\nStep 3: Less interaction with matter allows deeper penetration.\nStep 4: State the conclusion.","steps":["Step 1: Compare the masses of alpha particles and gamma rays.","Step 2: Recall that gamma rays have no mass or charge.","Step 3: Less interaction with matter allows deeper penetration.","Step 4: State the conclusion."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q6","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 5),
  (649, 110, 'Name two applications of modern physics.', 'text', 1, 'Think medicine and energy.', '{"why":"Both rely on atomic and nuclear physics.","sol":"Step 1: Identify one medical application.\nStep 2: Identify one energy application.\nStep 3: State both applications.","steps":["Step 1: Identify one medical application.","Step 2: Identify one energy application.","Step 3: State both applications."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q7","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 6),
  (650, 110, 'State one medical application of radioactivity.', 'text', 1, 'Think hospitals.', '{"why":"Radiation destroys cancer cells.","sol":"Step 1: Recall how radiation is used in medicine.\nStep 2: Identify one example.\nStep 3: State the application.","steps":["Step 1: Recall how radiation is used in medicine.","Step 2: Identify one example.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q8","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 7),
  (651, 110, 'State one industrial application of radioactivity.', 'text', 1, 'Think manufacturing.', '{"why":"Radiation helps monitor product quality.","sol":"Step 1: Recall industrial uses of radiation.\nStep 2: Identify one example.\nStep 3: State the application.","steps":["Step 1: Recall industrial uses of radiation.","Step 2: Identify one example.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q9","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 8),
  (652, 110, 'State one agricultural application of radioactivity.', 'text', 1, 'Think crops.', '{"why":"Radiation can produce useful genetic variations.","sol":"Step 1: Recall how radiation is used in agriculture.\nStep 2: Identify one use.\nStep 3: State the application.","steps":["Step 1: Recall how radiation is used in agriculture.","Step 2: Identify one use.","Step 3: State the application."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q10","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 9),
  (653, 110, 'State one disadvantage of radioactivity.', 'text', 1, 'Think health effects.', '{"why":"Ionising radiation damages body cells and DNA.","sol":"Step 1: Recall the harmful effects of radiation.\nStep 2: Identify one effect.\nStep 3: State the disadvantage.","steps":["Step 1: Recall the harmful effects of radiation.","Step 2: Identify one effect.","Step 3: State the disadvantage."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q11","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 10),
  (654, 110, 'Why must radioactive materials be handled carefully?', 'text', 1, 'Think safety.', '{"why":"Proper handling reduces exposure and protects human health.","sol":"Step 1: Recall that radiation can damage living tissue.\nStep 2: Consider long-term exposure effects.\nStep 3: State why safety precautions are necessary.","steps":["Step 1: Recall that radiation can damage living tissue.","Step 2: Consider long-term exposure effects.","Step 3: State why safety precautions are necessary."],"options":[],"conceptId":"physics_modern_physics_modern_physics","skillId":"physics_modern_physics","subskillId":"physics_modern_physics_q12","subject":"physics","chapter":"modern_physics","topic":"Modern Physics"}', 11),
  (655, 111, 'What are cathode rays?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"Cathode rays consist of negatively charged electrons.","sol":"Step 1: Recall that a cathode ray tube contains a cathode and an anode in a vacuum.\nStep 2: Electrons are emitted from the cathode when a high voltage is applied.\nStep 3: The electrons travel across the vacuum toward the anode.\nStep 4: These moving electrons are called cathode rays.","steps":["Step 1: Recall that a cathode ray tube contains a cathode and an anode in a vacuum.","Step 2: Electrons are emitted from the cathode when a high voltage is applied.","Step 3: The electrons travel across the vacuum toward the anode.","Step 4: These moving electrons are called cathode rays."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q1","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 0),
  (656, 111, 'State two properties of cathode rays.', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"These properties were demonstrated using cathode ray tubes.","sol":"Step 1: Recall the characteristics of cathode rays.\nStep 2: Identify that they travel in straight lines.\nStep 3: Identify that they are negatively charged.\nStep 4: State both properties.","steps":["Step 1: Recall the characteristics of cathode rays.","Step 2: Identify that they travel in straight lines.","Step 3: Identify that they are negatively charged.","Step 4: State both properties."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q2","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 1),
  (657, 111, 'Why do cathode rays produce shadows?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"Straight-line motion causes shadow formation.","sol":"Step 1: Recall that cathode rays travel in straight lines.\nStep 2: Place an object in their path.\nStep 3: The object blocks the rays.\nStep 4: A shadow forms behind the object.","steps":["Step 1: Recall that cathode rays travel in straight lines.","Step 2: Place an object in their path.","Step 3: The object blocks the rays.","Step 4: A shadow forms behind the object."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q3","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 2),
  (658, 111, 'Why do cathode rays cause fluorescence?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"The kinetic energy of electrons is converted into light energy.","sol":"Step 1: Cathode rays strike a fluorescent material.\nStep 2: The electrons transfer energy to the material.\nStep 3: The material emits visible light.\nStep 4: The screen glows.","steps":["Step 1: Cathode rays strike a fluorescent material.","Step 2: The electrons transfer energy to the material.","Step 3: The material emits visible light.","Step 4: The screen glows."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q4","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 3),
  (659, 111, 'Why can cathode rays turn a light paddle wheel?', 'text', 1, 'Focus on the core principle of Cathode Rays and Cathode Ray Tube.', '{"why":"This demonstrates that cathode rays are particles.","sol":"Step 1: Recall that cathode rays are streams of particles.\nStep 2: The particles strike the paddle wheel.\nStep 3: They transfer momentum to the wheel.\nStep 4: The wheel rotates.","steps":["Step 1: Recall that cathode rays are streams of particles.","Step 2: The particles strike the paddle wheel.","Step 3: They transfer momentum to the wheel.","Step 4: The wheel rotates."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q5","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 4),
  (660, 111, 'Why are cathode rays deflected in electric fields?', 'text', 1, 'Think about their charge.', '{"why":"Charged particles experience forces in electric fields.","sol":"Step 1: Recall that cathode rays are electrons.\nStep 2: Electrons have a negative charge.\nStep 3: Electric fields exert forces on charged particles.\nStep 4: Therefore, cathode rays are deflected toward the positive plate.","steps":["Step 1: Recall that cathode rays are electrons.","Step 2: Electrons have a negative charge.","Step 3: Electric fields exert forces on charged particles.","Step 4: Therefore, cathode rays are deflected toward the positive plate."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q6","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 5),
  (661, 111, 'Why are cathode rays deflected by magnetic fields?', 'text', 1, 'Think about moving charges.', '{"why":"Magnetic fields affect moving charged particles.","sol":"Step 1: Recall that cathode rays are moving electrons.\nStep 2: Moving charges experience magnetic forces.\nStep 3: The magnetic field changes their direction.\nStep 4: The rays are deflected.","steps":["Step 1: Recall that cathode rays are moving electrons.","Step 2: Moving charges experience magnetic forces.","Step 3: The magnetic field changes their direction.","Step 4: The rays are deflected."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q7","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 6),
  (662, 111, 'What happens when cathode rays strike a metal target?', 'text', 1, 'Think X-rays.', '{"why":"Rapid deceleration of electrons produces X-rays.","sol":"Step 1: Cathode rays move at very high speed.\nStep 2: They collide with the metal target.\nStep 3: They lose energy suddenly.\nStep 4: X-rays are produced.","steps":["Step 1: Cathode rays move at very high speed.","Step 2: They collide with the metal target.","Step 3: They lose energy suddenly.","Step 4: X-rays are produced."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q8","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 7),
  (663, 111, 'Why is a vacuum needed in a cathode ray tube?', 'text', 1, 'Think collisions.', '{"why":"The rays can travel efficiently only in a vacuum.","sol":"Step 1: Recall that air contains many particles.\nStep 2: Electrons would collide with air molecules.\nStep 3: These collisions would reduce their energy.\nStep 4: A vacuum allows electrons to travel freely.","steps":["Step 1: Recall that air contains many particles.","Step 2: Electrons would collide with air molecules.","Step 3: These collisions would reduce their energy.","Step 4: A vacuum allows electrons to travel freely."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q9","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 8),
  (664, 111, 'How do cathode rays demonstrate that electrons are particles?', 'text', 1, 'Think mass and momentum.', '{"why":"Objects with mass behave as particles.","sol":"Step 1: Observe that cathode rays can move a light paddle wheel.\nStep 2: Only particles with mass can transfer momentum.\nStep 3: The wheel rotates after being struck.\nStep 4: Therefore, cathode rays are particles.","steps":["Step 1: Observe that cathode rays can move a light paddle wheel.","Step 2: Only particles with mass can transfer momentum.","Step 3: The wheel rotates after being struck.","Step 4: Therefore, cathode rays are particles."],"options":[],"conceptId":"physics_cathode_rays_cathode_rays_and_cathode_ray_tube","skillId":"physics_cathode_rays","subskillId":"physics_cathode_rays_q10","subject":"physics","chapter":"cathode_rays","topic":"Cathode Rays and Cathode Ray Tube"}', 9),
  (665, 112, 'What is photoelectric emission?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Photons transfer their energy to electrons in the metal, causing them to escape if energy exceeds work function.","sol":"Step 1: Identify incident radiation (light of sufficient frequency).\nStep 2: Identify the surface (metal surface).\nStep 3: State the emission of electrons (photoelectrons).","steps":["Step 1: Identify incident radiation (light of sufficient frequency).","Step 2: Identify the surface (metal surface).","Step 3: State the emission of electrons (photoelectrons)."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q1","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 0),
  (666, 112, 'Define threshold frequency (f₀) in photoelectric effect.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"If light frequency is below threshold frequency, individual photon energy is less than the work function.","sol":"Step 1: Consider the frequency of incident radiation.\nStep 2: Define the minimum boundary required for emission.\nStep 3: Explain that light below this frequency causes no electron ejection regardless of intensity.","steps":["Step 1: Consider the frequency of incident radiation.","Step 2: Define the minimum boundary required for emission.","Step 3: Explain that light below this frequency causes no electron ejection regardless of intensity."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q2","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 1),
  (667, 112, 'Define the work function (φ) of a metal.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Electrons are bound to metal atoms and require a specific threshold energy to escape.","sol":"Step 1: Consider the binding energy of electrons in a metal.\nStep 2: Define the minimum energy required.\nStep 3: State that it is the minimum energy needed to free an electron from the metal surface.","steps":["Step 1: Consider the binding energy of electrons in a metal.","Step 2: Define the minimum energy required.","Step 3: State that it is the minimum energy needed to free an electron from the metal surface."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q3","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 2),
  (668, 112, 'State Einstein''s photoelectric equation.', 'text', 1, 'Think energy of photon = work function + max kinetic energy.', '{"why":"Incident photon energy (hf) is used to overcome work function (φ) and any remaining energy becomes kinetic energy of photoelectron.","sol":"Step 1: Write photon energy (hf).\nStep 2: Equate to work function (φ) plus maximum kinetic energy (KEmax).\nStep 3: State equation: hf = φ + KEmax or KEmax = hf - φ.","steps":["Step 1: Write photon energy (hf).","Step 2: Equate to work function (φ) plus maximum kinetic energy (KEmax).","Step 3: State equation: hf = φ + KEmax or KEmax = hf - φ."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q4","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 3),
  (669, 112, 'What effect does increasing the intensity of incident light have on photoelectric emission?', 'text', 1, 'Think number of photons vs energy per photon.', '{"why":"Intensity determines the photon flux, while light frequency determines individual photon energy.","sol":"Step 1: Understand that higher intensity means more photons per second.\nStep 2: State that each photon interacts with one electron.\nStep 3: Conclude that more photoelectrons are emitted per second (photocurrent), but max kinetic energy stays constant.","steps":["Step 1: Understand that higher intensity means more photons per second.","Step 2: State that each photon interacts with one electron.","Step 3: Conclude that more photoelectrons are emitted per second (photocurrent), but max kinetic energy stays constant."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q5","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 4),
  (670, 112, 'Why does light below threshold frequency fail to emit electrons even if intensity is increased?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"Photoelectric absorption is a one-to-one photon-electron interaction.","sol":"Step 1: Recognize that one photon interacts with one electron.\nStep 2: Note that if individual photon energy (hf) < work function (φ), no energy accumulates.\nStep 3: Conclude that increasing intensity only supplies more low-energy photons.","steps":["Step 1: Recognize that one photon interacts with one electron.","Step 2: Note that if individual photon energy (hf) < work function (φ), no energy accumulates.","Step 3: Conclude that increasing intensity only supplies more low-energy photons."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q6","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 5),
  (671, 112, 'Calculate the energy of a photon of light with frequency 6.0 × 10¹⁴ Hz. (Planck''s constant h = 6.63 × 10⁻³⁴ J·s)', 'text', 1, 'Use E = hf', '{"why":"Photon energy is directly proportional to frequency via Planck''s constant.","sol":"Step 1: Identify h = 6.63 × 10⁻³⁴ J·s and f = 6.0 × 10¹⁴ Hz.\nStep 2: Apply formula E = h × f.\nStep 3: Substitute: E = (6.63 × 10⁻³⁴) × (6.0 × 10¹⁴).\nStep 4: Calculate: E = 3.978 × 10⁻¹⁹ J.","steps":["Step 1: Identify h = 6.63 × 10⁻³⁴ J·s and f = 6.0 × 10¹⁴ Hz.","Step 2: Apply formula E = h × f.","Step 3: Substitute: E = (6.63 × 10⁻³⁴) × (6.0 × 10¹⁴).","Step 4: Calculate: E = 3.978 × 10⁻¹⁹ J."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q7","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 6),
  (672, 112, 'A metal has a work function of 2.5 × 10⁻¹⁹ J. If incident light delivers photon energy of 4.2 × 10⁻¹⁹ J, find the maximum kinetic energy of the emitted photoelectrons.', 'text', 1, 'Use KEmax = hf - φ', '{"why":"The excess energy above the work function becomes the maximum kinetic energy of the emitted photoelectron.","sol":"Step 1: Identify photon energy E = hf = 4.2 × 10⁻¹⁹ J.\nStep 2: Identify work function φ = 2.5 × 10⁻¹⁹ J.\nStep 3: Apply KEmax = hf - φ.\nStep 4: Calculate KEmax = (4.2 × 10⁻¹⁹) - (2.5 × 10⁻¹⁹) = 1.7 × 10⁻¹⁹ J.","steps":["Step 1: Identify photon energy E = hf = 4.2 × 10⁻¹⁹ J.","Step 2: Identify work function φ = 2.5 × 10⁻¹⁹ J.","Step 3: Apply KEmax = hf - φ.","Step 4: Calculate KEmax = (4.2 × 10⁻¹⁹) - (2.5 × 10⁻¹⁹) = 1.7 × 10⁻¹⁹ J."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q8","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 7),
  (673, 112, 'What is stopping potential in the photoelectric effect?', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"At stopping potential, work done against electric field equals maximum kinetic energy of photoelectrons (eVs = KEmax).","sol":"Step 1: Define opposing electric potential applied to anode.\nStep 2: State the minimum retarding potential that stops the fastest photoelectrons.\nStep 3: Relate to maximum kinetic energy (eVs = KEmax).","steps":["Step 1: Define opposing electric potential applied to anode.","Step 2: State the minimum retarding potential that stops the fastest photoelectrons.","Step 3: Relate to maximum kinetic energy (eVs = KEmax)."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q9","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 8),
  (674, 112, 'State two practical applications of photoelectric emission.', 'text', 1, 'Focus on the core principle of Photoelectric Emission.', '{"why":"These devices convert incident light energy directly into electrical signals using photoelectric principles.","sol":"Step 1: Identify technology utilizing light detection.\nStep 2: Give solar cells / solar panels.\nStep 3: Give light sensors in cameras or automatic doors.","steps":["Step 1: Identify technology utilizing light detection.","Step 2: Give solar cells / solar panels.","Step 3: Give light sensors in cameras or automatic doors."],"options":[],"conceptId":"physics_photoelectric_emission_photoelectric_emission","skillId":"physics_photoelectric_emission","subskillId":"physics_photoelectric_emission_q10","subject":"physics","chapter":"photoelectric_emission","topic":"Photoelectric Emission"}', 9),
  (675, 113, 'What is chemistry?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Core definition","sol":"Step 1: Identify matter\nStep 2: Study composition\nStep 3: Study changes","steps":["Step 1: Identify matter","Step 2: Study composition","Step 3: Study changes"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q1","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 0),
  (676, 113, 'What is matter?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Foundation concept","sol":"Step 1: Has mass\nStep 2: Occupies space","steps":["Step 1: Has mass","Step 2: Occupies space"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q2","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 1),
  (677, 113, 'Why is chemistry important?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Application","sol":"Step 1: Explains substances\nStep 2: Helps medicine\nStep 3: Supports industry","steps":["Step 1: Explains substances","Step 2: Helps medicine","Step 3: Supports industry"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q3","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 2),
  (678, 113, 'What is a chemical change?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Concept clarity","sol":"Step 1: Identify reaction\nStep 2: New substance formed","steps":["Step 1: Identify reaction","Step 2: New substance formed"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q4","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 3),
  (679, 113, 'Why does structure affect properties?', 'text', 1, 'Focus on the core principle of Meaning of Chemistry.', '{"why":"Advanced understanding","sol":"Step 1: Arrangement matters\nStep 2: Affects bonding\nStep 3: Changes behavior","steps":["Step 1: Arrangement matters","Step 2: Affects bonding","Step 3: Changes behavior"],"options":[],"conceptId":"chemistry_introduction_meaning_of_chemistry","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q5","subject":"chemistry","chapter":"introduction","topic":"Meaning of Chemistry"}', 4),
  (680, 114, 'Why should safety rules be followed in a laboratory?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Safety importance","sol":"Step 1: Identify possible dangers\nStep 2: Understand prevention\nStep 3: Link to safety","steps":["Step 1: Identify possible dangers","Step 2: Understand prevention","Step 3: Link to safety"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q1","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 0),
  (681, 114, 'Why should you not smell chemicals directly?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Health protection","sol":"Step 1: Chemicals may be toxic\nStep 2: Direct inhalation is dangerous","steps":["Step 1: Chemicals may be toxic","Step 2: Direct inhalation is dangerous"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q2","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 1),
  (682, 114, 'Why is a round-bottom flask used for heating?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Efficiency","sol":"Step 1: Shape distributes heat\nStep 2: Prevents cracking","steps":["Step 1: Shape distributes heat","Step 2: Prevents cracking"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q3","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 2),
  (683, 114, 'Why is a burette used in titration?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Accuracy","sol":"Step 1: Requires precision\nStep 2: Measures small volumes accurately","steps":["Step 1: Requires precision","Step 2: Measures small volumes accurately"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q4","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 3),
  (684, 114, 'Why is a pipette important?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Precision","sol":"Step 1: Transfers liquids\nStep 2: Needs exact measurement","steps":["Step 1: Transfers liquids","Step 2: Needs exact measurement"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q5","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 4),
  (685, 114, 'What is the use of a desiccator?', 'text', 1, 'Focus on the core principle of Laboratory Safety and Apparatus.', '{"why":"Preservation","sol":"Step 1: Remove moisture\nStep 2: Keep substances dry","steps":["Step 1: Remove moisture","Step 2: Keep substances dry"],"options":[],"conceptId":"chemistry_introduction_laboratory_safety_and_apparatus","skillId":"chemistry_introduction","subskillId":"chemistry_introduction_q6","subject":"chemistry","chapter":"introduction","topic":"Laboratory Safety and Apparatus"}', 5),
  (686, 115, 'What is a solid?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Definition based on particle arrangement","sol":"Step 1: Particles tightly packed\nStep 2: Cannot move freely\nStep 3: Fixed shape and volume","steps":["Step 1: Particles tightly packed","Step 2: Cannot move freely","Step 3: Fixed shape and volume"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 0),
  (687, 115, 'What is a gas?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Particle spacing and movement","sol":"Step 1: Particles far apart\nStep 2: Move freely\nStep 3: No fixed shape or volume","steps":["Step 1: Particles far apart","Step 2: Move freely","Step 3: No fixed shape or volume"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 1),
  (688, 115, 'Why do liquids flow?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Structure determines behavior","sol":"Step 1: Particles are loosely packed\nStep 2: Particles can move past each other","steps":["Step 1: Particles are loosely packed","Step 2: Particles can move past each other"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 2),
  (689, 115, 'Why are gases compressible?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Particle spacing","sol":"Step 1: Large spaces between particles\nStep 2: Particles can be pushed closer","steps":["Step 1: Large spaces between particles","Step 2: Particles can be pushed closer"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 3),
  (690, 115, 'Explain melting using particle theory', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Energy and motion","sol":"Step 1: Heat is added\nStep 2: Particles gain energy\nStep 3: Particles move more freely","steps":["Step 1: Heat is added","Step 2: Particles gain energy","Step 3: Particles move more freely"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 4),
  (691, 115, 'What is sublimation?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Direct state change","sol":"Step 1: Solid gains energy\nStep 2: Changes directly to gas","steps":["Step 1: Solid gains energy","Step 2: Changes directly to gas"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q6","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 5),
  (692, 115, 'What is deposition?', 'text', 1, 'Focus on the core principle of States of Matter.', '{"why":"Reverse of sublimation","sol":"Step 1: Gas loses energy\nStep 2: Changes directly to solid","steps":["Step 1: Gas loses energy","Step 2: Changes directly to solid"],"options":[],"conceptId":"chemistry_matter_states_of_matter","skillId":"chemistry_matter","subskillId":"chemistry_matter_q7","subject":"chemistry","chapter":"matter","topic":"States of Matter"}', 6),
  (693, 116, 'Calculate heat required to raise temperature of 2kg water from 20°C to 50°C (c = 4200 J/kg°C)', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Heat calculation","sol":"Step 1: Use Q = mcΔT\nStep 2: m = 2kg, c = 4200, ΔT = (50-20)=30\nStep 3: Q = 2 × 4200 × 30\nStep 4: Q = 252000 J","steps":["Step 1: Use Q = mcΔT","Step 2: m = 2kg, c = 4200, ΔT = (50-20)=30","Step 3: Q = 2 × 4200 × 30","Step 4: Q = 252000 J"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 0),
  (694, 116, 'Calculate heat needed to melt 1kg of ice (L = 334000 J/kg)', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Latent heat of fusion","sol":"Step 1: Use Q = mL\nStep 2: Q = 1 × 334000\nStep 3: Q = 334000 J","steps":["Step 1: Use Q = mL","Step 2: Q = 1 × 334000","Step 3: Q = 334000 J"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 1),
  (695, 116, 'Explain what happens during melting on a graph', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Latent heat","sol":"Step 1: Temperature stays constant\nStep 2: Energy breaks bonds\nStep 3: Solid becomes liquid","steps":["Step 1: Temperature stays constant","Step 2: Energy breaks bonds","Step 3: Solid becomes liquid"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 2),
  (696, 116, 'Warm water at 25°C is placed in a room at 10°C. After time, what happens?', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Heat transfer","sol":"Step 1: Heat flows from water to room\nStep 2: Water loses energy\nStep 3: Temperature decreases gradually\nStep 4: Final temperature = 10°C (thermal equilibrium)","steps":["Step 1: Heat flows from water to room","Step 2: Water loses energy","Step 3: Temperature decreases gradually","Step 4: Final temperature = 10°C (thermal equilibrium)"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 3),
  (697, 116, 'If water cools from 25°C to 15°C, calculate heat lost (m=1kg, c=4200)', 'text', 1, 'Focus on the core principle of Phase Changes (Advanced).', '{"why":"Cooling calculation","sol":"Step 1: Q = mcΔT\nStep 2: ΔT = 25 - 15 = 10\nStep 3: Q = 1 × 4200 × 10\nStep 4: Q = 42000 J","steps":["Step 1: Q = mcΔT","Step 2: ΔT = 25 - 15 = 10","Step 3: Q = 1 × 4200 × 10","Step 4: Q = 42000 J"],"options":[],"conceptId":"chemistry_matter_phase_changes_advanced","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"Phase Changes (Advanced)"}', 4),
  (698, 117, 'What is a mixture?', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Definition","sol":"Step 1: Substances are combined\nStep 2: Not chemically bonded\nStep 3: Can be separated physically","steps":["Step 1: Substances are combined","Step 2: Not chemically bonded","Step 3: Can be separated physically"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 0),
  (699, 117, 'Differentiate between homogeneous and heterogeneous mixtures', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Concept comparison","sol":"Step 1: Homogeneous is uniform\nStep 2: Heterogeneous is not uniform","steps":["Step 1: Homogeneous is uniform","Step 2: Heterogeneous is not uniform"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 1),
  (700, 117, 'A student accidentally mixes iron filings, sand, salt, and sulphur. Describe how to separate the mixture.', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Uses different physical properties","sol":"Step 1: Use a magnet to remove iron filings (magnetic)\nStep 2: Add water to dissolve salt (salt is soluble)\nStep 3: Filter the mixture to separate sand and sulphur from salt solution\nStep 4: Evaporate the filtrate to obtain salt\nStep 5: Separate sand and sulphur manually or using a suitable solvent (if needed)","steps":["Step 1: Use a magnet to remove iron filings (magnetic)","Step 2: Add water to dissolve salt (salt is soluble)","Step 3: Filter the mixture to separate sand and sulphur from salt solution","Step 4: Evaporate the filtrate to obtain salt","Step 5: Separate sand and sulphur manually or using a suitable solvent (if needed)"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 2),
  (701, 117, 'Why is filtration used to separate sand and water?', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Property-based separation","sol":"Step 1: Sand is insoluble\nStep 2: Water passes through filter","steps":["Step 1: Sand is insoluble","Step 2: Water passes through filter"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 3),
  (702, 117, 'Why is evaporation used to obtain salt from salt solution?', 'text', 1, 'Focus on the core principle of Elements compounds mixtures.', '{"why":"Difference in volatility","sol":"Step 1: Heat solution\nStep 2: Water evaporates\nStep 3: Salt remains","steps":["Step 1: Heat solution","Step 2: Water evaporates","Step 3: Salt remains"],"options":[],"conceptId":"chemistry_matter_elements_compounds_mixtures","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"Elements compounds mixtures"}', 4),
  (703, 118, 'Give 5 examples of physical changes.', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"All involve change in form only","sol":"Step 1: Identify state or shape changes\nStep 2: Ensure no new substance forms\nStep 3: List common examples","steps":["Step 1: Identify state or shape changes","Step 2: Ensure no new substance forms","Step 3: List common examples"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q1","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 0),
  (704, 118, 'Give 5 examples of chemical changes.', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"All produce new substances","sol":"Step 1: Identify reactions forming new substances\nStep 2: Look for irreversible processes\nStep 3: List examples","steps":["Step 1: Identify reactions forming new substances","Step 2: Look for irreversible processes","Step 3: List examples"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q2","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 1),
  (705, 118, 'Why is cooking food a chemical change?', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"Chemical composition changes permanently","sol":"Step 1: Identify heat application\nStep 2: Check for new substances\nStep 3: Confirm irreversibility","steps":["Step 1: Identify heat application","Step 2: Check for new substances","Step 3: Confirm irreversibility"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q3","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 2),
  (706, 118, 'Why is crushing a can a physical change?', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"Only physical structure is affected","sol":"Step 1: Observe shape change\nStep 2: Check if new substance forms\nStep 3: Confirm reversibility","steps":["Step 1: Observe shape change","Step 2: Check if new substance forms","Step 3: Confirm reversibility"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q4","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 3),
  (707, 118, 'State one similarity between physical and chemical changes.', 'text', 1, 'Focus on the core principle of Physical and chemical changes.', '{"why":"Energy is involved in both processes","sol":"Step 1: Compare both processes\nStep 2: Identify energy involvement\nStep 3: Give common feature","steps":["Step 1: Compare both processes","Step 2: Identify energy involvement","Step 3: Give common feature"],"options":[],"conceptId":"chemistry_matter_physical_and_chemical_changes","skillId":"chemistry_matter","subskillId":"chemistry_matter_q5","subject":"chemistry","chapter":"matter","topic":"Physical and chemical changes"}', 4),
  (708, 119, 'What is electron arrangement?', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Structure of atom","sol":"Step 1: Electrons are arranged in shells\nStep 2: Each shell has a fixed capacity\nStep 3: Electrons fill from inner to outer shells","steps":["Step 1: Electrons are arranged in shells","Step 2: Each shell has a fixed capacity","Step 3: Electrons fill from inner to outer shells"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 0),
  (709, 119, 'What is the maximum number of electrons in the first shell?', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Shell rule","sol":"Step 1: Identify K shell\nStep 2: Apply rule","steps":["Step 1: Identify K shell","Step 2: Apply rule"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 1),
  (710, 119, 'Why are electrons arranged in shells?', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Energy stability","sol":"Step 1: Electrons have energy levels\nStep 2: They occupy fixed regions\nStep 3: Lower energy shells fill first","steps":["Step 1: Electrons have energy levels","Step 2: They occupy fixed regions","Step 3: Lower energy shells fill first"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 2),
  (711, 119, 'Write electron arrangement for oxygen', 'text', 1, 'Focus on the core principle of Atomic Structure and Electron Arrangement.', '{"why":"Shell filling rule","sol":"Step 1: Oxygen has 8 electrons\nStep 2: Fill K shell = 2\nStep 3: Remaining = 6 in L shell","steps":["Step 1: Oxygen has 8 electrons","Step 2: Fill K shell = 2","Step 3: Remaining = 6 in L shell"],"options":[],"conceptId":"chemistry_atoms_atomic_structure_and_electron_arrangement","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Atomic Structure and Electron Arrangement"}', 3),
  (712, 120, 'What is an atomic orbital?', 'text', 1, 'Think about probability regions rather than fixed tracks', '{"why":"Definition of an atomic orbital based on quantum mechanics.","sol":"Step 1: Identify that electrons do not move in fixed orbits.\nStep 2: Define orbital as a 3D region of space.\nStep 3: State that it represents high probability (90%+) of finding an electron.","steps":["Step 1: Identify that electrons do not move in fixed orbits.","Step 2: Define orbital as a 3D region of space.","Step 3: State that it represents high probability (90%+) of finding an electron."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 0),
  (713, 120, 'What are the shapes of s and p orbitals?', 'text', 1, 's is symmetrical in all directions, p extends along axes', '{"why":"s orbitals are spherically symmetrical; p orbitals have two lobes creating a dumbbell shape along spatial axes.","sol":"Step 1: Recall the shape of the s energy level orbitals.\nStep 2: Recall the shape of the p energy level orbitals.","steps":["Step 1: Recall the shape of the s energy level orbitals.","Step 2: Recall the shape of the p energy level orbitals."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 1),
  (714, 120, 'What is the maximum number of electrons that can occupy the p energy level?', 'text', 1, 'The p energy level contains 3 orbitals, and each orbital holds up to 2 electrons.', '{"why":"The p energy level has 3 orbitals (px, py, pz). Each orbital holds 2 electrons, giving 3 x 2 = 6 electrons total.","sol":"Step 1: Determine number of orbitals in the p energy level = 3.\nStep 2: Multiply by maximum capacity per orbital (2 electrons).\nStep 3: 3 x 2 = 6 electrons.","steps":["Step 1: Determine number of orbitals in the p energy level = 3.","Step 2: Multiply by maximum capacity per orbital (2 electrons).","Step 3: 3 x 2 = 6 electrons."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 2),
  (715, 120, 'State the Aufbau principle.', 'text', 1, 'Focus on the energy order in which orbitals are filled.', '{"why":"The Aufbau principle dictates that electron configurations build up from the lowest energy level outward.","sol":"Step 1: Consider how electrons build up in an atom.\nStep 2: State that lower energy levels fill before higher energy levels.","steps":["Step 1: Consider how electrons build up in an atom.","Step 2: State that lower energy levels fill before higher energy levels."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 3),
  (716, 120, 'Write the full electron configuration for a neutral sodium atom (atomic number 11).', 'text', 1, 'Fill energy levels in order: 1s, 2s, 2p, 3s until you reach 11 electrons.', '{"why":"1s holds 2, 2s holds 2, 2p holds 6, and 3s holds the 11th electron, totaling 1s² 2s² 2p⁶ 3s¹.","sol":"Step 1: Total electrons for Na = 11.\nStep 2: Fill 1s with 2 electrons -> 1s² (9 remaining).\nStep 3: Fill 2s with 2 electrons -> 2s² (7 remaining).\nStep 4: Fill 2p with 6 electrons -> 2p⁶ (1 remaining).\nStep 5: Place final electron in 3s -> 3s¹.","steps":["Step 1: Total electrons for Na = 11.","Step 2: Fill 1s with 2 electrons -> 1s² (9 remaining).","Step 3: Fill 2s with 2 electrons -> 2s² (7 remaining).","Step 4: Fill 2p with 6 electrons -> 2p⁶ (1 remaining).","Step 5: Place final electron in 3s -> 3s¹."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q5","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 4),
  (717, 120, 'Why does the 4s energy level fill before the 3d energy level?', 'text', 1, 'Compare the relative energies of the 4s and 3d energy levels.', '{"why":"According to the Aufbau principle, orbitals fill in order of increasing energy. 4s is slightly lower in energy than 3d, so it fills first.","sol":"Step 1: Compare energy of 4s and 3d energy levels.\nStep 2: Apply the Aufbau principle.\nStep 3: 4s has lower energy than 3d in uncharged atoms.","steps":["Step 1: Compare energy of 4s and 3d energy levels.","Step 2: Apply the Aufbau principle.","Step 3: 4s has lower energy than 3d in uncharged atoms."],"options":[],"conceptId":"chemistry_atoms_atomic_orbitals_and_electron_configurations","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q6","subject":"chemistry","chapter":"atoms","topic":"Atomic Orbitals and Electron Configurations"}', 5),
  (718, 121, 'What is atomic number?', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Element identity","sol":"Step 1: Count protons in nucleus\nStep 2: That number defines element\nStep 3: It is called atomic number","steps":["Step 1: Count protons in nucleus","Step 2: That number defines element","Step 3: It is called atomic number"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 0),
  (719, 121, 'What is mass number?', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Nuclear structure","sol":"Step 1: Add protons and neutrons\nStep 2: This gives total nuclear particles","steps":["Step 1: Add protons and neutrons","Step 2: This gives total nuclear particles"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 1),
  (720, 121, 'An atom has 8 protons and 10 neutrons. Find atomic and mass number.', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Calculation using formulas","sol":"Step 1: Atomic number = protons = 8\nStep 2: Mass number = 8 + 10 = 18","steps":["Step 1: Atomic number = protons = 8","Step 2: Mass number = 8 + 10 = 18"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 2),
  (721, 121, 'How do you find neutrons in an atom?', 'text', 1, 'Focus on the core principle of Mass Number and Atomic Number.', '{"why":"Formula derivation","sol":"Step 1: Identify mass number\nStep 2: Subtract atomic number","steps":["Step 1: Identify mass number","Step 2: Subtract atomic number"],"options":[],"conceptId":"chemistry_atoms_mass_number_and_atomic_number","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Mass Number and Atomic Number"}', 3),
  (722, 122, 'What are isotopes?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Definition","sol":"Step 1: Same element\nStep 2: Same protons\nStep 3: Different neutrons","steps":["Step 1: Same element","Step 2: Same protons","Step 3: Different neutrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 0),
  (723, 122, 'Why do isotopes have the same chemical properties?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Electron structure","sol":"Step 1: Chemical behavior depends on electrons\nStep 2: Isotopes have same electrons\nStep 3: Therefore same reactions","steps":["Step 1: Chemical behavior depends on electrons","Step 2: Isotopes have same electrons","Step 3: Therefore same reactions"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 1),
  (724, 122, 'What is the difference between Carbon-12 and Carbon-14?', 'text', 1, 'Focus on the core principle of Isotopes.', '{"why":"Mass difference","sol":"Step 1: Both have 6 protons\nStep 2: C-12 has 6 neutrons\nStep 3: C-14 has 8 neutrons","steps":["Step 1: Both have 6 protons","Step 2: C-12 has 6 neutrons","Step 3: C-14 has 8 neutrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 2),
  (725, 122, 'State two properties of isotopes', 'text', 1, 'think protons and neutrons', '{"why":"Definition","sol":"Step 1: Same element\nStep 2: Different neutrons","steps":["Step 1: Same element","Step 2: Different neutrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 3),
  (726, 122, 'Why are isotopes of chlorine chemically similar?', 'text', 1, 'electrons', '{"why":"Chemical behavior","sol":"Step 1: Same atomic number\nStep 2: Same electrons","steps":["Step 1: Same atomic number","Step 2: Same electrons"],"options":[],"conceptId":"chemistry_atoms_isotopes","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q5","subject":"chemistry","chapter":"atoms","topic":"Isotopes"}', 4),
  (727, 123, 'What is an ion?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Definition","sol":"Step 1: Start with atom\nStep 2: Gain or lose electrons\nStep 3: Become charged","steps":["Step 1: Start with atom","Step 2: Gain or lose electrons","Step 3: Become charged"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q1","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 0),
  (728, 123, 'What is a cation?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Electron loss","sol":"Step 1: Atom loses electrons\nStep 2: More protons than electrons\nStep 3: Positive charge formed","steps":["Step 1: Atom loses electrons","Step 2: More protons than electrons","Step 3: Positive charge formed"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q2","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 1),
  (729, 123, 'What is an anion?', 'text', 1, 'Focus on the core principle of Ion Formation.', '{"why":"Electron gain","sol":"Step 1: Atom gains electrons\nStep 2: More electrons than protons\nStep 3: Negative charge formed","steps":["Step 1: Atom gains electrons","Step 2: More electrons than protons","Step 3: Negative charge formed"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q3","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 2),
  (730, 123, 'How is Na⁺ formed?', 'text', 1, 'electron loss', '{"why":"Cation formation","sol":"Step 1: Sodium has 11 electrons\nStep 2: Loses 1 electron\nStep 3: Becomes Na⁺","steps":["Step 1: Sodium has 11 electrons","Step 2: Loses 1 electron","Step 3: Becomes Na⁺"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q4","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 3),
  (731, 123, 'How is Cl⁻ formed?', 'text', 1, 'electron gain', '{"why":"Anion formation","sol":"Step 1: Chlorine has 17 electrons\nStep 2: Gains 1 electron\nStep 3: Becomes Cl⁻","steps":["Step 1: Chlorine has 17 electrons","Step 2: Gains 1 electron","Step 3: Becomes Cl⁻"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q5","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 4),
  (732, 123, 'Why is Mg²⁺ formed?', 'text', 1, 'loses two electrons', '{"why":"Charge increase","sol":"Step 1: Magnesium has 12 electrons\nStep 2: Loses 2 electrons\nStep 3: Becomes Mg²⁺","steps":["Step 1: Magnesium has 12 electrons","Step 2: Loses 2 electrons","Step 3: Becomes Mg²⁺"],"options":[],"conceptId":"chemistry_atoms_ion_formation","skillId":"chemistry_atoms","subskillId":"chemistry_atoms_q6","subject":"chemistry","chapter":"atoms","topic":"Ion Formation"}', 5),
  (733, 124, 'What is the periodic table?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Definition","sol":"Step 1: Arrangement of elements\nStep 2: Based on atomic number\nStep 3: Similar properties grouped","steps":["Step 1: Arrangement of elements","Step 2: Based on atomic number","Step 3: Similar properties grouped"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q1","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 0),
  (734, 124, 'Why are elements in the same group similar?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Electron structure","sol":"Step 1: Same number of valence electrons\nStep 2: Similar chemical behavior","steps":["Step 1: Same number of valence electrons","Step 2: Similar chemical behavior"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q2","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 1),
  (735, 124, 'Which element has the largest atomic radius: Na, Mg, Al, Cl?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Trend across period","sol":"Step 1: All are in same period\nStep 2: Atomic radius decreases across period\nStep 3: Na is farthest left","steps":["Step 1: All are in same period","Step 2: Atomic radius decreases across period","Step 3: Na is farthest left"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q3","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 2),
  (736, 124, 'Which element is most likely to form a chloride ion?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Halogen behavior","sol":"Step 1: Look for non-metal in Group 17\nStep 2: Chlorine gains electron easily","steps":["Step 1: Look for non-metal in Group 17","Step 2: Chlorine gains electron easily"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q4","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 3),
  (737, 124, 'Which two elements react to form a salt?', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Ionic compound formation","sol":"Step 1: Metal + Non-metal\nStep 2: Example sodium + chlorine\nStep 3: Forms NaCl","steps":["Step 1: Metal + Non-metal","Step 2: Example sodium + chlorine","Step 3: Forms NaCl"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q5","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 4),
  (738, 124, 'Compare reactivity of Group 1 elements down the group', 'text', 1, 'Focus on the core principle of Periodic Table and Periodicity.', '{"why":"Electron distance effect","sol":"Step 1: Atoms get larger\nStep 2: Outer electron is easier to lose\nStep 3: Reactivity increases","steps":["Step 1: Atoms get larger","Step 2: Outer electron is easier to lose","Step 3: Reactivity increases"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q6","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 5),
  (739, 124, 'Why are noble gases unreactive?', 'text', 1, 'outer shell', '{"why":"Stability","sol":"Step 1: Full outer shell\nStep 2: No need to gain or lose electrons","steps":["Step 1: Full outer shell","Step 2: No need to gain or lose electrons"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q7","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 6),
  (740, 124, 'Which element forms a -1 ion easily?', 'text', 1, 'halogen', '{"why":"Electron gain","sol":"Step 1: Group 17 elements\nStep 2: Gain 1 electron","steps":["Step 1: Group 17 elements","Step 2: Gain 1 electron"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q8","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 7),
  (741, 124, 'Arrange Na, Mg, Al in order of increasing atomic radius', 'text', 1, 'across period', '{"why":"Periodic trend","sol":"Step 1: radius decreases across period\nStep 2: Al < Mg < Na","steps":["Step 1: radius decreases across period","Step 2: Al < Mg < Na"],"options":[],"conceptId":"chemistry_elements_periodic_table_and_periodicity","skillId":"chemistry_elements","subskillId":"chemistry_elements_q9","subject":"chemistry","chapter":"elements","topic":"Periodic Table and Periodicity"}', 8),
  (742, 125, 'What is chemical bonding?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Atoms bond to become stable","sol":"Step 1: Atoms come close together\nStep 2: They interact through electrons\nStep 3: A force holds them together","steps":["Step 1: Atoms come close together","Step 2: They interact through electrons","Step 3: A force holds them together"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 0),
  (743, 125, 'What happens during ionic bonding?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Electrostatic attraction forms the bond","sol":"Step 1: Metal loses electrons\nStep 2: Non-metal gains electrons\nStep 3: Opposite charges attract","steps":["Step 1: Metal loses electrons","Step 2: Non-metal gains electrons","Step 3: Opposite charges attract"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 1),
  (744, 125, 'What happens during covalent bonding?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Sharing leads to stability","sol":"Step 1: Two non-metals approach\nStep 2: They share electrons\nStep 3: Shared electrons complete outer shells","steps":["Step 1: Two non-metals approach","Step 2: They share electrons","Step 3: Shared electrons complete outer shells"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 2),
  (745, 125, 'Which type of bonding involves transfer of electrons?', 'text', 1, 'metal + non-metal', '{"why":"Electron transfer creates charged ions","sol":"Step 1: One atom loses electrons\nStep 2: Another gains electrons\nStep 3: Ions form","steps":["Step 1: One atom loses electrons","Step 2: Another gains electrons","Step 3: Ions form"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 3),
  (746, 125, 'Which type of bonding involves sharing electrons?', 'text', 1, 'non-metal + non-metal', '{"why":"Sharing fills outer shells","sol":"Step 1: Atoms approach\nStep 2: Share electrons\nStep 3: Form molecule","steps":["Step 1: Atoms approach","Step 2: Share electrons","Step 3: Form molecule"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 4),
  (747, 125, 'Why are noble gases unreactive?', 'text', 1, 'Focus on the core principle of Chemical bonding.', '{"why":"Stable electronic configuration","sol":"Step 1: Outer shell is full\nStep 2: No need to gain or lose electrons\nStep 3: No bonding required","steps":["Step 1: Outer shell is full","Step 2: No need to gain or lose electrons","Step 3: No bonding required"],"options":[],"conceptId":"chemistry_bonding_chemical_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q6","subject":"chemistry","chapter":"bonding","topic":"Chemical bonding"}', 5),
  (748, 126, 'What is ionic bonding?', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Opposite charges create strong attraction","sol":"Step 1: Identify two atoms (metal and non-metal)\nStep 2: Electron is transferred from metal to non-metal\nStep 3: Oppositely charged ions form\nStep 4: Ions attract each other","steps":["Step 1: Identify two atoms (metal and non-metal)","Step 2: Electron is transferred from metal to non-metal","Step 3: Oppositely charged ions form","Step 4: Ions attract each other"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 0),
  (749, 126, 'Why does ionic bonding occur between metals and non-metals?', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Both achieve stable electron configuration","sol":"Step 1: Metals have few outer electrons\nStep 2: They lose electrons easily\nStep 3: Non-metals need electrons to complete outer shell\nStep 4: Electron transfer happens","steps":["Step 1: Metals have few outer electrons","Step 2: They lose electrons easily","Step 3: Non-metals need electrons to complete outer shell","Step 4: Electron transfer happens"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 1),
  (750, 126, 'Explain step-by-step formation of NaCl', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Opposite ions attract strongly","sol":"Step 1: Sodium has 1 valence electron\nStep 2: Sodium loses 1 electron → Na⁺\nStep 3: Chlorine has 7 valence electrons\nStep 4: Chlorine gains 1 electron → Cl⁻\nStep 5: Na⁺ and Cl⁻ attract each other\nStep 6: Ionic bond forms NaCl crystal","steps":["Step 1: Sodium has 1 valence electron","Step 2: Sodium loses 1 electron → Na⁺","Step 3: Chlorine has 7 valence electrons","Step 4: Chlorine gains 1 electron → Cl⁻","Step 5: Na⁺ and Cl⁻ attract each other","Step 6: Ionic bond forms NaCl crystal"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 2);
INSERT INTO public.questions (id, quiz_id, question, type, points, hint, explain, position) VALUES
  (751, 126, 'Why is NaCl electrically neutral overall?', 'text', 1, 'charges cancel', '{"why":"Total charge becomes zero","sol":"Step 1: Na becomes +1\nStep 2: Cl becomes -1\nStep 3: Charges balance out","steps":["Step 1: Na becomes +1","Step 2: Cl becomes -1","Step 3: Charges balance out"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 3),
  (752, 126, 'Explain why ionic compounds form crystal structures', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Ions arrange in a stable repeating structure","sol":"Step 1: Ions attract in all directions\nStep 2: Repeating pattern forms\nStep 3: Strong lattice structure develops","steps":["Step 1: Ions attract in all directions","Step 2: Repeating pattern forms","Step 3: Strong lattice structure develops"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 4),
  (753, 126, 'Predict what happens when magnesium reacts with chlorine', 'text', 1, 'Focus on the core principle of Ionic bonding.', '{"why":"Charge balance determines formula","sol":"Step 1: Magnesium loses 2 electrons → Mg²⁺\nStep 2: Chlorine gains 1 electron → Cl⁻\nStep 3: Two Cl atoms needed for balance\nStep 4: Mg²⁺ + 2Cl⁻ → MgCl₂","steps":["Step 1: Magnesium loses 2 electrons → Mg²⁺","Step 2: Chlorine gains 1 electron → Cl⁻","Step 3: Two Cl atoms needed for balance","Step 4: Mg²⁺ + 2Cl⁻ → MgCl₂"],"options":[],"conceptId":"chemistry_bonding_ionic_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q6","subject":"chemistry","chapter":"bonding","topic":"Ionic bonding"}', 5),
  (754, 127, 'What is covalent bonding?', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Sharing allows atoms to complete outer shells","sol":"Step 1: Identify two non-metal atoms\nStep 2: Each atom needs electrons\nStep 3: They share electrons instead of transferring\nStep 4: Shared electrons form a bond","steps":["Step 1: Identify two non-metal atoms","Step 2: Each atom needs electrons","Step 3: They share electrons instead of transferring","Step 4: Shared electrons form a bond"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 0),
  (755, 127, 'Why does covalent bonding occur between non-metals?', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Electron sharing is energetically favorable","sol":"Step 1: Non-metals have nearly full outer shells\nStep 2: They need a few electrons\nStep 3: Losing electrons is difficult\nStep 4: Sharing is easier than transfer","steps":["Step 1: Non-metals have nearly full outer shells","Step 2: They need a few electrons","Step 3: Losing electrons is difficult","Step 4: Sharing is easier than transfer"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 1),
  (756, 127, 'What is a single covalent bond?', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"One shared pair creates a single bond","sol":"Step 1: Two atoms approach\nStep 2: They share one pair of electrons\nStep 3: Bond holds atoms together","steps":["Step 1: Two atoms approach","Step 2: They share one pair of electrons","Step 3: Bond holds atoms together"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 2),
  (757, 127, 'Which is stronger: single, double, or triple bond?', 'text', 1, 'more sharing = stronger', '{"why":"More shared electrons increase bond strength","sol":"Step 1: compare electron pairs\nStep 2: single = 1 pair\nStep 3: double = 2 pairs\nStep 4: triple = 3 pairs","steps":["Step 1: compare electron pairs","Step 2: single = 1 pair","Step 3: double = 2 pairs","Step 4: triple = 3 pairs"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 3),
  (758, 127, 'Explain why O₂ has a double bond', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Each oxygen needs 2 electrons for stability","sol":"Step 1: Oxygen has 6 outer electrons\nStep 2: Needs 2 more to complete octet\nStep 3: Two oxygen atoms share 2 pairs\nStep 4: Double bond forms O₂","steps":["Step 1: Oxygen has 6 outer electrons","Step 2: Needs 2 more to complete octet","Step 3: Two oxygen atoms share 2 pairs","Step 4: Double bond forms O₂"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 4),
  (759, 127, 'Explain why N₂ has a triple bond', 'text', 1, 'Focus on the core principle of Covalent bonding.', '{"why":"Each nitrogen needs 3 electrons for stability","sol":"Step 1: Nitrogen has 5 outer electrons\nStep 2: Needs 3 more to complete octet\nStep 3: Two nitrogen atoms share 3 pairs\nStep 4: Strong triple bond forms","steps":["Step 1: Nitrogen has 5 outer electrons","Step 2: Needs 3 more to complete octet","Step 3: Two nitrogen atoms share 3 pairs","Step 4: Strong triple bond forms"],"options":[],"conceptId":"chemistry_bonding_covalent_bonding","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q6","subject":"chemistry","chapter":"bonding","topic":"Covalent bonding"}', 5),
  (760, 128, 'What is the main difference between ionic and covalent bonding?', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Electron movement defines bonding type","sol":"Step 1: Identify electron behavior\nStep 2: Ionic involves transfer\nStep 3: Covalent involves sharing\nStep 4: Compare outcomes (ions vs molecules)","steps":["Step 1: Identify electron behavior","Step 2: Ionic involves transfer","Step 3: Covalent involves sharing","Step 4: Compare outcomes (ions vs molecules)"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q1","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 0),
  (761, 128, 'Which elements form covalent bonds?', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Similar electronegativity leads to sharing","sol":"Step 1: Identify non-metals\nStep 2: Both need electrons\nStep 3: Neither wants to lose electrons\nStep 4: They share electrons","steps":["Step 1: Identify non-metals","Step 2: Both need electrons","Step 3: Neither wants to lose electrons","Step 4: They share electrons"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q2","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 1),
  (762, 128, 'Why do ionic compounds have high melting points?', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Strong bonds require high energy to break","sol":"Step 1: Identify ionic lattice\nStep 2: Strong electrostatic forces\nStep 3: Requires large energy to break bonds","steps":["Step 1: Identify ionic lattice","Step 2: Strong electrostatic forces","Step 3: Requires large energy to break bonds"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q3","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 2),
  (763, 128, 'Explain why NaCl is ionic but H₂ is covalent', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Type of elements determines bonding type","sol":"Step 1: Na is a metal, Cl is non-metal\nStep 2: electron transfer occurs → ionic bond\nStep 3: H and H are both non-metals\nStep 4: electrons are shared → covalent bond","steps":["Step 1: Na is a metal, Cl is non-metal","Step 2: electron transfer occurs → ionic bond","Step 3: H and H are both non-metals","Step 4: electrons are shared → covalent bond"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q4","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 3),
  (764, 128, 'Predict bonding type in MgO and CO₂', 'text', 1, 'Focus on the core principle of Ionic vs covalent.', '{"why":"Element types determine bonding","sol":"Step 1: MgO has metal + non-metal → ionic\nStep 2: CO₂ has non-metal + non-metal → covalent","steps":["Step 1: MgO has metal + non-metal → ionic","Step 2: CO₂ has non-metal + non-metal → covalent"],"options":[],"conceptId":"chemistry_bonding_ionic_vs_covalent","skillId":"chemistry_bonding","subskillId":"chemistry_bonding_q5","subject":"chemistry","chapter":"bonding","topic":"Ionic vs covalent"}', 4),
  (765, 129, 'A chemistry student is told that 1 mole of any substance always contains the same fixed number of particles. What is this number, and what is it called?', 'text', 1, 'Focus on the core principle of Meaning of mole.', '{"why":"The mole is defined as the amount of substance containing exactly 6.02 × 10²³ particles. This number is always the same regardless of what substance you are measuring.","sol":"Step 1: Recall that the mole is a counting unit, like ''dozen'' means 12\nStep 2: Remember the fixed number linked to 1 mole is Avogadro''s constant\nStep 3: State the value: 6.02 × 10²³ particles per mole","steps":["Step 1: Recall that the mole is a counting unit, like ''dozen'' means 12","Step 2: Remember the fixed number linked to 1 mole is Avogadro''s constant","Step 3: State the value: 6.02 × 10²³ particles per mole"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 0),
  (766, 129, 'A sample contains 1.204 × 10²⁴ atoms of sodium. How many moles of sodium is this?', 'text', 1, 'Divide the number of particles by Avogadro''s number (6.02 × 10²³)', '{"why":"You divide by Avogadro''s constant to convert from number of particles to moles. 1.204 × 10²⁴ is exactly twice Avogadro''s number, so it equals 2 moles.","sol":"Step 1: Write the formula: n = number of particles ÷ 6.02 × 10²³\nStep 2: Substitute the values: n = 1.204 × 10²⁴ ÷ 6.02 × 10²³\nStep 3: Divide: 1.204 ÷ 6.02 = 0.2, and 10²⁴ ÷ 10²³ = 10¹ = 10\nStep 4: So n = 0.2 × 10 = 2","steps":["Step 1: Write the formula: n = number of particles ÷ 6.02 × 10²³","Step 2: Substitute the values: n = 1.204 × 10²⁴ ÷ 6.02 × 10²³","Step 3: Divide: 1.204 ÷ 6.02 = 0.2, and 10²⁴ ÷ 10²³ = 10¹ = 10","Step 4: So n = 0.2 × 10 = 2"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 1),
  (767, 129, 'A teacher asks: ''How many individual molecules are contained in 2 moles of water (H₂O)?'' Show your working.', 'text', 1, 'Multiply the number of moles by Avogadro''s number', '{"why":"Each mole contains 6.02 × 10²³ molecules, so 2 moles contains twice that amount. Scientific notation is used because the number is extremely large.","sol":"Step 1: Write the formula: Number of particles = n × 6.02 × 10²³\nStep 2: Substitute: Number of particles = 2 × 6.02 × 10²³\nStep 3: Multiply the coefficient: 2 × 6.02 = 12.04\nStep 4: Express in standard scientific notation: 1.204 × 10²⁴","steps":["Step 1: Write the formula: Number of particles = n × 6.02 × 10²³","Step 2: Substitute: Number of particles = 2 × 6.02 × 10²³","Step 3: Multiply the coefficient: 2 × 6.02 = 12.04","Step 4: Express in standard scientific notation: 1.204 × 10²⁴"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 2),
  (768, 129, 'A scientist measures out 3 moles of oxygen gas (O₂). How many oxygen molecules does this sample contain?', 'text', 1, 'Focus on the core principle of Meaning of mole.', '{"why":"Multiplying moles by Avogadro''s number converts from moles to individual particles. Since each mole has 6.02 × 10²³ molecules, 3 moles has 3 times that.","sol":"Step 1: Write the formula: Number of molecules = n × 6.02 × 10²³\nStep 2: Substitute: Number of molecules = 3 × 6.02 × 10²³\nStep 3: Multiply: 3 × 6.02 = 18.06\nStep 4: Write in scientific notation: 1.806 × 10²⁴ molecules","steps":["Step 1: Write the formula: Number of molecules = n × 6.02 × 10²³","Step 2: Substitute: Number of molecules = 3 × 6.02 × 10²³","Step 3: Multiply: 3 × 6.02 = 18.06","Step 4: Write in scientific notation: 1.806 × 10²⁴ molecules"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 3),
  (769, 129, 'Why do chemists use the mole instead of counting atoms directly? Explain using the idea of microscopic vs macroscopic.', 'text', 1, 'Focus on the core principle of Meaning of mole.', '{"why":"Without the mole, it would be impossible to connect what we measure in the lab (grams, litres) to what is happening at the atomic level. The mole is the essential bridge.","sol":"Step 1: Recognise that atoms are too small to count individually — even 1 g of hydrogen contains ~6 × 10²³ atoms\nStep 2: The mole groups this enormous number into a manageable counting unit\nStep 3: It bridges the microscopic world (atoms) and the macroscopic world (grams on a balance scale)","steps":["Step 1: Recognise that atoms are too small to count individually — even 1 g of hydrogen contains ~6 × 10²³ atoms","Step 2: The mole groups this enormous number into a manageable counting unit","Step 3: It bridges the microscopic world (atoms) and the macroscopic world (grams on a balance scale)"],"options":[],"conceptId":"chemistry_mole_meaning_of_mole","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Meaning of mole"}', 4),
  (770, 130, 'A chemist has 36 g of water (H₂O). The molar mass of water is 18 g/mol. Calculate how many moles of water are present.', 'text', 1, 'Use the formula: n = mass ÷ molar mass', '{"why":"Dividing mass by molar mass converts grams into moles. Since 36 g is exactly twice the molar mass (18 g/mol), the sample contains 2 moles.","sol":"Step 1: Write the formula: n = m ÷ M\nStep 2: Identify values: m = 36 g, M = 18 g/mol\nStep 3: Substitute: n = 36 ÷ 18\nStep 4: Calculate: n = 2 mol","steps":["Step 1: Write the formula: n = m ÷ M","Step 2: Identify values: m = 36 g, M = 18 g/mol","Step 3: Substitute: n = 36 ÷ 18","Step 4: Calculate: n = 2 mol"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 0),
  (771, 130, 'A student measures 0.5 moles of nitrogen gas (N₂). How many individual molecules does this sample contain?', 'text', 1, 'Multiply the number of moles by Avogadro''s number (6.02 × 10²³)', '{"why":"Half a mole contains exactly half of Avogadro''s number of particles. Moles and particle count are directly proportional.","sol":"Step 1: Write the formula: N = n × 6.02 × 10²³\nStep 2: Substitute: N = 0.5 × 6.02 × 10²³\nStep 3: Multiply: 0.5 × 6.02 = 3.01\nStep 4: Write the answer: N = 3.01 × 10²³ molecules","steps":["Step 1: Write the formula: N = n × 6.02 × 10²³","Step 2: Substitute: N = 0.5 × 6.02 × 10²³","Step 3: Multiply: 0.5 × 6.02 = 3.01","Step 4: Write the answer: N = 3.01 × 10²³ molecules"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 1),
  (772, 130, 'A laboratory has 2 moles of carbon dioxide (CO₂). The molar mass of CO₂ is 44 g/mol. What is the total mass of this CO₂ sample?', 'text', 1, 'Focus on the core principle of Mole relationships.', '{"why":"Multiplying moles by molar mass converts moles back into grams. Each mole of CO₂ has a mass of 44 g, so 2 moles has twice the mass.","sol":"Step 1: Write the formula: m = n × M\nStep 2: Identify values: n = 2 mol, M = 44 g/mol\nStep 3: Substitute: m = 2 × 44\nStep 4: Calculate: m = 88 g","steps":["Step 1: Write the formula: m = n × M","Step 2: Identify values: n = 2 mol, M = 44 g/mol","Step 3: Substitute: m = 2 × 44","Step 4: Calculate: m = 88 g"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 2),
  (773, 130, 'A sample contains 9.03 × 10²³ atoms of iron (Fe). How many moles of iron is this?', 'text', 1, 'Divide the particle count by Avogadro''s number', '{"why":"Dividing the number of particles by Avogadro''s constant gives moles. 9.03 × 10²³ is 1.5 times Avogadro''s number, so the answer is 1.5 moles.","sol":"Step 1: Write the formula: n = N ÷ 6.02 × 10²³\nStep 2: Substitute: n = 9.03 × 10²³ ÷ 6.02 × 10²³\nStep 3: Divide: 9.03 ÷ 6.02 ≈ 1.5\nStep 4: Answer: n = 1.5 mol","steps":["Step 1: Write the formula: n = N ÷ 6.02 × 10²³","Step 2: Substitute: n = 9.03 × 10²³ ÷ 6.02 × 10²³","Step 3: Divide: 9.03 ÷ 6.02 ≈ 1.5","Step 4: Answer: n = 1.5 mol"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 3),
  (774, 130, 'The molar mass of NaOH (sodium hydroxide) is 40 g/mol. A student uses 20 g of NaOH in an experiment. How many moles of NaOH is this?', 'text', 1, 'Use n = mass ÷ molar mass', '{"why":"20 g is exactly half the molar mass of NaOH (40 g/mol), so the sample contains 0.5 moles.","sol":"Step 1: Write the formula: n = m ÷ M\nStep 2: Identify values: m = 20 g, M = 40 g/mol\nStep 3: Substitute: n = 20 ÷ 40\nStep 4: Calculate: n = 0.5 mol","steps":["Step 1: Write the formula: n = m ÷ M","Step 2: Identify values: m = 20 g, M = 40 g/mol","Step 3: Substitute: n = 20 ÷ 40","Step 4: Calculate: n = 0.5 mol"],"options":[],"conceptId":"chemistry_mole_mole_relationships","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Mole relationships"}', 4),
  (775, 131, 'A student is asked to calculate the molar mass of carbon dioxide (CO₂). Given that the atomic mass of C = 12 and O = 16, find the molar mass of CO₂.', 'text', 1, 'Focus on the core principle of Molar mass.', '{"why":"Molar mass is found by adding the atomic masses of all atoms in the formula. CO₂ has one C (mass 12) and two O atoms (mass 16 each), giving 44 g/mol.","sol":"Step 1: Write the molecular formula: CO₂ — it contains 1 carbon atom and 2 oxygen atoms\nStep 2: Find the mass of carbon: 1 × 12 = 12\nStep 3: Find the mass of oxygen: 2 × 16 = 32\nStep 4: Add all atomic masses together: 12 + 32 = 44 g/mol","steps":["Step 1: Write the molecular formula: CO₂ — it contains 1 carbon atom and 2 oxygen atoms","Step 2: Find the mass of carbon: 1 × 12 = 12","Step 3: Find the mass of oxygen: 2 × 16 = 32","Step 4: Add all atomic masses together: 12 + 32 = 44 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 0),
  (776, 131, 'Calculate the molar mass of sodium chloride (NaCl). Use: Na = 23, Cl = 35.5.', 'text', 1, 'Add the atomic mass of each element present in one formula unit', '{"why":"NaCl is a simple ionic compound with one atom of each element. Adding their atomic masses directly gives the molar mass.","sol":"Step 1: Write the formula: NaCl — it contains 1 Na and 1 Cl atom\nStep 2: Mass of Na = 1 × 23 = 23\nStep 3: Mass of Cl = 1 × 35.5 = 35.5\nStep 4: Total molar mass = 23 + 35.5 = 58.5 g/mol","steps":["Step 1: Write the formula: NaCl — it contains 1 Na and 1 Cl atom","Step 2: Mass of Na = 1 × 23 = 23","Step 3: Mass of Cl = 1 × 35.5 = 35.5","Step 4: Total molar mass = 23 + 35.5 = 58.5 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 1),
  (777, 131, 'Find the molar mass of sodium oxide (Na₂O). Use: Na = 23, O = 16.', 'text', 1, 'Note there are 2 sodium atoms — multiply the atomic mass of Na by 2', '{"why":"The subscript 2 in Na₂O means there are 2 sodium atoms. Always multiply the atomic mass by the subscript number before adding.","sol":"Step 1: Write the formula: Na₂O — it contains 2 Na atoms and 1 O atom\nStep 2: Mass of Na: 2 × 23 = 46\nStep 3: Mass of O: 1 × 16 = 16\nStep 4: Total molar mass = 46 + 16 = 62 g/mol","steps":["Step 1: Write the formula: Na₂O — it contains 2 Na atoms and 1 O atom","Step 2: Mass of Na: 2 × 23 = 46","Step 3: Mass of O: 1 × 16 = 16","Step 4: Total molar mass = 46 + 16 = 62 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 2),
  (778, 131, 'Calculate the molar mass of calcium hydroxide, Ca(OH)₂. Use: Ca = 40, O = 16, H = 1.', 'text', 1, 'The bracket (OH)₂ means there are 2 OH groups — so 2 oxygen atoms and 2 hydrogen atoms in total', '{"why":"The bracket and subscript 2 in Ca(OH)₂ mean both O and H appear twice. Always expand brackets before calculating molar mass.","sol":"Step 1: Expand the formula: Ca(OH)₂ = Ca + 2O + 2H\nStep 2: Mass of Ca: 1 × 40 = 40\nStep 3: Mass of O: 2 × 16 = 32\nStep 4: Mass of H: 2 × 1 = 2\nStep 5: Total = 40 + 32 + 2 = 74 g/mol","steps":["Step 1: Expand the formula: Ca(OH)₂ = Ca + 2O + 2H","Step 2: Mass of Ca: 1 × 40 = 40","Step 3: Mass of O: 2 × 16 = 32","Step 4: Mass of H: 2 × 1 = 2","Step 5: Total = 40 + 32 + 2 = 74 g/mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 3),
  (779, 131, 'A chemist knows that the molar mass of H₂SO₄ (sulphuric acid) is 98 g/mol and uses 49 g in a reaction. How many moles of H₂SO₄ does the chemist use?', 'text', 1, 'Use n = mass ÷ molar mass', '{"why":"Once you know the molar mass, you can find moles by dividing the given mass by it. 49 g is half of 98 g/mol, so this is 0.5 moles.","sol":"Step 1: Write the formula: n = m ÷ M\nStep 2: Identify: m = 49 g, M = 98 g/mol\nStep 3: Substitute: n = 49 ÷ 98\nStep 4: Calculate: n = 0.5 mol","steps":["Step 1: Write the formula: n = m ÷ M","Step 2: Identify: m = 49 g, M = 98 g/mol","Step 3: Substitute: n = 49 ÷ 98","Step 4: Calculate: n = 0.5 mol"],"options":[],"conceptId":"chemistry_mole_molar_mass","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Molar mass"}', 4),
  (780, 132, 'In the reaction 2H₂ + O₂ → 2H₂O, a student burns 2 moles of hydrogen gas (H₂). Using the mole ratio from the equation, how many moles of water (H₂O) are produced?', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"The balanced equation shows H₂ and H₂O are in a 1:1 ratio. The coefficient of each is 2, so they cancel to give an equal mole relationship.","sol":"Step 1: Read the balanced equation: 2H₂ + O₂ → 2H₂O\nStep 2: Identify the mole ratio of H₂ to H₂O from the coefficients: 2 : 2, which simplifies to 1 : 1\nStep 3: Since the ratio is 1:1, every mole of H₂ produces exactly 1 mole of H₂O\nStep 4: Therefore 2 moles of H₂ → 2 moles of H₂O","steps":["Step 1: Read the balanced equation: 2H₂ + O₂ → 2H₂O","Step 2: Identify the mole ratio of H₂ to H₂O from the coefficients: 2 : 2, which simplifies to 1 : 1","Step 3: Since the ratio is 1:1, every mole of H₂ produces exactly 1 mole of H₂O","Step 4: Therefore 2 moles of H₂ → 2 moles of H₂O"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 0),
  (781, 132, 'Using the equation N₂ + 3H₂ → 2NH₃, calculate how many moles of ammonia (NH₃) are produced from 1 mole of nitrogen gas (N₂).', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"The coefficient of N₂ is 1 and NH₃ is 2 in the balanced equation. The ratio 1:2 means for every mole of N₂ used, 2 moles of NH₃ are produced.","sol":"Step 1: Write the balanced equation: N₂ + 3H₂ → 2NH₃\nStep 2: Read the mole ratio of N₂ to NH₃ from the coefficients: 1 : 2\nStep 3: Since 1 mole of N₂ produces 2 moles of NH₃, multiply: 1 × 2 = 2\nStep 4: Answer: 1 mol N₂ → 2 mol NH₃","steps":["Step 1: Write the balanced equation: N₂ + 3H₂ → 2NH₃","Step 2: Read the mole ratio of N₂ to NH₃ from the coefficients: 1 : 2","Step 3: Since 1 mole of N₂ produces 2 moles of NH₃, multiply: 1 × 2 = 2","Step 4: Answer: 1 mol N₂ → 2 mol NH₃"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 1),
  (782, 132, 'In the reaction 2H₂ + O₂ → 2H₂O, if 4 moles of H₂ are burned, how many moles of water are formed?', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"Because H₂ and H₂O have an equal (1:1) ratio in this equation, the number of moles produced always equals the number of moles of H₂ used.","sol":"Step 1: Read the equation: 2H₂ + O₂ → 2H₂O\nStep 2: Find the mole ratio H₂ : H₂O = 2 : 2 = 1 : 1\nStep 3: Apply the ratio to 4 moles of H₂: 4 × (1/1) = 4\nStep 4: 4 moles of H₂ produces 4 moles of H₂O","steps":["Step 1: Read the equation: 2H₂ + O₂ → 2H₂O","Step 2: Find the mole ratio H₂ : H₂O = 2 : 2 = 1 : 1","Step 3: Apply the ratio to 4 moles of H₂: 4 × (1/1) = 4","Step 4: 4 moles of H₂ produces 4 moles of H₂O"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 2),
  (783, 132, 'Calcium carbonate decomposes according to: CaCO₃ → CaO + CO₂. If 1 mole of CaCO₃ fully decomposes, how many moles of carbon dioxide (CO₂) are released?', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"In a 1:1 decomposition, every formula unit of CaCO₃ produces exactly one CO₂ molecule. The coefficients are all 1, making this a direct conversion.","sol":"Step 1: Write the balanced equation: CaCO₃ → CaO + CO₂\nStep 2: Read the mole ratio of CaCO₃ to CO₂ from coefficients: 1 : 1\nStep 3: Apply the ratio: 1 mole of CaCO₃ → 1 mole of CO₂\nStep 4: Answer: 1 mole of CO₂ is released","steps":["Step 1: Write the balanced equation: CaCO₃ → CaO + CO₂","Step 2: Read the mole ratio of CaCO₃ to CO₂ from coefficients: 1 : 1","Step 3: Apply the ratio: 1 mole of CaCO₃ → 1 mole of CO₂","Step 4: Answer: 1 mole of CO₂ is released"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 3),
  (784, 132, 'In the reaction 4Al + 3O₂ → 2Al₂O₃, calculate the moles of aluminium oxide (Al₂O₃) produced from 4 moles of aluminium (Al).', 'text', 1, 'Focus on the core principle of Stoichiometry.', '{"why":"The equation shows that 4 moles of Al always produce 2 moles of Al₂O₃. The ratio is 4:2 = 2:1. With exactly 4 moles of Al, the answer is directly 2 moles of product.","sol":"Step 1: Write the balanced equation: 4Al + 3O₂ → 2Al₂O₃\nStep 2: Find the mole ratio of Al to Al₂O₃: 4 : 2, which simplifies to 2 : 1\nStep 3: Set up the ratio calculation: moles of Al₂O₃ = 4 × (2/4) = 4 × 0.5 = 2\nStep 4: Wait — use ratio directly: if 4 mol Al → 2 mol Al₂O₃ (from equation)","steps":["Step 1: Write the balanced equation: 4Al + 3O₂ → 2Al₂O₃","Step 2: Find the mole ratio of Al to Al₂O₃: 4 : 2, which simplifies to 2 : 1","Step 3: Set up the ratio calculation: moles of Al₂O₃ = 4 × (2/4) = 4 × 0.5 = 2","Step 4: Wait — use ratio directly: if 4 mol Al → 2 mol Al₂O₃ (from equation)"],"options":[],"conceptId":"chemistry_mole_stoichiometry","skillId":"chemistry_mole","subskillId":"chemistry_mole_q5","subject":"chemistry","chapter":"mole","topic":"Stoichiometry"}', 4),
  (785, 133, 'A compound contains 52.2% carbon, 13% hydrogen, and 34.8% oxygen by mass. Determine its empirical formula. (C = 12, H = 1, O = 16)', 'text', 1, 'Assume 100 g of the compound, then convert each mass to moles, divide by the smallest, and write the whole-number ratio', '{"why":"After dividing all mole values by the smallest (2.18), the ratios become whole numbers: 2, 6, 1. This gives the simplest atom ratio, which is the empirical formula.","sol":"Step 1: Assume 100 g — so C = 52.2 g, H = 13 g, O = 34.8 g\nStep 2: Convert to moles: C = 52.2 ÷ 12 = 4.35, H = 13 ÷ 1 = 13, O = 34.8 ÷ 16 = 2.18\nStep 3: Divide all by the smallest value (2.18): C = 4.35/2.18 ≈ 2, H = 13/2.18 ≈ 6, O = 2.18/2.18 = 1\nStep 4: The whole-number ratio is C:H:O = 2:6:1, so the empirical formula is C₂H₆O","steps":["Step 1: Assume 100 g — so C = 52.2 g, H = 13 g, O = 34.8 g","Step 2: Convert to moles: C = 52.2 ÷ 12 = 4.35, H = 13 ÷ 1 = 13, O = 34.8 ÷ 16 = 2.18","Step 3: Divide all by the smallest value (2.18): C = 4.35/2.18 ≈ 2, H = 13/2.18 ≈ 6, O = 2.18/2.18 = 1","Step 4: The whole-number ratio is C:H:O = 2:6:1, so the empirical formula is C₂H₆O"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 0),
  (786, 133, 'An iron oxide compound contains 70% iron (Fe) and 30% oxygen (O) by mass. Find its empirical formula. (Fe = 56, O = 16)', 'text', 1, 'When the ratio gives a decimal like 1.5, multiply all values by 2 to get whole numbers', '{"why":"The ratio 1:1.5 must be made into whole numbers. Multiplying by 2 gives 2:3, which is the correct ratio of Fe to O atoms in iron(III) oxide.","sol":"Step 1: Assume 100 g — Fe = 70 g, O = 30 g\nStep 2: Convert to moles: Fe = 70 ÷ 56 = 1.25, O = 30 ÷ 16 = 1.875\nStep 3: Divide by the smallest (1.25): Fe = 1.25/1.25 = 1, O = 1.875/1.25 = 1.5\nStep 4: Ratio 1 : 1.5 is not whole — multiply everything by 2: Fe = 2, O = 3\nStep 5: Empirical formula = Fe₂O₃","steps":["Step 1: Assume 100 g — Fe = 70 g, O = 30 g","Step 2: Convert to moles: Fe = 70 ÷ 56 = 1.25, O = 30 ÷ 16 = 1.875","Step 3: Divide by the smallest (1.25): Fe = 1.25/1.25 = 1, O = 1.875/1.25 = 1.5","Step 4: Ratio 1 : 1.5 is not whole — multiply everything by 2: Fe = 2, O = 3","Step 5: Empirical formula = Fe₂O₃"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 1),
  (787, 133, 'A sample contains 2.0 g of hydrogen (H) and 16 g of oxygen (O). What is the empirical formula of the compound formed? (H = 1, O = 16)', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"The mole ratio of 2:1 directly gives the subscripts in the empirical formula. Since both values are already whole numbers, no further adjustment is needed.","sol":"Step 1: Convert each mass to moles: H = 2.0 ÷ 1 = 2, O = 16 ÷ 16 = 1\nStep 2: Find the mole ratio: H : O = 2 : 1\nStep 3: Check — are these already whole numbers? Yes.\nStep 4: Write the empirical formula: H₂O","steps":["Step 1: Convert each mass to moles: H = 2.0 ÷ 1 = 2, O = 16 ÷ 16 = 1","Step 2: Find the mole ratio: H : O = 2 : 1","Step 3: Check — are these already whole numbers? Yes.","Step 4: Write the empirical formula: H₂O"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 2),
  (788, 133, 'A compound is made from 3.0 g of carbon (C) and 8.0 g of oxygen (O). Find the empirical formula. (C = 12, O = 16)', 'text', 1, 'Focus on the core principle of Empirical Formula.', '{"why":"Dividing both mole values by the smallest (0.25) gives a ratio of 1:2, meaning for every 1 carbon atom there are 2 oxygen atoms. This matches the known formula of carbon dioxide.","sol":"Step 1: Convert to moles: C = 3.0 ÷ 12 = 0.25, O = 8.0 ÷ 16 = 0.5\nStep 2: Divide by the smallest value (0.25): C = 0.25/0.25 = 1, O = 0.5/0.25 = 2\nStep 3: Ratio C : O = 1 : 2\nStep 4: Empirical formula = CO₂","steps":["Step 1: Convert to moles: C = 3.0 ÷ 12 = 0.25, O = 8.0 ÷ 16 = 0.5","Step 2: Divide by the smallest value (0.25): C = 0.25/0.25 = 1, O = 0.5/0.25 = 2","Step 3: Ratio C : O = 1 : 2","Step 4: Empirical formula = CO₂"],"options":[],"conceptId":"chemistry_mole_empirical_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Empirical Formula"}', 3),
  (789, 134, 'A compound has an empirical formula of CH₂ and a molar mass (Mr) of 56 g/mol. Find the molecular formula.', 'text', 1, 'Find the empirical formula mass first, then divide Mr by it to get the multiplying factor n', '{"why":"The empirical formula CH₂ has a mass of 14. Since the actual Mr is 56, the molecular formula is 4 times bigger, giving C₄H₈ (the formula for butene).","sol":"Step 1: Calculate the empirical formula mass (EFM): CH₂ → C = 12, H₂ = 2, EFM = 14\nStep 2: Calculate the multiplying factor: n = Mr ÷ EFM = 56 ÷ 14 = 4\nStep 3: Multiply the entire empirical formula by n: CH₂ × 4 = C₄H₈","steps":["Step 1: Calculate the empirical formula mass (EFM): CH₂ → C = 12, H₂ = 2, EFM = 14","Step 2: Calculate the multiplying factor: n = Mr ÷ EFM = 56 ÷ 14 = 4","Step 3: Multiply the entire empirical formula by n: CH₂ × 4 = C₄H₈"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 0),
  (790, 134, 'A compound has the empirical formula NH₂ and a molar mass (Mr) of 32 g/mol. What is its molecular formula? (N = 14, H = 1)', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"The EFM of NH₂ is 16. With Mr = 32, n = 2. Multiplying every subscript by 2 gives N₂H₄, which is hydrazine.","sol":"Step 1: Calculate EFM: NH₂ → N = 14, H₂ = 2, EFM = 16\nStep 2: Find n: n = Mr ÷ EFM = 32 ÷ 16 = 2\nStep 3: Multiply formula by 2: NH₂ × 2 = N₂H₄","steps":["Step 1: Calculate EFM: NH₂ → N = 14, H₂ = 2, EFM = 16","Step 2: Find n: n = Mr ÷ EFM = 32 ÷ 16 = 2","Step 3: Multiply formula by 2: NH₂ × 2 = N₂H₄"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 1),
  (791, 134, 'The empirical formula of a compound is CH and its molar mass is 78 g/mol. Determine the molecular formula. (C = 12, H = 1)', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"EFM of CH is 13. Since Mr = 78 and 78 ÷ 13 = 6, the molecular formula is 6 times the empirical formula, giving C₆H₆ (benzene).","sol":"Step 1: Calculate EFM: CH → C = 12, H = 1, EFM = 13\nStep 2: Find n: n = Mr ÷ EFM = 78 ÷ 13 = 6\nStep 3: Multiply formula by 6: CH × 6 = C₆H₆","steps":["Step 1: Calculate EFM: CH → C = 12, H = 1, EFM = 13","Step 2: Find n: n = Mr ÷ EFM = 78 ÷ 13 = 6","Step 3: Multiply formula by 6: CH × 6 = C₆H₆"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 2),
  (792, 134, 'A compound has the empirical formula CH₂O and a molar mass of 90 g/mol. Find the molecular formula. (C = 12, H = 1, O = 16)', 'text', 1, 'Focus on the core principle of Molecular Formula.', '{"why":"EFM of CH₂O is 30. Dividing the actual Mr (90) by 30 gives n = 3. Every atom in the empirical formula is multiplied by 3 to get the molecular formula.","sol":"Step 1: Calculate EFM: CH₂O → C = 12, H₂ = 2, O = 16, EFM = 30\nStep 2: Find n: n = Mr ÷ EFM = 90 ÷ 30 = 3\nStep 3: Multiply formula by 3: CH₂O × 3 = C₃H₆O₃","steps":["Step 1: Calculate EFM: CH₂O → C = 12, H₂ = 2, O = 16, EFM = 30","Step 2: Find n: n = Mr ÷ EFM = 90 ÷ 30 = 3","Step 3: Multiply formula by 3: CH₂O × 3 = C₃H₆O₃"],"options":[],"conceptId":"chemistry_mole_molecular_formula","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Molecular Formula"}', 3),
  (793, 135, 'In the reaction N₂ + 3H₂ → 2NH₃, a student has 6 mol of H₂ and 2 mol of N₂. Which substance, if any, is the limiting reagent?', 'text', 1, 'Check how much H₂ is needed for 2 mol of N₂ using the mole ratio from the equation', '{"why":"When the available amounts of reactants exactly match the required mole ratio, both are fully consumed. There is no limiting reagent and no excess.","sol":"Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. The ratio is N₂ : H₂ = 1 : 3\nStep 2: Calculate H₂ needed for 2 mol N₂: 2 × 3 = 6 mol of H₂ is required\nStep 3: Compare with what is available: we have exactly 6 mol H₂\nStep 4: Both reactants are used up at the same rate — neither runs out first","steps":["Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. The ratio is N₂ : H₂ = 1 : 3","Step 2: Calculate H₂ needed for 2 mol N₂: 2 × 3 = 6 mol of H₂ is required","Step 3: Compare with what is available: we have exactly 6 mol H₂","Step 4: Both reactants are used up at the same rate — neither runs out first"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 0),
  (794, 135, 'In the reaction N₂ + 3H₂ → 2NH₃, a student mixes 10 mol of H₂ with 2 mol of N₂. Which reactant is the limiting reagent?', 'text', 1, 'Focus on the core principle of Limiting Reagent.', '{"why":"N₂ runs out first because the 2 mol available is completely consumed when reacting with 6 mol H₂. The remaining 4 mol of H₂ is excess and does not react.","sol":"Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. Ratio N₂ : H₂ = 1 : 3\nStep 2: Calculate how much H₂ is needed to react with 2 mol N₂: 2 × 3 = 6 mol H₂\nStep 3: Compare: we have 10 mol H₂ but only need 6 mol — so H₂ is in excess\nStep 4: N₂ is used up completely (only 2 mol available), so N₂ is the limiting reagent","steps":["Step 1: Read the equation: N₂ + 3H₂ → 2NH₃. Ratio N₂ : H₂ = 1 : 3","Step 2: Calculate how much H₂ is needed to react with 2 mol N₂: 2 × 3 = 6 mol H₂","Step 3: Compare: we have 10 mol H₂ but only need 6 mol — so H₂ is in excess","Step 4: N₂ is used up completely (only 2 mol available), so N₂ is the limiting reagent"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 1),
  (795, 135, 'In the reaction 2H₂ + O₂ → 2H₂O, a student has 4 mol of H₂ and only 1 mol of O₂. Identify the limiting reagent and state how many moles of water are produced.', 'text', 1, 'Focus on the core principle of Limiting Reagent.', '{"why":"Only 1 mol of O₂ is available, and it can react with at most 2 mol of H₂. The remaining 2 mol of H₂ goes unreacted. The limiting reagent controls the amount of product formed.","sol":"Step 1: Read the equation: 2H₂ + O₂ → 2H₂O. Ratio H₂ : O₂ = 2 : 1\nStep 2: Calculate H₂ needed for 1 mol O₂: 1 × 2 = 2 mol H₂ needed\nStep 3: We have 4 mol H₂ — that is more than enough, so H₂ is in excess\nStep 4: O₂ is the limiting reagent. The reaction produces 2 × 1 = 2 mol H₂O","steps":["Step 1: Read the equation: 2H₂ + O₂ → 2H₂O. Ratio H₂ : O₂ = 2 : 1","Step 2: Calculate H₂ needed for 1 mol O₂: 1 × 2 = 2 mol H₂ needed","Step 3: We have 4 mol H₂ — that is more than enough, so H₂ is in excess","Step 4: O₂ is the limiting reagent. The reaction produces 2 × 1 = 2 mol H₂O"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 2),
  (796, 135, 'In the reaction 4Al + 3O₂ → 2Al₂O₃, a student has 4 mol of Al but has a very large excess of O₂. Which is the limiting reagent, and how many moles of Al₂O₃ are produced?', 'text', 1, 'Focus on the core principle of Limiting Reagent.', '{"why":"When one reactant is in large excess, the other (Al here) is the limiting reagent. The amount of product is always determined by the limiting reagent, not by the excess.","sol":"Step 1: Read the equation: 4Al + 3O₂ → 2Al₂O₃. Ratio Al : Al₂O₃ = 4 : 2 = 2 : 1\nStep 2: Since O₂ is in excess, the amount of Al controls the reaction\nStep 3: Al is the limiting reagent. Use the ratio: 4 mol Al → 2 mol Al₂O₃\nStep 4: 4 mol Al produces (4 ÷ 2) × 1 = 2 mol Al₂O₃","steps":["Step 1: Read the equation: 4Al + 3O₂ → 2Al₂O₃. Ratio Al : Al₂O₃ = 4 : 2 = 2 : 1","Step 2: Since O₂ is in excess, the amount of Al controls the reaction","Step 3: Al is the limiting reagent. Use the ratio: 4 mol Al → 2 mol Al₂O₃","Step 4: 4 mol Al produces (4 ÷ 2) × 1 = 2 mol Al₂O₃"],"options":[],"conceptId":"chemistry_mole_limiting_reagent","skillId":"chemistry_mole","subskillId":"chemistry_mole_q4","subject":"chemistry","chapter":"mole","topic":"Limiting Reagent"}', 3),
  (797, 136, 'A container holds 44.8 dm³ of carbon dioxide gas at STP. How many moles of CO₂ does the container hold?', 'text', 1, 'Use the formula: moles = volume ÷ 22.4', '{"why":"At STP, 1 mole of any gas occupies 22.4 dm³. Dividing 44.8 by 22.4 gives 2, meaning the container holds 2 moles of CO₂.","sol":"Step 1: Write the formula: n = Volume ÷ 22.4\nStep 2: Substitute: n = 44.8 ÷ 22.4\nStep 3: Calculate: n = 2 mol","steps":["Step 1: Write the formula: n = Volume ÷ 22.4","Step 2: Substitute: n = 44.8 ÷ 22.4","Step 3: Calculate: n = 2 mol"],"options":[],"conceptId":"chemistry_mole_gas_volume","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Gas Volume"}', 0),
  (798, 136, 'A chemist needs 5 moles of hydrogen gas (H₂) for an experiment. What volume of hydrogen gas, measured at STP, would the chemist need to collect?', 'text', 1, 'Focus on the core principle of Gas Volume.', '{"why":"Multiplying moles by 22.4 converts to volume at STP. 5 moles of any gas takes up 5 × 22.4 = 112 dm³ under standard conditions.","sol":"Step 1: Write the formula: Volume = n × 22.4\nStep 2: Substitute: Volume = 5 × 22.4\nStep 3: Calculate: Volume = 112 dm³","steps":["Step 1: Write the formula: Volume = n × 22.4","Step 2: Substitute: Volume = 5 × 22.4","Step 3: Calculate: Volume = 112 dm³"],"options":[],"conceptId":"chemistry_mole_gas_volume","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Gas Volume"}', 1),
  (799, 136, 'A balloon contains 11.2 dm³ of helium gas at STP. How many moles of helium are in the balloon?', 'text', 1, 'Focus on the core principle of Gas Volume.', '{"why":"11.2 dm³ is exactly half of 22.4 dm³ (the molar volume at STP). So the balloon contains half a mole of helium gas.","sol":"Step 1: Write the formula: n = Volume ÷ 22.4\nStep 2: Substitute: n = 11.2 ÷ 22.4\nStep 3: Calculate: n = 0.5 mol","steps":["Step 1: Write the formula: n = Volume ÷ 22.4","Step 2: Substitute: n = 11.2 ÷ 22.4","Step 3: Calculate: n = 0.5 mol"],"options":[],"conceptId":"chemistry_mole_gas_volume","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Gas Volume"}', 2),
  (800, 137, 'A student says ''the mole concept is a bridge in chemistry.'' What do they mean by this? Explain using the difference between the microscopic and macroscopic worlds.', 'text', 1, 'Think about how atoms are too small to weigh individually, but we can measure grams in the lab', '{"why":"Without the mole, chemists could not relate what happens at the atomic level (e.g. 2 atoms of H react with 1 atom of O) to what they measure in the lab (grams of hydrogen and oxygen).","sol":"Step 1: The microscopic world = individual atoms and molecules, which are far too small to count or weigh directly\nStep 2: The macroscopic world = the gram quantities we can measure using a balance in a laboratory\nStep 3: The mole links these two worlds — 1 mole of any substance has a fixed number of particles (6.02 × 10²³) AND a measurable mass in grams (its molar mass)\nStep 4: This allows chemists to move between counting particles and measuring mass","steps":["Step 1: The microscopic world = individual atoms and molecules, which are far too small to count or weigh directly","Step 2: The macroscopic world = the gram quantities we can measure using a balance in a laboratory","Step 3: The mole links these two worlds — 1 mole of any substance has a fixed number of particles (6.02 × 10²³) AND a measurable mass in grams (its molar mass)","Step 4: This allows chemists to move between counting particles and measuring mass"],"options":[],"conceptId":"chemistry_mole_importance_and_applications_of_mole_concept","skillId":"chemistry_mole","subskillId":"chemistry_mole_q1","subject":"chemistry","chapter":"mole","topic":"Importance and applications of mole concept"}', 0),
  (801, 137, 'Explain how the mole concept is used in the pharmaceutical (medicine) industry when manufacturing drugs.', 'text', 1, 'Think about why precise amounts of substances matter in medicine', '{"why":"Drug effectiveness depends on having the right number of molecules, not just the right weight. The mole converts between particle counts and measurable gram quantities.","sol":"Step 1: Drug molecules must be mixed in exact proportions to be effective and safe\nStep 2: Chemists use mole ratios to calculate exactly how many grams of each ingredient to combine\nStep 3: The mole ensures that the correct number of molecules of the active substance is in every tablet or dose\nStep 4: Too little is ineffective; too much can be toxic — the mole concept enables precision","steps":["Step 1: Drug molecules must be mixed in exact proportions to be effective and safe","Step 2: Chemists use mole ratios to calculate exactly how many grams of each ingredient to combine","Step 3: The mole ensures that the correct number of molecules of the active substance is in every tablet or dose","Step 4: Too little is ineffective; too much can be toxic — the mole concept enables precision"],"options":[],"conceptId":"chemistry_mole_importance_and_applications_of_mole_concept","skillId":"chemistry_mole","subskillId":"chemistry_mole_q2","subject":"chemistry","chapter":"mole","topic":"Importance and applications of mole concept"}', 1),
  (802, 137, 'State two industrial applications of the mole concept and briefly explain how it is used in each.', 'text', 1, 'Think of industries that involve chemical reactions at large scale', '{"why":"Large-scale chemical manufacturing depends on accurate mole calculations. Even small errors in mole ratios can result in wasted materials, unsafe products, or financial loss.","sol":"Step 1: Ammonia production (Haber Process) — N₂ + 3H₂ → 2NH₃. Mole ratios tell engineers exactly how much N₂ and H₂ to feed into the reactor to maximise yield.\nStep 2: Fertilizer production — nutrients like nitrogen, phosphorus, and potassium (NPK) must be present in precise mole ratios for plant growth.\nStep 3: Both industries use mole calculations to avoid waste, maximise efficiency, and ensure product quality.","steps":["Step 1: Ammonia production (Haber Process) — N₂ + 3H₂ → 2NH₃. Mole ratios tell engineers exactly how much N₂ and H₂ to feed into the reactor to maximise yield.","Step 2: Fertilizer production — nutrients like nitrogen, phosphorus, and potassium (NPK) must be present in precise mole ratios for plant growth.","Step 3: Both industries use mole calculations to avoid waste, maximise efficiency, and ensure product quality."],"options":[],"conceptId":"chemistry_mole_importance_and_applications_of_mole_concept","skillId":"chemistry_mole","subskillId":"chemistry_mole_q3","subject":"chemistry","chapter":"mole","topic":"Importance and applications of mole concept"}', 2),
  (803, 138, 'Balance: N₂ + H₂ → NH₃', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Match nitrogen first, then hydrogen","sol":"Step 1: Nitrogen is 2 on left, 1 on right\nStep 2: Put 2 in front of NH₃\nStep 3: Now H = 6 on right\nStep 4: Put 3 in front of H₂","steps":["Step 1: Nitrogen is 2 on left, 1 on right","Step 2: Put 2 in front of NH₃","Step 3: Now H = 6 on right","Step 4: Put 3 in front of H₂"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 0),
  (804, 138, 'Balance: Na + Cl₂ → NaCl', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Equal chlorine atoms required","sol":"Step 1: Chlorine is 2 on left\nStep 2: Put 2 in front of NaCl\nStep 3: Adjust sodium to 2Na","steps":["Step 1: Chlorine is 2 on left","Step 2: Put 2 in front of NaCl","Step 3: Adjust sodium to 2Na"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 1),
  (805, 138, 'Balance: Mg + O₂ → MgO', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Balance oxygen first","sol":"Step 1: Oxygen is 2 on left, 1 on right\nStep 2: Put 2 in front of MgO\nStep 3: Put 2 in front of Mg","steps":["Step 1: Oxygen is 2 on left, 1 on right","Step 2: Put 2 in front of MgO","Step 3: Put 2 in front of Mg"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 2),
  (806, 138, 'Balance: Al + O₂ → Al₂O₃', 'text', 1, 'Focus on the core principle of Balancing equations.', '{"why":"Use least common multiple method","sol":"Step 1: Oxygen: LCM of 2 and 3 = 6\nStep 2: Put 3O₂ and 2Al₂O₃\nStep 3: Adjust aluminum to 4Al","steps":["Step 1: Oxygen: LCM of 2 and 3 = 6","Step 2: Put 3O₂ and 2Al₂O₃","Step 3: Adjust aluminum to 4Al"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 3),
  (807, 138, 'Balance: Fe + O₂ → Fe₂O₃', 'text', 1, 'use LCM', '{"why":"equal oxygen atoms first","sol":"Step 1: Oxygen LCM = 6\nStep 2: 3O₂ and 2Fe₂O₃\nStep 3: adjust Fe to 4","steps":["Step 1: Oxygen LCM = 6","Step 2: 3O₂ and 2Fe₂O₃","Step 3: adjust Fe to 4"],"options":[],"conceptId":"chemistry_reactions_balancing_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q5","subject":"chemistry","chapter":"reactions","topic":"Balancing equations"}', 4),
  (808, 139, 'In H₂ + O₂ → H₂O, is mass conserved?', 'text', 1, 'Focus on the core principle of Conservation of mass.', '{"why":"Balanced equation ensures equal atoms","sol":"Step 1: Count atoms on both sides\nStep 2: Same number of H and O atoms\nStep 3: Total mass remains constant","steps":["Step 1: Count atoms on both sides","Step 2: Same number of H and O atoms","Step 3: Total mass remains constant"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 0),
  (809, 139, 'Why must equations be balanced to obey this law?', 'text', 1, 'Focus on the core principle of Conservation of mass.', '{"why":"Balancing enforces conservation of mass","sol":"Step 1: Count atoms in reactants\nStep 2: Count atoms in products\nStep 3: Ensure equality\nStep 4: Adjust coefficients","steps":["Step 1: Count atoms in reactants","Step 2: Count atoms in products","Step 3: Ensure equality","Step 4: Adjust coefficients"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 1),
  (810, 139, 'Why is a closed container important in experiments?', 'text', 1, 'gas loss', '{"why":"Open systems lose matter","sol":"Step 1: Check reaction system\nStep 2: Prevent gas escape\nStep 3: Measure total mass correctly","steps":["Step 1: Check reaction system","Step 2: Prevent gas escape","Step 3: Measure total mass correctly"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 2),
  (811, 139, 'What law explains balancing chemical equations?', 'text', 1, 'Focus on the core principle of Conservation of mass.', '{"why":"Equations must reflect equal atoms","sol":"Step 1: Identify principle\nStep 2: Relate to atom conservation\nStep 3: State law","steps":["Step 1: Identify principle","Step 2: Relate to atom conservation","Step 3: State law"],"options":[],"conceptId":"chemistry_reactions_conservation_of_mass","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Conservation of mass"}', 3),
  (812, 140, 'Balance: Mg + O₂ → MgO', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Equal number of atoms on both sides","sol":"Step 1: Oxygen atoms are 2 on left and 1 on right\nStep 2: Put 2 in front of MgO\nStep 3: Adjust magnesium to 2\nStep 4: Final check","steps":["Step 1: Oxygen atoms are 2 on left and 1 on right","Step 2: Put 2 in front of MgO","Step 3: Adjust magnesium to 2","Step 4: Final check"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 0),
  (813, 140, 'Write equation for hydrogen reacting with oxygen', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Water formation reaction","sol":"Step 1: Identify reactants H₂ and O₂\nStep 2: Product is H₂O\nStep 3: Balance equation\nStep 4: Final form","steps":["Step 1: Identify reactants H₂ and O₂","Step 2: Product is H₂O","Step 3: Balance equation","Step 4: Final form"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 1),
  (814, 140, 'What type of reaction is Fe + S → FeS?', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Two reactants form one product","sol":"Step 1: Two elements combine\nStep 2: Form one compound\nStep 3: Identify reaction type","steps":["Step 1: Two elements combine","Step 2: Form one compound","Step 3: Identify reaction type"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 2),
  (815, 140, 'Identify reactants in: CaCO₃ → CaO + CO₂', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Left side shows reactant","sol":"Step 1: Look left side\nStep 2: Identify compound present","steps":["Step 1: Look left side","Step 2: Identify compound present"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 3),
  (816, 140, 'Identify products in: Zn + HCl → ZnCl₂ + H₂', 'text', 1, 'Focus on the core principle of Chemical equations.', '{"why":"Right side shows products","sol":"Step 1: Look right side\nStep 2: List substances formed","steps":["Step 1: Look right side","Step 2: List substances formed"],"options":[],"conceptId":"chemistry_reactions_chemical_equations","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q5","subject":"chemistry","chapter":"reactions","topic":"Chemical equations"}', 4),
  (817, 141, 'Why is neutralization an exothermic reaction?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"Bond formation releases energy","sol":"Step 1: H⁺ and OH⁻ combine\nStep 2: Energy is released\nStep 3: Temperature increases","steps":["Step 1: H⁺ and OH⁻ combine","Step 2: Energy is released","Step 3: Temperature increases"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q1","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 0),
  (818, 141, 'What are the product formed after this reaction: HCl + NaOH → ?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"acid + base reaction","sol":"Step 1: Identify acid (HCl)\nStep 2: Identify base (NaOH)\nStep 3: Swap ions\nStep 4: Form NaCl + H₂O","steps":["Step 1: Identify acid (HCl)","Step 2: Identify base (NaOH)","Step 3: Swap ions","Step 4: Form NaCl + H₂O"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q2","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 1),
  (819, 141, 'What are the product formed after this reaction: H₂SO₄ + KOH → ?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"neutralization produces salt + water","sol":"Step 1: Acid = H₂SO₄\nStep 2: Base = KOH\nStep 3: Form salt K₂SO₄\nStep 4: Form water","steps":["Step 1: Acid = H₂SO₄","Step 2: Base = KOH","Step 3: Form salt K₂SO₄","Step 4: Form water"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q3","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 2),
  (820, 141, 'What ions react in neutralization?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"they form water","sol":"Step 1: Acid releases H⁺\nStep 2: Base releases OH⁻\nStep 3: Combine ions","steps":["Step 1: Acid releases H⁺","Step 2: Base releases OH⁻","Step 3: Combine ions"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q4","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 3),
  (821, 141, 'Why does pH move towards 7?', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"neutral solution forms","sol":"Step 1: Acid lowers pH\nStep 2: Base raises pH\nStep 3: Reaction balances ions","steps":["Step 1: Acid lowers pH","Step 2: Base raises pH","Step 3: Reaction balances ions"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q5","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 4),
  (822, 141, 'Example 5: Identify salt in HNO₃ + NaOH', 'text', 1, 'Focus on the core principle of Neutralization.', '{"why":"salt is ionic product","sol":"Step 1: Remove H from acid\nStep 2: Remove OH from base\nStep 3: Combine Na + NO₃","steps":["Step 1: Remove H from acid","Step 2: Remove OH from base","Step 3: Combine Na + NO₃"],"options":[],"conceptId":"chemistry_reactions_neutralization","skillId":"chemistry_reactions","subskillId":"chemistry_reactions_q6","subject":"chemistry","chapter":"reactions","topic":"Neutralization"}', 5),
  (823, 142, 'What is an acid?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"Acidity is due to hydrogen ions","sol":"Step 1: Identify substance in water\nStep 2: Check for ion production\nStep 3: Confirm H⁺ ions released","steps":["Step 1: Identify substance in water","Step 2: Check for ion production","Step 3: Confirm H⁺ ions released"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q1","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 0),
  (824, 142, 'What happens when HCl is added in water?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"strong acid fully dissociates","sol":"Step 1: Identify acid (HCl)\nStep 2: Dissociation occurs\nStep 3: H⁺ and Cl⁻ form","steps":["Step 1: Identify acid (HCl)","Step 2: Dissociation occurs","Step 3: H⁺ and Cl⁻ form"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q2","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 1),
  (825, 142, 'What is H₂SO₄ dissociation?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"releases two hydrogen ions","sol":"Step 1: Recognize diprotic acid\nStep 2: Releases 2 H⁺ ions\nStep 3: Forms SO₄²⁻ ion","steps":["Step 1: Recognize diprotic acid","Step 2: Releases 2 H⁺ ions","Step 3: Forms SO₄²⁻ ion"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q3","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 2),
  (826, 142, 'Why are acids corrosive?', 'text', 1, 'Focus on the core principle of Acids.', '{"why":"chemical reactivity of H⁺","sol":"Step 1: Acids release H⁺ ions\nStep 2: H⁺ reacts with proteins\nStep 3: Tissue damage occurs","steps":["Step 1: Acids release H⁺ ions","Step 2: H⁺ reacts with proteins","Step 3: Tissue damage occurs"],"options":[],"conceptId":"chemistry_acids_bases_acids","skillId":"chemistry_acids_bases","subskillId":"chemistry_acids_bases_q4","subject":"chemistry","chapter":"acids_bases","topic":"Acids"}', 3),
